// ============================================================
// 界面优化工具函数 - 按钮文字格式化 & 表格Excel风
// ============================================================

/**
 * 格式化按钮文字：
 * - 1-2字：单行
 * - 3-4字：单行
 * - 超过4字：自动拆分为2行显示，每行2个字
 * 智能分隔符：空格、标点会优先在分隔符处换行
 */
function formatButtonText(rawText) {
    if (!rawText) return '';
    const text = String(rawText).trim();

    // 纯数字或极短文本保持原样
    if (text.length <= 4) {
        return text;
    }

    // 含明确分隔符的：优先用分隔符换行
    const splitChars = [' ', '/', '·', '：', ':', '-', '_'];
    for (const ch of splitChars) {
        if (text.includes(ch) && text.length > 4) {
            const parts = text.split(ch).filter(s => s.length > 0);
            if (parts.length >= 2) {
                // 将长文本按分隔符折成两行（大致平衡长度）
                let firstHalf = parts[0];
                let secondHalf = parts.slice(1).join(ch);
                if (firstHalf.length > 4 && secondHalf.length > 4) {
                    return firstHalf + '\n' + secondHalf;
                }
            }
        }
    }

    // 对长中文字按每2个字一组换行（4字以内一行，超过则2x2）
    const chars = Array.from(text);
    if (chars.length <= 4) return text;

    // 按每2个字一组，但最多显示两组（4个字），多余省略
    const visible = chars.slice(0, 4);
    const line1 = visible.slice(0, 2).join('');
    const line2 = visible.slice(2, 4).join('');
    // 原文本超过4字时，第一行末尾+超...提示
    const hasMore = chars.length > 4;
    return line1 + '\n' + line2 + (hasMore ? '' : '');
}

/**
 * 统一处理页面中所有.btn按钮的文字：
 * - 提取按钮中的文字节点（忽略icon/emoji/数字计数）
 * - 将纯中文核心文字包装为 <span class="btn-text"> 并按2字换行
 * - 短按钮（2字以内）添加 .short-btn 类
 */
function processAllButtonLabels() {
    const buttons = document.querySelectorAll('.btn');
    buttons.forEach(btn => {
        // 已处理的跳过
        if (btn.dataset.btnTextProcessed === '1') return;

        let iconHtml = '';
        let textNode = null;

        // 1. 查找现有图标span和文字
        const iconSpan = btn.querySelector('.btn-icon');
        if (iconSpan) {
            iconHtml = iconSpan.outerHTML;
        }

        // 2. 提取纯文本（跳过icon/计数等子元素）
        let rawText = '';
        btn.childNodes.forEach(node => {
            if (node.nodeType === Node.TEXT_NODE) {
                rawText += node.textContent || '';
            } else if (node.nodeType === Node.ELEMENT_NODE) {
                const el = node;
                // 跳过图标和计数器span
                if (el.classList && (el.classList.contains('btn-icon') || el.querySelector('.btn-icon'))) {
                    return;
                }
                // 对其他span/div：若仅含数字或短文本则保留为独立span
                const t = (el.textContent || '').trim();
                if (t && /^[\d()（）]+$/.test(t)) {
                    // 如 "(0)" 这种计数，附加到文本
                    rawText += t;
                } else {
                    rawText += t;
                }
            }
        });

        rawText = rawText.trim();
        if (!rawText) {
            btn.dataset.btnTextProcessed = '1';
            return;
        }

        // 3. 根据长度处理
        const cnCount = (rawText.match(/[\u4e00-\u9fa5]/g) || []).length;
        let formattedHtml = '';

        if (cnCount <= 2 && rawText.length <= 4) {
            // 短按钮：单行显示
            btn.classList.add('short-btn');
            formattedHtml = '<span class="btn-text" style="display:inline-block;text-align:center;line-height:1.2;">' + escapeHtml(rawText) + '</span>';
        } else if (rawText.length <= 4) {
            // 3-4字单行
            formattedHtml = '<span class="btn-text" style="display:inline-block;text-align:center;line-height:1.2;">' + escapeHtml(rawText) + '</span>';
        } else {
            // 超过4字：2行显示（每行2字）
            const formatted = formatButtonText(rawText);
            const lines = formatted.split('\n');
            formattedHtml = '<span class="btn-text" style="display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:1.15;gap:2px;">' +
                lines.map(line => '<span style="display:block;white-space:nowrap;">' + escapeHtml(line) + '</span>').join('') +
                '</span>';
        }

        // 4. 重建按钮内容
        btn.innerHTML = (iconHtml ? iconHtml + ' ' : '') + formattedHtml;
        btn.dataset.btnTextProcessed = '1';
    });
}

/**
 * 根据内容自动判断表格单元格对齐方式：
 * - 纯数字/小数/百分比 → 右对齐
 * - 日期 / 时间 → 居中或右对齐
 * - 短编号/代号 → 居中
 * - 长文字描述 → 左对齐
 */
function getAlignTypeByContent(content) {
    const t = String(content || '').trim();
    if (!t) return 'center';

    // 纯数字（含负号、小数点、逗号、百分号）
    if (/^-?\d{1,3}(,\d{3})*(\.\d+)?%?$/.test(t)) return 'right';
    // 分数（如 98.5 / 请假 混合在培训表 - 有单独逻辑）
    if (/^\d+(\.\d+)?$/.test(t)) return 'right';
    // 日期 yyyy-mm-dd / yyyy/mm/dd / yyyy年mm月dd日
    if (/^\d{4}[-/.年]\d{1,2}[-/.月]\d{1,2}日?$/.test(t)) return 'right';
    // 年月
    if (/^\d{4}[-/.年]\d{1,2}月?$/.test(t)) return 'center';
    // 身份证号等长数字串
    if (/^\d{6,}$/.test(t)) return 'left';
    // 短文本(≤4字)居中
    if ([...t].length <= 4) return 'center';
    // 长文本左对齐
    return 'left';
}

/**
 * 为所有台账表格应用智能格式：
 * - 表头加.sortable样式（可排序）+ 点击排序事件
 * - 单元格根据内容类型自动对齐
 */
function optimizeLedgerTables() {
    const tables = document.querySelectorAll('#personnelTable, #inspectionTable, #honorTable, #trainingTable, #patrolDataTable, #samplingCarTable, #instrumentTable, #teamPersonnelTable');
    tables.forEach(table => {
        // 表头智能：根据列索引内容判断是否可排序
        const ths = table.querySelectorAll('thead th');
        ths.forEach((th, colIdx) => {
            // 复选框列和操作列不可排序
            const text = (th.textContent || '').trim();
            if (!text || th.querySelector('input[type="checkbox"]')) return;
            if (text.includes('操作') || text.includes('选择')) return;

            if (!th.classList.contains('sortable')) {
                th.classList.add('sortable');
            }

            // 绑定排序事件（仅绑定一次）
            if (th.dataset.sortBound !== '1') {
                th.dataset.sortBound = '1';
                th.addEventListener('click', () => sortTableByColumn(table, colIdx, th));
            }
        });

        // 数据行单元格智能对齐
        const rows = table.querySelectorAll('tbody tr');
        rows.forEach(row => {
            const cells = row.querySelectorAll('td');
            cells.forEach((cell, idx) => {
                // 已手动设置的跳过
                if (cell.classList.contains('text-align-left') ||
                    cell.classList.contains('text-align-center') ||
                    cell.classList.contains('text-align-right')) return;

                // 第一列（序号/复选框）强制居中
                const hasCheckbox = cell.querySelector('input[type="checkbox"]');
                if (idx === 0 || hasCheckbox) {
                    cell.classList.add('text-align-center');
                    return;
                }

                const content = cell.textContent || '';
                const align = getAlignTypeByContent(content);
                cell.classList.add('text-align-' + align);
            });
        });
    });
}

/**
 * 按列对表格进行排序
 */
function sortTableByColumn(table, colIdx, thEl) {
    const tbody = table.querySelector('tbody');
    if (!tbody) return;

    // 判断当前排序方向
    const isAsc = thEl.classList.contains('sorted-asc');
    const newDir = isAsc ? 'desc' : 'asc';

    // 重置所有表头排序标记
    table.querySelectorAll('thead th.sortable').forEach(th => {
        th.classList.remove('sorted-asc', 'sorted-desc');
    });
    thEl.classList.add(newDir === 'asc' ? 'sorted-asc' : 'sorted-desc');

    // 获取所有数据行并排序
    const rows = Array.from(tbody.querySelectorAll('tr'));
    if (rows.length === 0) return;

    // 判断该列是否为数字列 - 根据第一行内容判断
    let isNumeric = true;
    for (const row of rows) {
        const cell = row.querySelectorAll('td')[colIdx];
        if (!cell) continue;
        const v = (cell.textContent || '').trim().replace(/[,，%%\s]/g, '');
        if (v && !/^-?\d+(\.\d+)?$/.test(v)) {
            // 允许有混合（如培训表的"请假"）- 用非数字优先判断
            if (v && !/[\u4e00-\u9fa5]/.test(v)) {
                // 不是中文也不是数字 => 文本
                isNumeric = false;
                break;
            }
        }
    }

    rows.sort((a, b) => {
        const aCell = a.querySelectorAll('td')[colIdx];
        const bCell = b.querySelectorAll('td')[colIdx];
        if (!aCell || !bCell) return 0;
        const av = (aCell.textContent || '').trim();
        const bv = (bCell.textContent || '').trim();

        if (isNumeric) {
            const an = parseFloat(av.replace(/[,，%%\s]/g, ''));
            const bn = parseFloat(bv.replace(/[,，%%\s]/g, ''));
            const aIsNum = !isNaN(an);
            const bIsNum = !isNaN(bn);
            if (aIsNum && bIsNum) return newDir === 'asc' ? an - bn : bn - an;
            if (aIsNum) return newDir === 'asc' ? -1 : 1;
            if (bIsNum) return newDir === 'asc' ? 1 : -1;
            return av.localeCompare(bv, 'zh-CN');
        }
        return newDir === 'asc'
            ? av.localeCompare(bv, 'zh-CN')
            : bv.localeCompare(av, 'zh-CN');
    });

    // 重新写入tbody
    rows.forEach(row => tbody.appendChild(row));
}

/**
 * HTML转义
 */
function escapeHtml(s) {
    if (s == null) return '';
    return String(s)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

/**
 * 统一的DOM就绪初始化
 */
function scheduleUIPostProcess() {
    // 立即执行一次 + 延后再执行2次（捕获动态渲染的表格）
    const run = () => {
        try { processAllButtonLabels(); } catch (e) { console.warn('按钮处理失败:', e); }
        try { optimizeLedgerTables(); } catch (e) { console.warn('表格优化失败:', e); }
    };
    run();
    setTimeout(run, 300);
    setTimeout(run, 1200);
    setTimeout(run, 3000);

    // MutationObserver：检测新增DOM后再处理
    if (typeof MutationObserver !== 'undefined') {
        let pending = false;
        const observer = new MutationObserver(() => {
            if (pending) return;
            pending = true;
            setTimeout(() => {
                pending = false;
                run();
            }, 200);
        });
        observer.observe(document.body, { childList: true, subtree: true });
    }
}

// 在DOM就绪后启动
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', scheduleUIPostProcess);
} else {
    scheduleUIPostProcess();
}


// ==================== UUID生成函数 ====================
function generateUUID() {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
    });
}

