async function loadFromGitHub() {
    const settings = JSON.parse(localStorage.getItem('githubSettings') || '{}');
    if (!settings.owner || !settings.repo || !settings.token) {
        showGitHubResult('❌ 请先配置GitHub信息', 'error');
        return;
    }
    
    try {
        showGitHubResult('📥 正在从GitHub加载数据...', 'info');
        
        await githubDB.init(settings.owner, settings.repo, settings.token);
        
        const data = githubDB.localCache?.data;
        if (data) {
            for (const [key, value] of Object.entries(data)) {
                localStorage.setItem(key, JSON.stringify(value));
            }
        }
        
        localStorage.setItem('lastSyncTime', new Date().toISOString());
        updateGitHubStatus();
        
        showGitHubResult('✅ 数据加载成功！', 'success');
        
        setTimeout(() => {
            location.reload();
        }, 1500);
    } catch (error) {
        showGitHubResult(`❌ 加载失败: ${error.message}`, 'error');
    }
}

async function saveToGitHub() {
    const settings = JSON.parse(localStorage.getItem('githubSettings') || '{}');
    if (!settings.owner || !settings.repo || !settings.token) {
        showGitHubResult('❌ 请先配置GitHub信息', 'error');
        return;
    }
    
    try {
        showGitHubResult('📤 正在保存数据到GitHub...', 'info');
        
        await githubDB.init(settings.owner, settings.repo, settings.token);
        
        const dataKeys = [
            'personnelData', 'systemUsers', 'trainingData',
            'teamPersonnelData', 
            'teamPersonnelVersionHistory', 'inspectionData', 'honorData',
            'violationDisciplineLedger', 'teamCompetitionLedger',
            'samplingCarLedger', 'instrumentLedger'
        ];
        
        for (const key of dataKeys) {
            const value = localStorage.getItem(key);
            if (value) {
                githubDB.set(key, JSON.parse(value));
            }
        }
        
        const success = await githubDB.save();
        
        if (success) {
            localStorage.setItem('lastSyncTime', new Date().toISOString());
            updateGitHubStatus();
            showGitHubResult('✅ 数据保存成功！', 'success');
        } else {
            showGitHubResult('⚠️ 数据已保存到本地（GitHub同步失败）', 'warning');
        }
    } catch (error) {
        showGitHubResult(`❌ 保存失败: ${error.message}`, 'error');
    }
}

function updateGitHubStatus() {
    const settings = JSON.parse(localStorage.getItem('githubSettings') || '{}');
    const lastSync = localStorage.getItem('lastSyncTime');
    
    const statusConfig = document.getElementById('statusConfig');
    const statusLastSync = document.getElementById('statusLastSync');
    const statusLocation = document.getElementById('statusLocation');
    
    if (settings.owner && settings.repo && settings.token) {
        statusConfig.innerHTML = '<span style="color: green;">已配置 ✓</span>';
        statusLocation.innerHTML = '<span style="color: blue;">GitHub + 本地</span>';
    } else {
        statusConfig.innerHTML = '<span style="color: red;">未配置</span>';
        statusLocation.innerHTML = '<span style="color: gray;">仅本地存储</span>';
    }
    
    if (lastSync) {
        const date = new Date(lastSync);
        statusLastSync.innerHTML = `<span style="color: green;">${date.toLocaleString()}</span>`;
    } else {
        statusLastSync.innerHTML = '<span style="color: gray;">从未同步</span>';
    }
}

function showGitHubResult(message, type) {
    const resultDiv = document.getElementById('githubResult');
    if (resultDiv) {
        const colors = {
            success: 'color: green',
            error: 'color: red',
            warning: 'color: orange',
            info: 'color: blue'
        };
        resultDiv.innerHTML = `<p style="${colors[type] || colors.info}">${message}</p>`;
        
        setTimeout(() => {
            resultDiv.innerHTML = '';
        }, 3000);
    }
}

function startAutoSync() {
    if (autoSyncInterval) {
        clearInterval(autoSyncInterval);
    }
    
    autoSyncInterval = setInterval(async () => {
        try {
            await saveToGitHub();
        } catch (e) {
            console.error('自动同步失败:', e);
        }
    }, 30 * 60 * 1000);
}

function stopAutoSync() {
    if (autoSyncInterval) {
        clearInterval(autoSyncInterval);
        autoSyncInterval = null;
    }
}

document.addEventListener('DOMContentLoaded', function() {
    const closeBtn = document.getElementById('closeGitHubSettingsModal');
    if (closeBtn) {
        closeBtn.addEventListener('click', closeGitHubSettingsModal);
    }
    
    const settings = JSON.parse(localStorage.getItem('githubSettings') || '{}');
    if (settings.autoSyncEnabled) {
        startAutoSync();
    }
});

