// 初始化系统数据 - 确保数据完整性和一致性
function initializeSystemData() {
    try {
        console.log('🔧 开始初始化系统数据');
        
        // 从localStorage读取用户数据
        let storedUsers = localStorage.getItem('systemUsers');
        let parsedUsers = [];
        
        try {
            parsedUsers = storedUsers ? JSON.parse(storedUsers) : [];
        } catch (e) {
            console.error('❌ localStorage数据解析失败，重置为空数组:', e);
            parsedUsers = [];
        }
        
        // 验证数据格式
        if (!Array.isArray(parsedUsers)) {
            console.warn('❌ 用户数据格式错误（不是数组），重置为空数组');
            parsedUsers = [];
        }
        
        // 过滤无效用户（确保username存在）
        const validUsers = parsedUsers.filter(u => u && typeof u.username === 'string' && u.username.trim() !== '');
        if (validUsers.length !== parsedUsers.length) {
            console.warn(`❌ 过滤了 ${parsedUsers.length - validUsers.length} 个无效用户`);
        }
        
        // 更新users数组
        users = validUsers;
        
        // 为已有用户添加必要的默认字段
        users.forEach((user, index) => {
            if (!user.id) {
                user.id = generateUniqueId();
            }
            if (!user.role) {
                user.role = 'user';
            }
            if (!user.status) {
                user.status = 'active';
            }
            if (!user.createdAt) {
                user.createdAt = new Date().toISOString();
            }
            if (user.passwordHash === undefined) {
                user.passwordHash = false;
            }
        });
        
        // 确保只有一个管理员账号
        ensureAdminUser();
        
        console.log(`✅ 系统数据初始化完成，当前有效用户数: ${users.length}`);
    } catch (error) {
        console.error('❌ 系统数据初始化出错:', error);
        // 如果初始化失败，强制重置用户数据
        users = [];
        localStorage.setItem('systemUsers', JSON.stringify(users));
        ensureAdminUser();
    }
}

// 生成唯一ID
function generateUniqueId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
}

function ensureAdminUser() {
    console.log('🔒 确保管理员账号存在');
    
    // 查找现有的管理员账号
    const adminIndex = users.findIndex(u => u.username === 'lil7020');
    
    // 确保管理员账号存在且密码正确
    if (adminIndex === -1) {
        console.log('🔒 管理员账号不存在，创建新账号');
        users.push({
            id: generateUniqueId(),
            username: 'lil7020',
            password: 'lil7020',
            realName: '系统管理员',
            role: 'topadmin',
            status: 'active',
            createdAt: new Date().toISOString(),
            passwordHash: false
        });
    } else {
        console.log('🔒 管理员账号已存在，确保密码正确');
        // 确保密码是明文的 lil7020（用于兼容性）
        users[adminIndex].password = 'lil7020';
        users[adminIndex].passwordHash = false;
        users[adminIndex].role = 'topadmin';
        users[adminIndex].status = 'active';
        if (!users[adminIndex].id) users[adminIndex].id = generateUniqueId();
        if (!users[adminIndex].createdAt) users[adminIndex].createdAt = new Date().toISOString();
    }
    
    // 删除其他重复的管理员账号
    for (let i = users.length - 1; i >= 0; i--) {
        if (users[i].username === 'lil7020' && users[i].role === 'topadmin') {
            if (i !== users.findIndex(u => u.username === 'lil7020')) {
                users.splice(i, 1);
            }
        }
    }
    
    saveUsers();
    console.log('🔒 管理员账号确保完成，当前用户数量:', users.length);
}

function saveUsers() {
    localStorage.setItem('systemUsers', JSON.stringify(users));
}



// 管理员检查函数
// 用户是否为管理员（通过角色系统判断）
function isAdminUser(username) {
    // 硬编码主任账号
    if (username === 'lil7020') {
        return true;
    }
    // 从 systemUsers 中查找该用户的角色
    const users = JSON.parse(localStorage.getItem('systemUsers') || '[]');
    const user = users.find(u => u.username === username);
    if (user && user.role === 'topadmin') {
        return true;
    }
    return false;
}

