// 更新所有页面的用户信息显示
function updateAllUserInfoDisplays(user) {
    const roleText = getRoleText(user.role);
    // 显示格式：真实姓名 (用户名) [角色]
    const realName = user.realName || user.realname || '';
    const displayText = realName && realName.trim() !== '' 
        ? `${realName} (${user.username || '用户'}) ${roleText}` 
        : `${user.username || '用户'} ${roleText}`;
    
    // 更新所有带有 current-user-name 类的元素（统一更新所有模块的用户信息显示）
    const allUserNameElements = document.querySelectorAll('.current-user-name');
    allUserNameElements.forEach(element => {
        element.textContent = displayText;
    });
    
    // 兼容旧的ID选择器
    const navUserName = document.getElementById('navUserName');
    if (navUserName) {
        navUserName.textContent = displayText;
    }
    
    const personnelUserName = document.getElementById('personnelUserName');
    if (personnelUserName) {
        personnelUserName.textContent = displayText;
    }
}

// 检查是否为管理员（班长、主任或管理者）
function isHazardManager() {
    const role = getCurrentRole();
    if (role === 'topadmin') return true;
    if (role === 'manager') return true;
    if (role === 'leader') return true;
    return false;
}

// 检查当前用户是否可以管理指定任务（用于删除权限）
function canManageTask(task) {
    const role = getCurrentRole();
    
    // 主任可以管理（删除）所有任务
    if (role === 'topadmin') {
        return true;
    }
    
    // 管理者不能删除任何任务
    return false;
}

// 检查当前用户是否可以标记任务完成
function canMarkTaskComplete(task) {
    const role = getCurrentRole();
    
    // 主任可以标记任何任务完成
    if (role === 'topadmin') {
        return task.status !== 'completed' && task.status !== 'closed';
    }
    
    // 管理者只能标记进行中的任务完成
    if (role === 'manager') {
        return task.status === 'progress';
    }
    
    return false;
}

// 检查当前用户是否可以编辑任务
function canEditTask(task) {
    const role = getCurrentRole();
    
    // 主任可以编辑所有任务（包括已闭环）
    if (role === 'topadmin') {
        return true;
    }
    
    // 管理者不能编辑任何任务
    return false;
}

// 检查当前用户是否可以删除任务
function canDeleteTask(task) {
    return canManageTask(task);
}

// 检查当前用户是否可以闭环任务
function canCloseTask(task) {
    const role = getCurrentRole();
    const currentUser = JSON.parse(localStorage.getItem('currentUser') || '{}');
    const username = currentUser.username || localStorage.getItem('username') || '';
    
    console.log('canCloseTask debug:', { role, username, taskStatus: task.status });
    
    // 只有主任可以闭环任务
    if (role === 'topadmin') {
        return task.status !== 'closed';
    }
    
    return false;
}

