// 初始化导航权限
function initNavPermissions() {
    const currentUser = JSON.parse(localStorage.getItem('currentUser') || '{}');
    const role = getCurrentRole();
    
    // 调试信息（过滤敏感信息）
    console.log('=== 导航权限初始化调试 ===');
    const { password, passwordHash, ...safeUser } = currentUser || {};
    console.log('currentUser:', safeUser);
    console.log('获取到的角色:', role);
    console.log('============================');

    const navCards = document.querySelectorAll('.nav-card');
    
    navCards.forEach(card => {
        const requiredRole = card.getAttribute('data-role');
        
        if (!requiredRole) {
            card.style.display = 'block';
            return;
        }

        // 主任（topadmin）：可见所有模块
        if (role === 'topadmin') {
            card.style.display = 'block';
        }
        // 管理者（manager）：可见 user 和 manager 模块，不可见 topadmin 模块
        else if (role === 'manager') {
            if (requiredRole === 'user' || requiredRole === 'manager') {
                card.style.display = 'block';
            } else {
                card.style.display = 'none';
            }
        }
        // 普通用户（user）：仅可见 user 模块
        else {
            if (requiredRole === 'user') {
                card.style.display = 'block';
            } else {
                card.style.display = 'none';
            }
        }
    });

    // 更新所有页面的用户信息显示
    updateAllUserInfoDisplays(currentUser);

    const changePwdBtn = document.getElementById('changePwdBtn');
    if (changePwdBtn) {
        changePwdBtn.style.display = 'inline-block';
    }

    const userManageBtn = document.getElementById('userManageBtn');
    if (userManageBtn) {
        // 用户管理功能：仅主任可见
        userManageBtn.style.display = role === 'topadmin' ? 'inline-block' : 'none';
    }

    const navLogoutBtn = document.getElementById('navLogoutBtn');
    if (navLogoutBtn) {
        navLogoutBtn.style.display = 'inline-block';
    }

    console.log('导航权限初始化完成，当前用户:', currentUser.username, '角色:', role);
}

