// 检查当前用户角色
function getCurrentRole() {
    const currentUser = JSON.parse(localStorage.getItem('currentUser') || '{}');
    const username = currentUser.username || localStorage.getItem('username') || '';
    
    // 主任账号确保始终拥有最高权限
    if (username === 'lil7020') {
        return 'topadmin';
    }
    
    // 从 currentUser 对象中获取角色
    if (currentUser.role) {
        return currentUser.role;
    }
    
    // 尝试从 systemUsers 中获取
    const users = JSON.parse(localStorage.getItem('systemUsers') || '[]');
    const user = users.find(u => u.username === username);
    if (user && user.role) {
        // 更新 currentUser 中的角色
        currentUser.role = user.role;
        localStorage.setItem('currentUser', JSON.stringify(currentUser));
        return user.role;
    }
    
    // 默认返回普通用户角色
    return 'user';
}

// 控制页面功能权限
function initPagePermissions(pageName) {
    const role = getCurrentRole();
    
    if (role === 'topadmin') {
        // 管理员可以使用所有功能
        return;
    }
    
    try {
        // 违章违纪台账模块：仅主任可以访问，其他角色不开放
        if (pageName === 'patrol') {
            if (role !== 'topadmin') {
                applyReadOnlyPermissions(pageName);
                return;
            }
        }
        
        // 检查问题台账模块：班长和普通用户都只能查看，不能编辑和删除
        if (pageName === 'inspection') {
            // 主任（topadmin）和管理人员（manager）可以编辑和删除，班长（leader）和普通用户（user）只读
            if (role !== 'topadmin' && role !== 'manager') {
                applyReadOnlyPermissions(pageName);
                return;
            }
        }
        
        // 获得荣誉台账模块：班长和普通用户都只能查看，不能编辑和删除
        if (pageName === 'honor') {
            // 主任（topadmin）和管理人员（manager）可以编辑和删除，班长（leader）和普通用户（user）只读
            if (role !== 'topadmin' && role !== 'manager') {
                applyReadOnlyPermissions(pageName);
                return;
            }
        }
        
        // 副班培训模块：班长和普通用户都只能查看，不能编辑和删除
        if (pageName === 'training') {
            // 主任（topadmin）和管理人员（manager）可以编辑和删除，班长（leader）和普通用户（user）只读
            if (role !== 'topadmin' && role !== 'manager') {
                applyReadOnlyPermissions(pageName);
                return;
            }
        }
        
        // 红旗班组模块：班长和普通用户都只能查看，不能编辑和删除
        if (pageName === 'team') {
            // 主任（topadmin）和管理人员（manager）可以编辑和删除，班长（leader）和普通用户（user）只读
            if (role !== 'topadmin' && role !== 'manager') {
                applyReadOnlyPermissions(pageName);
                return;
            }
        }
        
        // 对于其他模块，普通用户只能查看、保存到云端、刷新数据、查询
        if (role === 'user') {
            applyReadOnlyPermissions(pageName);
            return;
        }
        
        // 管理者（manager）和班长（leader）的权限保持原样
        if (pageName === 'teamPersonnel') {
            // 普通用户在班组人员模块只能查看，不能编辑
            const allButtons = document.querySelectorAll('.team-personnel-page .btn');
            allButtons.forEach(btn => {
                const btnText = btn.textContent || '';
                // 隐藏所有编辑按钮
                if (btnText.includes('添加') || btnText.includes('编辑') || 
                    btnText.includes('删除') || btnText.includes('导入') || 
                    btnText.includes('导出') || btnText.includes('保存') ||
                    btnText.includes('撤销')) {
                    btn.style.display = 'none';
                }
            });
            
            // 隐藏编辑按钮
            const editBtn = document.getElementById('editTeamPersonnelBtn');
            if (editBtn) {
                editBtn.style.display = 'none';
            }
            
            // 隐藏添加按钮
            const addBtn = document.getElementById('addTeamBtn');
            if (addBtn) {
                addBtn.style.display = 'none';
            }
        }
    } catch (error) {
        console.error('权限控制出错:', error);
    }
}

// 为普通用户应用只读权限（保留保存到云端、刷新数据、查询）
function applyReadOnlyPermissions(pageName) {
    const pageSelector = `#${pageName}Page`;
    const pageElement = document.querySelector(pageSelector);
    if (!pageElement) return;
    
    const allButtons = pageElement.querySelectorAll('.btn');
    
    allButtons.forEach(btn => {
        const btnText = btn.textContent || '';
        const btnId = btn.id || '';
        
        // 保留的按钮：刷新数据、查询、搜索、导出（普通用户非违章违纪模块不保留保存到云端）
        const isKeepButton = 
            btnText.includes('刷新数据') || 
            btnText.includes('刷新') ||
            btnText.includes('查询') || 
            btnText.includes('搜索') ||
            btnText.includes('导出') ||
            btnText.includes('🔍') ||
            btnText.includes('📥') ||
            btnId.includes('search') ||
            btnId.includes('Search') ||
            btnId.includes('refresh') ||
            btnId.includes('Refresh') ||
            btnId.includes('export') ||
            btnId.includes('Export');
        
        // 隐藏的按钮：添加、编辑、删除、导入、保存（本地）、撤销、清空、批量上传/删除
        const isHideButton = 
            btnText.includes('添加') || 
            btnText.includes('编辑') || 
            btnText.includes('删除') || 
            btnText.includes('导入') || 
            btnText.includes('保存') && !btnText.includes('保存到云端') ||
            btnText.includes('撤销') ||
            btnText.includes('清空') ||
            (btnText.includes('批量') && !btnText.includes('导出')) ||
            btnText.includes('上传') ||
            btnText.includes('📤') ||
            btnText.includes('➕') ||
            btnText.includes('✏️') ||
            btnText.includes('🗑️');
        
        if (isHideButton && !isKeepButton) {
            btn.style.display = 'none';
        }
    });
    
    // 针对各个模块的特殊处理
    applyModuleSpecificPermissions(pageName);
}

