function openChangePasswordModal() {
    document.getElementById('changePasswordForm').reset();
    document.getElementById('changePasswordModal').style.display = 'block';
}

// 关闭修改密码模态框
function closeChangePasswordModal() {
    document.getElementById('changePasswordModal').style.display = 'none';
}

// 修改密码
async function changePassword(e) {
    e.preventDefault();

    const currentPassword = document.getElementById('currentPassword').value;
    const newPassword = document.getElementById('newPasswordInput').value;
    const confirmPassword = document.getElementById('confirmNewPassword').value;

    if (!currentPassword || !newPassword || !confirmPassword) {
        alert('请填写所有字段');
        return;
    }

    if (newPassword.length < 6) {
        alert('新密码至少需要6个字符');
        return;
    }

    if (newPassword !== confirmPassword) {
        alert('两次输入的新密码不一致');
        return;
    }

    const currentUser = JSON.parse(localStorage.getItem('currentUser') || '{}');
    const username = currentUser.username || localStorage.getItem('username') || '';
    
    if (!username) {
        alert('请先登录');
        return;
    }

    try {
        // 验证当前密码
        let user = null;
        
        // 先从云端验证
        if (typeof cloudUserManager !== 'undefined') {
            const cloudUser = await cloudUserManager.getUserByUsername(username);
            if (cloudUser) {
                let passwordMatch = currentPassword === cloudUser.password;
                if (!passwordMatch && cloudUser.passwordHash) {
                    const inputHash = await hashPassword(currentPassword);
                    passwordMatch = inputHash === cloudUser.password;
                }
                if (passwordMatch) {
                    user = cloudUser;
                }
            }
        }
        
        // 如果云端没找到或验证失败，从本地验证
        if (!user) {
            const localUsers = JSON.parse(localStorage.getItem('systemUsers') || '[]');
            for (const u of localUsers) {
                if (u.username === username) {
                    let passwordMatch = currentPassword === u.password;
                    if (!passwordMatch && u.passwordHash) {
                        const inputHash = await hashPassword(currentPassword);
                        passwordMatch = inputHash === u.password;
                    }
                    if (passwordMatch) {
                        user = u;
                        break;
                    }
                }
            }
        }

        if (!user) {
            alert('当前密码不正确');
            return;
        }

        // 更新密码
        const updatedUser = { ...user, password: newPassword, passwordHash: false };
        
        // 同步到云端
        if (typeof updateUserInCloud === 'function' && user.id) {
            await updateUserInCloud(user.id, { password: newPassword, passwordHash: false });
        }
        
        // 更新本地存储
        const localUsers = JSON.parse(localStorage.getItem('systemUsers') || '[]');
        const index = localUsers.findIndex(u => u.username === username);
        if (index >= 0) {
            localUsers[index] = updatedUser;
            localStorage.setItem('systemUsers', JSON.stringify(localUsers));
        }
        
        // 更新当前用户信息
        localStorage.setItem('currentUser', JSON.stringify(updatedUser));

        alert('密码修改成功！请使用新密码登录');
        closeChangePasswordModal();
        logout();
        
    } catch (error) {
        console.error('修改密码失败:', error);
        alert('修改密码失败: ' + error.message);
    }
}

