// 注册新账号
async function registerUser(e) {
    e.preventDefault();

    const username = document.getElementById('regUsername').value.trim();
    const realName = document.getElementById('regRealName').value.trim();
    const password = document.getElementById('regPassword').value;
    const confirmPassword = document.getElementById('regConfirmPassword').value;
    const role = document.getElementById('regRole').value;

    if (!username || !realName || !password || !confirmPassword || !role) {
        alert('请填写所有字段');
        return;
    }

    if (username.length < 3) {
        alert('用户名至少需要3个字符');
        return;
    }

    if (password.length < 6) {
        alert('密码至少需要6个字符');
        return;
    }

    if (password !== confirmPassword) {
        alert('两次输入的密码不一致');
        return;
    }

    if (users.find(u => u.username === username)) {
        alert('该用户名已存在');
        return;
    }

    // 检查云端是否已存在该用户名
    if (typeof cloudUserManager !== 'undefined') {
        try {
            const existingCloudUser = await cloudUserManager.getUserByUsername(username);
            if (existingCloudUser) {
                alert('该用户名已存在');
                return;
            }
        } catch (error) {
            console.log('检查云端用户失败:', error.message);
        }
    }

    try {
        // 优先保存到云端
        if (typeof cloudUserManager !== 'undefined') {
            const cloudResult = await cloudUserManager.createUser({
                username,
                realName,
                password: password,
                role,
                status: 'pending'
            });
            
            if (cloudResult.success) {
                // 同步到本地
                users.push({
                    ...cloudResult.data,
                    username,
                    realName,
                    password: password,
                    passwordHash: false,
                    role,
                    status: 'pending',
                    createdAt: new Date().toISOString()
                });
                saveUsers();
                alert('注册成功！请等待管理员审核后再登录');
                closeRegisterModal();
            } else {
                alert(cloudResult.message || '注册失败，请检查网络连接');
            }
        } else {
            // 备用：保存到本地
            users.push({
                username,
                realName,
                password: password,
                passwordHash: false,
                role,
                status: 'pending',
                createdAt: new Date().toISOString()
            });
            saveUsers();
            alert('注册成功！请等待管理员审核后再登录');
            closeRegisterModal();
        }
    } catch (error) {
        console.error('注册失败:', error);
        alert(`注册失败: ${error.message}`);
    }
}

