// 渲染用户列表
function renderUserList() {
    const userList = document.getElementById('userList');

    if (users.length === 0) {
        userList.innerHTML = '<div class="user-empty">暂无注册用户</div>';
        return;
    }

    let html = '';
    users.forEach((user, index) => {
        const isAdmin = isAdminUser(user.username);
        const statusText = user.status === 'active' ? '已激活' : (user.status === 'pending' ? '待审核' : '已禁用');
        const statusClass = user.status;
        const passwordDisplay = user.password || '未设置';
        
        // 确定角色显示文本
        let roleText = '';
        let roleLabel = '';
        if (isAdmin || user.role === 'topadmin') {
            roleText = ' (主任)';
            roleLabel = '角色: 主任';
        } else if (user.role === 'manager') {
            roleText = ' (管理者)';
            roleLabel = '角色: 管理者';
        } else if (user.role === 'leader') {
            roleText = ' (班长)';
            roleLabel = '角色: 班长';
        } else {
            roleText = ' (普通用户)';
            roleLabel = '角色: 普通用户';
        }

        const realName = user.realName || user.realname || user.name || '';
        const displayName = realName && realName.trim() !== '' 
            ? `${realName} (${user.username})` 
            : user.username;
            
        html += `
            <div class="user-item">
                <div class="user-info">
                    <span class="user-name">${displayName}${roleText}</span>
                    <span class="user-password">密码: ${passwordDisplay}</span>
                    <span class="user-role">${roleLabel}</span>
                    <span class="user-realname">姓名: ${realName || '未填写'}</span>
                    <span class="user-status ${statusClass}">状态: ${statusText}</span>
                </div>
                <div class="user-actions">
        `;

        if (!isAdmin) {
            if (user.status === 'pending') {
                html += `<button class="btn btn-success btn-sm" onclick="activateUser(${index})">激活</button>`;
            } else if (user.status === 'active') {
                html += `<button class="btn btn-warning btn-sm" onclick="deactivateUser(${index})">禁用</button>`;
            } else if (user.status === 'inactive') {
                html += `<button class="btn btn-success btn-sm" onclick="activateUser(${index})">激活</button>`;
            }
            html += `<button class="btn btn-delete btn-sm" onclick="deleteUser(${index})">删除</button>`;
        }

        html += `</div></div>`;
    });

    userList.innerHTML = html;
}

// 激活用户
async function activateUser(index) {
    const user = users[index];
    user.status = 'active';
    saveUsers();
    
    // 同步到云端
    if (typeof updateUserInCloud === 'function' && user.id) {
        await updateUserInCloud(user.id, { status: 'active' });
    }
    
    renderUserList();
    alert(`用户 ${user.username} 已激活，其他设备会自动同步`);
}

// 禁用用户
async function deactivateUser(index) {
    const user = users[index];
    user.status = 'inactive';
    saveUsers();
    
    // 同步到云端
    if (typeof updateUserInCloud === 'function' && user.id) {
        await updateUserInCloud(user.id, { status: 'inactive' });
    }
    
    renderUserList();
    alert(`用户 ${user.username} 已禁用，其他设备会自动同步`);
}

// 删除用户
async function deleteUser(index) {
    const user = users[index];
    if (confirm(`确定要删除用户 "${user.username}" 吗？此操作不可恢复！`)) {
        // 先同步到云端
        if (typeof deleteUserFromCloud === 'function' && user.id) {
            await deleteUserFromCloud(user.id);
        }
        
        users.splice(index, 1);
        saveUsers();
        renderUserList();
        alert(`用户 ${user.username} 已删除，其他设备会自动同步`);
    }
}

// 管理员新增用户
async function addUserByAdmin(e) {
    e.preventDefault();

    const username = document.getElementById('newUsername').value.trim();
    const realName = document.getElementById('newRealName').value.trim();
    const password = document.getElementById('newPassword').value;
    const role = document.getElementById('newRole').value;

    if (!username || !realName || !password || !role) {
        alert('请填写用户名、真实姓名、密码和角色');
        return;
    }

    if (username.length < 3) {
        alert('用户名至少需要3个字符');
        return;
    }

    if (password.length < 6) {
        alert('密码至少需要6个字符');
        return;
    }

    if (users.find(u => u.username === username)) {
        alert('该用户名已存在');
        return;
    }

    const newUser = {
        username,
        realName,
        password: password,
        passwordHash: false,
        role,
        status: 'active',
        createdAt: new Date().toISOString()
    };
    
    // 先保存到云端
    if (typeof saveUsersToCloud === 'function') {
        const result = await saveUsersToCloud(newUser);
        if (result.success) {
            users.push(result.data);
        } else {
            // 如果云端保存失败，只保存到本地
            newUser.id = generateUniqueId();
            users.push(newUser);
        }
    } else {
        newUser.id = generateUniqueId();
        users.push(newUser);
    }
    
    saveUsers();

    document.getElementById('newUsername').value = '';
    document.getElementById('newPassword').value = '';
    document.getElementById('newRole').value = '';

    renderUserList();
    alert(`用户 ${username} 已添加并激活，角色：${role === 'user' ? '普通用户' : '管理者'}`);
}

