async function initInspection() {
    try {
        // 检查本地数据是否存在
        const localCenterData = localStorage.getItem('centerInspectionData');
        const localWorkshopData = localStorage.getItem('workshopInspectionData');
        
        if (!localCenterData) {
            // 中心检查问题数据：本地没有，从云端同步
            console.log('中心检查台账：本地无数据，从云端同步...');
            await syncModuleFromCloud('centerInspection', 'centerInspectionData', 'centerInspectionData', false);
        }
        
        if (!localWorkshopData) {
            // 作业区检查问题数据：本地没有，从云端同步
            console.log('作业区检查台账：本地无数据，从云端同步...');
            await syncModuleFromCloud('workshopInspection', 'workshopInspectionData', 'workshopInspectionData', false);
        }
    } catch (error) {
        console.log('云端同步失败，使用本地数据:', error.message);
    }
    
    loadCenterInspectionData();
    loadWorkshopInspectionData();
    
    // 初始化筛选数据并按检查时间倒序排序（时间晚的在前面）
    filteredCenterInspectionData = [...centerInspectionData].sort(compareInspectionByDate);
    filteredWorkshopInspectionData = [...workshopInspectionData].sort(compareInspectionByDate);
    
    initInspectionYearFilter();
    switchInspectionPage('center');
    initColumnResizing();
    
    // 初始化责任人和整改负责人下拉列表（从班组人员模块获取）
    populateInspectionPersonnelDropdowns();
    
    // 初始化动态同步状态指示器
    if (window.DynamicSync) {
        // 为当前页面创建状态指示器
        const moduleKey = currentInspectionPage === 'center' ? 'centerInspection' : 'workshopInspection';
        window.DynamicSync.initModule(moduleKey, 'saveInspectionToCloudBtn', '#inspectionPage .page-header');
    }
    
    // 先绑定按钮事件
    const exportBtn = document.getElementById('exportInspectionBtn');
    if (exportBtn) {
        exportBtn.onclick = exportInspectionData;
        console.log('✅ 检查问题台账导出按钮已绑定');
    }
    
    const saveBtn = document.getElementById('saveInspectionToCloudBtn');
    if (saveBtn) {
        saveBtn.onclick = saveInspectionToCloud;
        console.log('✅ 检查问题台账保存到云端按钮已绑定');
    }
    
    // 权限控制：只有topadmin和manager可以编辑，user只能查看
    const role = getCurrentRole();
    const isReadOnly = role === 'user';
    
    // 隐藏编辑相关按钮
    if (exportBtn) {
        exportBtn.style.display = isReadOnly ? 'none' : 'inline-flex';
    }
    if (saveBtn) {
        saveBtn.style.display = isReadOnly ? 'none' : 'inline-flex';
    }
    
    // 添加刷新按钮 - 使用专门的检查问题台账刷新函数
    if (typeof addModuleRefreshButton === 'function') {
        // 先移除旧的按钮（如果存在）
        const oldBtn = document.getElementById('refreshBtn_inspection');
        if (oldBtn) {
            oldBtn.remove();
        }
        
        const container = document.querySelector('#inspectionPage .toolbar-left');
        if (container) {
            const refreshBtn = document.createElement('button');
            refreshBtn.id = 'refreshBtn_inspection';
            refreshBtn.innerHTML = '<span>🔄</span> 刷新数据';
            refreshBtn.style.cssText = `
                margin-left: 8px;
                padding: 8px 16px;
                background: linear-gradient(135deg, #10b981 0%, #059669 100%);
                border: none;
                border-radius: 6px;
                color: white;
                font-weight: bold;
                cursor: pointer;
                font-size: 13px;
                display: inline-flex;
                align-items: center;
                gap: 6px;
                transition: all 0.2s;
            `;
            refreshBtn.onclick = refreshInspectionData;
            container.appendChild(refreshBtn);
            console.log('✅ 检查问题台账刷新按钮已添加');
        }
    }
    
    // 初始化导出选中按钮的显示状态
    updateInspectionExportButton();
}

// 初始化年份和月份选择器
function initInspectionDateSelectors() {
    const yearSelect = document.getElementById('inspectionYearSelect');
    const monthSelect = document.getElementById('inspectionMonthSelect');
    const currentYear = new Date().getFullYear();
    
    if (yearSelect) {
        yearSelect.innerHTML = '<option value="">选择年份</option>';
        // 从2020年到当前年份+1（允许提前录入下一年的数据）
        for (let year = 2020; year <= currentYear + 1; year++) {
            const option = document.createElement('option');
            option.value = year;
            option.textContent = year + '年';
            yearSelect.appendChild(option);
        }
    }
    
    if (monthSelect) {
        monthSelect.innerHTML = '<option value="">选择月份</option>';
        for (let month = 1; month <= 12; month++) {
            const option = document.createElement('option');
            option.value = month;
            option.textContent = month + '月';
            monthSelect.appendChild(option);
        }
    }
}

// 检查问题台账筛选
function filterInspection() {
    const yearFilter = document.getElementById('inspectionYearFilter').value;
    const monthFilter = document.getElementById('inspectionMonthFilter').value;
    const personFilter = document.getElementById('inspectionPersonFilter').value;
    const searchKeyword = document.getElementById('inspectionSearchInput').value || '';
    const clearBtn = document.getElementById('inspectionSearchClearBtn');

    // 显示/隐藏清除按钮
    if (clearBtn) {
        clearBtn.style.display = searchKeyword.trim() ? 'flex' : 'none';
    }

    console.log('🔍 检查问题台账筛选:', { yearFilter, monthFilter, personFilter, searchKeyword });

    // 根据当前页面筛选数据
    if (currentInspectionPage === 'center') {
        filteredCenterInspectionData = centerInspectionData.filter(item => {
            const personValue = item.responsible || '';
            const matchSearch = !searchKeyword || 
                (item.description && item.description.toLowerCase().includes(searchKeyword.toLowerCase())) ||
                (personValue && personValue.toLowerCase().includes(searchKeyword.toLowerCase())) ||
                (item.inspector && item.inspector.toLowerCase().includes(searchKeyword.toLowerCase())) ||
                (item.responsiblePerson && item.responsiblePerson.toLowerCase().includes(searchKeyword.toLowerCase())) ||
                (item.checkunit && item.checkunit.toLowerCase().includes(searchKeyword.toLowerCase()));
            
            let matchYear = true;
            if (yearFilter !== 'all') {
                const itemDate = getInspectionDate(item);
                matchYear = itemDate && itemDate.getFullYear().toString() === yearFilter;
            }
            
            let matchMonth = true;
            if (monthFilter !== 'all') {
                const itemDate = getInspectionDate(item);
                matchMonth = itemDate && String(itemDate.getMonth() + 1).padStart(2, '0') === monthFilter;
            }
            
            let matchPerson = true;
            if (personFilter !== 'all') {
                matchPerson = personValue && 
                    personValue.toLowerCase().includes(personFilter.toLowerCase());
            }
            
            return matchSearch && matchYear && matchMonth && matchPerson;
        });
        // 保持初始化时的排序顺序，不再重新排序
        console.log('✅ 中心及以上检查问题台账筛选完成，结果条数:', filteredCenterInspectionData.length);
        centerInspectionCurrentPage = 1;
    } else {
        filteredWorkshopInspectionData = workshopInspectionData.filter(item => {
            const personValue = item.responsible || '';
            const matchSearch = !searchKeyword || 
                (item.description && item.description.toLowerCase().includes(searchKeyword.toLowerCase())) ||
                (personValue && personValue.toLowerCase().includes(searchKeyword.toLowerCase())) ||
                (item.inspector && item.inspector.toLowerCase().includes(searchKeyword.toLowerCase())) ||
                (item.responsiblePerson && item.responsiblePerson.toLowerCase().includes(searchKeyword.toLowerCase())) ||
                (item.checkunit && item.checkunit.toLowerCase().includes(searchKeyword.toLowerCase()));
            
            let matchYear = true;
            if (yearFilter !== 'all') {
                const itemDate = getInspectionDate(item);
                matchYear = itemDate && itemDate.getFullYear().toString() === yearFilter;
            }
            
            let matchMonth = true;
            if (monthFilter !== 'all') {
                const itemDate = getInspectionDate(item);
                matchMonth = itemDate && String(itemDate.getMonth() + 1).padStart(2, '0') === monthFilter;
            }
            
            let matchPerson = true;
            if (personFilter !== 'all') {
                matchPerson = personValue && 
                    personValue.toLowerCase().includes(personFilter.toLowerCase());
            }
            
            return matchSearch && matchYear && matchMonth && matchPerson;
        });
        // 保持初始化时的排序顺序，不再重新排序
        console.log('✅ 作业区检查问题台账筛选完成，结果条数:', filteredWorkshopInspectionData.length);
        workshopInspectionCurrentPage = 1;
    }

    renderInspectionTable();
    renderInspectionPagination();
}

// 获取检查问题台账的日期
function getInspectionDate(item) {
    const dateStr = item.checktime || item.date;
    if (dateStr) {
        const parsedDate = new Date(dateStr);
        if (!isNaN(parsedDate.getTime())) {
            return parsedDate;
        }
    }
    return null;
}

// 检查问题台账按日期比较函数（倒序，时间晚的在前面）
function compareInspectionByDate(a, b) {
    const dateA = getInspectionDate(a);
    const dateB = getInspectionDate(b);
    
    if (!dateA && !dateB) return 0;
    if (!dateA) return 1;
    if (!dateB) return -1;
    
    return dateB.getTime() - dateA.getTime();
}

// 获取指定年份的所有月份
function getMonthsForYear(year) {
    const months = new Set(['all']);
    
    const allData = [...centerInspectionData, ...workshopInspectionData];
    
    allData.forEach(item => {
        const itemDate = getInspectionDate(item);
        if (itemDate && itemDate.getFullYear().toString() === year) {
            const month = String(itemDate.getMonth() + 1).padStart(2, '0');
            months.add(month);
        }
    });
    
    return Array.from(months).sort();
}

// 更新月份筛选器选项（联动年份）
function updateInspectionMonthFilter(year) {
    const monthFilter = document.getElementById('inspectionMonthFilter');
    if (!monthFilter) return;
    
    let months;
    if (year === 'all') {
        // 显示所有月份
        months = ['all', '01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11', '12'];
    } else {
        // 只显示该年份存在的月份
        months = getMonthsForYear(year);
    }
    
    monthFilter.innerHTML = '';
    for (const month of months) {
        const option = document.createElement('option');
        option.value = month;
        option.textContent = month === 'all' ? '全部月份' : month + '月';
        monthFilter.appendChild(option);
    }
    
    console.log('🔄 月份筛选器已更新，年份:', year, '月份:', months);
}

// 初始化检查问题台账年份筛选器
function initInspectionYearFilter() {
    const yearFilter = document.getElementById('inspectionYearFilter');
    if (!yearFilter) {
        console.log('❌ inspectionYearFilter 元素不存在');
        return;
    }
    
    console.log('🔄 初始化检查问题台账年份筛选器');
    console.log('📊 中心检查数据条数:', centerInspectionData.length);
    console.log('📊 作业区检查数据条数:', workshopInspectionData.length);
    
    const years = new Set(['all']);
    
    // 收集中心及以上检查问题台账的年份
    centerInspectionData.forEach(item => {
        const itemDate = getInspectionDate(item);
        if (itemDate) {
            years.add(itemDate.getFullYear().toString());
        }
    });
    
    // 收集作业区检查问题台账的年份
    workshopInspectionData.forEach(item => {
        const itemDate = getInspectionDate(item);
        if (itemDate) {
            years.add(itemDate.getFullYear().toString());
        }
    });
    
    // 只显示数据中实际存在的年份，不强制添加
    console.log('📅 收集到的年份:', Array.from(years));
    
    const sortedYears = Array.from(years).filter(y => y !== 'all').sort((a, b) => parseInt(b) - parseInt(a));
    
    yearFilter.innerHTML = '<option value="all">全部年份</option>';
    for (const year of sortedYears) {
        const option = document.createElement('option');
        option.value = year;
        option.textContent = year + '年';
        yearFilter.appendChild(option);
    }
    
    // 绑定年份变化事件，联动更新月份
    yearFilter.onchange = function() {
        updateInspectionMonthFilter(this.value);
        filterInspection();
    };
    
    // 初始化月份筛选器
    updateInspectionMonthFilter('all');
    
    console.log('✅ 检查问题台账年份筛选器初始化完成，共', sortedYears.length, '个年份');
    
    // 初始化责任人筛选器
    initInspectionPersonFilter();
}

// 初始化检查问题台账责任人筛选器
function initInspectionPersonFilter() {
    const personFilter = document.getElementById('inspectionPersonFilter');
    if (!personFilter) {
        console.log('❌ inspectionPersonFilter 元素不存在');
        return;
    }
    
    console.log('🔄 初始化检查问题台账责任人筛选器');
    
    // 从班组人员数据中获取所有人员
    const personnel = new Set();
    
    // 获取本地存储的班组人员数据
    const savedTeamPersonnel = localStorage.getItem('teamPersonnelData');
    let teamPersonnelData = currentTeamPersonnelData;
    
    if (savedTeamPersonnel) {
        try {
            teamPersonnelData = JSON.parse(savedTeamPersonnel);
        } catch (e) {
            console.log('解析班组人员数据失败，使用默认数据');
        }
    }
    
    // 遍历所有班组获取人员
    for (const team in teamPersonnelData) {
        if (Array.isArray(teamPersonnelData[team])) {
            teamPersonnelData[team].forEach(person => {
                if (person && person.trim()) {
                    personnel.add(person.trim());
                }
            });
        }
    }
    
    // 转换为排序后的数组
    const sortedPersonnel = Array.from(personnel).sort();
    
    console.log('👥 收集到的责任人:', sortedPersonnel);
    
    // 更新筛选器选项
    personFilter.innerHTML = '<option value="all">全部责任人</option>';
    for (const person of sortedPersonnel) {
        const option = document.createElement('option');
        option.value = person;
        option.textContent = person;
        personFilter.appendChild(option);
    }
    
    console.log('✅ 检查问题台账责任人筛选器初始化完成，共', sortedPersonnel.length, '个责任人');
}

// 清除检查问题台账搜索
function clearInspectionSearch() {
    document.getElementById('inspectionSearchInput').value = '';
    document.getElementById('inspectionPersonFilter').value = 'all';
    filterInspection();
}

// 加载中心及以上检查问题台账数据
function loadCenterInspectionData() {
    try {
        const saved = localStorage.getItem('centerInspectionData');
        if (saved) {
            centerInspectionData = JSON.parse(saved);
            console.log('从localStorage加载中心及以上检查问题台账数据，条数:', centerInspectionData.length);
        } else {
            centerInspectionData = [...mockCenterInspectionData];
            console.log('使用默认中心及以上检查问题台账数据');
            saveCenterInspectionData();
        }
    } catch (e) {
        console.error('加载中心及以上检查问题台账数据失败:', e);
        centerInspectionData = [...mockCenterInspectionData];
    }
}

// 加载作业区检查问题台账数据
function loadWorkshopInspectionData() {
    try {
        const saved = localStorage.getItem('workshopInspectionData');
        if (saved) {
            workshopInspectionData = JSON.parse(saved);
            console.log('从localStorage加载作业区检查问题台账数据，条数:', workshopInspectionData.length);
        } else {
            workshopInspectionData = [...mockWorkshopInspectionData];
            console.log('使用默认作业区检查问题台账数据');
            saveWorkshopInspectionData();
        }
    } catch (e) {
        console.error('加载作业区检查问题台账数据失败:', e);
        workshopInspectionData = [...mockWorkshopInspectionData];
    }
}

// 保存中心及以上检查问题台账数据
function saveCenterInspectionData() {
    // 按检查时间升序排序（时间早的在前）
    centerInspectionData.sort((a, b) => {
        const dateA = new Date(a.checktime || a.date || '');
        const dateB = new Date(b.checktime || b.date || '');
        return dateA.getTime() - dateB.getTime();
    });
    localStorage.setItem('centerInspectionData', JSON.stringify(centerInspectionData));

    // 自动同步到云端（仅在线时，使用新的批量增量同步）
    if (navigator.onLine && typeof window.syncInspectionDataIncrementally === 'function') {
        clearTimeout(window._inspectionSyncTimer);
        window._inspectionSyncTimer = setTimeout(async () => {
            console.log('[自动同步] 中心及以上检查问题台账（批量同步）');
            const result = await window.syncInspectionDataIncrementally(centerInspectionData, 'centerInspection');
            if (result && result.success) {
                console.log('[自动同步] 中心及以上检查问题台账同步成功');
            } else {
                console.warn('[自动同步] 中心及以上检查问题台账同步失败');
            }
        }, 500);
    }
}

function saveWorkshopInspectionData() {
    workshopInspectionData.sort((a, b) => {
        const dateA = new Date(a.checktime || a.date || '');
        const dateB = new Date(b.checktime || b.date || '');
        return dateA.getTime() - dateB.getTime();
    });
    localStorage.setItem('workshopInspectionData', JSON.stringify(workshopInspectionData));

    if (navigator.onLine && typeof window.syncInspectionDataIncrementally === 'function') {
        clearTimeout(window._workshopInspectionSyncTimer);
        window._workshopInspectionSyncTimer = setTimeout(async () => {
            console.log('[自动同步] 作业区检查问题台账（批量同步）');
            const result = await window.syncInspectionDataIncrementally(workshopInspectionData, 'workshopInspection');
            if (result && result.success) {
                console.log('[自动同步] 作业区检查问题台账同步成功');
            } else {
                console.warn('[自动同步] 作业区检查问题台账同步失败');
            }
        }, 500);
    }
}

