function initColumnResizing() {
    const table = document.getElementById('inspectionTable');
    if (!table) return;
    
    const thead = table.querySelector('thead tr');
    if (!thead) return;
    
    const thElements = thead.querySelectorAll('th');
    thElements.forEach((th, index) => {
        if (index === thElements.length - 1) return;
        
        const handle = document.createElement('div');
        handle.className = 'resize-handle';
        th.appendChild(handle);
        
        handle.addEventListener('mousedown', (e) => {
            e.preventDefault();
            startColumnResize(e, th, index);
        });
    });
}

function startColumnResize(e, th, columnIndex) {
    const table = document.getElementById('inspectionTable');
    const startX = e.clientX;
    const startWidth = th.offsetWidth;
    
    const handleMouseMove = (e) => {
        const deltaX = e.clientX - startX;
        const newWidth = Math.max(60, startWidth + deltaX);
        
        th.style.width = newWidth + 'px';
        
        const tbodyRows = table.querySelectorAll('tbody tr');
        tbodyRows.forEach(row => {
            const td = row.querySelectorAll('td')[columnIndex];
            if (td) {
                td.style.width = newWidth + 'px';
            }
        });
    };
    
    const handleMouseUp = () => {
        document.removeEventListener('mousemove', handleMouseMove);
        document.removeEventListener('mouseup', handleMouseUp);
    };
    
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
}

function switchInspectionPage(pageType) {
    currentInspectionPage = pageType;
    console.log('切换到检查问题台账页面:', pageType);
    
    const centerBtn = document.getElementById('centerInspectionBtn');
    const workshopBtn = document.getElementById('workshopInspectionBtn');
    
    if (centerBtn && workshopBtn) {
        centerBtn.classList.toggle('active', pageType === 'center');
        workshopBtn.classList.toggle('active', pageType === 'workshop');
    }
    
    // 清除筛选
    document.getElementById('inspectionYearFilter').value = 'all';
    document.getElementById('inspectionMonthFilter').value = 'all';
    document.getElementById('inspectionPersonFilter').value = 'all';
    document.getElementById('inspectionSearchInput').value = '';
    document.getElementById('inspectionSearchClearBtn').style.display = 'none';
    
    // 重置筛选数据并按检查时间倒序排序（时间晚的在前面）
    if (pageType === 'center') {
        filteredCenterInspectionData = [...centerInspectionData].sort(compareInspectionByDate);
        centerInspectionCurrentPage = 1;
    } else {
        filteredWorkshopInspectionData = [...workshopInspectionData].sort(compareInspectionByDate);
        workshopInspectionCurrentPage = 1;
    }
    
    renderInspectionTable();
    renderInspectionPagination();
}



function renderInspectionTable() {
    const tableHead = document.getElementById('inspectionTableHead');
    const tableBody = document.getElementById('inspectionTableBody');
    
    // 获取当前页面的数据和页码
    const inspectionData = getCurrentInspectionData();
    const inspectionCurrentPage = getCurrentInspectionCurrentPage();
    const inspectionSelectedIds = getCurrentInspectionSelectedIds();
    
    // 获取当前用户角色（用于控制编辑删除权限）
    const currentRole = getCurrentRole();
    const canEdit = currentRole === 'topadmin' || currentRole === 'manager'; // 主任和管理人员可以编辑和删除
    
    const startIndex = (inspectionCurrentPage - 1) * inspectionPageSize;
    const endIndex = startIndex + inspectionPageSize;
    const currentData = inspectionData.slice(startIndex, endIndex);
    
    // 检查当前页是否全部选中
    const currentPageIds = new Set(currentData.map(item => item.id));
    const selectedIdsSet = new Set(inspectionSelectedIds);
    const allSelected = currentData.length > 0 && currentPageIds.size > 0 && 
                        [...currentPageIds].every(id => selectedIdsSet.has(id));

    // 渲染表头
    const unitLabel = currentInspectionPage === 'center' ? '检查单位' : '责任单位';
    const inspectionHeaders = ['责任人', unitLabel, '检查时间', '问题', '整改期限', '整改措施', '类别', '整改负责人', '检查人', '整改情况'];
    
    // 当用户没有编辑权限时（普通用户和班长），不渲染复选框列
    const checkboxColumn = canEdit ? '<th style="min-width: 40px;"><input type="checkbox" id="inspectionSelectAll" ' + (allSelected ? 'checked' : '') + ' onchange="toggleAllInspectionSelection(this.checked)" style="width: 20px; height: 20px; cursor: pointer;"></th>' : '';
    tableHead.innerHTML = `
        <tr>
            ${checkboxColumn}
            <th style="min-width: 50px;">序号</th>
            ${inspectionHeaders.map((header, index) => `
                <th data-col="${index}">
                    <span>${header}</span>
                    <span class="resize-handle" onmousedown="startInspectionColumnResize(event, ${index})"></span>
                </th>
            `).join('')}
            ${canEdit ? '<th style="min-width: 100px;">操作</th>' : ''}
        </tr>
    `;

    tableBody.innerHTML = '';

    if (currentData.length === 0) {
        const colCount = canEdit ? 13 : 11; // 没有编辑权限时少两列（复选框列和操作列）
        tableBody.innerHTML = `<tr><td colspan="${colCount}" style="text-align:center;">暂无数据</td></tr>`;
        return;
    }

    currentData.forEach((item, index) => {
        const row = document.createElement('tr');
        const statusClass = item.status === '已完成' ? 'status-completed' : 
                            item.status === '整改中' ? 'status-in-progress' : 'status-pending';
        const isChecked = inspectionSelectedIds.includes(item.id);
        const category = item.inspectioncategory || item.category || '综合类';
        const categoryClass = category === '综合类' ? 'category-comprehensive' :
                              category === '安全类' ? 'category-safety' :
                              category === '环保类' ? 'category-environmental' :
                              category === '生产类' ? 'category-production' :
                              category === '设备类' ? 'category-equipment' :
                              category === '培训类' ? 'category-training' :
                              'category-other';
        
        const actionCell = canEdit ? `
            <td class="action-cell">
                <button class="btn btn-edit" onclick="editInspection('${item.id}')">编辑</button>
                <button class="btn btn-delete" onclick="deleteInspection('${item.id}')">删除</button>
            </td>
        ` : '';
        
        // 当用户没有编辑权限时，不渲染复选框列
        const checkboxCell = canEdit ? `
            <td>
                <input type="checkbox" ${isChecked ? 'checked' : ''} 
                       onchange="toggleInspectionSelection('${item.id}', this.checked)"
                       style="width: 20px; height: 20px; cursor: pointer;">
            </td>
        ` : '';
        
        row.innerHTML = `
            ${checkboxCell}
            <td>${startIndex + index + 1}</td>
            <td>${item.responsible || ''}</td>
            <td>${item.checkunit || ''}</td>
            <td>${formatDeadlineDate(item.checktime) || ''}</td>
            <td>${item.description || ''}</td>
            <td>${formatDeadlineDate(item.deadline) || ''}</td>
            <td>${item.measures || ''}</td>
            <td><span class="category-badge ${categoryClass}">${category}</span></td>
            <td>${item.responsiblePerson || item.responsibleperson || ''}</td>
            <td>${item.inspector || ''}</td>
            <td><span class="status-badge ${statusClass}">${item.status}</span></td>
            ${actionCell}
        `;
        tableBody.appendChild(row);
    });
    
    setupInspectionTableHeaderFreeze();
    
    // 表格渲染完成后，自动调整列宽
    setTimeout(() => {
        if (typeof autoAdjustTableColumnWidths === 'function') {
            autoAdjustTableColumnWidths('inspectionTable');
        }
    }, 100);
}

function renderInspectionPagination() {
    const pagination = document.getElementById('inspectionPagination');
    const inspectionData = getCurrentInspectionData();
    const inspectionCurrentPage = getCurrentInspectionCurrentPage();
    const totalPages = Math.ceil(inspectionData.length / inspectionPageSize);
    
    // 保存总页数
    if (currentInspectionPage === 'center') {
        centerInspectionTotalPages = totalPages;
    } else {
        workshopInspectionTotalPages = totalPages;
    }

    if (totalPages <= 1) {
        pagination.innerHTML = '';
        return;
    }

    let html = `
        <button onclick="changeInspectionPage(${inspectionCurrentPage - 1})" ${inspectionCurrentPage === 1 ? 'disabled' : ''}>上一页</button>
    `;

    for (let i = 1; i <= totalPages; i++) {
        html += `
            <button onclick="changeInspectionPage(${i})" ${inspectionCurrentPage === i ? 'class="active"' : ''}>${i}</button>
        `;
    }

    html += `
        <button onclick="changeInspectionPage(${inspectionCurrentPage + 1})" ${inspectionCurrentPage === totalPages ? 'disabled' : ''}>下一页</button>
    `;

    pagination.innerHTML = html;
}

function changeInspectionPage(page) {
    const totalPages = currentInspectionPage === 'center' ? centerInspectionTotalPages : workshopInspectionTotalPages;
    if (page < 1 || page > totalPages) return;
    
    if (currentInspectionPage === 'center') {
        centerInspectionCurrentPage = page;
    } else {
        workshopInspectionCurrentPage = page;
    }
    renderInspectionTable();
    renderInspectionPagination();
}

