function toggleAllInspectionSelection(checked) {
    const inspectionData = getCurrentInspectionData();
    const inspectionCurrentPage = getCurrentInspectionCurrentPage();
    let inspectionSelectedIds = getCurrentInspectionSelectedIds();
    
    // 计算当前页的数据范围
    const startIndex = (inspectionCurrentPage - 1) * inspectionPageSize;
    const endIndex = startIndex + inspectionPageSize;
    const currentPageData = inspectionData.slice(startIndex, endIndex);
    
    if (checked) {
        // 全选当前页的数据
        const currentPageIds = currentPageData.map(item => item.id);
        inspectionSelectedIds = [...new Set([...inspectionSelectedIds, ...currentPageIds])];
    } else {
        // 取消当前页的选中状态
        const currentPageIds = new Set(currentPageData.map(item => item.id));
        inspectionSelectedIds = inspectionSelectedIds.filter(id => !currentPageIds.has(id));
    }
    
    setCurrentInspectionSelectedIds(inspectionSelectedIds);
    updateInspectionExportButton();
    renderInspectionTable();
}

function toggleInspectionSelection(id, checked) {
    let inspectionSelectedIds = getCurrentInspectionSelectedIds();
    
    const index = inspectionSelectedIds.indexOf(id);
    if (checked && index === -1) {
        inspectionSelectedIds.push(id);
    } else if (!checked && index !== -1) {
        inspectionSelectedIds.splice(index, 1);
    }
    
    setCurrentInspectionSelectedIds(inspectionSelectedIds);
    updateInspectionExportButton();
}

function updateInspectionExportButton() {
    const exportBtn = document.getElementById('inspectionExportSelectedBtn');
    const deleteBtn = document.getElementById('inspectionDeleteSelectedBtn');
    const inspectionSelectedIds = getCurrentInspectionSelectedIds();
    const hasSelection = inspectionSelectedIds.length > 0;
    
    // 获取当前用户角色，主任和管理人员可以删除
    const currentRole = getCurrentRole();
    const canDelete = currentRole === 'topadmin' || currentRole === 'manager';
    
    if (exportBtn) {
        exportBtn.disabled = !hasSelection;
        exportBtn.style.display = hasSelection ? 'inline-block' : 'none';
        exportBtn.innerHTML = `<span class="btn-icon">📥</span> 导出选中 (${inspectionSelectedIds.length})`;
    }
    
    if (deleteBtn) {
        // 只有主任可以看到删除按钮
        if (!canDelete) {
            deleteBtn.style.display = 'none';
            return;
        }
        deleteBtn.disabled = !hasSelection;
        deleteBtn.style.display = hasSelection ? 'inline-block' : 'none';
        deleteBtn.innerHTML = `<span class="btn-icon">🗑️</span> 删除选中 (${inspectionSelectedIds.length})`;
    }
}

// 删除选中的检查问题台账数据
function deleteSelectedInspection() {
    const inspectionSelectedIds = getCurrentInspectionSelectedIds();
    
    if (inspectionSelectedIds.length === 0) {
        alert('请先选择要删除的记录');
        return;
    }
    
    const confirmDelete = confirm(`确定要删除选中的 ${inspectionSelectedIds.length} 条记录吗？\n\n此操作不可恢复，请谨慎操作！`);
    
    if (!confirmDelete) {
        return;
    }
    
    try {
        const currentPageData = currentInspectionPage === 'center' ? centerInspectionData : workshopInspectionData;
        const pageName = currentInspectionPage === 'center' ? '中心及以上检查问题台账' : '作业区检查问题台账';
        const moduleKey = currentInspectionPage === 'center' ? 'centerInspection' : 'workshopInspection';
        
        // 筛选出未被选中的记录
        const remainingData = currentPageData.filter(item => !inspectionSelectedIds.includes(item.id));
        
        // 更新数据
        if (currentInspectionPage === 'center') {
            centerInspectionData = remainingData;
            filteredCenterInspectionData = [...centerInspectionData];
            saveCenterInspectionData();
        } else {
            workshopInspectionData = remainingData;
            filteredWorkshopInspectionData = [...workshopInspectionData];
            saveWorkshopInspectionData();
        }
        
        // 更新年份筛选器
        initInspectionYearFilter();
        
        // 清空选中状态
        setCurrentInspectionSelectedIds([]);
        
        // 记录审计日志
        if (typeof recordAuditLog === 'function') {
            recordAuditLog({
                module: 'inspection',
                action: 'batchDelete',
                targetId: 'multiple',
                targetDesc: `批量删除 ${inspectionSelectedIds.length} 条检查问题`,
                changes: null
            });
        }
        
        // 将每个删除操作添加到离线队列进行自动同步
        if (window.OfflineQueue) {
            inspectionSelectedIds.forEach(id => {
                window.OfflineQueue.add({
                    module: moduleKey,
                    type: 'delete',
                    recordId: String(id),
                    data: null
                });
            });
        }
        
        // 重新设置筛选数据为全部数据（不触发排序）
        if (currentInspectionPage === 'center') {
            filteredCenterInspectionData = [...centerInspectionData];
            centerInspectionCurrentPage = 1;
        } else {
            filteredWorkshopInspectionData = [...workshopInspectionData];
            workshopInspectionCurrentPage = 1;
        }
        
        // 重置筛选器显示（不触发onchange事件）
        const yearFilter = document.getElementById('inspectionYearFilter');
        const monthFilter = document.getElementById('inspectionMonthFilter');
        const personFilter = document.getElementById('inspectionPersonFilter');
        const searchInput = document.getElementById('inspectionSearchInput');
        const searchClearBtn = document.getElementById('inspectionSearchClearBtn');
        
        if (yearFilter) yearFilter.selectedIndex = 0;
        if (monthFilter) monthFilter.selectedIndex = 0;
        if (personFilter) personFilter.selectedIndex = 0;
        if (searchInput) searchInput.value = '';
        if (searchClearBtn) searchClearBtn.style.display = 'none';
        
        // 重新渲染表格
        renderInspectionTable();
        renderInspectionPagination();
        updateInspectionExportButton();
        
        alert(`✅ 成功删除 ${inspectionSelectedIds.length} 条记录！\n\n正在自动同步到云端...`);
        console.log(`删除了 ${inspectionSelectedIds.length} 条 ${pageName} 数据`);
    } catch (error) {
        console.error('删除选中记录失败:', error);
        alert('❌ 删除失败: ' + error.message);
    }
}

async function exportSelectedInspectionToExcel() {
    const inspectionSelectedIds = getCurrentInspectionSelectedIds();
    
    if (inspectionSelectedIds.length === 0) {
        alert('请先选择要导出的记录');
        return;
    }
    
    const inspectionData = getCurrentInspectionData();
    const selectedData = inspectionData.filter(item => inspectionSelectedIds.includes(item.id));
    
    if (selectedData.length === 0) {
        alert('未找到选中的记录');
        return;
    }
    
    const headers = ['序号', '责任单位', '检查单位', '检查时间', '问题描述', '整改期限', '整改措施', '类别', '整改负责人', '检查人', '整改情况'];
    
    const dataToExport = selectedData.map((item, index) => [
        index + 1,
        item.unit || '',
        item.checkunit || item.unit || '',
        item.checktime || '',
        item.description || '',
        item.deadline || '',
        item.measures || '',
        item.category || item.inspectioncategory || '综合类',
        item.responsible || '',
        item.inspector || '',
        item.status || ''
    ]);
    
    const sheetName = currentInspectionPage === 'center' ? '中心及以上检查问题台账' : '作业区检查问题台账';
    const fileName = (currentInspectionPage === 'center' ? '中心及以上' : '作业区') + '检查问题台账_选中_' + new Date().toLocaleDateString('zh-CN').replace(/\//g, '-') + '.xlsx';
    
    await exportToExcelWithStyle(dataToExport, headers, sheetName, fileName);
    
    setCurrentInspectionSelectedIds([]);
    updateInspectionExportButton();
    renderInspectionTable();
    
    alert(`已成功导出 ${selectedData.length} 条记录！`);
}



function getTeamPersonnelList() {
    const personnel = new Set();
    
    const savedTeamPersonnel = localStorage.getItem('teamPersonnelData');
    let teamPersonnelData = currentTeamPersonnelData;
    
    if (savedTeamPersonnel) {
        try {
            teamPersonnelData = JSON.parse(savedTeamPersonnel);
        } catch (e) {
            console.log('解析班组人员数据失败，使用默认数据');
        }
    }
    
    for (const team in teamPersonnelData) {
        if (Array.isArray(teamPersonnelData[team])) {
            teamPersonnelData[team].forEach(person => {
                if (person && person.trim()) {
                    personnel.add(person.trim());
                }
            });
        }
    }
    
    return Array.from(personnel).sort();
}

function populateInspectionPersonnelDropdowns() {
    const responsibleInput = document.getElementById('inspectionResponsible');
    const responsibleList = document.getElementById('inspectionResponsibleList');
    const responsiblePersonSelect = document.getElementById('inspectionResponsiblePerson');
    
    if (!responsibleInput || !responsiblePersonSelect) {
        return;
    }
    
    const personnelList = getTeamPersonnelList();
    
    // 填充责任人的 datalist
    if (responsibleList) {
        let optionsHtml = '';
        for (const person of personnelList) {
            optionsHtml += `<option value="${person}">${person}</option>`;
        }
        responsibleList.innerHTML = optionsHtml;
    }
    
    // 填充整改负责人的 select
    let optionsHtml = '<option value="">请选择</option>';
    for (const person of personnelList) {
        optionsHtml += `<option value="${person}">${person}</option>`;
    }
    
    responsiblePersonSelect.innerHTML = optionsHtml;
}

