async function saveInspectionForm() {
    const checkunit = document.getElementById('inspectionCheckUnit').value;
    const date = document.getElementById('inspectionDate').value;
    const deadline = document.getElementById('inspectionDeadline').value;
    const description = document.getElementById('inspectionDescription').value;
    const inspector = document.getElementById('inspectionPerson').value;
    const status = document.getElementById('inspectionStatus').value;
    const responsible = document.getElementById('inspectionResponsible').value;
    const responsiblePerson = document.getElementById('inspectionResponsiblePerson').value || '';
    const measures = document.getElementById('inspectionMeasures').value;
    const inspectioncategory = document.getElementById('inspectionCategory').value || '';

    if (!date) {
        alert('请选择检查时间');
        return;
    }
    if (!description) {
        alert('请输入问题描述');
        return;
    }

    // 不需要设置category来区分页面，数据本身就是分开存储的
    let success = false;

    const editingId = getCurrentEditingId();
    let oldItem = null;
    let changes = null;

    // 如果是编辑操作，先保存旧数据用于记录变更
    if (editingId) {
        const inspectionData = getCurrentInspectionData();
        oldItem = inspectionData.find(x => x.id === editingId);
        
        if (oldItem) {
            // 计算变更详情
            changes = {};
            const fieldMap = {
                'checkunit': checkunit,
                'checktime': date,
                'deadline': deadline,
                'description': description,
                'inspector': inspector,
                'status': status,
                'responsible': responsible,
                'responsiblePerson': responsiblePerson,
                'measures': measures,
                'inspectioncategory': inspectioncategory
            };
            
            Object.keys(fieldMap).forEach(field => {
                const oldValue = oldItem[field] || '';
                const newValue = fieldMap[field] || '';
                if (oldValue !== newValue) {
                    changes[field] = { old: oldValue, new: newValue };
                }
            });
            
            if (Object.keys(changes).length === 0) {
                changes = null;
            }
        }
    }

    const now = new Date().toISOString();
    
    const newInspectionItem = {
        checkunit,
        checktime: date,
        deadline,
        description,
        inspector,
        status,
        responsible,
        responsiblePerson,
        measures,
        inspectioncategory,
        updated_at: now
    };

    // 直接保存到本地
    let savedId = editingId;
    if (currentInspectionPage === 'center') {
        if (editingId) {
            const index = centerInspectionData.findIndex(x => x.id === editingId);
            if (index !== -1) {
                centerInspectionData[index] = {
                    ...centerInspectionData[index],
                    ...newInspectionItem,
                    updated_at: now
                };
            }
        } else {
            savedId = generateUUID();
            centerInspectionData.push({
                id: savedId,
                ...newInspectionItem,
                created_at: now,
                updated_at: now
            });
        }
        saveCenterInspectionData();
    } else {
        if (editingId) {
            const index = workshopInspectionData.findIndex(x => x.id === editingId);
            if (index !== -1) {
                workshopInspectionData[index] = {
                    ...workshopInspectionData[index],
                    ...newInspectionItem,
                    updated_at: now
                };
            }
        } else {
            savedId = generateUUID();
            workshopInspectionData.push({
                id: savedId,
                ...newInspectionItem,
                created_at: now,
                updated_at: now
            });
        }
        saveWorkshopInspectionData();
    }
    
    // 添加到离线队列进行自动同步（增量同步）
    if (window.OfflineQueue) {
        const data = currentInspectionPage === 'center' 
            ? centerInspectionData.find(x => x.id === savedId)
            : workshopInspectionData.find(x => x.id === savedId);
            
        if (data) {
            const moduleKey = currentInspectionPage === 'center' ? 'centerInspection' : 'workshopInspection';
            window.OfflineQueue.add({
                module: moduleKey,
                type: editingId ? 'update' : 'create',
                recordId: String(savedId),
                data: data
            });
        }
    }
    
    success = true;

    if (success) {
        // 更新筛选数据并按检查时间倒序排序（时间晚的在前面）
        if (currentInspectionPage === 'center') {
            filteredCenterInspectionData = [...centerInspectionData].sort(compareInspectionByDate);
        } else {
            filteredWorkshopInspectionData = [...workshopInspectionData].sort(compareInspectionByDate);
        }
        
        // 更新年份筛选器
        initInspectionYearFilter();
        
        // 记录审计日志
        if (typeof recordAuditLog === 'function') {
            const action = editingId ? 'update' : 'create';
            const targetId = editingId || newInspectionItem.id || 'new';
            const actionText = editingId ? '修改' : '新增';
            recordAuditLog({
                module: 'inspection',
                action: action,
                targetId: targetId,
                targetDesc: `${actionText}检查问题: ${description.substring(0, 30)}`,
                changes: changes
            });
        }
        
        // 重置筛选并刷新
        document.getElementById('inspectionYearFilter').value = 'all';
        document.getElementById('inspectionMonthFilter').value = 'all';
        document.getElementById('inspectionPersonFilter').value = 'all';
        document.getElementById('inspectionSearchInput').value = '';
        document.getElementById('inspectionSearchClearBtn').style.display = 'none';
        
        renderInspectionTable();
        renderInspectionPagination();
        
        closeAddInspectionModal();
        alert(editingInspectionId ? '修改成功！数据已保存到本地，点击"保存到云端"按钮上传到数据库。' : '添加成功！数据已保存到本地，点击"保存到云端"按钮上传到数据库。');
    } else {
        alert(editingInspectionId ? '修改失败！' : '添加失败！');
    }
}

function editInspection(id) {
    // 从当前页面的数据中查找
    const inspectionData = getCurrentInspectionData();
    const item = inspectionData.find(x => x.id === id);
    
    if (item) {
        setCurrentEditingId(id);
        const modalTitle = safeGetElement('addInspectionModalTitle');
        if (modalTitle) modalTitle.textContent = '编辑检查问题';
        
        // 先填充责任人和整改负责人下拉列表
        populateInspectionPersonnelDropdowns();
        
        const checkunit = safeGetElement('inspectionCheckUnit');
        if (checkunit) checkunit.value = item.checkunit || '';
        const date = safeGetElement('inspectionDate');
        if (date) date.value = item.checktime || '';
        const deadline = safeGetElement('inspectionDeadline');
        if (deadline) deadline.value = item.deadline || '';
        const description = safeGetElement('inspectionDescription');
        if (description) description.value = item.description || '';
        const inspector = safeGetElement('inspectionPerson');
        if (inspector) inspector.value = item.inspector || '';
        const status = safeGetElement('inspectionStatus');
        if (status) status.value = item.status || '待整改';
        const responsible = safeGetElement('inspectionResponsible');
        if (responsible) responsible.value = item.responsible || '';
        const responsiblePerson = safeGetElement('inspectionResponsiblePerson');
        if (responsiblePerson) responsiblePerson.value = item.responsiblePerson || item.responsibleperson || '';
        const measures = safeGetElement('inspectionMeasures');
        if (measures) measures.value = item.measures || '';
        const inspectioncategory = safeGetElement('inspectionCategory');
        if (inspectioncategory) inspectioncategory.value = item.inspectioncategory || '综合类';
        safeSetDisplay('addInspectionModal', 'block');
    }
}

async function deleteInspection(id) {
    if (!confirm('确定要删除该检查问题记录吗？')) {
        return;
    }
    
    try {
        // 获取要删除的记录信息用于审计
        const inspectionData = getCurrentInspectionData();
        const item = inspectionData.find(x => x.id === id);
        
        // 直接删除本地数据
        if (currentInspectionPage === 'center') {
            centerInspectionData = centerInspectionData.filter(item => item.id !== id);
            filteredCenterInspectionData = [...centerInspectionData];
            if (centerInspectionCurrentPage > Math.ceil(centerInspectionData.length / inspectionPageSize) && centerInspectionCurrentPage > 1) {
                centerInspectionCurrentPage--;
            }
            saveCenterInspectionData();
        } else {
            workshopInspectionData = workshopInspectionData.filter(item => item.id !== id);
            filteredWorkshopInspectionData = [...workshopInspectionData];
            if (workshopInspectionCurrentPage > Math.ceil(workshopInspectionData.length / inspectionPageSize) && workshopInspectionCurrentPage > 1) {
                workshopInspectionCurrentPage--;
            }
            saveWorkshopInspectionData();
        }
        
        // 更新年份筛选器
        initInspectionYearFilter();
        
        // 记录审计日志
        if (typeof recordAuditLog === 'function') {
            recordAuditLog({
                module: 'inspection',
                action: 'delete',
                targetId: id,
                targetDesc: `删除检查问题: ${item?.description || '未知描述'}`.substring(0, 50),
                changes: null
            });
        }
        
        // 重置筛选器显示（不触发onchange事件）
        const yearFilter = document.getElementById('inspectionYearFilter');
        const monthFilter = document.getElementById('inspectionMonthFilter');
        const personFilter = document.getElementById('inspectionPersonFilter');
        const searchInput = document.getElementById('inspectionSearchInput');
        const searchClearBtn = document.getElementById('inspectionSearchClearBtn');
        
        if (yearFilter) yearFilter.selectedIndex = 0;
        if (monthFilter) monthFilter.selectedIndex = 0;
        if (personFilter) personFilter.selectedIndex = 0;
        if (searchInput) searchInput.value = '';
        if (searchClearBtn) searchClearBtn.style.display = 'none';
        
        renderInspectionTable();
        renderInspectionPagination();
        
        // 添加到离线队列进行自动同步删除
        if (window.OfflineQueue) {
            const moduleKey = currentInspectionPage === 'center' ? 'centerInspection' : 'workshopInspection';
            window.OfflineQueue.add({
                module: moduleKey,
                type: 'delete',
                recordId: String(id),
                data: null
            });
        }
        
        alert('删除成功！数据已保存到本地，正在自动同步到云端...');
    } catch (error) {
        console.error('删除检查问题记录失败:', error);
        alert(`删除失败: ${error.message}`);
    }
}

