// 计算年龄
function parseDate(dateStr) {
    if (!dateStr) return null;
    if (typeof dateStr !== 'string') {
        dateStr = String(dateStr);
    }
    
    let date = new Date(dateStr);
    if (!isNaN(date.getTime())) {
        return date;
    }
    
    const formats = [
        /^(\d{4})[年\-\/](\d{1,2})[月\-\/](\d{1,2})日?$/,
        /^(\d{4})[年\-\/](\d{1,2})[月\-\/]$/,
        /^(\d{4})[年\-\/](\d{1,2})$/
    ];
    
    for (const format of formats) {
        const match = dateStr.match(format);
        if (match) {
            const year = parseInt(match[1]);
            const month = parseInt(match[2]) - 1;
            const day = match[3] ? parseInt(match[3]) : 1;
            date = new Date(year, month, day);
            if (!isNaN(date.getTime())) {
                return date;
            }
        }
    }
    
    const slashParts = dateStr.split('/');
    if (slashParts.length === 3) {
        let year = parseInt(slashParts[0]);
        const month = parseInt(slashParts[1]) - 1;
        const day = parseInt(slashParts[2]);
        if (year < 100) year += 1900;
        date = new Date(year, month, day);
        if (!isNaN(date.getTime())) {
            return date;
        }
    }
    
    const dashParts = dateStr.split('-');
    if (dashParts.length === 3) {
        let year = parseInt(dashParts[0]);
        const month = parseInt(dashParts[1]) - 1;
        const day = parseInt(dashParts[2]);
        if (year < 100) year += 1900;
        date = new Date(year, month, day);
        if (!isNaN(date.getTime())) {
            return date;
        }
    }
    
    return null;
}

function calculateAge(birthDate) {
    if (!birthDate) return '';
    
    const birth = parseDate(birthDate);
    if (!birth) return '';
    
    const today = new Date();
    let age = today.getFullYear() - birth.getFullYear();
    const monthDiff = today.getMonth() - birth.getMonth();
    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) {
        age--;
    }
    
    if (age < 0 || age > 150) return '';
    return age;
}

// 格式化日期
function formatDate(dateValue) {
    if (!dateValue) return '';
    
    let date;
    if (dateValue instanceof Date) {
        date = dateValue;
    } else if (typeof dateValue === 'string') {
        date = new Date(dateValue);
        if (isNaN(date.getTime())) {
            // 尝试解析常见的日期格式
            date = parseDateString(dateValue);
        }
    } else {
        return String(dateValue);
    }
    
    if (isNaN(date.getTime())) {
        return String(dateValue);
    }
    
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    
    return `${year}-${month}-${day}`;
}

// 格式化整改期限日期（兼容各种格式，包括文字描述）
function formatDeadlineDate(dateValue) {
    if (!dateValue) return '';
    
    // 如果是数字，可能是Excel日期序列号
    if (typeof dateValue === 'number') {
        // Excel日期序列号转换为JavaScript日期
        // Excel使用1900年1月1日作为基准（Windows）
        const jsDate = new Date((dateValue - 25569) * 86400000);
        if (!isNaN(jsDate.getTime())) {
            const year = jsDate.getFullYear();
            const month = String(jsDate.getMonth() + 1).padStart(2, '0');
            const day = String(jsDate.getDate()).padStart(2, '0');
            return `${year}-${month}-${day}`;
        }
        return '';
    }
    
    // 如果已经是 xxxx-xx-xx 格式，直接返回
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateValue)) {
        return dateValue;
    }
    
    // 如果是其他格式，尝试使用 formatDate 格式化
    const formatted = formatDate(dateValue);
    
    // 如果格式化结果仍然是原始值，说明无法解析（如"近期完成"等文字），保留原始值
    if (formatted === String(dateValue) || formatted === '') {
        return String(dateValue);
    }
    
    return formatted;
}

function formatDateForSupabase(dateStr) {
    if (!dateStr) return null;
    
    // 如果已经是 xxxx-xx-xx 格式，直接返回
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
        return dateStr;
    }
    
    // 尝试解析日期
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) {
        return null;
    }
    
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

function parseDateString(dateStr) {
    const formats = [
        { pattern: /^(\d{4})[\-/](\d{1,2})[\-/](\d{1,2})$/, yearIndex: 1, monthIndex: 2, dayIndex: 3 },
        { pattern: /^(\d{4})年(\d{1,2})月(\d{1,2})日?$/, yearIndex: 1, monthIndex: 2, dayIndex: 3 },
        { pattern: /^(\d{2})[\-/](\d{1,2})[\-/](\d{4})$/, yearIndex: 3, monthIndex: 2, dayIndex: 1 },
        { pattern: /^(\d{1,2})月(\d{1,2})日?$/, yearIndex: 0, monthIndex: 1, dayIndex: 2 }  // 缺少年份
    ];
    
    for (const format of formats) {
        const match = dateStr.match(format.pattern);
        if (match) {
            let year, month, day;
            
            if (format.yearIndex === 0) {
                // 缺少年份，使用当前年份
                year = new Date().getFullYear();
                month = parseInt(match[format.monthIndex]) - 1;
                day = parseInt(match[format.dayIndex]);
            } else {
                year = parseInt(match[format.yearIndex]);
                month = parseInt(match[format.monthIndex]) - 1;
                day = parseInt(match[format.dayIndex]);
                
                if (year < 100) year += 2000;
            }
            
            const date = new Date(year, month, day);
            if (!isNaN(date.getTime())) {
                return date;
            }
        }
    }
    
    return new Date(NaN);
}

// 计算综合成绩
function calculateTotalScore(theory, practical) {
    if (theory === null || theory === undefined || theory === '' || practical === null || practical === undefined || practical === '') return '-';
    return theory;
}

// 判断是否合格
function isQualified(totalScore) {
    if (!totalScore || totalScore === '-') return '-';
    return totalScore >= 60 ? '合格' : '不合格';
}

