// 保存人员数据到localStorage
function savePersonnelData() {
    try {
        localStorage.setItem('personnelData', JSON.stringify(allPersonnelData));
        console.log('人员数据已保存，当前数据条数:', allPersonnelData.length);
    } catch (e) {
        console.error('保存人员数据失败:', e);
    }
}

// 加载人员数据从localStorage
function loadPersonnelData() {
    try {
        const saved = localStorage.getItem('personnelData');
        if (saved) {
            const data = JSON.parse(saved);
            // 确保数据是数组
            if (!Array.isArray(data)) {
                console.warn('人员数据格式不正确，使用默认数据');
                return [...mockPersonnelData];
            }
            
            // 过滤无效数据（空对象或缺少必要字段的记录）
            const validData = data.filter(item => item && item.id && item.name);
            
            // 强制去重：按人员编号去重，相同编号只保留一条
            const uniqueData = deduplicatePersonnelData(validData);
            
            console.log('从localStorage加载人员数据，有效条数:', validData.length, '去重后条数:', uniqueData.length);
            
            // 如果去重后数据减少，说明有重复，需要重新保存
            if (uniqueData.length < validData.length) {
                localStorage.setItem('personnelData', JSON.stringify(uniqueData));
                console.log('发现重复数据，已自动清理');
            }
            
            return uniqueData.length > 0 ? uniqueData : [...mockPersonnelData];
        }
        console.log('localStorage中没有数据，使用默认数据');
    } catch (e) {
        console.error('加载人员数据失败:', e);
    }
    return [...mockPersonnelData];
}

function deduplicatePersonnelData(data) {
    const idMap = new Map();
    
    data.forEach(item => {
        // 获取人员编号
        const key = item.personnelId || item.idCardNumber || item.id || item['人员编号'] || item.身份证号码 || item.idNumber || item.employeeId;
        
        if (!key) {
            // 没有编号的数据保留
            return;
        }
        
        const keyStr = String(key).trim();
        if (!keyStr || keyStr === 'undefined' || keyStr === 'null') {
            return;
        }
        
        if (!idMap.has(keyStr)) {
            idMap.set(keyStr, item);
        }
    });
    
    return Array.from(idMap.values());
}

// ==================== 模块级云端同步辅助函数 ====================

/**
 * 从云端同步单个模块数据到本地
 * @param {string} moduleKey - 模块键名 (如 'personnel', 'training' 等)
 * @param {string} storageKey - localStorage 存储键名
 * @param {string} arrayRef - 全局数组引用变量名
 * @param {boolean} isObject - 是否是对象类型数据
 */
async function syncModuleFromCloud(moduleKey, storageKey, arrayRef, isObject = false) {
    try {
        if (typeof supabaseRequest !== 'function') {
            console.log(`Supabase不可用，跳过 ${moduleKey} 模块同步`);
            return false;
        }

        const tableName = moduleKey === 'personnel' ? 'personnel_data' :
                         moduleKey === 'training' ? 'training_data' :
                         moduleKey === 'team' ? 'team_data' :
                         moduleKey === 'inspection' ? 'inspection_center_records' :
                         moduleKey === 'centerInspection' ? 'inspection_center_records' :
                         moduleKey === 'workshopInspection' ? 'inspection_workshop_data' :
                         moduleKey === 'honor' ? 'honor_data' :
                         moduleKey === 'patrol' ? 'violation_discipline_data' :
                         moduleKey === 'samplingCar' ? 'sampling_car_data' :
                         moduleKey === 'instrument' ? 'instrument_data' :
                         moduleKey === 'teamPersonnel' ? 'team_personnel_data' :
                         moduleKey === 'teamCompetition' ? 'team_competition_data' :
                         moduleKey === 'task' ? 'task_data' : null;

        if (!tableName) {
            console.log(`未找到 ${moduleKey} 对应的表名`);
            return false;
        }

        console.log(`开始从云端同步 ${moduleKey} 数据...`);
        const result = await supabaseRequest('GET', tableName);
        
        console.log(`[DEBUG] ${moduleKey} 云端原始数据:`, JSON.stringify(result, null, 2));
        
        // 检查问题台账模块：空数组是有效状态，不应该返回失败
        const isInspectionModule = moduleKey === 'inspection' || moduleKey === 'centerInspection' || moduleKey === 'workshopInspection';
        
        if (!result || result.length === 0) {
            console.log(`云端没有 ${moduleKey} 数据`);
            // 检查问题台账模块：空数据也是有效的，返回成功
            if (isInspectionModule) {
                console.log(`${moduleKey} 模块：空数据有效，初始化空数组`);
                localStorage.setItem(storageKey, JSON.stringify([]));
                return true;
            }
            return false;
        }
        
        // 检查第一个记录
        const firstRecord = result[0];
        console.log(`[DEBUG] ${moduleKey} 第一个记录:`, JSON.stringify(firstRecord, null, 2));
        
        // patrol 模块使用关系型表，不需要 data 字段检查
        // 检查问题台账模块：空数据也是有效的
        if (moduleKey !== 'patrol' && !isInspectionModule) {
            if (!firstRecord || !firstRecord.data) {
                console.warn(`云端 ${moduleKey} 数据格式不正确，没有 data 字段`);
                return false;
            }
        }
        
        // firstRecord.data 就是保存到云端的完整数据对象（包含 headers、data、lastModified 等字段）
        // 直接使用它作为 cloudData
        // 检查问题台账模块：直接使用 result（数组格式）
        let cloudData = moduleKey === 'patrol' ? result : (isInspectionModule ? result : (firstRecord.data || {}));
        console.log(`[DEBUG] ${moduleKey} cloudData (原始):`, JSON.stringify(cloudData, null, 2));
        console.log(`[DEBUG] ${moduleKey} cloudData 类型:`, typeof cloudData);
        
        // 关键修复：如果 cloudData 是字符串，说明是 JSON 字符串，需要解析
        if (typeof cloudData === 'string') {
            try {
                cloudData = JSON.parse(cloudData);
                console.log(`[DEBUG] ${moduleKey} cloudData (解析后):`, JSON.stringify(cloudData, null, 2));
            } catch (e) {
                console.error(`[DEBUG] ${moduleKey} 解析 cloudData 失败:`, e);
                return false;
            }
        }
        
        // 根据模块类型存储正确格式的数据
        let storageData;
        
        // 检查云端数据格式：可能是数组，也可能是包含 data 字段的对象
        const actualData = Array.isArray(cloudData) ? cloudData : (cloudData.data || []);
        console.log(`[DEBUG] ${moduleKey} actualData:`, JSON.stringify(actualData, null, 2));
        
        if (moduleKey === 'honor') {
            // 荣誉模块需要特定格式
            if (cloudData && cloudData.headers && Array.isArray(cloudData.data)) {
                // 云端数据已经是完整格式，直接使用
                storageData = cloudData;
            } else {
                // 云端数据格式不正确，重新创建
                storageData = {
                    headers: ['荣誉名称', '获奖人/单位', '荣誉级别', '颁发单位', '获奖日期', '备注'],
                    data: actualData,
                    lastModified: new Date().toISOString()
                };
            }
        } else if (moduleKey === 'inspection' || moduleKey === 'centerInspection' || moduleKey === 'workshopInspection') {
            // 检查问题台账模块：直接存储数组
            storageData = actualData;
        } else if (moduleKey === 'samplingCar') {
            // 采样车模块需要特定格式
            if (cloudData && cloudData.headers && Array.isArray(cloudData.data)) {
                storageData = cloudData;
            } else {
                storageData = {
                    headers: ['维修厂家', '维修日期', '故障描述', '维修项目', '维修人', '费用', '备注'],
                    data: actualData,
                    lastModified: new Date().toISOString()
                };
            }
        } else if (moduleKey === 'instrument') {
            // 仪器模块需要特定格式
            if (cloudData && cloudData.headers && Array.isArray(cloudData.data)) {
                storageData = cloudData;
            } else {
                storageData = {
                    headers: ['仪器编号', '仪器名称', '维修日期', '维修内容', '维修人员', '更换配件', '备注'],
                    data: actualData,
                    lastModified: new Date().toISOString()
                };
            }
        } else if (moduleKey === 'patrol') {
            // 违章违纪台账模块 - 新的关系型表结构
            // 直接使用查询结果数组（每个元素是一行记录）
            console.log('从云端获取的原始数据:', result);
            const mappedData = result.map(item => ({
                id: item.id,
                recordDate: item.record_date || '',
                name: item.name || '',
                department: item.department || '',
                category: item.category || '',
                facts: item.facts || '',
                occurDate: item.occur_date || '',
                basis: item.basis || '',
                punishmentLevel: item.punishment_level || '',
                economicPenalty: item.economic_penalty || '',
                safetyScore: item.safety_score || '',
                rectificationStatus: item.rectification_status || '',
                remark: item.remark || ''
            }));
            console.log('映射后的数据:', mappedData);
            storageData = {
                headers: ['记录日期', '姓名', '所属部门/单位', '行为/事件类别', '具体事实/经过', '发生日期', '处理依据', '行政处分等级', '经济考核内容', '安全记分', '整改/关闭情况', '备注'],
                data: mappedData,
                lastModified: new Date().toISOString()
            };
        } else if (moduleKey === 'personnel') {
            // 人员信息模块直接存储数组
            storageData = actualData;
        } else if (moduleKey === 'training') {
            // 培训模块直接存储数组
            storageData = actualData;
        } else if (moduleKey === 'teamPersonnel') {
            // 班组人员模块的数据格式
            // cloudData 是 { data: {...}, lastModified: ... }，其中 data 字段是 { 一班: [...], 二班: [...] }
            // firstRecord.data 已经是 { data: {...}, lastModified: ... }
            console.log('teamPersonnel firstRecord.data:', firstRecord.data);
            if (firstRecord.data && 
                typeof firstRecord.data === 'object' && 
                !Array.isArray(firstRecord.data)) {
                // firstRecord.data.data 应该是实际的班组数据 { 一班: [...], ... }
                if (firstRecord.data.data && 
                    typeof firstRecord.data.data === 'object' &&
                    (firstRecord.data.data['一班'] || firstRecord.data.data['二班'])) {
                    storageData = firstRecord.data.data;
                    console.log('teamPersonnel storageData (嵌套格式):', storageData);
                } else {
                    // 如果 data 字段本身就是班组数据对象
                    storageData = firstRecord.data;
                    console.log('teamPersonnel storageData (直接格式):', storageData);
                }
            } else {
                storageData = firstRecord.data;
                console.warn('teamPersonnel 数据格式异常:', storageData);
            }
        } else if (moduleKey === 'task') {
            // 任务管理模块需要特定格式
            if (cloudData && cloudData.headers && Array.isArray(cloudData.data)) {
                storageData = cloudData;
            } else {
                storageData = {
                    headers: ['任务标题', '任务描述', '负责人', '优先级', '状态', '进度', '截止日期', '备注', '创建时间', '更新时间'],
                    data: actualData,
                    lastModified: new Date().toISOString()
                };
            }
        } else if (isObject) {
            // 其他对象类型数据直接存储
            storageData = cloudData;
        } else {
            // 其他模块直接存储数组
            storageData = actualData;
        }
        
        // 保存到 localStorage 前先记录要保存的数据条数
        const saveCount = Array.isArray(storageData) ? storageData.length : (storageData.data?.length || '未知');
        console.log(`[SYNC-DEBUG] ${moduleKey} 准备保存到 localStorage，数据条数: ${saveCount}`);
        console.log(`[SYNC-DEBUG] ${moduleKey} storageKey: ${storageKey}`);
        
        localStorage.setItem(storageKey, JSON.stringify(storageData));
        
        // 验证是否保存成功
        const savedData = localStorage.getItem(storageKey);
        if (savedData) {
            const parsedSaved = JSON.parse(savedData);
            const savedCount = Array.isArray(parsedSaved) ? parsedSaved.length : (parsedSaved.data?.length || '未知');
            console.log(`[SYNC-DEBUG] ${moduleKey} 保存成功，验证数据条数: ${savedCount}`);
        } else {
            console.error(`[SYNC-DEBUG] ${moduleKey} 保存失败，localStorage 中为空`);
        }
        
        // 更新全局数组引用
        if (arrayRef && typeof window[arrayRef] !== 'undefined') {
            // 对于 patrol 模块，只取 data 数组
            if (moduleKey === 'patrol') {
                window[arrayRef] = storageData.data || [];
            } else if (isObject) {
                window[arrayRef] = storageData;
            } else {
                window[arrayRef] = Array.isArray(storageData) ? storageData : (storageData.data || []);
            }
            console.log(`[SYNC-DEBUG] ${moduleKey} 全局数组 ${arrayRef} 已更新`);
        }
        
        console.log(`✅ ${moduleKey} 数据同步成功`);
        return true;
        
    } catch (error) {
        console.error(`同步 ${moduleKey} 数据失败:`, error);
        return false;
    }
}

async function initPersonnel() {
    selectedIds = [];
    updateBatchDeleteButton();
    
    try {
        // 检查本地数据是否存在
        const localData = localStorage.getItem('personnelData');
        
        if (!localData) {
            // 本地没有数据，从云端同步
            console.log('人员管理：本地无数据，从云端同步...');
            if (typeof syncModuleFromCloud === 'function') {
                await syncModuleFromCloud('personnel', 'personnelData', 'allPersonnelData', false);
                console.log('人员数据云端同步完成');
            }
        } else {
            // 有本地数据，直接使用
            console.log('人员管理：使用本地缓存');
        }
    } catch (error) {
        console.log('云端同步失败，使用本地数据:', error.message);
    }
    
    // 加载数据（优先使用云端同步后的本地数据）
    allPersonnelData = loadPersonnelData();
    personnelData = [...allPersonnelData];
    renderPersonnelTable();
    renderPersonnelPagination();
    
    const saveToCloudBtn = document.getElementById('saveToCloudBtn');
    if (saveToCloudBtn) {
        saveToCloudBtn.onclick = savePersonnelToCloud;
    }
}

async function savePersonnelToCloud() {
    const btn = document.getElementById('saveToCloudBtn');
    const originalText = btn.innerHTML;
    
    try {
        btn.innerHTML = '<span class="btn-icon">⏳</span> 检查锁状态...';
        btn.disabled = true;
        
        // 获取上传锁（支持等待）
        const lockResult = await new Promise((resolve) => {
            tryAcquireUploadLockWithWaiting(resolve);
        });
        
        if (!lockResult.success) {
            alert(`⚠️ ${lockResult.message}`);
            btn.innerHTML = originalText;
            btn.disabled = false;
            return;
        }
        
        btn.innerHTML = '<span class="btn-icon">⏳</span> 同步中...';
        
        // 先保存当前页面的数据到 localStorage
        savePersonnelData();
        
        const personnelData = [...allPersonnelData];
        
        if (!personnelData || personnelData.length === 0) {
            alert('没有人员数据需要保存');
            await releaseUploadLock();
            btn.innerHTML = originalText;
            btn.disabled = false;
            return;
        }
        
        const confirmResult = confirm(`确定要将本地 ${personnelData.length} 条人员数据同步到云端吗？\n\n此操作将：\n1. 更新或创建云端的人员数据\n2. 确保云端数据与当前页面数据完全一致\n\n请谨慎操作！`);
        if (!confirmResult) {
            await releaseUploadLock();
            btn.innerHTML = originalText;
            btn.disabled = false;
            return;
        }
        
        console.log('开始同步人员数据到云端...');

        if (typeof supabaseRequest === 'function') {
            // 使用 UPSERT 方式
            btn.innerHTML = '<span class="btn-icon">🔍</span> 检查云端数据...';

            const cloudData = {
                data: personnelData,
                updated_at: new Date().toISOString()
            };

            const existingData = await supabaseRequest('GET', 'personnel_data');

            let result;
            if (existingData && existingData.length > 0 && existingData[0].id) {
                btn.innerHTML = '<span class="btn-icon">📤</span> 更新云端数据...';
                console.log('云端已有数据，使用 PATCH 更新');
                result = await supabaseRequest('PATCH', 'personnel_data', cloudData, {
                    id: `eq.${existingData[0].id}`
                });
            } else {
                btn.innerHTML = '<span class="btn-icon">📤</span> 创建云端数据...';
                console.log('云端没有数据，使用 POST 创建');
                result = await supabaseRequest('POST', 'personnel_data', {
                    id: generateUUID(),
                    ...cloudData,
                    created_at: new Date().toISOString()
                });
            }

            if (result !== null) {
                alert(`✅ 同步成功！\n\n已云端同步 ${personnelData.length} 条人员数据。\n\n现在页面数据与数据库数据完全一致。`);
                console.log('人员数据同步成功');
                if (typeof updateBottomBarStats === 'function') {
                    await updateBottomBarStats();
                }
            } else {
                alert('⚠️ 同步失败\n\n未能将数据同步到云端');
                console.error('人员数据同步失败');
            }
        } else {
            alert('同步功能不可用，请检查页面是否正确加载');
        }
        
    } catch (error) {
        console.error('同步异常:', error);
        alert('同步失败，请检查网络连接\n\n错误: ' + error.message);
    } finally {
        await releaseUploadLock();
        btn.innerHTML = originalText;
        btn.disabled = false;
    }
}

/**
 * 从云端刷新人员信息数据
 */
async function refreshPersonnelFromCloud() {
    const btn = document.getElementById('refreshPersonnelBtn');
    let originalText = null;
    try {
        if (btn) {
            originalText = btn.innerHTML;
            btn.innerHTML = '<span class="btn-icon">⏳</span> 刷新中...';
            btn.disabled = true;
        }

        if (typeof syncModuleFromCloud === 'function') {
            const ok = await syncModuleFromCloud('personnel', 'personnelData', 'allPersonnelData', false);
            if (ok) {
                allPersonnelData = loadPersonnelData();
                personnelData = [...allPersonnelData];
                renderPersonnelTable();
                renderPersonnelPagination();
                if (typeof updateBottomBarStats === 'function') {
                    await updateBottomBarStats();
                }
                alert('✅ 人员数据刷新成功！');
            } else {
                alert('⚠️ 云端没有人员数据或刷新失败');
            }
        } else {
            // 降级：直接重新加载本地数据并重绘表格
            allPersonnelData = loadPersonnelData();
            personnelData = [...allPersonnelData];
            renderPersonnelTable();
            renderPersonnelPagination();
            alert('已重新加载本地数据');
        }
    } catch (err) {
        console.error('[人员管理] 刷新失败:', err);
        alert('刷新失败：' + (err && err.message ? err.message : err));
    } finally {
        if (btn && originalText !== null) {
            btn.innerHTML = originalText;
            btn.disabled = false;
        }
    }
}

