// ==================== 批量导入功能 ====================
let importedData = [];
let importDataKeys = [];
let isImporting = false;

function openImportModal() {
    document.getElementById('importModal').style.display = 'block';
    document.getElementById('importFileInput').value = '';
    document.getElementById('fileNameDisplay').textContent = '';
    document.getElementById('importPreview').style.display = 'none';
    importedData = [];
    importDataKeys = [];
}

function closeImportModal() {
    document.getElementById('importModal').style.display = 'none';
}

function handleFileSelect(event) {
    const file = event.target?.files?.[0] || event.dataTransfer?.files?.[0];
    if (!file) return;
    
    if (isImporting) {
        alert('正在导入中，请稍候...');
        return;
    }
    isImporting = true;

    document.getElementById('fileNameDisplay').textContent = `已选择: ${file.name}`;

    const reader = new FileReader();
    reader.onload = function(e) {
        try {
            const data = new Uint8Array(e.target.result);
            const workbook = XLSX.read(data, { 
                type: 'array',
                cellDates: true,
                raw: false
            });
            
            if (!workbook || !workbook.SheetNames || workbook.SheetNames.length === 0) {
                alert('Excel文件中没有工作表');
                return;
            }
            
            const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
            const jsonData = XLSX.utils.sheet_to_json(firstSheet, { 
                defval: '',
                raw: false
            });

            if (jsonData.length < 1) {
                alert('Excel文件中没有数据');
                return;
            }

            let foundNameKey = '姓名';
            if (!jsonData[0]['姓名']) {
                for (let i = 0; i < Math.min(5, jsonData.length); i++) {
                    const rowKeys = Object.keys(jsonData[i]);
                    for (const key of rowKeys) {
                        const cleanKey = key.toLowerCase().replace(/[\s\-_–·、，。,]/g, '');
                        if (cleanKey.includes('姓名') || cleanKey.includes('name') || cleanKey.includes('xingming')) {
                            foundNameKey = key;
                            break;
                        }
                    }
                    if (foundNameKey !== '姓名') break;
                }
            }
            
            if (!jsonData[0][foundNameKey]) {
                alert('未在Excel中找到"姓名"列，请确保Excel文件包含正确的表头\n\n提示：表头列名可以是"姓名"、"name"或包含这些关键词的名称');
                return;
            }

            importedData = jsonData;
            importDataKeys = Object.keys(jsonData[0]);

            document.getElementById('importPreview').style.display = 'none';

            const validData = importedData.filter(row => {
                return row[foundNameKey] && String(row[foundNameKey]).trim();
            });
            
            if (validData.length > 0) {
                confirmImport();
            } else {
                alert('未检测到有效数据，请检查Excel文件格式是否包含"姓名"列');
            }
        } catch (error) {
            console.error('Excel解析错误:', error);
            alert(`读取Excel文件失败: ${error.message || '请确保文件格式正确，支持.xlsx和.xls格式'}`);
            isImporting = false;
        }
    };
    reader.onerror = function(e) {
        alert('文件读取失败，请尝试使用其他浏览器或更换文件');
        console.error('FileReader error:', e);
        isImporting = false;
    };
    reader.readAsArrayBuffer(file);
}

function handleDragOver(e) {
    e.preventDefault();
    e.stopPropagation();
    e.dataTransfer.dropEffect = 'copy';
    const uploadAreas = document.querySelectorAll('.upload-area');
    uploadAreas.forEach(area => {
        area.classList.add('drag-over');
    });
}

function handleDragLeave(e) {
    e.preventDefault();
    e.stopPropagation();
    const uploadAreas = document.querySelectorAll('.upload-area');
    uploadAreas.forEach(area => {
        area.classList.remove('drag-over');
    });
}

function handleDrop(e) {
    e.preventDefault();
    e.stopPropagation();
    
    const uploadAreas = document.querySelectorAll('.upload-area');
    uploadAreas.forEach(area => {
        area.classList.remove('drag-over');
    });
    
    const trainingModal = document.getElementById('trainingImportModal');
    const importModal = document.getElementById('importModal');
    const inspectionModal = document.getElementById('inspectionImportModal');
    const honorModal = document.getElementById('honorImportModal');
    
    if (trainingModal && trainingModal.style.display === 'block') {
        handleTrainingFileSelect(e);
    } else if (inspectionModal && inspectionModal.style.display === 'block') {
        handleInspectionFileSelect(e);
    } else if (honorModal && honorModal.style.display === 'block') {
        handleHonorFileSelect(e);
    } else if (importModal && importModal.style.display === 'block') {
        handleFileSelect(e);
    }
}

function showImportPreview(data) {
    const previewDiv = document.getElementById('importPreview');
    const previewTable = document.getElementById('previewTable');
    const summaryP = document.getElementById('importSummary');

    const previewData = data.slice(0, 5);

    let tableHTML = '<thead><tr>';
    importDataKeys.forEach(key => {
        tableHTML += `<th>${key}</th>`;
    });
    tableHTML += '</tr></thead><tbody>';

    previewData.forEach(row => {
        tableHTML += '<tr>';
        importDataKeys.forEach(key => {
            tableHTML += `<td>${row[key] || ''}</td>`;
        });
        tableHTML += '</tr>';
    });
    tableHTML += '</tbody>';

    previewTable.innerHTML = tableHTML;
    summaryP.textContent = `共 ${data.length} 条数据待导入`;

    previewDiv.style.display = 'block';
}

function confirmImport() {
    if (importedData.length === 0) {
        return;
    }

    const fieldMapping = {
        '人员编号': 'personnelNo',
        '班次': 'shift',
        '姓名': 'name',
        '性别': 'gender',
        '民族': 'ethnicity',
        '籍贯': 'nativePlace',
        '身份证号码': 'idCard',
        '出生年月': 'birthDate',
        '工作时间': 'workStartDate',
        '入司时间': 'companyStartDate',
        '政治面貌': 'politicalStatus',
        '身份证地址': 'idCardAddress',
        '现家庭住址': 'currentAddress',
        '文化程度': 'education',
        '所学专业': 'major',
        '毕业院校': 'school',
        '毕业时间': 'graduationDate',
        '专业技术（职业）资格': 'professionalTitle',
        '手机号码': 'phone',
        '婚姻状况': 'maritalStatus',
        '健康状况': 'healthStatus',
        '紧急联系人': 'emergencyContact',
        '关系': 'emergencyRelationship',
        '联系电话': 'emergencyPhone',
        '统一账号': 'unifiedNo',
        '有无驾照': 'hasDrivingLicense',
        '备注': 'remark'
    };

    function findMappingKey(header) {
        if (!header || typeof header !== 'string') {
            console.log(`无效表头: ${header}`);
            return null;
        }
        
        // 移除所有特殊字符和空格，统一转为小写
        const headerClean = header.toLowerCase().replace(/[\s\-_–·、，。,()（）【】\[\]{}<>《》]/g, '');
        console.log(`正在匹配表头: "${header}" (长度: ${header.length}) -> 清理后: "${headerClean}" (长度: ${headerClean.length})`);
        
        // 定义所有可能的字段别名
        const fieldAliases = {
            'personnelNo': ['人员编号', '编号', '员工编号', '工号', 'employeeno', 'staffno', 'id', 'no'],
            'shift': ['班次', '班别', '班组', 'team', 'group', 'shift', 'banci'],
            'name': ['姓名', '名字', '名称', 'name', 'xingming', 'username'],
            'gender': ['性别', 'sex', 'gender', 'xingbie'],
            'ethnicity': ['民族', '民族', 'ethnicity', 'minzu'],
            'nativePlace': ['籍贯', '祖籍', '出生地', 'nativeplace', 'jiguan'],
            'idCard': ['身份证号码', '身份证', '证件号码', '身份证号', 'idcard', 'sfz', 'idnumber'],
            'birthDate': ['出生年月', '出生日期', '生日', 'birthdate', 'birthday', 'birth', 'chusheng'],
            'workStartDate': ['工作时间', '参加工作时间', '参加工作日期', 'workdate'],
            'companyStartDate': ['入司时间', '入职时间', '到岗时间', '公司入职时间', 'employdate', 'hiredate'],
            'politicalStatus': ['政治面貌', '面貌', '政治', 'party', 'zhengzhi'],
            'idCardAddress': ['身份证地址', '身份证住址', '户籍地址', '户口地址'],
            'currentAddress': ['现家庭住址', '家庭住址', '住址', '现住址', '居住地', 'address'],
            'education': ['文化程度', '学历', '教育程度', 'education', 'xueli'],
            'major': ['所学专业', 'zhuanye', 'major'],
            'school': ['毕业院校', '毕业学校', '院校', '学校', 'school', 'college', 'university'],
            'graduationDate': ['毕业时间', '毕业日期', 'graduation', 'biye'],
            'professionalTitle': ['专业技术职业资格', '专业技术资格', '职业资格', '职称', '技术职称', 'title', 'professional'],
            'phone': ['手机号码', '手机', '手机号', '移动电话', 'mobile', 'phone', 'tel', 'cellphone', 'shouji'],
            'maritalStatus': ['婚姻状况', '婚姻', '婚否', 'marital', 'hunyin'],
            'healthStatus': ['健康状况', '健康', '身体状况', 'health', 'jiankang'],
            'emergencyContact': ['紧急联系人', '紧急联系', '联系人', 'emergency', 'jinji'],
            'emergencyRelationship': ['关系', '与本人关系', 'relationship', 'guanxi'],
            'emergencyPhone': ['联系电话', '紧急联系电话', '紧急电话', '家属电话', 'homephone', 'familyphone'],
            'unifiedNo': ['统一账号', '账号', '统一编号', 'unifiedno', 'account'],
            'hasDrivingLicense': ['有无驾照', '驾照', '驾驶证', '驾驶', 'driving', 'license', 'jiashao'],
            'remark': ['备注', '备注信息', '说明', 'remark', 'beizhu', 'note']
        };
        
        // 精确匹配（按别名长度排序，长别名优先）
        for (const [fieldKey, aliases] of Object.entries(fieldAliases)) {
            const sortedAliases = [...aliases].sort((a, b) => b.length - a.length);
            for (const alias of sortedAliases) {
                const aliasClean = alias.toLowerCase().replace(/[\s\-_–·、，。,()（）【】\[\]{}<>《》]/g, '');
                if (headerClean === aliasClean) {
                    console.log(`精确匹配成功: "${header}" -> "${fieldKey}" (通过别名: "${alias}")`);
                    return fieldKey;
                }
            }
        }
        
        // 包含匹配（别名长度>=3才进行包含匹配，避免短词误匹配）
        for (const [fieldKey, aliases] of Object.entries(fieldAliases)) {
            for (const alias of aliases) {
                const aliasClean = alias.toLowerCase().replace(/[\s\-_–·、，。,()（）【】\[\]{}<>《》]/g, '');
                if (headerClean.includes(aliasClean) && aliasClean.length >= 3) {
                    console.log(`包含匹配成功: "${header}" -> "${fieldKey}" (通过别名: "${alias}")`);
                    return fieldKey;
                }
            }
        }
        
        console.log(`未匹配到字段: "${header}"`);
        return null;
    }

    let successCount = 0;
    let skipCount = 0;
    
    console.log('=== 开始导入人员数据 ===');
    console.log('Excel表头:', importDataKeys);
    
    importedData.forEach((row, index) => {
        const person = {};
        let hasValidName = false;
        
        importDataKeys.forEach(key => {
            const mappedKey = findMappingKey(key);
            if (mappedKey) {
                let value = row[key];
                if (typeof value === 'number' && !isNaN(value)) {
                    if (value > 25569 && value < 2958465) {
                        const date = new Date((value - 25569) * 86400 * 1000);
                        value = date.toISOString().split('T')[0];
                    } else {
                        value = String(value);
                    }
                } else if (value !== null && value !== undefined) {
                    value = String(value).trim();
                } else {
                    value = '';
                }
                person[mappedKey] = value;
                console.log(`第${index+1}行: "${key}" -> "${mappedKey}" = "${value}"`);
                if (mappedKey === 'name' && value && value.trim()) {
                    hasValidName = true;
                }
            } else {
                console.log(`第${index+1}行: "${key}" -> 未匹配到字段`);
            }
        });

        if (hasValidName) {
            person.id = Date.now() + successCount;
            allPersonnelData.push(person);
            successCount++;
            console.log('导入成功:', person.name);
        } else {
            skipCount++;
        }
    });

    console.log('导入完成，总共添加', successCount, '条数据，allPersonnelData当前条数:', allPersonnelData.length);
    savePersonnelData();
    searchPersonnel();
    closeImportModal();
    
    if (successCount > 0) {
        alert(`成功导入 ${successCount} 条人员信息！${skipCount > 0 ? '(跳过 ' + skipCount + ' 条无效数据)' : ''}`);
    } else {
        alert('没有有效数据可导入，请检查Excel文件格式');
    }
    isImporting = false;
}

