async function exportTrainingData() {
    const yearData = getPersonnelDataForYear(currentTrainingYear);
    
    const headers = ['序号', '姓名', '班次'];
    for (let month = 1; month <= 12; month++) {
        headers.push(`${month}月`);
    }

    const data = yearData.map((person, index) => {
        const row = [index + 1, person.name || '', person.shift || ''];
        for (let month = 1; month <= 12; month++) {
            const monthData = person.months && person.months[month] ? person.months[month] : { status: '', totalScore: '' };
            if (monthData.status === '请假') {
                row.push('请假');
            } else if (monthData.totalScore && monthData.totalScore !== '-') {
                row.push(monthData.totalScore);
            } else {
                row.push('/');
            }
        }
        return row;
    });

    exportToExcelWithStyle(data, headers, `${currentTrainingYear}年培训成绩`, `副班培训成绩_${currentTrainingYear}年.xlsx`);
}

