async function saveTrainingChanges() {
    var tableBody = document.getElementById('trainingTableBody');
    if (!tableBody) {
        alert('错误：找不到表格！');
        return;
    }
    
    var rows = tableBody.getElementsByTagName('tr');
    if (!rows || rows.length === 0) {
        alert('错误：没有数据可以保存！');
        return;
    }
    
    var newData = [];
    var savedCount = 0;
    var i, j;
    
    for (i = 0; i < rows.length; i++) {
        var row = rows[i];
        var allCells = row.getElementsByTagName('td');
        
        var nameInput = row.querySelector('input[data-field="name"]');
        var name = nameInput ? nameInput.value.trim() : '';
        
        var personData = {
            id: Date.now() + Math.random(),
            name: name,
            shift: '未分配',
            year: currentTrainingYear,
            months: {}
        };
        
        for (j = 2; j < allCells.length - 1; j++) {
            var cell = allCells[j];
            var inputs = cell.getElementsByTagName('input');
            if (inputs.length === 0) continue;
            
            var value = inputs[0].value.trim();
            var month = j - 1;
            
            if (value === '请假') {
                personData.months[month] = {
                    status: '请假',
                    totalScore: ''
                };
            } else if (value !== '/' && value !== '') {
                var score = parseFloat(value);
                if (!isNaN(score)) {
                    personData.months[month] = {
                        status: '正常',
                        totalScore: score
                    };
                }
            }
        }
        
        if (name || Object.keys(personData.months).length > 0) {
            newData.push(personData);
            savedCount++;
        }
    }
    
    if (newData.length === 0) {
        alert('错误：没有有效的数据可以保存！');
        return;
    }
    
    var yearData = formatTrainingDataForYear(newData, currentTrainingYear);
    
    // 保存前记录旧数据用于审计日志
    const oldTrainingDataForYear = allTrainingData.filter(item => item.year === currentTrainingYear);
    
    // 直接保存到本地
    var keptData = [];
    for (var k = 0; k < allTrainingData.length; k++) {
        if (allTrainingData[k].year !== currentTrainingYear) {
            keptData.push(allTrainingData[k]);
        }
    }
    
    allTrainingData = keptData.concat(yearData);
    
    trainingData = [];
    for (var m = 0; m < allTrainingData.length; m++) {
        trainingData[m] = allTrainingData[m];
    }
    
    try {
        localStorage.setItem('trainingData', JSON.stringify(allTrainingData));
    } catch (e) {
        alert('保存失败：' + e.message);
        return;
    }
    
    // 添加到离线队列进行自动同步
    // 培训数据按年份分别存储，便于按年查询
    if (window.OfflineQueue) {
        // 按年份分组数据
        const yearGroups = {};
        allTrainingData.forEach(item => {
            const year = item.year;
            if (!yearGroups[year]) {
                yearGroups[year] = [];
            }
            yearGroups[year].push(item);
        });
        
        // 为每个年份创建一个同步操作
        Object.keys(yearGroups).forEach(year => {
            window.OfflineQueue.add({
                module: 'training',
                type: 'update',
                recordId: `training_year_${year}`,
                data: { 
                    year: parseInt(year),
                    data: yearGroups[year] 
                }
            });
        });
    }
    
    isTrainingEditMode = false;
    
    var addBtn = safeGetElement('addTrainingBtn');
    var toolbarActions = safeGetElement('trainingToolbarActions');
    
    if (addBtn) {
        addBtn.innerHTML = '<span class="btn-icon">✏️</span> 编辑成绩';
    }
    if (toolbarActions) {
        toolbarActions.style.display = 'none';
    }
    
    var addPersonBtn = document.getElementById('addPersonBtn');
    if (addPersonBtn) {
        addPersonBtn.style.display = 'none';
    }
    
    renderTrainingTable();
    
    // 记录审计日志
    if (typeof recordAuditLog === 'function') {
        // 计算变更详情（使用标准格式：{字段名: {old: 旧值, new: 新值}}）
        const changes = {
            totalRecords: {
                old: oldTrainingDataForYear.length,
                new: yearData.length
            },
            year: {
                old: currentTrainingYear,
                new: currentTrainingYear
            },
            updatedRecords: {
                old: 0,
                new: savedCount
            }
        };
        
        recordAuditLog({
            module: 'training',
            action: 'update',
            targetId: 'batch',
            targetDesc: `批量保存 ${savedCount} 条培训成绩（${currentTrainingYear}年）`,
            changes: changes,
            beforeData: oldTrainingDataForYear,
            afterData: yearData
        });
    }
    
    alert('保存成功！已保存 ' + savedCount + ' 条记录。数据已保存到本地，点击"保存到云端"按钮上传到数据库。');
}

