function formatTrainingDataForYear(persons, year) {
    var result = [];
    persons.forEach(function(person) {
        var months = person.months || {};
        var hasMonthData = Object.keys(months).length > 0;
        
        if (hasMonthData) {
            Object.keys(months).forEach(function(month) {
                var monthData = months[month];
                result.push({
                    id: Date.now() + Math.random(),
                    name: person.name,
                    shift: person.shift || '未分配',
                    year: year,
                    month: parseInt(month),
                    theoryScore: monthData.status === '请假' ? 0 : (monthData.totalScore || 0),
                    practicalScore: monthData.status === '请假' ? 0 : (monthData.totalScore || 0),
                    status: monthData.status || '正常',
                    remark: ''
                });
            });
        } else if (person.name) {
            result.push({
                id: Date.now() + Math.random(),
                name: person.name,
                shift: person.shift || '未分配',
                year: year,
                month: 1,
                theoryScore: 0,
                practicalScore: 0,
                status: '正常',
                remark: ''
            });
        }
    });
    return result;
}

