function addTrainingRecord() {
    const nameEl = safeGetElement('addTrainingName');
    const shiftEl = safeGetElement('addTrainingShift');
    const monthEl = safeGetElement('addTrainingMonth');
    const statusEl = safeGetElement('addTrainingStatus');
    const theoryEl = safeGetElement('addTrainingTheory');
    const practicalEl = safeGetElement('addTrainingPractical');
    const remarkEl = safeGetElement('addTrainingRemark');

    if (!nameEl || !shiftEl || !monthEl || !statusEl) {
        return;
    }

    const name = nameEl.value.trim();
    const shift = shiftEl.value;
    const month = parseInt(monthEl.value);
    const status = statusEl.value;
    const theoryScore = status === '正常' ? parseInt(theoryEl?.value) || 0 : 0;
    const practicalScore = status === '正常' ? parseInt(practicalEl?.value) || 0 : 0;
    const remark = remarkEl?.value.trim() || '';

    if (!name) {
        alert('请输入姓名');
        return;
    }

    const existingIndex = allTrainingData.findIndex(
        item => item.name === name && item.year === currentTrainingYear && item.month === month
    );

    let newRecord;
    if (existingIndex !== -1) {
        newRecord = {
            ...allTrainingData[existingIndex],
            shift: shift,
            theoryScore: theoryScore,
            practicalScore: practicalScore,
            status: status,
            remark: remark
        };
        allTrainingData[existingIndex] = newRecord;
    } else {
        newRecord = {
            id: Date.now(),
            name: name,
            shift: shift,
            year: currentTrainingYear,
            month: month,
            theoryScore: theoryScore,
            practicalScore: practicalScore,
            status: status,
            remark: remark
        };
        allTrainingData.push(newRecord);
    }

    trainingData = [...allTrainingData];
    
    try {
        localStorage.setItem('trainingData', JSON.stringify(allTrainingData));
    } catch (e) {
        alert('保存失败：' + e.message);
        return;
    }
    
    if (typeof syncModuleChangesToCloud === 'function') {
        const changes = existingIndex !== -1 
            ? { added: [], updated: [{ rowId: newRecord.id, data: newRecord }], deleted: [] }
            : { added: [{ rowId: newRecord.id, data: newRecord }], updated: [], deleted: [] };
        syncModuleChangesToCloud('training', changes).catch(err => {
            console.error('培训成绩同步到云端失败:', err);
        });
    }
    
    renderTrainingTable();
    closeAddTrainingModal();
    alert('培训成绩添加成功！');
}

