function handleTrainingFileSelect(event) {
    const file = event.target?.files?.[0] || event.dataTransfer?.files?.[0];
    if (!file) return;
    
    if (isTrainingImporting) {
        alert('正在导入中，请稍候...');
        return;
    }
    isTrainingImporting = true;

    const fileNameDisplay = safeGetElement('trainingFileNameDisplay');
    if (fileNameDisplay) fileNameDisplay.textContent = `已选择: ${file.name}`;

    const fileName = file.name.toLowerCase();
    const isExcel = fileName.endsWith('.xlsx') || fileName.endsWith('.xls');
    const isImage = fileName.endsWith('.jpg') || fileName.endsWith('.jpeg') || fileName.endsWith('.png') || fileName.endsWith('.gif');

    if (isExcel) {
        handleExcelFile(file);
    } else if (isImage) {
        handleImageFile(file);
    } else {
        alert('不支持的文件格式，请上传Excel文件或图片文件');
    }
}

function handleExcelFile(file) {
    const reader = new FileReader();
    reader.onload = function(e) {
        try {
            const data = new Uint8Array(e.target.result);
            const workbook = XLSX.read(data, { 
                type: 'array',
                cellDates: true,
                raw: false
            });
            
            if (!workbook || !workbook.SheetNames || workbook.SheetNames.length === 0) {
                alert('Excel文件中没有工作表');
                isTrainingImporting = false;
                return;
            }
            
            const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
            const jsonData = XLSX.utils.sheet_to_json(firstSheet, { 
                defval: '',
                raw: false
            });

            if (jsonData.length < 1) {
                alert('Excel文件中没有数据');
                isTrainingImporting = false;
                return;
            }

            const headers = Object.keys(jsonData[0]);
            const hasName = headers.some(h => h.toLowerCase().includes('姓名') || h.toLowerCase().includes('name'));
            
            if (!hasName) {
                alert('未在Excel中找到"姓名"列，请确保Excel文件包含正确的表头');
                isTrainingImporting = false;
                return;
            }

            trainingImportedData = jsonData;
            trainingImportDataKeys = headers;
            
            closeTrainingImportModal();
            confirmTrainingImport();
        } catch (error) {
            console.error('Excel解析错误:', error);
            alert(`读取Excel文件失败: ${error.message || '请确保文件格式正确'}`);
            isTrainingImporting = false;
        }
    };
    reader.onerror = function() {
        alert('文件读取失败，请重试');
        isTrainingImporting = false;
    };
    reader.readAsArrayBuffer(file);
}

