function convertImageDataToImportFormat(imageData) {
    var result = [];
    for (var i = 0; i < imageData.length; i++) {
        var person = imageData[i];
        var row = { '姓名': person.name, '班次': '未分配' };
        for (var m = 1; m <= 12; m++) {
            row[m + '月'] = person.months[m] || '/';
        }
        result.push(row);
    }
    return result;
}

function confirmTrainingImport() {
    if (!trainingImportedData || trainingImportedData.length === 0) {
        return;
    }

    var successCount = 0;
    
    var newData = [];
    
    for (var i = 0; i < trainingImportedData.length; i++) {
        var row = trainingImportedData[i];
        var name = '';
        var shift = '';
        var monthData = {};
        
        for (var j = 0; j < trainingImportDataKeys.length; j++) {
            var key = trainingImportDataKeys[j];
            var value = String(row[key] || '').trim();
            
            if (key.toLowerCase().indexOf('姓名') !== -1 || key.toLowerCase().indexOf('name') !== -1) {
                name = value;
            } else if (key.toLowerCase().indexOf('班次') !== -1 || key.toLowerCase().indexOf('shift') !== -1) {
                shift = value;
            } else {
                var monthMatch = key.match(/(\d{1,2})月/);
                if (monthMatch) {
                    var month = parseInt(monthMatch[1]);
                    
                    if (!monthData[month]) {
                        monthData[month] = { theoryScore: '', practicalScore: '', status: '' };
                    }
                    
                    if (value === '请假') {
                        monthData[month].status = '请假';
                    } else if (value !== '/' && value !== '' && !isNaN(parseFloat(value))) {
                        var score = parseFloat(value);
                        monthData[month].theoryScore = score;
                        monthData[month].practicalScore = score;
                        monthData[month].status = '正常';
                    }
                }
            }
        }
        
        if (name) {
            for (var m = 1; m <= 12; m++) {
                var data = monthData[m] || { theoryScore: '', practicalScore: '', status: '' };
                
                newData.push({
                    id: generateUUID(),
                    name: name,
                    shift: shift,
                    year: currentTrainingYear,
                    month: m,
                    theoryScore: data.theoryScore,
                    practicalScore: data.practicalScore,
                    status: data.status || '',
                    remark: ''
                });
                successCount++;
            }
        }
    }
    
    var keptData = [];
    for (var k = 0; k < allTrainingData.length; k++) {
        if (allTrainingData[k].year !== currentTrainingYear) {
            keptData.push(allTrainingData[k]);
        }
    }
    
    allTrainingData = keptData.concat(newData);

    trainingData = [];
    for (var ci = 0; ci < allTrainingData.length; ci++) {
        trainingData[ci] = allTrainingData[ci];
    }
    
    // 保存到 localStorage
    try {
        localStorage.setItem('trainingData', JSON.stringify(allTrainingData));
        console.log(`批量导入成功，已保存 ${newData.length} 条记录到本地存储`);
    } catch (e) {
        console.error('保存到本地存储失败:', e);
    }
    
    renderTrainingTable();
    
    // 异步增量同步到云端
    if (typeof syncModuleChangesToCloud === 'function') {
        const addedRecords = newData.map(item => ({
            rowId: item.id,
            data: item
        }));
        syncModuleChangesToCloud('training', {
            added: addedRecords,
            updated: [],
            deleted: []
        }).catch(err => {
            console.error('培训成绩批量导入数据增量同步失败:', err);
        });
    }
    
    alert(`成功导入 ${successCount} 条培训记录！\n\n数据已保存到本地，点击"保存到云端"按钮上传到数据库。`);
    
    isTrainingImporting = false;
}

let isDownloadingTemplate = false;

async function downloadTrainingTemplate(e) {
    if (e) e.preventDefault();
    
    if (isDownloadingTemplate) {
        console.log('正在下载模板中，请稍后...');
        return;
    }
    isDownloadingTemplate = true;
    
    try {
        const headers = ['序号', '姓名', '班次'];
        for (let month = 1; month <= 12; month++) {
            headers.push(`${month}月`);
        }

        const templateData = [{
            '序号': 1,
            '姓名': '张三',
            '班次': '一班',
            '1月': 90,
            '2月': '请假',
            '3月': 88,
            '4月': '/',
            '5月': '/',
            '6月': '/',
            '7月': '/',
            '8月': '/',
            '9月': '/',
            '10月': '/',
            '11月': '/',
            '12月': '/'
        }];

        const ws = XLSX.utils.aoa_to_sheet([headers]);
        XLSX.utils.sheet_add_json(ws, templateData, {skipHeader: true, origin: 'A2'});
        
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, '培训成绩模板');
        
        const wss = wb.Sheets['培训成绩模板'];
        wss['!cols'] = [
            {wch: 8},
            {wch: 10},
            {wch: 10},
            {wch: 8}, {wch: 8}, {wch: 8}, {wch: 8}, {wch: 8}, {wch: 8},
            {wch: 8}, {wch: 8}, {wch: 8}, {wch: 8}, {wch: 8}, {wch: 8}
        ];
        
        const range = XLSX.utils.decode_range(wss['!ref']);
        for (let col = range.s.c; col <= range.e.c; col++) {
            for (let row = range.s.r; row <= range.e.r; row++) {
                const cell_address = {c: col, r: row};
                const cell_ref = XLSX.utils.encode_cell(cell_address);
                if (!wss[cell_ref]) {
                    wss[cell_ref] = {v: ''};
                }
                if (!wss[cell_ref].s) {
                    wss[cell_ref].s = {};
                }
                wss[cell_ref].s.alignment = {horizontal: 'center', vertical: 'center'};
                wss[cell_ref].s.border = {
                    top: {style: 'thin'},
                    bottom: {style: 'thin'},
                    left: {style: 'thin'},
                    right: {style: 'thin'}
                };
                if (row === 0) {
                    wss[cell_ref].s.font = {bold: true};
                    wss[cell_ref].s.fill = {fgColor: {rgb: 'CCCCCC'}};
                }
            }
        }
        
        const now = new Date();
        const dateStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
        await exportWorkbook(wb, `培训成绩导入模板_${dateStr}.xlsx`);
    } finally {
        isDownloadingTemplate = false;
    }
}



// ==================== 班组人员管理 ====================
async function initTeamPersonnel() {
    try {
        // 检查本地数据是否存在
        const localData = localStorage.getItem('teamPersonnelData');
        
        if (!localData) {
            // 本地没有数据，从云端同步
            console.log('班组人员：本地无数据，从云端同步...');
            await syncModuleFromCloud('teamPersonnel', 'teamPersonnelData', 'currentTeamPersonnelData', true);
        } else {
            // 有本地数据，直接使用
            console.log('班组人员：使用本地缓存');
        }
    } catch (error) {
        console.log('云端同步失败，使用本地数据:', error.message);
    }
    
    loadTeamPersonnelData();
    loadTeamPersonnelVersionHistory();
    syncTeamPersonnelToPersonnelData();
    updateLastEditTime();
    renderTeamPersonnelTable();
    
    // 添加刷新按钮
    if (typeof addModuleRefreshButton === 'function') {
        addModuleRefreshButton('teamPersonnel', 'teamPersonnelData', 'currentTeamPersonnelData', '#teamPersonnelPage .toolbar-left', async () => {
            // 从云端刷新最新数据
            try {
                if (typeof syncModuleFromCloud === 'function') {
                    await syncModuleFromCloud('teamPersonnel', 'teamPersonnelData', 'currentTeamPersonnelData', true);
                    loadTeamPersonnelData();
                    renderTeamPersonnelTable();
                    console.log('✅ 班组人员数据已从云端刷新');
                } else {
                    // 如果没有云同步函数，至少重新加载本地数据
                    loadTeamPersonnelData();
                    renderTeamPersonnelTable();
                }
            } catch (error) {
                console.error('从云端刷新失败:', error.message);
                alert('❌ 刷新失败：' + error.message);
            }
        }, true); // 班组人员是对象类型数据
    }
}

function loadTeamPersonnelData() {
    const saved = localStorage.getItem('teamPersonnelData');
    if (saved) {
        const parsed = JSON.parse(saved);
        if (Object.keys(parsed).length > 0) {
            currentTeamPersonnelData = parsed;
            // 确保所有必需的班都有数据
            const requiredTeams = ['一班', '二班', '三班', '四班', '临时白班', '管理人员'];
            requiredTeams.forEach(team => {
                if (!currentTeamPersonnelData[team]) {
                    currentTeamPersonnelData[team] = [];
                }
            });
        } else {
            localStorage.setItem('teamPersonnelData', JSON.stringify(currentTeamPersonnelData));
        }
    } else {
        localStorage.setItem('teamPersonnelData', JSON.stringify(currentTeamPersonnelData));
    }
}

async function saveTeamPersonnelData() {
    // 保存到本地存储
    localStorage.setItem('teamPersonnelData', JSON.stringify(currentTeamPersonnelData));
    
    // 尝试保存到云端
    if (typeof syncTableData === 'function') {
        try {
            console.log('正在保存班组人员数据到云端...');
            const result = await syncTableData('teamPersonnel', 'teamPersonnelData', 'currentTeamPersonnelData', true);
            if (result.success) {
                console.log('✅ 班组人员数据已保存到云端');
            } else {
                console.warn('⚠️ 云端保存失败，将使用本地数据');
            }
        } catch (error) {
            console.error('保存到云端失败:', error.message);
        }
    }
}

function loadTeamPersonnelVersionHistory() {
    const saved = localStorage.getItem('teamPersonnelVersionHistory');
    if (saved) {
        teamPersonnelVersionHistory = JSON.parse(saved);
    }
}

function saveTeamPersonnelVersionHistory() {
    localStorage.setItem('teamPersonnelVersionHistory', JSON.stringify(teamPersonnelVersionHistory));
}

function renderTeamPersonnelTable() {
    const tableBody = document.getElementById('teamPersonnelTableBody');
    tableBody.innerHTML = '';

    const teams = ['一班', '二班', '三班', '四班', '临时白班', '管理人员'];
    const leaderNames = ['呼腾飞', '赵小红', '杨积福', '张帅', '咸月'];

    const maxLength = Math.max(...teams.map(team => (currentTeamPersonnelData[team] || []).length));

    const displayLength = isEditingTeamPersonnel ? maxLength + 1 : maxLength;

    for (let i = 0; i < displayLength; i++) {
        const row = document.createElement('tr');

        teams.forEach((team, teamIndex) => {
            const cell = document.createElement('td');
            const name = (currentTeamPersonnelData[team] || [])[i];
            const isLastRow = i === displayLength - 1;

            if (isEditingTeamPersonnel) {
                if (isLastRow) {
                    cell.className = 'empty-row-cell';
                    cell.innerHTML = `<span class="add-hint" onclick="startAddPerson(this, '${team}')">点击添加</span>`;
                } else if (name) {
                    cell.className = 'editable';
                    cell.innerHTML = `<input type="text" value="${name}" data-team="${team}" data-index="${i}" onblur="handleCellEdit(this)">`;
                } else {
                    cell.className = 'editable';
                    cell.innerHTML = `<input type="text" value="" data-team="${team}" data-index="${i}" onblur="handleCellEdit(this)" placeholder="点击添加">`;
                }
            } else if (name) {
                let className = '';
                if (leaderNames.includes(name)) {
                    className = 'team-leader';
                }
                cell.innerHTML = `<span class="name-link" onclick="showPersonCard('${name}')">${name}</span>`;
                cell.className = className;
            }

            row.appendChild(cell);
        });

        tableBody.appendChild(row);
    }
    
    setupTeamPersonnelTableHeaderFreeze();
}

function startAddPerson(element, team) {
    const cell = element.parentElement;
    cell.className = 'editable';
    cell.innerHTML = `<input type="text" value="" data-team="${team}" data-index="${(currentTeamPersonnelData[team] || []).length}" onblur="handleAddPerson(this)" placeholder="输入姓名后按回车添加">`;
    const input = cell.querySelector('input');
    input.focus();
    input.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') {
            input.blur();
        }
    });
}

function handleAddPerson(input) {
    const team = input.dataset.team;
    const newValue = input.value.trim();

    if (newValue) {
        if (!currentTeamPersonnelData[team]) {
            currentTeamPersonnelData[team] = [];
        }
        currentTeamPersonnelData[team].push(newValue);
        saveTeamPersonnelData();
    }
    renderTeamPersonnelTable();
}

function findPersonByName(name) {
    if (!name) return null;
    
    const cleanName = name.trim();
    
    let person = allPersonnelData.find(p => p.name && p.name.trim() === cleanName);
    if (person) return person;
    
    const normalizedName = cleanName.replace(/\s+/g, '');
    person = allPersonnelData.find(p => {
        if (!p.name) return false;
        return p.name.replace(/\s+/g, '') === normalizedName;
    });
    if (person) return person;
    
    const lowerName = cleanName.toLowerCase();
    person = allPersonnelData.find(p => p.name && p.name.toLowerCase() === lowerName);
    
    return person;
}

