function handleCellEdit(input) {
    const team = input.dataset.team;
    const index = parseInt(input.dataset.index);
    const newValue = input.value.trim();

    if (!currentTeamPersonnelData[team]) {
        currentTeamPersonnelData[team] = [];
    }

    if (newValue) {
        currentTeamPersonnelData[team][index] = newValue;
        saveTeamPersonnelData();
    } else if (currentTeamPersonnelData[team][index]) {
        delete currentTeamPersonnelData[team][index];
        currentTeamPersonnelData[team] = currentTeamPersonnelData[team].filter(item => item);
        saveTeamPersonnelData();
        renderTeamPersonnelTable();
    }
}

