async function saveTaskToCloud() {
    const btn = safeGetElement('saveTaskToCloudBtn');
    if (btn) {
        btn.disabled = true;
        btn.textContent = '⏳ 保存中...';
    }

    try {
        console.log('[任务云端保存] 开始增量同步任务数据...');
        
        // 获取任务数据 - 优先使用最新的 taskData，确保包含最新删除的变更
        const taskDataToSync = taskData;
        
        if (!Array.isArray(taskDataToSync) || taskDataToSync.length === 0) {
            showToast('没有任务数据需要同步', 'info');
            return;
        }

        console.log(`[任务云端保存] 当前本地任务数量: ${taskDataToSync.length}`);
        console.log(`[任务云端保存] 本地任务ID列表: ${taskDataToSync.map(t => t.id).join(', ')}`);

        // 优先使用增量同步函数
        if (typeof window.syncTaskDataIncrementally === 'function') {
            console.log('[任务云端保存] 调用增量同步函数');
            const result = await window.syncTaskDataIncrementally(taskDataToSync);
            
            console.log('[任务云端保存] 增量同步结果:', result);
            
            if (result.success) {
                showToast(result.message, 'success');
                // 更新同步时间
                localStorage.setItem('lastTaskSyncTime', new Date().toISOString());
            } else {
                showToast('同步失败: ' + result.message, 'error');
            }
        } else if (typeof window.reliableSync !== 'undefined') {
            // 回退到可靠同步模块
            console.log('[任务云端保存] 回退到可靠同步模块');
            const result = await window.reliableSync.syncToCloud('task', taskTableData);
            if (result.success) {
                showToast('数据已保存到云端', 'success');
                localStorage.setItem('lastTaskSyncTime', new Date().toISOString());
            } else {
                showToast('同步失败', 'error');
            }
        } else {
            showToast('云端同步不可用', 'warning');
        }
    } catch (error) {
        console.error('保存到云端失败:', error);
        showToast('保存到云端失败: ' + error.message, 'error');
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.textContent = '☁️ 保存到云端';
        }
    }
}

