// 检查当前用户是否可以查看指定任务
function canViewTask(task) {
    const role = getCurrentRole();
    
    // 主任可以查看所有任务
    if (role === 'topadmin') {
        return true;
    }
    
    // 管理者和普通用户不能查看待分配的任务
    if (task.status === 'pending') {
        return false;
    }
    
    return true;
}

function filterTasks() {
    const statusFilter = safeGetElement('taskStatusFilter')?.value || 'all';
    const yearFilter = safeGetElement('taskYearFilter')?.value || 'all';
    const monthFilter = safeGetElement('taskMonthFilter')?.value || 'all';
    const searchKeyword = safeGetElement('taskSearchInput')?.value || '';
    const clearBtn = safeGetElement('searchClearBtn');

    // 显示/隐藏清除按钮
    if (clearBtn) {
        clearBtn.style.display = searchKeyword.trim() ? 'flex' : 'none';
    }

    filteredTaskData = taskData.filter(task => {
        // 权限检查：管理者和普通用户不能查看待分配的任务
        if (!canViewTask(task)) {
            return false;
        }
        
        const matchStatus = statusFilter === 'all' || task.status === statusFilter;
        const matchSearch = !searchKeyword || 
            task.title.toLowerCase().includes(searchKeyword.toLowerCase()) ||
            task.assignee.toLowerCase().includes(searchKeyword.toLowerCase());
        
        // 年份筛选
        let matchYear = true;
        if (yearFilter !== 'all') {
            const taskDate = getTaskCreateDate(task);
            matchYear = taskDate && taskDate.getFullYear().toString() === yearFilter;
        }
        
        // 月份筛选
        let matchMonth = true;
        if (monthFilter !== 'all') {
            const taskDate = getTaskCreateDate(task);
            matchMonth = taskDate && String(taskDate.getMonth() + 1).padStart(2, '0') === monthFilter;
        }
        
        return matchStatus && matchSearch && matchYear && matchMonth;
    });

    renderTaskList();
}

function getTaskCreateDate(task) {
    const possibleDateFields = [task.created_at, task.update_time, task.updated_at];
    for (const dateStr of possibleDateFields) {
        if (dateStr) {
            const parsedDate = new Date(dateStr);
            if (!isNaN(parsedDate.getTime())) {
                return parsedDate;
            }
        }
    }
    return null;
}

function initYearFilter() {
    const yearFilter = safeGetElement('taskYearFilter');
    if (!yearFilter) return;
    
    const years = new Set(['all']);
    
    taskData.forEach(task => {
        const taskDate = getTaskCreateDate(task);
        if (taskDate) {
            years.add(taskDate.getFullYear().toString());
        }
    });
    
    const currentYear = new Date().getFullYear();
    for (let year = currentYear; year >= 2020; year--) {
        if (years.has(year.toString()) || year === currentYear || year === currentYear - 1) {
            years.add(year.toString());
        }
    }
    
    const sortedYears = Array.from(years).sort((a, b) => {
        if (a === 'all') return -1;
        if (b === 'all') return 1;
        return parseInt(b) - parseInt(a);
    });
    
    yearFilter.innerHTML = sortedYears.map(year => 
        `<option value="${year}">${year === 'all' ? '全部年份' : `${year}年`}</option>`
    ).join('');
}

function clearSearch() {
    const searchInput = safeGetElement('taskSearchInput');
    const clearBtn = safeGetElement('searchClearBtn');
    
    if (searchInput) {
        searchInput.value = '';
    }
    if (clearBtn) {
        clearBtn.style.display = 'none';
    }
    
    filterTasks();
}

