// ==================== 隐患排查治理模块 ====================
const HAZARD_STORAGE_KEY = 'hazardData';

let hazardData = [];
let hazardTableData = {
    headers: ['序号', '隐患标题', '隐患描述', '处理结果', '部门/单位', '报告人', '专业类别', '隐患分类', '隐患等级', '填报日期', '负责人', '优先级', '状态', '进度', '截止日期', '备注', '创建时间', '更新时间'],
    data: [],
    lastModified: new Date().toISOString()
};
let editingHazardId = null;
let filteredHazardData = [];

function loadHazards() {
    const stored = localStorage.getItem(HAZARD_STORAGE_KEY);
    if (stored) {
        const parsed = JSON.parse(stored);
        if (parsed.data) {
            hazardTableData = parsed;
            hazardData = parsed.data;
        } else {
            hazardData = Array.isArray(parsed) ? parsed : [];
            hazardTableData = {
                headers: ['序号', '隐患标题', '隐患描述', '处理结果', '部门/单位', '报告人', '专业类别', '隐患分类', '隐患等级', '填报日期', '负责人', '优先级', '状态', '进度', '截止日期', '备注', '创建时间', '更新时间'],
                data: hazardData,
                lastModified: new Date().toISOString()
            };
            saveHazards();
        }
        
        // 修复没有状态字段的隐患数据
        hazardData.forEach((hazard, index) => {
            if (!hazard.status || hazard.status === '') {
                console.log(`修复隐患 ${index} 的状态字段，设置为待班长确认`);
                hazardData[index].status = hazard.is_admin_created ? 'waitingAdminConfirm' : 'waitingLeaderConfirm';
                hazardData[index]._sync_version = (hazardData[index]._sync_version || 0) + 1;
            }
            
            // 为旧数据添加整改完成人字段（如果没有的话）
            if (!hazard.completionUser) {
                hazardData[index].completionUser = '-';
            }
            
            // 同步下划线命名的数组到驼峰命名（关键修复！确保历史记录不丢失）
            // 处理可能的字符串化数组数据
            let completionRecordsArray = hazardData[index].completion_records;
            if (!Array.isArray(completionRecordsArray)) {
                try {
                    completionRecordsArray = JSON.parse(completionRecordsArray);
                    if (!Array.isArray(completionRecordsArray)) completionRecordsArray = [];
                } catch (e) {
                    completionRecordsArray = [];
                }
            }
            let statusChangeRecordsArray = hazardData[index].status_change_records;
            if (!Array.isArray(statusChangeRecordsArray)) {
                try {
                    statusChangeRecordsArray = JSON.parse(statusChangeRecordsArray);
                    if (!Array.isArray(statusChangeRecordsArray)) statusChangeRecordsArray = [];
                } catch (e) {
                    statusChangeRecordsArray = [];
                }
            }
            let rejectRecordsArray = hazardData[index].reject_records;
            if (!Array.isArray(rejectRecordsArray)) {
                try {
                    rejectRecordsArray = JSON.parse(rejectRecordsArray);
                    if (!Array.isArray(rejectRecordsArray)) rejectRecordsArray = [];
                } catch (e) {
                    rejectRecordsArray = [];
                }
            }
            
            // 【关键修复】确保两个字段都有正确的数据
            // 优先使用下划线版本（下划线版本是同步到云端的主要字段）
            // 如果下划线版本为空但驼峰版本有数据，则从驼峰版本同步
            if (completionRecordsArray.length === 0 && Array.isArray(hazardData[index].completionRecords) && hazardData[index].completionRecords.length > 0) {
                completionRecordsArray = [...hazardData[index].completionRecords];
                hazardData[index].completion_records = completionRecordsArray;
            }
            
            if (statusChangeRecordsArray.length === 0 && Array.isArray(hazardData[index].statusChangeRecords) && hazardData[index].statusChangeRecords.length > 0) {
                statusChangeRecordsArray = [...hazardData[index].statusChangeRecords];
                hazardData[index].status_change_records = statusChangeRecordsArray;
            }
            
            if (rejectRecordsArray.length === 0 && Array.isArray(hazardData[index].rejectRecords) && hazardData[index].rejectRecords.length > 0) {
                rejectRecordsArray = [...hazardData[index].rejectRecords];
                hazardData[index].reject_records = rejectRecordsArray;
            }
            
            // 【关键修复】始终同步两个字段，确保数据一致性
            hazardData[index].completionRecords = [...completionRecordsArray];
            hazardData[index].completion_records = [...completionRecordsArray];
            hazardData[index].statusChangeRecords = [...statusChangeRecordsArray];
            hazardData[index].status_change_records = [...statusChangeRecordsArray];
            hazardData[index].rejectRecords = [...rejectRecordsArray];
            hazardData[index].reject_records = [...rejectRecordsArray];
            
            // 【新增】同步下划线命名字段到驼峰命名，确保详情页正确显示
            if (!hazardData[index].reportDate && hazardData[index].report_date) {
                hazardData[index].reportDate = hazardData[index].report_date;
            }
            if (!hazardData[index].report_date && hazardData[index].reportDate) {
                hazardData[index].report_date = hazardData[index].reportDate;
            }
            if (!hazardData[index].hazardType && hazardData[index].hazard_type) {
                hazardData[index].hazardType = hazardData[index].hazard_type;
            }
            if (!hazardData[index].hazard_type && hazardData[index].hazardType) {
                hazardData[index].hazard_type = hazardData[index].hazardType;
            }
            if (!hazardData[index].hazardLevel && hazardData[index].hazard_level) {
                hazardData[index].hazardLevel = hazardData[index].hazard_level;
            }
            if (!hazardData[index].hazard_level && hazardData[index].hazardLevel) {
                hazardData[index].hazard_level = hazardData[index].hazardLevel;
            }
            if (!hazardData[index].createTime) {
                hazardData[index].createTime = hazardData[index].created_at || hazardData[index].updated_at || new Date().toLocaleString('zh-CN');
            }
            
            // 智能计算并存储隐患进度
            hazardData[index].progress = calculateHazardProgress(hazardData[index]);
        });
    } else {
        hazardData = [];
        hazardTableData = {
            headers: ['序号', '隐患标题', '隐患描述', '处理结果', '部门/单位', '报告人', '专业类别', '隐患分类', '隐患等级', '填报日期', '负责人', '优先级', '状态', '进度', '截止日期', '备注', '创建时间', '更新时间'],
            data: hazardData,
            lastModified: new Date().toISOString()
        };
        saveHazards();
    }

    // 关键防御：加载完成后按ID去重，防止重复记录
    const beforeCount = hazardData.length;
    hazardData = dedupByKey(hazardData, 'id');
    if (beforeCount !== hazardData.length) {
        console.log(`[隐患去重] 从 ${beforeCount} 条减少到 ${hazardData.length} 条，移除 ${beforeCount - hazardData.length} 条重复`);
        saveHazards();
    }
}

/**
 * 智能计算隐患进度（隐患排查治理专用）
 * 多维度计算：状态映射 + 记录细化 + 时间辅助 + 优先级调整
 */
function calculateHazardProgress(hazard) {
    if (!hazard) return 0;
    
    // 1. 终态直接返回
    if (hazard.status === 'completed' || hazard.status === 'closed') return 100;
    if (hazard.status === 'cancelled') return 0;
    if (hazard.status === 'notExists' || hazard.status === 'notExistsByLeader') return 0;
    
    // 2. 根据状态映射基准进度
    let baseProgress = 0;
    
    // 起始阶段 - 等待开始/需要重新整改
    if (['draft', 'pending', 'waitingRectify'].includes(hazard.status)) {
        baseProgress = 5;
    }
    // 整改中 - 各级人员正在处理
    else if (['progress'].includes(hazard.status)) {
        baseProgress = 35;
    }
    else if (['leaderRectifying', 'adminRectifying'].includes(hazard.status)) {
        baseProgress = 45;
    }
    // 已确认存在但正在处理
    else if (['leaderConfirmed', 'confirmedByAdmin', 'leaderConfirmedExists'].includes(hazard.status)) {
        baseProgress = 40;
    }
    // 升级状态
    else if (hazard.status === 'escalatedToLeader') {
        baseProgress = 30;
    }
    else if (hazard.status === 'escalatedToAdmin') {
        baseProgress = 35;
    }
    else if (hazard.status === 'escalatedToTopAdmin') {
        baseProgress = 40;
    }
    // 审核阶段
    else if (hazard.status === 'waitingLeaderReview') {
        baseProgress = 55;
    }
    else if (hazard.status === 'waitingAdminReview') {
        baseProgress = 70;
    }
    // 待闭环阶段
    else if (['waitingTopAdminClose', 'waitingAdminConfirm', 'waitingTopAdminConfirm', 'waitingTopAdminHandle'].includes(hazard.status)) {
        baseProgress = 85;
    }
    // 需重新整改 - 说明之前做过一些工作但需要重做
    else if (hazard.status === 'needRectify') {
        baseProgress = 25;
    }
    // 待班长确认
    else if (hazard.status === 'waitingLeaderConfirm') {
        baseProgress = 15;
    }
    
    // 3. 记录维度：根据整改/进度/拒绝记录细化
    let recordAdjustment = 0;
    
    // 进度记录：表示有人在持续跟踪
    const progressRecords = (hazard.progress_records?.length || 0) + 
                           (hazard.progressRecords?.length || 0);
    recordAdjustment += Math.min(progressRecords * 5, 30);
    
    // 整改完成记录：表示已有实质整改工作
    const completionRecords = (hazard.completion_records?.length || 0) + 
                              (hazard.completionRecords?.length || 0);
    recordAdjustment += Math.min(completionRecords * 8, 40);
    
    // 拒绝记录：表示整改需要重新做，扣除进度
    const rejectRecords = (hazard.reject_records?.length || 0) + 
                          (hazard.rejectRecords?.length || 0);
    recordAdjustment -= Math.min(rejectRecords * 5, 20);
    
    // 升级记录：表示问题需要更高层级处理，适当增加
    const escalateRecords = (hazard.escalate_records?.length || 0) + 
                           (hazard.escalateRecords?.length || 0);
    recordAdjustment += Math.min(escalateRecords * 3, 15);
    
    // 4. 时间维度：结合截止日期
    let progress = baseProgress + recordAdjustment;
    
    const timeProgress = calculateTimeBasedProgress(hazard);
    if (timeProgress > 0) {
        // 结合30%的时间进度因素，避免完全被时间主导
        progress = Math.round(progress * 0.7 + timeProgress * 0.3);
    }
    
    // 5. 超期处理：超期隐患显示更高的"紧迫感"进度
    if (hazard.deadline && isOverdue(hazard.deadline, hazard.status)) {
        progress = Math.max(progress, 80);
    }
    
    // 6. 优先级微调：高优先级的进行中隐患显示稍高进度
    if (hazard.priority === 'high' && progress > 0 && progress < 100) {
        progress = Math.min(progress + 5, 95);
    }
    
    // 限制范围并返回
    progress = Math.min(Math.max(progress, 0), 95);
    return progress;
}

/**
 * 获取隐患卡片显示的进度值
 * 优先使用用户手动设置的进度，否则使用智能计算的进度
 */
function getHazardDisplayProgress(hazard) {
    if (!hazard) return 0;
    
    // 终态直接返回
    if (hazard.status === 'completed' || hazard.status === 'closed') return 100;
    if (hazard.status === 'cancelled') return 0;
    if (hazard.status === 'notExists' || hazard.status === 'notExistsByLeader') return 0;
    
    // 如果用户明确设置过进度值（非0的有意义值），优先显示
    if (hazard.progress !== undefined && hazard.progress !== null && 
        hazard.progress !== 0 && hazard.progress > 0 && hazard.progress < 100) {
        return hazard.progress;
    }
    
    // 使用智能计算的进度
    return calculateHazardProgress(hazard);
}

function checkAndUpdateOverdueHazards() {
    const now = new Date();
    let hasChanges = false;
    
    hazardData.forEach((hazard, index) => {
        if (hazard.deadline && hazard.status !== 'completed' && hazard.status !== 'closed' && hazard.status !== 'cancelled') {
            const deadline = new Date(hazard.deadline);
            if (now > deadline) {
                hazard.is_overdue = true;
                hasChanges = true;
            }
        }
    });
    
    if (hasChanges) {
        saveHazards();
    }
}

function saveHazards() {
    // 保存前防御：确保无重复ID
    const originalLen = hazardData.length;
    hazardData = dedupByKey(hazardData, 'id');
    if (originalLen !== hazardData.length) {
        console.log(`[隐患去重] 保存时移除 ${originalLen - hazardData.length} 条重复记录`);
    }
    hazardTableData.data = hazardData;
    hazardTableData.lastModified = new Date().toISOString();
    localStorage.setItem(HAZARD_STORAGE_KEY, JSON.stringify(hazardTableData));
}

async function syncDataInBatches(data, batchSize, syncFunction, moduleKey, loadingToast) {
    // 【优化版】直接一次传递全部数据给批量同步函数，不再分批、不再等待
    // 批量同步函数内部已处理 GET + 一次 POST upsert + 一次 DELETE，请求数已大幅减少
    const result = await syncFunction(data);

    if (window.DynamicSync && loadingToast && result.success) {
        window.DynamicSync.updateToast(loadingToast, `数据已同步至云端... 100%`, 'loading', 0);
    }

    return result;
}

async function saveHazardToCloud() {
    const moduleKey = 'hazard';
    const btn = safeGetElement('saveHazardToCloudBtn');
    const buttonText = '<span class="btn-icon">☁️</span> 保存到云端';
    const BATCH_SIZE = 50;
    
    if (window.DynamicSync) {
        const cooldown = window.DynamicSync.checkCooldown(moduleKey);
        if (!cooldown.canClick) {
            window.DynamicSync.showCooldownWarning(moduleKey);
            return;
        }
    }
    
    if (!hazardData || hazardData.length === 0) {
        if (window.DynamicSync) {
            window.DynamicSync.showToast('当前没有隐患数据需要同步', 'info');
        } else {
            showToast('没有隐患数据需要同步', 'info');
        }
        return;
    }
    
    let loadingToast = null;
    if (window.DynamicSync) {
        loadingToast = window.DynamicSync.showToast('⚠️ 正在同步隐患排查治理数据... 0%', 'loading', 0);
        window.DynamicSync.updateStatus(moduleKey, 'syncing');
    }
    
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span class="btn-icon">⏳</span> 同步中...';
    }

    try {
        console.log('[隐患云端保存] 开始分批增量同步隐患数据...');
        
        if (typeof window.syncHazardDataIncrementally === 'function') {
            console.log('[隐患云端保存] 调用分批增量同步');
            
            const syncFunction = async (batch) => {
                return await window.syncHazardDataIncrementally(batch);
            };
            
            const result = await syncDataInBatches(hazardData, BATCH_SIZE, syncFunction, moduleKey, loadingToast);
            
            console.log('[隐患云端保存] 分批增量同步结果:', result);
            
            if (result.success) {
                if (window.DynamicSync) {
                    window.DynamicSync.updateToast(loadingToast, `✅ 隐患排查治理同步成功！${result.message}`, 'success');
                    window.DynamicSync.updateStatus(moduleKey, 'success', '同步完成');
                    window.DynamicSync.setCooldown(moduleKey, btn);
                    localStorage.setItem(`lastSyncTime_${moduleKey}`, new Date().toISOString());
                } else {
                    showToast(result.message, 'success');
                    localStorage.setItem('lastHazardSyncTime', new Date().toISOString());
                }
                
                if (typeof updateBottomBarStats === 'function') {
                    await updateBottomBarStats();
                }
            } else {
                throw new Error(result.message || '同步失败');
            }
        } else if (typeof window.reliableSync !== 'undefined') {
            console.log('[隐患云端保存] 回退到可靠同步模块');
            const result = await window.reliableSync.syncToCloud('hazard', hazardTableData);
            if (result.success) {
                if (window.DynamicSync) {
                    window.DynamicSync.updateToast(loadingToast, '✅ 隐患排查治理同步成功！', 'success');
                    window.DynamicSync.updateStatus(moduleKey, 'success', '同步完成');
                    window.DynamicSync.setCooldown(moduleKey, btn);
                    localStorage.setItem(`lastSyncTime_${moduleKey}`, new Date().toISOString());
                } else {
                    showToast('数据已保存到云端', 'success');
                    localStorage.setItem('lastHazardSyncTime', new Date().toISOString());
                }
            } else {
                throw new Error('同步失败');
            }
        } else {
            if (window.DynamicSync) {
                window.DynamicSync.updateToast(loadingToast, '⚠️ 云端同步功能不可用', 'warning');
                window.DynamicSync.updateStatus(moduleKey, 'pending', '同步功能不可用');
            } else {
                showToast('云端同步不可用', 'warning');
            }
            
            if (btn) {
                btn.disabled = false;
                btn.innerHTML = buttonText;
            }
            return;
        }
    } catch (error) {
        console.error('[隐患云端保存] 失败:', error);
        
        let errorMsg = error.message || error.toString();
        if (errorMsg.includes('Could not find the') && errorMsg.includes('column')) {
            errorMsg = '云端表结构不匹配，请联系管理员';
        } else if (errorMsg.includes('uuid')) {
            errorMsg = 'ID格式不匹配，数据已保存到本地';
        }
        
        if (window.DynamicSync) {
            window.DynamicSync.updateToast(loadingToast, `❌ 隐患排查治理同步失败: ${errorMsg}`, 'error');
            window.DynamicSync.updateStatus(moduleKey, 'error', '同步失败');
            
            if (window.OfflineQueue) {
                window.OfflineQueue.add({
                    module: moduleKey,
                    type: 'update',
                    recordId: 'batch',
                    data: hazardData
                });
            }
        } else {
            showToast('保存到云端失败: ' + errorMsg, 'error');
        }
        
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = buttonText;
        }
    }
}

function refreshHazardStats() {
    const statusFilter = safeGetElement('hazardStatusFilter')?.value || 'all';
    const yearFilter = safeGetElement('hazardYearFilter')?.value || 'all';
    const monthFilter = safeGetElement('hazardMonthFilter')?.value || 'all';
    
    const filteredData = hazardData.filter(hazard => {
        if (!canViewHazard(hazard)) {
            return false;
        }
        
        let matchYear = true;
        if (yearFilter !== 'all') {
            const hazardDate = getHazardCreateDate(hazard);
            matchYear = hazardDate && hazardDate.getFullYear().toString() === yearFilter;
        }
        
        let matchMonth = true;
        if (monthFilter !== 'all') {
            const hazardDate = getHazardCreateDate(hazard);
            matchMonth = hazardDate && String(hazardDate.getMonth() + 1).padStart(2, '0') === monthFilter;
        }
        
        return matchYear && matchMonth;
    });
    
    const pending = filteredData.filter(t => t.status === 'draft').length;
    const progress = filteredData.filter(t => 
        t.status === 'waitingLeaderReview' || 
        t.status === 'leaderRectifying' || 
        t.status === 'waitingAdminReview' ||
        t.status === 'adminRectifying' ||
        t.status === 'waitingTopAdminClose'
    ).length;
    const completed = filteredData.filter(t => t.status === 'completed').length;
    const closed = filteredData.filter(t => t.status === 'closed').length;

    const statPending = safeGetElement('hazardStatPending');
    const statProgress = safeGetElement('hazardStatProgress');
    const statCompleted = safeGetElement('hazardStatCompleted');
    const statClosed = safeGetElement('hazardStatClosed');

    if (statPending) statPending.textContent = pending;
    if (statProgress) statProgress.textContent = progress;
    if (statCompleted) statCompleted.textContent = completed;
    if (statClosed) statClosed.textContent = closed;
}

function canViewHazard(task) {
    const role = getCurrentRole();
    if (role === 'topadmin') {
        return true;
    }
    if (task.status === 'pending' || task.status === 'draft') {
        return false;
    }
    return true;
}

function filterHazards() {
    const statusFilter = safeGetElement('hazardStatusFilter')?.value || 'all';
    const yearFilter = safeGetElement('hazardYearFilter')?.value || 'all';
    const monthFilter = safeGetElement('hazardMonthFilter')?.value || 'all';
    const searchKeyword = safeGetElement('hazardSearchInput')?.value || '';
    const clearBtn = safeGetElement('hazardSearchClearBtn');

    if (clearBtn) {
        clearBtn.style.display = searchKeyword.trim() ? 'flex' : 'none';
    }

    filteredHazardData = hazardData.filter(hazard => {
        if (!canViewHazard(hazard)) {
            return false;
        }
        
        const matchStatus = statusFilter === 'all' || hazard.status === statusFilter;
        const matchSearch = !searchKeyword || 
            hazard.title.toLowerCase().includes(searchKeyword.toLowerCase()) ||
            hazard.assignee.toLowerCase().includes(searchKeyword.toLowerCase());
        
        let matchYear = true;
        if (yearFilter !== 'all') {
            const hazardDate = getHazardCreateDate(hazard);
            matchYear = hazardDate && hazardDate.getFullYear().toString() === yearFilter;
        }
        
        let matchMonth = true;
        if (monthFilter !== 'all') {
            const hazardDate = getHazardCreateDate(hazard);
            matchMonth = hazardDate && String(hazardDate.getMonth() + 1).padStart(2, '0') === monthFilter;
        }
        
        return matchStatus && matchSearch && matchYear && matchMonth;
    });

    // 排序逻辑：1. 过期未完成的排在最前面 2. 按填报日期正序排列（最早的在前）
    filteredHazardData.sort((a, b) => {
        const aOverdue = isOverdue(a.deadline, a.status);
        const bOverdue = isOverdue(b.deadline, b.status);
        
        // 过期的排在前面
        if (aOverdue && !bOverdue) return -1;
        if (!aOverdue && bOverdue) return 1;
        
        // 按填报日期正序排列（最早的在前）- 使用与卡片显示一致的字段
        const dateA = new Date(a.report_date || a.reportDate || a.created_at || a.update_time || Date.now());
        const dateB = new Date(b.report_date || b.reportDate || b.created_at || b.update_time || Date.now());
        return dateA - dateB;
    });

    // 刷新统计卡片（根据筛选条件）
    refreshHazardStats();
    renderHazardList();
}

function getHazardCreateDate(hazard) {
    const possibleDateFields = [hazard.created_at, hazard.update_time, hazard.updated_at];
    for (const dateStr of possibleDateFields) {
        if (dateStr) {
            const parsedDate = new Date(dateStr);
            if (!isNaN(parsedDate.getTime())) {
                return parsedDate;
            }
        }
    }
    return null;
}

function initHazardYearFilter() {
    const yearFilter = safeGetElement('hazardYearFilter');
    if (!yearFilter) return;
    
    const years = new Set(['all']);
    
    hazardData.forEach(hazard => {
        const hazardDate = getHazardCreateDate(hazard);
        if (hazardDate) {
            years.add(hazardDate.getFullYear().toString());
        }
    });
    
    const currentYear = new Date().getFullYear();
    for (let year = currentYear; year >= 2020; year--) {
        if (years.has(year.toString()) || year === currentYear || year === currentYear - 1) {
            years.add(year.toString());
        }
    }
    
    const sortedYears = Array.from(years).sort((a, b) => {
        if (a === 'all') return -1;
        if (b === 'all') return 1;
        return parseInt(b) - parseInt(a);
    });
    
    yearFilter.innerHTML = sortedYears.map(year => 
        `<option value="${year}">${year === 'all' ? '全部年份' : `${year}年`}</option>`
    ).join('');
}

function clearHazardSearch() {
    const searchInput = safeGetElement('hazardSearchInput');
    const clearBtn = safeGetElement('hazardSearchClearBtn');
    
    if (searchInput) {
        searchInput.value = '';
    }
    if (clearBtn) {
        clearBtn.style.display = 'none';
    }
    
    filterHazards();
}

function isOverdue(deadline, status) {
    if (!deadline) return false;
    const deadlineDate = new Date(deadline);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    deadlineDate.setHours(0, 0, 0, 0);
    const completedStatuses = ['closed', 'completed', 'cancelled', 'notExists', 'notExistsByLeader'];
    return deadlineDate < today && !completedStatuses.includes(status);
}

// 获取用户显示名和角色
function getUserWithRoleDisplay(username) {
    if (!username) return '-';
    
    const displayName = getUserDisplayName(username);
    
    // 获取用户角色
    let role = '';
    try {
        const user = users.find(u => u && u.username && u.username === username);
        if (user && user.role) {
            role = getHazardRoleText(user.role);
        }
    } catch (e) {
        console.warn('获取用户角色失败:', e);
    }
    
    return role ? `${displayName}(${role})` : displayName;
}

// 获取用户显示名称（优先真实姓名，否则返回账号）
function getUserDisplayName(username) {
    if (!username) return '未知';
    
    // 1. 先从系统用户表（登录用户）查找
    try {
        const user = users.find(u => 
            u && u.username && u.username === username
        );
        if (user) {
            // 优先返回真实姓名（支持两种字段名：realName 和 realname）
            if (user.realName) return user.realName;
            if (user.realname) return user.realname;
            if (user.name) return user.name;
        }
    } catch (e) {
        console.warn('读取系统用户数据失败:', e);
    }
    
    // 2. 再从 localStorage 读取人员数据（人员管理模块）
    try {
        const saved = localStorage.getItem('personnelData');
        if (saved) {
            const personnelData = JSON.parse(saved);
            if (Array.isArray(personnelData)) {
                // 查找匹配的人员
                let personnel = personnelData.find(p => 
                    p && p.name && p.name === username
                );
                
                // 如果没找到，按人员编号匹配
                if (!personnel) {
                    personnel = personnelData.find(p => 
                        p && p.personnelNo && p.personnelNo === username
                    );
                }
                
                // 如果还没找到，检查是否有 username 字段
                if (!personnel) {
                    personnel = personnelData.find(p => 
                        p && p.username && p.username === username
                    );
                }
                
                if (personnel && personnel.name) {
                    return personnel.name;
                }
            }
        }
    } catch (e) {
        console.warn('读取人员数据失败:', e);
    }
    
    // 3. 如果都没找到，返回原始用户名
    return username;
}

function renderHazardList() {
    const hazardList = safeGetElement('hazardList');
    const emptyState = safeGetElement('hazardEmptyState');

    if (!hazardList) return;

    if (filteredHazardData.length === 0) {
        if (emptyState) emptyState.style.display = 'block';
        hazardList.innerHTML = '<div class="empty-state"><div class="empty-icon">🔍</div><p>暂无隐患数据</p><p class="empty-hint">点击"添加隐患"创建新的隐患记录</p></div>';
        return;
    }

    if (emptyState) emptyState.style.display = 'none';

    const role = getCurrentRole();
    const currentUser = getCurrentUserInfo();
    const currentUsername = currentUser ? currentUser.username : '';
    const isAdmin = role === 'topadmin';
    const isManager = role === 'manager';
    const isLeader = role === 'leader';
    const isUser = role === 'user';

    hazardList.innerHTML = filteredHazardData.map(hazard => {
        let cardClass = 'task-card';
        const disabledStatuses = ['closed', 'cancelled', 'notExists', 'notExistsByLeader'];
        if (disabledStatuses.includes(hazard.status)) {
            cardClass = 'task-card disabled-card';
        } else if (isOverdue(hazard.deadline, hazard.status)) {
            cardClass = 'task-card overdue';
        }
        const statusClass = getHazardStatusClass(hazard.status);
        
        // 获取负责人姓名和角色
        const assigneeName = getUserDisplayName(hazard.assignee);
        const assigneeRole = hazard.assigneeRole || '';
        const assigneeInfo = assigneeRole ? `${assigneeName}(${getHazardRoleText(assigneeRole)})` : assigneeName;
        
        // 获取创建者信息
        const creatorName = hazard.creator ? getUserDisplayName(hazard.creator) : (hazard.assignee || '');
        const isCreator = hazard.creator === currentUsername;
        
        // 获取填报日期
        const reportDate = hazard.report_date || hazard.reportDate || hazard.created_at || hazard.update_time || '';
        const formattedReportDate = reportDate ? formatDate(reportDate) : '';
        
        // 获取专业类别和隐患分类
        const category = hazard.category || hazard.hazardCategory || hazard.profession || '';
        const hazardType = hazard.hazard_type || hazard.hazardType || hazard.type || '';
        
        // 获取描述（截断显示）
        const description = hazard.description || hazard.desc || hazard.content || '';
        const shortDescription = description.length > 60 ? description.substring(0, 60) + '...' : description;
        
        // 智能计算显示进度
        const displayProgress = getHazardDisplayProgress(hazard);
        
        // 判断是否可以编辑
        const canEdit = isAdmin || isManager || (isLeader && isCreator) || (isUser && isCreator && (hazard.status === 'draft' || hazard.status === 'pending' || hazard.status === 'progress'));
        
        // 判断是否可以删除
        const canDelete = isAdmin || isManager || (isLeader && isCreator) || (isUser && isCreator && hazard.status === 'draft');
        
        // 判断是否可以更新状态
        const canChangeStatus = isAdmin || 
                               (isManager && ['pending', 'progress', 'waitingAdminReview', 'completed'].includes(hazard.status)) || 
                               (isLeader && ['pending', 'leaderRectifying', 'waitingLeaderReview', 'completed'].includes(hazard.status)) || 
                               (isUser && isCreator && ['draft', 'pending', 'progress', 'waitingLeaderReview', 'completed'].includes(hazard.status));
        
        // 构建信息元数据区
        let metaInfo = '<div class="task-meta">';
        metaInfo += `<div><span style="color: #718096;">📅 填报: ${formattedReportDate}</span></div>`;
        if (hazard.deadline) {
            const deadlineClass = isOverdue(hazard.deadline, hazard.status) ? 'color: #e53e3e; font-weight: 600;' : 'color: #718096;';
            metaInfo += `<div><span style="${deadlineClass}">⏰ 截止: ${hazard.deadline}</span></div>`;
        }
        if (category) {
            metaInfo += `<div><span style="color: #667eea; font-weight: 500;">📁 ${escapeHtml(category)}</span></div>`;
        }
        if (hazardType) {
            metaInfo += `<div><span style="color: #48bb78; font-weight: 500;">🏷️ ${escapeHtml(hazardType)}</span></div>`;
        }
        if (creatorName && creatorName !== assigneeName) {
            metaInfo += `<div><span style="color: #4a5568;">👤 填报人: ${escapeHtml(creatorName)}</span></div>`;
        }
        metaInfo += '</div>';
        
        // 构建描述区
        let descriptionHtml = '';
        if (shortDescription) {
            descriptionHtml = `<div class="task-description" style="padding: 8px 12px; background: #f7fafc; border-radius: 8px; margin-bottom: 10px; color: #4a5568; font-size: 13px; line-height: 1.5; border-left: 3px solid #667eea;">${escapeHtml(shortDescription)}</div>`;
        }
        
        // 构建操作按钮
        let actionsHtml = '';
        if (canEdit || canDelete || canChangeStatus) {
            actionsHtml = '<div class="card-actions" onclick="event.stopPropagation();">';
            // 查看按钮始终显示
            actionsHtml += `<button class="card-action-btn btn-view" onclick="openHazardDetailModal('${hazard.id}')">📄 查看详情</button>`;
            
            if (canEdit) {
                actionsHtml += `<button class="card-action-btn btn-edit" onclick="openEditHazardModal('${hazard.id}')">✏️ 编辑</button>`;
            }
            
            if (canChangeStatus && !disabledStatuses.includes(hazard.status)) {
                actionsHtml += `<button class="card-action-btn btn-status" onclick="openHazardStatusChangeModal('${hazard.id}')">🔄 状态变更</button>`;
            }
            
            if (canDelete) {
                actionsHtml += `<button class="card-action-btn btn-delete" onclick="deleteHazard('${hazard.id}')">🗑️ 删除</button>`;
            }
            
            actionsHtml += '</div>';
        }
        
        return `
        <div class="${cardClass}" data-hazard-id="${hazard.id}" onclick="openHazardDetailModal('${hazard.id}')">
            <div class="task-header">
                <div class="task-title">${escapeHtml(hazard.title)}</div>
                <div class="task-status ${statusClass}">${getHazardStatusText(hazard.status)}</div>
            </div>
            <div class="task-info">
                <span class="task-assignee">👁️ ${escapeHtml(assigneeName)}${assigneeRole ? `(${getHazardRoleText(assigneeRole)})` : ''}</span>
                <span class="task-priority priority-${hazard.priority}">${getHazardPriorityText(hazard.priority)}</span>
            </div>
            ${metaInfo}
            ${descriptionHtml}
            <div class="task-progress-bar">
                <div class="task-progress-fill" style="width: ${displayProgress}%"></div>
            </div>
            <div class="task-footer">
                <span class="task-progress-text">进度 ${displayProgress}%</span>
                <span class="task-deadline">${hazard.deadline ? `⏰ ${hazard.deadline}` : ''}</span>
            </div>
            ${actionsHtml}
        </div>
    `}).join('');
}

function getHazardStatusText(status) {
    const statusMap = {
        'draft': '草稿',
        'pending': '未开始',
        'progress': '进行中',
        'completed': '已完成',
        'closed': '已闭环',
        'waitingLeaderReview': '待班长审核',
        'leaderRectifying': '班长整改中',
        'waitingAdminReview': '待管理人员审核',
        'adminRectifying': '管理人员整改中',
        'waitingTopAdminClose': '待主任终审',
        'cancelled': '已撤销',
        'waitingLeaderConfirm': '待班长确认',
        'needRectify': '需重新整改',
        'waitingRectify': '待整改',
        'waitingTopAdminClose': '待主任闭环',
        'escalatedToLeader': '已升级至班长',
        'escalatedToAdmin': '已升级至管理人员',
        'escalatedToTopAdmin': '已升级至主任',
        'confirmedByAdmin': '管理人员已确认',
        'notExists': '隐患不存在',
        'notExistsByLeader': '班长确认不存在',
        'leaderConfirmed': '班长已确认',
        'waitingTopAdminConfirm': '等待主任确认',
        'waitingTopAdminHandle': '等待主任处理',
        'leaderConfirmedExists': '班长已确认存在'
    };
    return statusMap[status] || status || '未知状态';
}

const HAZARD_STATUS_CLASS_MAP = {
    'draft': 'status-pending',
    'pending': 'status-pending',
    'progress': 'status-progress',
    'completed': 'status-completed',
    'closed': 'status-disabled',
    'waitingLeaderReview': 'status-pending',
    'leaderRectifying': 'status-progress',
    'waitingAdminReview': 'status-pending',
    'adminRectifying': 'status-progress',
    'waitingTopAdminClose': 'status-pending',
    'cancelled': 'status-disabled',
    'waitingLeaderConfirm': 'status-pending',
    'needRectify': 'status-progress',
    'waitingRectify': 'status-pending',
    'waitingTopAdminClose': 'status-pending',
    'escalatedToLeader': 'status-progress',
    'escalatedToAdmin': 'status-progress',
    'escalatedToTopAdmin': 'status-progress',
    'leaderConfirmedExists': 'status-progress',
    'notExistsByLeader': 'status-disabled',
    'confirmedByAdmin': 'status-progress',
    'notExists': 'status-disabled',
    'waitingAdminConfirm': 'status-pending',
    'leaderConfirmed': 'status-progress',
    'waitingTopAdminConfirm': 'status-pending',
    'waitingTopAdminHandle': 'status-pending',
    'adminRectifying': 'status-progress'
};

function getHazardStatusClass(status) {
    return HAZARD_STATUS_CLASS_MAP[status] || 'status-pending';
}

function getHazardPriorityText(priority) {
    const priorityMap = {
        high: '高',
        medium: '中',
        low: '低'
    };
    return priorityMap[priority] || priority;
}

function getHazardCreatorRole(hazard) {
    if (!hazard) return 'user';
    
    const creator = hazard.creator || hazard.created_by || hazard.assignee || '';
    
    // 如果没有创建者，返回 user
    if (!creator) {
        console.log('[getHazardCreatorRole] 没有创建者，返回 user');
        return 'user';
    }
    
    // 如果有 creatorRole 字段，直接使用
    if (hazard.creatorRole) {
        console.log('[getHazardCreatorRole] 使用 hazard.creatorRole:', hazard.creatorRole);
        return hazard.creatorRole;
    }
    
    // 尝试从 personnelData 中查找角色
    try {
        const personnelData = JSON.parse(localStorage.getItem('personnelData') || '[]');
        const creatorInfo = personnelData.find(p => 
            (p.name && p.name === creator) || 
            (p.username && p.username === creator)
        );
        if (creatorInfo && creatorInfo.role) {
            console.log('[getHazardCreatorRole] 从 personnelData 找到角色:', creatorInfo.role, '创建者:', creator);
            return creatorInfo.role;
        }
    } catch (e) {
        console.log('[getHazardCreatorRole] 查找 personnelData 出错:', e);
    }
    
    // 尝试从 personnelList 中查找（如果存在）
    try {
        const personnelList = JSON.parse(localStorage.getItem('personnelList') || '[]');
        const creatorInfo = personnelList.find(p => 
            (p.name && p.name === creator) || 
            (p.username && p.username === creator)
        );
        if (creatorInfo && creatorInfo.role) {
            console.log('[getHazardCreatorRole] 从 personnelList 找到角色:', creatorInfo.role, '创建者:', creator);
            return creatorInfo.role;
        }
    } catch (e) {
        console.log('[getHazardCreatorRole] 查找 personnelList 出错:', e);
    }
    
    // 如果是班长用户名模式，返回 leader
    if (creator.includes('班长') || creator.includes('leader')) {
        return 'leader';
    }
    
    // 如果是管理人员/管理员模式，返回 manager
    if (creator.includes('管理') || creator.includes('admin') || creator.includes('manager')) {
        return 'manager';
    }
    
    // 默认返回 user 角色
    console.log('[getHazardCreatorRole] 未找到角色，默认返回 user', '创建者:', creator);
    return 'user';
}

function loadHazardAssignees() {
    const input = safeGetElement('hazardAssignee');
    const datalist = safeGetElement('hazardAssigneeList');
    if (!input || !datalist) return;

    // 从班组人员模块获取人员列表
    const teamPersonnelData = JSON.parse(localStorage.getItem('teamPersonnelData') || '{}');
    const names = [];
    for (const team in teamPersonnelData) {
        if (Array.isArray(teamPersonnelData[team])) {
            teamPersonnelData[team].forEach(name => {
                if (name && !names.includes(name)) {
                    names.push(name);
                }
            });
        }
    }

    // 添加当前用户作为默认选项（如果有）
    const currentUser = getCurrentUserInfo();
    if (currentUser.name && !names.includes(currentUser.name)) {
        names.unshift(currentUser.name);
    }

    // 填充datalist
    datalist.innerHTML = names.map(name => `<option value="${escapeHtml(name)}">`).join('');
    
    // 设置placeholder提示
    input.placeholder = '请选择或输入报告人';
}

function openAddHazardModal(hazardId = null) {
    const modal = safeGetElement('addHazardModal');
    const title = safeGetElement('addHazardTitle');
    const form = safeGetElement('addHazardForm');
    const assigneeInput = safeGetElement('hazardAssignee');

    if (!modal || !title || !form) return;
    
    // 所有人都可以添加隐患，不需要权限检查
    if (hazardId) {
        const hazard = hazardData.find(t => t.id === hazardId);
        if (hazard && !canEditHazard(hazard)) {
            showToast('您没有权限编辑此隐患', 'error');
            return;
        }
    }
    
    editingHazardId = hazardId;
    loadHazardAssignees();
    
    const statusSelect = safeGetElement('hazardStatus');
    const progressInput = safeGetElement('hazardProgress');
    const role = getCurrentRole();
    // 只有主任可以编辑状态和进度条
    statusSelect.disabled = role !== 'topadmin';
    progressInput.disabled = role !== 'topadmin';
    
    // 只有主任账号可以修改报告人（基于角色判断，而非具体用户名）
    const canModifyReporter = role === 'topadmin';
    if (canModifyReporter) {
        assigneeInput.disabled = false;
        assigneeInput.removeAttribute('disabled');
    } else {
        assigneeInput.disabled = true;
        assigneeInput.setAttribute('disabled', 'disabled');
    }

    if (hazardId) {
        const hazard = hazardData.find(t => t.id === hazardId);
        if (hazard) {
            title.textContent = '✏️ 编辑隐患';
            safeGetElement('hazardTitle').value = hazard.title;
            safeGetElement('hazardDescription').value = hazard.description;
            safeGetElement('hazardAssignee').value = hazard.assignee;
            safeGetElement('hazardPriority').value = hazard.priority;
            safeGetElement('hazardDeadline').value = hazard.deadline;
            safeGetElement('hazardStatus').value = hazard.status;
            safeGetElement('hazardProgress').value = hazard.progress;
            safeGetElement('hazardProgressValue').textContent = hazard.progress + '%';
            safeGetElement('hazardRemark').value = hazard.remark || '';
            safeGetElement('hazardCompletionNote').value = hazard.completionNote || '';
            // 台账字段 - 同时支持驼峰和下划线两种命名
            safeGetElement('hazardReportDate').value = hazard.reportDate || hazard.report_date || '';
            safeGetElement('hazardDepartment').value = hazard.department || '';
            // hazardReporter 已移除，报告人通过 hazardAssignee 选择器处理
            safeGetElement('hazardCategory').value = hazard.category || '';
            safeGetElement('hazardType').value = hazard.hazardType || hazard.hazard_type || '';
            safeGetElement('hazardLevel').value = hazard.hazardLevel || hazard.hazard_level || '';
            // hazardResult 已移除，处理结果由系统自动记录

            const completionNoteGroup = safeGetElement('hazardCompletionNoteGroup');
            if (completionNoteGroup) {
                completionNoteGroup.style.display = 'none';
            }
            
            const rejectReasonGroup = safeGetElement('hazardRejectReasonGroup');
            if (rejectReasonGroup) {
                rejectReasonGroup.style.display = 'none';
            }
            
            const reformNoteGroup = safeGetElement('hazardReformNoteGroup');
            if (reformNoteGroup) {
                reformNoteGroup.style.display = 'none';
            }
        }
    } else {
        title.textContent = '➕ 新建隐患';
        
        // 先设置默认值，再重置表单（确保默认值不被清空）
        const now = new Date();
        const formattedDate = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
        
        form.reset();
        
        safeGetElement('hazardProgress').value = 0;
        safeGetElement('hazardProgressValue').textContent = '0%';
        
        // 设置报告人默认值为当前登录用户的真实姓名（不可修改，除主任外）
        const currentUser = getCurrentUserInfo();
        if (currentUser) {
            const displayName = getUserDisplayName(currentUser.username || currentUser.name || '');
            safeGetElement('hazardAssignee').value = displayName;
        }
        
        // 设置填报日期默认值为当前日期（必须在reset之后设置）
        safeGetElement('hazardReportDate').value = formattedDate;

        const completionNoteGroup = safeGetElement('hazardCompletionNoteGroup');
        if (completionNoteGroup) {
            completionNoteGroup.style.display = 'none';
        }
        const rejectReasonGroup = safeGetElement('hazardRejectReasonGroup');
        if (rejectReasonGroup) {
            rejectReasonGroup.style.display = 'none';
        }
        const reformNoteGroup = safeGetElement('hazardReformNoteGroup');
        if (reformNoteGroup) {
            reformNoteGroup.style.display = 'none';
        }
    }

    safeSetDisplay('addHazardModal', 'block');

    const saveBtn = safeGetElement('saveHazardBtn');
    const cancelBtn = safeGetElement('cancelAddHazardBtn');
    
    if (saveBtn) {
        saveBtn.onclick = async function() {
            const btn = this;
            btn.disabled = true;
            btn.textContent = '保存中...';
            try {
                await saveHazard({ preventDefault: function(){} });
            } catch (e) {
                console.error('保存出错:', e);
                showToast('保存出错: ' + e.message, 'error');
            } finally {
                btn.disabled = false;
                btn.textContent = '保存';
            }
        };
    }
    
    if (cancelBtn) {
        cancelBtn.onclick = function() {
            closeAddHazardModal();
        };
    }

    setTimeout(() => {
        const statusSelect = safeGetElement('hazardStatus');
        if (statusSelect) {
            statusSelect.onchange = function() {
                const status = this.value;
                const completionNoteGroup = safeGetElement('hazardCompletionNoteGroup');
                const reformNoteGroup = safeGetElement('hazardReformNoteGroup');
                const rejectReasonGroup = safeGetElement('hazardRejectReasonGroup');
                const currentRole = getCurrentRole();
                
                // 显示/隐藏完成情况说明（待班长确认、待主任闭环、已完成、已闭环时显示）
                if (completionNoteGroup) {
                    const showCompletionNote = ['waitingLeaderConfirm', 'waitingTopAdminClose', 'completed', 'closed'].includes(status);
                    completionNoteGroup.style.display = showCompletionNote ? 'block' : 'none';
                }
                
                // 显示/隐藏整改情况说明（有打回记录且状态为待班长确认/待主任闭环/已完成/已闭环时显示）
                if (reformNoteGroup) {
                    if (editingHazardId) {
                        const hazard = hazardData.find(t => t.id === editingHazardId);
                        const hasRejectRecords = hazard && hazard.reject_records && hazard.reject_records.length > 0;
                        const showReformNote = ['waitingLeaderConfirm', 'waitingTopAdminClose', 'completed', 'closed'].includes(status) && hasRejectRecords;
                        reformNoteGroup.style.display = showReformNote ? 'block' : 'none';
                    } else {
                        reformNoteGroup.style.display = 'none';
                    }
                }
                
                // 显示/隐藏打回原因（主任打回时显示）
                if (rejectReasonGroup && editingHazardId) {
                    const hazard = hazardData.find(t => t.id === editingHazardId);
                    const isTopAdmin = currentRole === 'topadmin';
                    const isRejectStatus = ['needRectify', 'leaderRectifying', 'adminRectifying'].includes(status);
                    const wasInFinalStatus = hazard && ['waitingTopAdminClose', 'completed', 'closed'].includes(hazard.status);
                    
                    rejectReasonGroup.style.display = (isTopAdmin && isRejectStatus && wasInFinalStatus) ? 'block' : 'none';
                }
            };
        }
    }, 100);
}

