// ============================================================
// 隐患操作点击保护：防止重复点击导致重复记录
// ============================================================
window._hazardActionInProgress = window._hazardActionInProgress || new Map();

function _acquireHazardActionLock(hazardId, actionName) {
    const key = `${actionName}_${hazardId}`;
    if (window._hazardActionInProgress.has(key)) {
        console.log(`[隐患操作保护] ${actionName} 正在处理中，忽略重复点击`);
        return false;
    }
    window._hazardActionInProgress.set(key, Date.now());
    return true;
}

function _releaseHazardActionLock(hazardId, actionName) {
    const key = `${actionName}_${hazardId}`;
    window._hazardActionInProgress.delete(key);
}

// 辅助函数：统一模式 - 推送记录到下划线数组，同步到驼峰数组
function _appendHazardRecord(hazardIndex, underscoreField, camelCaseField, record) {
    if (!Array.isArray(hazardData[hazardIndex][underscoreField])) {
        hazardData[hazardIndex][underscoreField] = [];
    }
    hazardData[hazardIndex][underscoreField].push(record);
    hazardData[hazardIndex][camelCaseField] = [...hazardData[hazardIndex][underscoreField]];
}

