// 升级处理操作
function escalateHazardAction(hazardId) {
    const hazard = hazardData.find(h => h.id === hazardId);
    if (!hazard) return;
    
    const role = getCurrentRole();
    const currentStatus = hazard.status;
    
    // 检查升级权限
    if (role !== 'user' && role !== 'leader' && role !== 'manager' && role !== 'topadmin') {
        showToast('您没有权限进行此操作', 'error');
        return;
    }
    
    // 根据当前状态决定升级目标状态
    let targetStatus = 'waitingLeaderReview';
    
    if (currentStatus === 'draft') {
        // 根据当前登录用户的角色判断目标状态
        if (role === 'leader') {
            targetStatus = 'waitingAdminReview';
        } else if (role === 'manager' || role === 'topadmin') {
            targetStatus = 'waitingTopAdminClose';
        } else {
            targetStatus = 'waitingLeaderReview';
        }
    } else if (currentStatus === 'leaderRectifying') {
        targetStatus = 'waitingAdminReview';
    } else if (currentStatus === 'adminRectifying') {
        targetStatus = 'waitingTopAdminClose';
    } else if (role === 'user') {
        targetStatus = 'waitingLeaderReview';
    } else if (role === 'leader') {
        targetStatus = 'waitingAdminReview';
    } else if (role === 'manager') {
        targetStatus = 'waitingTopAdminClose';
    }
    
    // 普通用户直接升级，不需要填写表单（与采样点异常一致）
    if (role === 'user') {
        escalateHazard(hazardId, targetStatus, role);
        closeHazardDetailModal();
        filterHazards();
        showToast(`已升级至${getHazardStatusText(targetStatus)}`, 'success');
        return;
    }
    
    // 班长和管理人员需要填写表单
    // 打开升级处理表单
    openEscalateHazardForm(hazardId, targetStatus);
}

function escalateHazard(hazardId, targetStatus, fromRole) {
    const index = hazardData.findIndex(t => t.id === hazardId);
    if (index === -1) {
        showToast('隐患不存在', 'error');
        return;
    }
    
    // 权限检查：普通用户、班长、管理人员、主任都可以升级（但主任一般不需要）
    const currentRole = getCurrentRole();
    if (currentRole !== 'user' && currentRole !== 'leader' && currentRole !== 'manager' && currentRole !== 'topadmin') {
        showToast('您没有权限进行此操作', 'error');
        return;
    }
    
    const now = new Date().toLocaleString('zh-CN');
    const currentUser = getCurrentUserInfo();
    const currentStatus = hazardData[index].status;
    
    hazardData[index].status = targetStatus;
    hazardData[index].update_time = now;
    hazardData[index].updated_at = new Date().toISOString();
    hazardData[index]._sync_version = (hazardData[index]._sync_version || 0) + 1;
    
    if (!hazardData[index].escalate_records || !Array.isArray(hazardData[index].escalate_records)) hazardData[index].escalate_records = [];
    if (!hazardData[index].escalateRecords || !Array.isArray(hazardData[index].escalateRecords)) hazardData[index].escalateRecords = [];
    const escalateRec = {
        time: now,
        from_role: fromRole,
        to_role: getTargetRole(targetStatus),
        current_progress: '当前操作人无法整改，请求升级处理',
        reason: '当前操作人无法完成整改',
        next_step_advice: '请上级处理',
        operator: {
            username: currentUser.username || currentUser.name || '未知',
            name: currentUser.username || currentUser.name || '未知',
            role: currentUser.role || ''
        },
        fromRole: fromRole,
        toRole: getTargetRole(targetStatus),
        currentProgress: '当前操作人无法整改，请求升级处理',
        nextStepAdvice: '请上级处理'
    };
    hazardData[index].escalate_records.push(escalateRec);
    hazardData[index].escalateRecords = [...hazardData[index].escalate_records];
    
    if (!hazardData[index].status_change_records || !Array.isArray(hazardData[index].status_change_records)) hazardData[index].status_change_records = [];
    if (!hazardData[index].statusChangeRecords || !Array.isArray(hazardData[index].statusChangeRecords)) hazardData[index].statusChangeRecords = [];
    const statusRec = {
        time: now,
        from_status: currentStatus,
        to_status: targetStatus,
        operator: currentUser.username || currentUser.name || '未知',
        operator_role: fromRole,
        fromStatus: currentStatus,
        toStatus: targetStatus,
        operatorRole: fromRole
    };
    hazardData[index].status_change_records.push(statusRec);
    hazardData[index].statusChangeRecords = [...hazardData[index].status_change_records];
    
    saveHazards();
    refreshHazardStats();
    filterHazards();
    closeHazardDetailModal();
    
    const targetRoleText = getTargetRoleText(targetStatus);
    showToast(`已升级至${targetRoleText}处理`, 'success');
    logAudit('hazard', 'update', `${fromRole}升级隐患至${targetRoleText}: ${hazardData[index].title}`);
}

function getTargetRole(targetStatus) {
    const roleMap = {
        'waitingLeaderReview': 'leader',
        'waitingAdminReview': 'manager',
        'waitingTopAdminClose': 'topadmin'
    };
    return roleMap[targetStatus] || 'leader';
}

function getTargetRoleText(targetStatus) {
    const textMap = {
        'waitingLeaderReview': '班长',
        'waitingAdminReview': '管理人员',
        'waitingTopAdminClose': '主任'
    };
    return textMap[targetStatus] || '班长';
}

// 显示升级处理模态框
let editingHazardEscalateId = null;

function showHazardEscalateModal(hazardId) {
    editingHazardEscalateId = hazardId;
    safeSetDisplay('hazardEscalateModal', 'block');
}

// 关闭升级处理模态框
function closeHazardEscalateModal() {
    safeSetDisplay('hazardEscalateModal', 'none');
    editingHazardEscalateId = null;
    
    // 清空表单
    safeGetElement('hazardEscalateProgress').value = '';
    safeGetElement('hazardEscalateReason').value = '';
    safeGetElement('hazardEscalateSuggestion').value = '';
}

// 确认升级处理
function confirmHazardEscalate() {
    const hazardId = editingHazardEscalateId;
    if (!hazardId) return;
    
    const role = getCurrentRole();
    let progress = safeGetElement('hazardEscalateProgress').value.trim();
    let reason = safeGetElement('hazardEscalateReason').value.trim();
    let suggestion = safeGetElement('hazardEscalateSuggestion').value.trim();
    
    // 普通用户升级处理时，如果什么都不填，使用默认值
    if (role === 'user' && !progress && !reason && !suggestion) {
        progress = '当前操作人无法整改，请求升级处理';
        reason = '无法完成整改，请求升级处理';
        suggestion = '请上级处理';
    } else if (!progress || !reason || !suggestion) {
        showToast('请填写所有必填项', 'error');
        return;
    }
    
    const index = hazardData.findIndex(t => t.id === hazardId);
    if (index !== -1) {
        const now = new Date().toLocaleString('zh-CN');
        const currentUser = getCurrentUserInfo();
        const currentStatus = hazardData[index].status;
        const role = getCurrentRole();
        let newStatus = '';
        let toRole = '';
        
        // 班长升级至管理员
        if (role === 'leader') {
            newStatus = 'escalatedToAdmin';
            toRole = 'manager';
        }
        // 管理员升级至主任
        else if (role === 'manager') {
            newStatus = 'escalatedToTopAdmin';
            toRole = 'topadmin';
        }
        
        hazardData[index].status = newStatus;
        hazardData[index].update_time = now;
        hazardData[index].updated_at = new Date().toISOString();
        hazardData[index]._sync_version = (hazardData[index]._sync_version || 0) + 1;
        
        // 添加升级记录
        if (!hazardData[index].escalate_records) hazardData[index].escalate_records = [];
        if (!hazardData[index].escalateRecords) hazardData[index].escalateRecords = [];
        const escalateRec = {
            time: new Date().toISOString(),
            from_role: role,
            to_role: toRole,
            current_progress: progress,
            reason: reason,
            next_step_advice: suggestion,
            operator: {
                username: currentUser.username || currentUser.name || '未知',
                name: currentUser.username || currentUser.name || '未知',
                role: currentUser.role || ''
            },
            fromRole: role,
            toRole: toRole,
            currentProgress: progress,
            nextStepAdvice: suggestion
        };
        hazardData[index].escalate_records.push(escalateRec);
        hazardData[index].escalateRecords.push(escalateRec);
        
        // 添加状态变更记录
        if (!hazardData[index].status_change_records) hazardData[index].status_change_records = [];
        if (!hazardData[index].statusChangeRecords) hazardData[index].statusChangeRecords = [];
        const statusRec = {
            time: now,
            from_status: currentStatus,
            to_status: newStatus,
            fromStatus: currentStatus,
            toStatus: newStatus,
            operator: currentUser.username || currentUser.name || '未知',
            operatorRole: role,
            operator_role: role
        };
        hazardData[index].status_change_records.push(statusRec);
        hazardData[index].statusChangeRecords = [...hazardData[index].status_change_records];
        
        saveHazards();
        refreshHazardStats();
        filterHazards();
        closeHazardEscalateModal();
        closeHazardDetailModal();
        
        if (role === 'leader') {
            showToast('已升级至管理人员处理', 'success');
            logAudit('hazard', 'update', `班长升级隐患至管理员: ${hazardData[index].title}`);
        } else {
            showToast('已升级至主任处理', 'success');
            logAudit('hazard', 'update', `管理员升级隐患至主任: ${hazardData[index].title}`);
        }
    }
}

// 检查是否超期
function isHazardOverdue(hazard) {
    if (!hazard.deadline) return false;
    
    const today = new Date();
    const deadline = new Date(hazard.deadline);
    
    // 清零时分秒，只比较日期
    today.setHours(0, 0, 0, 0);
    deadline.setHours(0, 0, 0, 0);
    
    return today > deadline;
}

// 管理员确认隐患
function confirmHazardByAdmin(hazardId) {
    const hazard = hazardData.find(t => t.id === hazardId);
    
    if (!hazard) {
        showToast('隐患不存在', 'error');
        return;
    }
    
    if (!canConfirmByAdmin(hazard)) {
        showToast('您没有权限确认此隐患', 'error');
        return;
    }
    
    // 检查截止日期是否为空，如果为空则弹出输入框
    if (!hazard.deadline || hazard.deadline.trim() === '') {
        openHazardDeadlineModal(hazardId, 'admin');
        return;
    }
    
    const index = hazardData.findIndex(t => t.id === hazardId);
    if (index !== -1) {
        const now = new Date().toLocaleString('zh-CN');
        const currentUser = getCurrentUserInfo();
        const currentRole = getCurrentRole();
        const currentStatus = hazardData[index].status;
        
        hazardData[index].status = 'waitingTopAdminClose';
        hazardData[index].is_confirmed_by_admin = true;
        hazardData[index].isConfirmedByAdmin = true;
        hazardData[index].adminConfirmUser = currentUser.username || currentUser.name || '未知';
        hazardData[index].update_time = now;
        hazardData[index].updated_at = new Date().toISOString();
        hazardData[index]._sync_version = (hazardData[index]._sync_version || 0) + 1;
        
        if (!hazardData[index].status_change_records) hazardData[index].status_change_records = [];
        if (!hazardData[index].statusChangeRecords) hazardData[index].statusChangeRecords = [];
        const statusRec = {
            time: now,
            from_status: currentStatus,
            to_status: 'waitingTopAdminClose',
            fromStatus: currentStatus,
            toStatus: 'waitingTopAdminClose',
            operator: currentUser.username || currentUser.name || '未知',
            operatorRole: currentRole,
            operator_role: currentRole
        };
        hazardData[index].status_change_records.push(statusRec);
        hazardData[index].statusChangeRecords = [...hazardData[index].status_change_records];
        
        saveHazards();
        refreshHazardStats();
        filterHazards();
        closeHazardDetailModal();
        showToast('隐患已确认，等待主任闭环', 'success');
        logAudit('hazard', 'update', `管理员确认隐患: ${hazardData[index].title}`);
    }
}

// 打开截止日期输入模态框
function openHazardDeadlineModal(hazardId, confirmType) {
    const modal = safeGetElement('hazardDeadlineModal');
    const hazardIdInput = safeGetElement('hazardDeadlineHazardId');
    const confirmTypeInput = safeGetElement('hazardDeadlineConfirmType');
    const deadlineInput = safeGetElement('hazardConfirmDeadline');
    
    if (modal && hazardIdInput && confirmTypeInput && deadlineInput) {
        hazardIdInput.value = hazardId;
        confirmTypeInput.value = confirmType;
        deadlineInput.value = '';
        
        // 设置默认截止日期为7天后
        const defaultDate = new Date();
        defaultDate.setDate(defaultDate.getDate() + 7);
        deadlineInput.value = defaultDate.toISOString().split('T')[0];
        
        safeSetDisplay('hazardDeadlineModal', 'block');
    }
}

// 关闭截止日期输入模态框
function closeHazardDeadlineModal() {
    safeSetDisplay('hazardDeadlineModal', 'none');
}

// 确认隐患并设置截止日期
function confirmHazardWithDeadline() {
    const hazardId = safeGetElement('hazardDeadlineHazardId')?.value;
    const confirmType = safeGetElement('hazardDeadlineConfirmType')?.value;
    const deadline = safeGetElement('hazardConfirmDeadline')?.value;
    
    if (!deadline) {
        showToast('请选择截止日期', 'error');
        return;
    }
    
    const index = hazardData.findIndex(h => h.id === hazardId);
    if (index === -1) {
        showToast('隐患不存在', 'error');
        closeHazardDeadlineModal();
        return;
    }
    
    // 更新截止日期
    hazardData[index].deadline = deadline;
    
    closeHazardDeadlineModal();
    
    // 根据确认类型继续执行确认逻辑
    if (confirmType === 'admin') {
        executeAdminConfirm(hazardId);
    } else if (confirmType === 'leader') {
        executeLeaderConfirm(hazardId);
    }
}

