let completingHazardId = null;


function confirmHazardRectifiedByLeader(hazardId) {
    const index = hazardData.findIndex(h => h.id === hazardId);
    if (index === -1) {
        showToast('隐患不存在', 'error');
        return;
    }
    
    // 检查权限
    const currentRole = getCurrentRole();
    if (currentRole !== 'leader' && currentRole !== 'manager' && currentRole !== 'topadmin') {
        showToast('您没有权限进行此操作', 'error');
        return;
    }
    
    const now = new Date().toLocaleString('zh-CN');
    const currentUser = getCurrentUserInfo();
    const currentStatus = hazardData[index].status;
    
    hazardData[index].status = 'waitingAdminReview';
    hazardData[index].update_time = now;
    hazardData[index].updated_at = new Date().toISOString();
    hazardData[index]._sync_version = (hazardData[index]._sync_version || 0) + 1;
    
    // 添加整改完成记录（追加，不覆盖原有记录）
    // 参考版本9.0：确保 completionRecords 数组存在
    if (!hazardData[index].completionRecords || !Array.isArray(hazardData[index].completionRecords)) {
        // 如果下划线版本有数据，先迁移到驼峰版本
        if (hazardData[index].completion_records && Array.isArray(hazardData[index].completion_records)) {
            hazardData[index].completionRecords = [...hazardData[index].completion_records];
        } else {
            hazardData[index].completionRecords = [];
        }
    }
    
    const completionRec = {
        id: `completion_${Date.now()}`,
        completionTime: now,
        completionNote: '班长确认隐患已整改',
        operator: currentUser.username || currentUser.name || '未知',
        operatorRole: currentRole,
        operator_role: currentRole,
        completion_time: now,
        completion_note: '班长确认隐患已整改',
        timestamp: Date.now()
    };
    
    // 参考版本9.0：只使用 completionRecords 数组
    hazardData[index].completionRecords.push(completionRec);
    
    // 同步到下划线版本（用于云端存储）
    hazardData[index].completion_records = [...hazardData[index].completionRecords];
    
    // 添加状态变更记录（追加，不覆盖原有记录）
    if (!hazardData[index].status_change_records || !Array.isArray(hazardData[index].status_change_records)) hazardData[index].status_change_records = [];
    if (!hazardData[index].statusChangeRecords || !Array.isArray(hazardData[index].statusChangeRecords)) hazardData[index].statusChangeRecords = [];
    const statusRec = {
        time: now,
        from_status: currentStatus,
        to_status: 'waitingAdminReview',
        fromStatus: currentStatus,
        toStatus: 'waitingAdminReview',
        operator: currentUser.username || currentUser.name || '未知',
        operatorRole: currentRole,
        operator_role: currentRole
    };
    hazardData[index].status_change_records.push(statusRec);
    hazardData[index].statusChangeRecords = [...hazardData[index].status_change_records];
    
    saveHazards();
    syncHazardDataIncrementally(hazardData);
    refreshHazardStats();
    filterHazards();
    closeHazardDetailModal();
    showToast('已确认隐患已整改，等待管理人员审核', 'success');
    logAudit('hazard', 'update', `班长确认隐患已整改: ${hazardData[index].title}`);
}

