function startRectifyHazard(hazardId, targetRole) {
    const index = hazardData.findIndex(h => h.id === hazardId);
    if (index === -1) {
        showToast('隐患不存在', 'error');
        return;
    }

    const currentRole = getCurrentRole();
    const hazard = hazardData[index];

    // 检查整改权限：只有对应角色才能开始整改
    if (targetRole === 'leader') {
        if (currentRole !== 'leader' && currentRole !== 'manager' && currentRole !== 'topadmin') {
            showToast('您没有权限进行此操作', 'error');
            return;
        }
    } else if (targetRole === 'admin') {
        if (currentRole !== 'manager' && currentRole !== 'topadmin') {
            showToast('您没有权限进行此操作', 'error');
            return;
        }
    } else {
        showToast('无效的整改角色', 'error');
        return;
    }

    const now = new Date().toLocaleString('zh-CN');
    const currentUser = getCurrentUserInfo();
    const currentStatus = hazard.status;

    const newStatus = targetRole === 'leader' ? 'leaderRectifying' : 'adminRectifying';

    if (!hazardData[index].status_change_records) hazardData[index].status_change_records = [];
    if (!hazardData[index].statusChangeRecords) hazardData[index].statusChangeRecords = [];
    const statusRec = {
        time: now,
        from_status: currentStatus,
        to_status: newStatus,
        operator: currentUser.username || currentUser.name || '未知',
        operator_role: currentRole,
        fromStatus: currentStatus,
        toStatus: newStatus,
        operatorRole: currentRole
    };
    hazardData[index].status_change_records.push(statusRec);
    hazardData[index].statusChangeRecords = [...hazardData[index].status_change_records];

    hazardData[index].status = newStatus;
    hazardData[index].update_time = now;
    hazardData[index].updated_at = new Date().toISOString();  // 同步设置ISO格式
    hazardData[index]._sync_version = (hazardData[index]._sync_version || 0) + 1;

    saveHazards();
    syncHazardDataIncrementally();
    refreshHazardStats();
    filterHazards();
    
    const targetRoleText = targetRole === 'leader' ? '班长' : '管理人员';
    showToast(`已开始${targetRoleText}整改`, 'success');
    logAudit('hazard', 'update', `${targetRoleText}开始整改: ${hazardData[index].title}`);
    
    closeHazardDetailModal();
}

function rejectHazardToRectify(hazardId, targetRole) {
    rejectingHazardId = hazardId;
    rejectTargetRole = targetRole;
    
    const hazard = hazardData.find(h => h.id === hazardId);
    if (!hazard) {
        showToast('隐患不存在', 'error');
        return;
    }
    
    // 检查打回权限
    const currentRole = getCurrentRole();
    if (targetRole === 'leader') {
        // 只有管理人员或主任可以打回给班长
        if (currentRole !== 'manager' && currentRole !== 'topadmin') {
            showToast('您没有权限进行此操作', 'error');
            return;
        }
    } else if (targetRole === 'admin') {
        // 只有主任可以打回给管理人员
        if (currentRole !== 'topadmin') {
            showToast('您没有权限进行此操作', 'error');
            return;
        }
    } else if (targetRole === 'user') {
        // 班长、管理人员或主任可以打回给普通用户创建者
        if (currentRole !== 'leader' && currentRole !== 'manager' && currentRole !== 'topadmin') {
            showToast('您没有权限进行此操作', 'error');
            return;
        }
    } else {
        showToast('无效的目标角色', 'error');
        return;
    }
    
    const content = safeGetElement('hazardCannotCompleteFormContent');
    if (content) {
        content.innerHTML = `
            <div class="detail-row">
                <span class="detail-label">隐患标题</span>
                <span class="detail-value">${escapeHtml(hazard.title)}</span>
            </div>
            <div class="detail-row">
                <span class="detail-label">隐患描述</span>
                <span class="detail-value">${escapeHtml(hazard.description) || '-'}</span>
            </div>
            <div class="detail-row">
                <span class="detail-label">当前状态</span>
                <span class="detail-value ${getHazardStatusClass(hazard.status)}">${getHazardStatusText(hazard.status)}</span>
            </div>
            <div class="detail-row">
                <span class="detail-label">打回目标</span>
                <span class="detail-value">${targetRole === 'leader' ? '班长' : targetRole === 'admin' ? '管理人员' : '创建者'}</span>
            </div>
        `;
    }
    
    const rejectReasonInput = safeGetElement('hazardCannotCompleteReasonInput');
    if (rejectReasonInput) {
        rejectReasonInput.value = '';
    }
    
    closeHazardDetailModal();
    showPage('hazardCannotComplete');
}

function submitHazardReject() {
    const confirmBtn = safeGetElement('confirmHazardCannotCompleteBtn');
    
    if (confirmBtn) {
        confirmBtn.disabled = true;
        confirmBtn.textContent = '提交中...';
    }

    try {
        // 【防重复提交】检查是否正在提交
        if (window._submittingHazardReject) {
            showToast('正在处理中，请稍候', 'warning');
            if (confirmBtn) {
                confirmBtn.disabled = false;
                confirmBtn.textContent = '确认提交';
            }
            return;
        }
        // 设置提交中标志
        window._submittingHazardReject = true;
        
        if (!rejectingHazardId) {
            showToast('隐患不存在', 'error');
            window._submittingHazardReject = false;
            return;
        }

        // 权限检查：班长可以打回给普通用户，管理人员可以打回给班长或普通用户，主任可以打回给任何人
        const currentRole = getCurrentRole();
        if (rejectTargetRole === 'user') {
            // 班长、管理人员、主任都可以打回给普通用户
            if (currentRole !== 'leader' && currentRole !== 'manager' && currentRole !== 'topadmin') {
                showToast('您没有权限进行此操作', 'error');
                return;
            }
        } else if (rejectTargetRole === 'leader') {
            // 只有管理人员或主任可以打回给班长
            if (currentRole !== 'manager' && currentRole !== 'topadmin') {
                showToast('您没有权限进行此操作', 'error');
                return;
            }
        } else if (rejectTargetRole === 'admin') {
            // 只有主任可以打回给管理人员
            if (currentRole !== 'topadmin') {
                showToast('您没有权限进行此操作', 'error');
                return;
            }
        } else {
            showToast('无效的目标角色', 'error');
            return;
        }

        const rejectReason = document.getElementById('hazardCannotCompleteReasonInput').value.trim();
        if (!rejectReason) {
            showToast('请填写打回情况说明', 'error');
            document.getElementById('hazardCannotCompleteReasonInput').focus();
            return;
        }

        const index = hazardData.findIndex(t => t.id === rejectingHazardId);
        if (index !== -1) {
            const now = new Date().toLocaleString('zh-CN');
            const currentUser = getCurrentUserInfo();
            const currentRole = getCurrentRole();
            const currentStatus = hazardData[index].status;
            
            let newStatus;
            // 根据当前状态决定打回目标
            if (currentStatus === 'waitingLeaderReview' || currentStatus === 'waitingLeaderConfirm') {
                // 待班长审核/确认 → 未完成整改 → 创建者整改中
                const hazard = hazardData[index];
                const creatorRole = hazard.creatorRole || getHazardCreatorRole(hazard);
                console.log('[rejectHazardToRectify] 待班长审核/确认阶段打回:', {
                    creator: hazard.creator,
                    creatorRole: hazard.creatorRole,
                    detectedRole: creatorRole,
                    newStatus: creatorRole === 'leader' ? 'leaderRectifying' : 
                              creatorRole === 'manager' ? 'adminRectifying' : 'draft'
                });
                if (creatorRole === 'leader') {
                    newStatus = 'leaderRectifying';
                } else if (creatorRole === 'manager') {
                    newStatus = 'adminRectifying';
                } else {
                    // 普通用户创建的隐患，打回至草稿状态
                    newStatus = 'draft';
                }
            } else if (currentStatus === 'waitingAdminReview') {
                // 待管理人员审核 → 未完成整改 → 班长整改中
                newStatus = 'leaderRectifying';
            } else {
                // 默认按传入的目标角色
                if (rejectTargetRole === 'leader') {
                    newStatus = 'leaderRectifying';
                } else if (rejectTargetRole === 'admin') {
                    newStatus = 'adminRectifying';
                } else if (rejectTargetRole === 'user') {
                    // 打回给普通用户，回到草稿状态
                    newStatus = 'draft';
                } else {
                    newStatus = 'draft';
                }
            }
            
            if (!hazardData[index].reject_records || !Array.isArray(hazardData[index].reject_records)) hazardData[index].reject_records = [];
            if (!hazardData[index].rejectRecords || !Array.isArray(hazardData[index].rejectRecords)) hazardData[index].rejectRecords = [];
            const rejectRec = {
                reject_time: now,
                reject_reason: rejectReason,
                reform_note: '',
                operator: currentUser,
                rejectTime: now,
                rejectReason: rejectReason,
                reformNote: ''
            };
            // 只添加一次，避免重复记录问题
            hazardData[index].reject_records.push(rejectRec);
            // 通过展开创建新数组，避免引用共享导致的重复显示问题
            hazardData[index].rejectRecords = [...hazardData[index].reject_records];
            
            if (!hazardData[index].status_change_records || !Array.isArray(hazardData[index].status_change_records)) hazardData[index].status_change_records = [];
            if (!hazardData[index].statusChangeRecords || !Array.isArray(hazardData[index].statusChangeRecords)) hazardData[index].statusChangeRecords = [];
            const statusRec = {
                time: now,
                from_status: currentStatus,
                to_status: newStatus,
                operator: currentUser.username || currentUser.name || '未知',
                operatorRole: currentRole,
                fromStatus: currentStatus,
                toStatus: newStatus,
                operator_role: currentRole
            };
            hazardData[index].status_change_records.push(statusRec);
            hazardData[index].statusChangeRecords = [...hazardData[index].status_change_records];
            
            hazardData[index].status = newStatus;
            hazardData[index].update_time = now;
            hazardData[index].updated_at = new Date().toISOString();  // 同步设置ISO格式
            hazardData[index]._sync_version = (hazardData[index]._sync_version || 0) + 1;
            
            saveHazards();
            syncHazardDataIncrementally();
            refreshHazardStats();
            filterHazards();
            const targetRoleText = rejectTargetRole === 'leader' ? '班长' : '管理人员';
            showToast(`已打回至${targetRoleText}整改`, 'success');
            logAudit('hazard', 'update', `打回至${targetRoleText}: ${hazardData[index].title}`);
        }
    } finally {
        // 【防重复提交】重置提交标志
        window._submittingHazardReject = false;
        rejectingHazardId = null;
        rejectTargetRole = null;
        if (confirmBtn) {
            confirmBtn.disabled = false;
            confirmBtn.textContent = '确认提交';
        }
        showPage('hazard');
    }
}

function confirmHazardNotExists(hazardId) {
    if (!confirm('确定此隐患不存在吗？')) return;
    
    const index = hazardData.findIndex(h => h.id === hazardId);
    if (index === -1) {
        showToast('隐患不存在', 'error');
        return;
    }
    
    // 检查权限
    const currentRole = getCurrentRole();
    if (currentRole !== 'leader' && currentRole !== 'manager' && currentRole !== 'topadmin') {
        showToast('您没有权限进行此操作', 'error');
        return;
    }
    
    const now = new Date().toLocaleString('zh-CN');
    const currentUser = getCurrentUserInfo();
    const currentStatus = hazardData[index].status;
    
    hazardData[index].status = 'cancelled';
    hazardData[index].update_time = now;
    hazardData[index].updated_at = new Date().toISOString();
    hazardData[index]._sync_version = (hazardData[index]._sync_version || 0) + 1;
    
    if (!hazardData[index].status_change_records) hazardData[index].status_change_records = [];
    if (!hazardData[index].statusChangeRecords) hazardData[index].statusChangeRecords = [];
    const statusRec = {
        time: now,
        from_status: currentStatus,
        to_status: 'cancelled',
        fromStatus: currentStatus,
        toStatus: 'cancelled',
        operator: currentUser.username || currentUser.name || '未知',
        operatorRole: currentRole,
        operator_role: currentRole
    };
    hazardData[index].status_change_records.push(statusRec);
    hazardData[index].statusChangeRecords = [...hazardData[index].status_change_records];
    
    hazardData[index].confirmed_by = currentUser.username || currentUser.name || '未知';
    hazardData[index].confirmedBy = currentUser.username || currentUser.name || '未知';
    hazardData[index].confirmed_by_role = currentRole;
    hazardData[index].confirmedByRole = currentRole;
    
    saveHazards();
    refreshHazardStats();
    filterHazards();
    closeHazardDetailModal();
    showToast('隐患已标记为不存在，状态已变更为已撤销', 'success');
    logAudit('hazard', 'update', `确认隐患不存在: ${hazardData[index].title}`);
}

