function markHazardComplete(hazardId) {
    completingHazardId = hazardId;
    const hazard = hazardData.find(t => t.id === hazardId);
    
    if (!hazard) {
        showToast('隐患不存在', 'error');
        return;
    }
    
    if (!canMarkHazardComplete(hazard)) {
        showToast('您没有权限标记此隐患完成', 'error');
        return;
    }
    
    const content = safeGetElement('hazardCompleteFormContent');
    if (content) {
        content.innerHTML = `
            <div class="detail-row">
                <span class="detail-label">隐患标题</span>
                <span class="detail-value">${escapeHtml(hazard.title)}</span>
            </div>
            <div class="detail-row">
                <span class="detail-label">隐患描述</span>
                <span class="detail-value">${escapeHtml(hazard.description) || '-'}</span>
            </div>
            <div class="detail-row">
                <span class="detail-label">发现人</span>
                <span class="detail-value">${escapeHtml(hazard.assignee)}</span>
            </div>
            <div class="detail-row">
                <span class="detail-label">优先级</span>
                <span class="detail-value priority-${hazard.priority}">${getHazardPriorityText(hazard.priority)}</span>
            </div>
            <div class="detail-row">
                <span class="detail-label">当前状态</span>
                <span class="detail-value ${getHazardStatusClass(hazard.status)}">${getHazardStatusText(hazard.status)}</span>
            </div>
            <div class="detail-row">
                <span class="detail-label">截止日期</span>
                <span class="detail-value">${hazard.deadline || '-'}</span>
            </div>
        `;
    }

    const completeNoteInput = safeGetElement('hazardCompleteNoteInput');
    if (completeNoteInput) {
        completeNoteInput.value = '';
    }

    closeHazardDetailModal();
    showPage('hazardComplete');
}

function cancelMarkHazardComplete() {
    completingHazardId = null;
    const completeNoteInput = safeGetElement('hazardCompleteNoteInput');
    if (completeNoteInput) {
        completeNoteInput.value = '';
    }
    showPage('hazard');
    refreshHazardStats();
    filterHazards();
}

function submitMarkHazardComplete() {
    const confirmBtn = safeGetElement('confirmHazardCompleteBtn');
    
    if (confirmBtn && confirmBtn.disabled) {
        return;
    }
    
    if (confirmBtn) {
        confirmBtn.disabled = true;
        confirmBtn.textContent = '提交中...';
    }

    try {
        if (!completingHazardId) {
            showToast('隐患不存在', 'error');
            return;
        }

        const completeNote = safeGetElement('hazardCompleteNoteInput').value.trim();
        if (!completeNote) {
            showToast('请填写隐患完成情况说明', 'error');
            safeGetElement('hazardCompleteNoteInput').focus();
            return;
        }

        const index = hazardData.findIndex(t => t.id === completingHazardId);
        if (index !== -1) {
            const now = new Date().toLocaleString('zh-CN');
            const currentRole = getCurrentRole();
            const currentUser = getCurrentUserInfo();
            const currentStatus = hazardData[index].status;
            
            console.log(`[submitMarkHazardComplete] 开始处理隐患 ${completingHazardId}:`, {
                currentUser: currentUser.username,
                currentRole: currentRole,
                currentStatus: currentStatus,
                hazardCreator: hazardData[index].creator,
                existingCompletionRecordsCount: Array.isArray(hazardData[index].completion_records) ? hazardData[index].completion_records.length : 0,
                existingStatusChangeRecordsCount: Array.isArray(hazardData[index].status_change_records) ? hazardData[index].status_change_records.length : 0
            });
            
            const existingCompletionNote = hazardData[index].completion_note || '';
            const newCompletionNote = `【${now}】${completeNote}`;
            const finalCompletionNote = existingCompletionNote ? 
                `${existingCompletionNote}\n\n${newCompletionNote}` : newCompletionNote;
            
            let newStatus = 'completed';
            
            if (currentStatus === 'draft') {
                // 根据当前登录用户的角色判断目标状态
                if (currentRole === 'leader') {
                    newStatus = 'waitingAdminReview';
                } else if (currentRole === 'manager' || currentRole === 'topadmin') {
                    newStatus = 'waitingTopAdminClose';
                } else {
                    // 【关键修复】普通用户标记完成后，状态改为待班长确认（waitingLeaderConfirm），而不是待班长审核
                    newStatus = 'waitingLeaderConfirm';
                }
            } else if (currentStatus === 'waitingLeaderConfirm') {
                // 待班长确认状态：普通用户（创建者）可以继续添加整改记录，状态不变；班长确认后进入待班长审核
                if (currentRole === 'user') {
                    newStatus = 'waitingLeaderConfirm';
                } else if (currentRole === 'leader') {
                    newStatus = 'waitingLeaderReview';
                } else {
                    newStatus = 'waitingLeaderConfirm';
                }
            } else if (currentStatus === 'waitingLeaderReview') {
                // 待班长审核状态：普通用户添加整改记录，状态不变；班长确认整改完成后进入待管理员审核
                if (currentRole === 'user') {
                    // 普通用户（创建者）添加整改记录，状态保持不变，继续累积记录
                    newStatus = 'waitingLeaderReview';
                } else if (currentRole === 'leader') {
                    newStatus = 'waitingAdminReview';
                } else {
                    newStatus = 'waitingLeaderReview';
                }
            } else if (currentStatus === 'leaderRectifying') {
                // 班长整改中状态：普通用户可以添加整改记录，状态不变；班长确认整改完成后进入待管理员审核
                if (currentRole === 'user') {
                    // 普通用户（创建者）添加整改记录，状态保持不变，继续累积记录
                    newStatus = 'leaderRectifying';
                } else {
                    newStatus = 'waitingAdminReview';
                }
            } else if (currentStatus === 'adminRectifying') {
                newStatus = 'waitingTopAdminClose';
            } else if (currentRole === 'user') {
                newStatus = 'waitingLeaderReview';
            } else if (currentRole === 'leader') {
                newStatus = 'waitingAdminReview';
            } else if (currentRole === 'manager') {
                newStatus = 'waitingTopAdminClose';
            }
            
            hazardData[index].status = newStatus;
            hazardData[index].progress = currentRole === 'topadmin' ? 100 : hazardData[index].progress;
            hazardData[index].completion_note = finalCompletionNote;
            hazardData[index].completionNote = finalCompletionNote;  // 同步设置驼峰命名
            hazardData[index].completion_user = currentUser.username || currentUser.name || '未知';
            hazardData[index].completionUser = currentUser.username || currentUser.name || '未知';
            
            // 参考版本9.0：确保 completionRecords 数组存在
            if (!hazardData[index].completionRecords || !Array.isArray(hazardData[index].completionRecords)) {
                // 如果下划线版本有数据，先迁移到驼峰版本
                if (hazardData[index].completion_records && Array.isArray(hazardData[index].completion_records)) {
                    hazardData[index].completionRecords = [...hazardData[index].completion_records];
                } else {
                    hazardData[index].completionRecords = [];
                }
            }
            
            const completionRec = {
                id: `completion_${Date.now()}`,
                completionTime: now,
                completionNote: completeNote,
                operator: currentUser.username || currentUser.name || '未知',
                operatorRole: currentRole,
                operator_role: currentRole,
                completion_time: now,
                completion_note: completeNote,
                timestamp: Date.now()
            };
            
            // 参考版本9.0：只使用 completionRecords 数组
            hazardData[index].completionRecords.push(completionRec);
            
            // 同步到下划线版本（用于云端存储）
            hazardData[index].completion_records = [...hazardData[index].completionRecords];
            
            // 添加确认整改完成记录
            if (!hazardData[index].confirm_records) hazardData[index].confirm_records = [];
            if (!hazardData[index].confirmRecords) hazardData[index].confirmRecords = [];
            const confirmRecord = {
                time: new Date().toISOString(),
                confirm_time: new Date().toISOString(),
                note: completeNote,
                confirm_note: completeNote,
                operator: { username: currentUser.username || currentUser.name || '未知', role: currentRole }
            };
            hazardData[index].confirm_records.push(confirmRecord);
            hazardData[index].confirmRecords = [...hazardData[index].confirm_records];
            
            console.log(`[submitMarkHazardComplete] 整改完成记录已添加:`, {
                operator: completionRec.operator,
                operatorRole: completionRec.operatorRole,
                completionNote: completionRec.completionNote,
                totalCompletionRecords: hazardData[index].completionRecords.length
            });
            
            if (!hazardData[index].status_change_records || !Array.isArray(hazardData[index].status_change_records)) hazardData[index].status_change_records = [];
            if (!hazardData[index].statusChangeRecords || !Array.isArray(hazardData[index].statusChangeRecords)) hazardData[index].statusChangeRecords = [];
            const statusRec = {
                time: now,
                from_status: currentStatus,
                to_status: newStatus,
                operator: currentUser.username || currentUser.name || '未知',
                operatorRole: currentRole,
                fromStatus: currentStatus,
                toStatus: newStatus,
                operator_role: currentRole
            };
            hazardData[index].status_change_records.push(statusRec);
            hazardData[index].statusChangeRecords = [...hazardData[index].status_change_records];
            
            hazardData[index].update_time = now;
            hazardData[index].updated_at = new Date().toISOString();  // 同步设置ISO格式
            hazardData[index]._sync_version = (hazardData[index]._sync_version || 0) + 1;
            saveHazards();
            syncHazardDataIncrementally(hazardData);

            showToast('隐患已标记完成', 'success');
            logAudit('hazard', 'update', `隐患标记完成: ${hazardData[index].title}`);
            cancelMarkHazardComplete();
        }
    } finally {
        if (confirmBtn) {
            confirmBtn.disabled = false;
            confirmBtn.textContent = '确认完成';
        }
    }
}

function markHazardClosed(hazardId) {
    const index = hazardData.findIndex(h => h.id === hazardId);
    if (index === -1) {
        showToast('隐患不存在', 'error');
        return;
    }
    
    const hazard = hazardData[index];
    
    // 检查闭环权限
    if (!canCloseHazard(hazard)) {
        showToast('您没有权限闭环此隐患', 'error');
        return;
    }
    
    const now = new Date().toLocaleString('zh-CN');
    const currentUser = getCurrentUserInfo();
    const currentStatus = hazardData[index].status;
    
    hazardData[index].status = 'closed';
    hazardData[index].progress = 100;
    hazardData[index].update_time = now;
    hazardData[index].updated_at = new Date().toISOString();  // 同步设置ISO格式
    hazardData[index]._sync_version = (hazardData[index]._sync_version || 0) + 1;
    
    if (!hazardData[index].status_change_records) hazardData[index].status_change_records = [];
    if (!hazardData[index].statusChangeRecords) hazardData[index].statusChangeRecords = [];
    const statusRec = {
        time: now,
        from_status: currentStatus,
        to_status: 'closed',
        fromStatus: currentStatus,
        toStatus: 'closed',
        operator: currentUser.username || currentUser.name || '未知',
        operatorRole: 'topadmin',
        operator_role: 'topadmin'
    };
    hazardData[index].status_change_records.push(statusRec);
    hazardData[index].statusChangeRecords = [...hazardData[index].status_change_records];
    
    // 添加确认整改完成记录（主任闭环）
    if (!hazardData[index].confirm_records) hazardData[index].confirm_records = [];
    if (!hazardData[index].confirmRecords) hazardData[index].confirmRecords = [];
    const confirmRecord = {
        time: new Date().toISOString(),
        confirm_time: new Date().toISOString(),
        note: '主任确认闭环完成',
        confirm_note: '主任确认闭环完成',
        operator: { username: currentUser.username || currentUser.name || '未知', role: 'topadmin' }
    };
    hazardData[index].confirm_records.push(confirmRecord);
    hazardData[index].confirmRecords = [...hazardData[index].confirm_records];
    
    saveHazards();
    refreshHazardStats();
    filterHazards();
    closeHazardDetailModal();
    showToast('隐患已闭环', 'success');
    
    if (typeof logAudit === 'function') {
        logAudit('hazard', 'update', `闭环隐患: ${hazardData[index].title}`);
    }
}

function deleteHazard(hazardId) {
    if (!confirm('确定要删除这条隐患吗？此操作不可撤销。')) {
        return;
    }
    
    const index = hazardData.findIndex(h => h.id === hazardId);
    if (index === -1) {
        showToast('隐患不存在', 'error');
        return;
    }
    
    const hazard = hazardData[index];
    
    // 检查删除权限
    if (!canDeleteHazard(hazard)) {
        showToast('您没有权限删除此隐患', 'error');
        return;
    }
    
    hazardData.splice(index, 1);
    saveHazards();
    
    // 更新同步状态为待同步
    if (window.DynamicSync) {
        window.DynamicSync.updateStatus('hazard', 'pending', '已删除，准备同步');
    }
    
    // 添加到离线队列进行自动同步
    if (window.OfflineQueue) {
        window.OfflineQueue.add({
            module: 'hazard',
            type: 'delete',
            recordId: hazardId,
            data: hazard
        });
    }
    
    // 触发自动同步（如果在线）
    if (navigator.onLine && window.DynamicSync) {
        window.DynamicSync.triggerAutoSync('hazard', 'delete', hazard);
    }
    
    refreshHazardStats();
    filterHazards();
    
    closeHazardDetailModal();
    
    if (navigator.onLine) {
        showToast('隐患已删除，正在同步到云端...', 'success');
    } else {
        showToast('隐患已删除，将在联网后自动同步', 'warning');
    }
    
    if (typeof logAudit === 'function') {
        logAudit('hazard', 'delete', `删除隐患: ${hazard.title}`);
    }
}

// 升级处理全局变量
let escalateHazardId = null;
let escalateTargetStatus = null;

// 打开升级处理表单
function openEscalateHazardForm(hazardId, targetStatus) {
    escalateHazardId = hazardId;
    escalateTargetStatus = targetStatus;
    
    const hazard = hazardData.find(h => h.id === hazardId);
    if (!hazard) {
        showToast('隐患不存在', 'error');
        return;
    }
    
    const content = safeGetElement('hazardEscalateFormContent');
    if (content) {
        content.innerHTML = `
            <div class="detail-row">
                <span class="detail-label">隐患标题</span>
                <span class="detail-value">${escapeHtml(hazard.title)}</span>
            </div>
            <div class="detail-row">
                <span class="detail-label">隐患描述</span>
                <span class="detail-value">${escapeHtml(hazard.description) || '-'}</span>
            </div>
            <div class="detail-row">
                <span class="detail-label">当前状态</span>
                <span class="detail-value ${getHazardStatusClass(hazard.status)}">${getHazardStatusText(hazard.status)}</span>
            </div>
            <div class="detail-row">
                <span class="detail-label">升级目标</span>
                <span class="detail-value">${getHazardStatusText(targetStatus)}</span>
            </div>
        `;
    }
    
    // 清空表单
    const currentProgressInput = safeGetElement('hazardEscalateProgressInput');
    const escalateReasonInput = safeGetElement('hazardEscalateReasonInput');
    const nextStepAdviceInput = safeGetElement('hazardEscalateNextStepInput');
    
    if (currentProgressInput) currentProgressInput.value = '';
    if (escalateReasonInput) escalateReasonInput.value = '';
    if (nextStepAdviceInput) nextStepAdviceInput.value = '';
    
    // 根据用户角色动态调整表单必填标记
    const currentRole = getCurrentRole();
    const isNormalUser = currentRole === 'user';
    
    // 获取表单标签元素
    const labels = document.querySelectorAll('#hazardEscalatePage .form-section label');
    const textareas = document.querySelectorAll('#hazardEscalatePage .form-section textarea');
    
    labels.forEach((label, index) => {
        if (isNormalUser) {
            // 普通用户：移除必填标记
            label.innerHTML = label.innerHTML.replace(/ <span style="color: red;">\*<\/span>/g, '');
        }
    });
    
    textareas.forEach(textarea => {
        if (isNormalUser) {
            // 普通用户：移除required属性和占位符中的"(必填)"
            textarea.removeAttribute('required');
            textarea.placeholder = textarea.placeholder.replace(/（必填）/g, '（选填）');
        } else {
            // 其他角色：确保有required属性和必填提示
            textarea.setAttribute('required', 'required');
            textarea.placeholder = textarea.placeholder.replace(/（选填）/g, '（必填）');
        }
    });
    
    closeHazardDetailModal();
    showPage('hazardEscalate');
}

// 取消升级处理
function cancelHazardEscalate() {
    escalateHazardId = null;
    escalateTargetStatus = null;
    showPage('hazard');
}

// 提交升级处理
function submitHazardEscalate() {
    if (!escalateHazardId || !escalateTargetStatus) {
        showToast('参数错误', 'error');
        return;
    }
    
    // 权限检查：普通用户、班长、管理人员、主任都可以升级
    const currentRole = getCurrentRole();
    if (currentRole !== 'user' && currentRole !== 'leader' && currentRole !== 'manager' && currentRole !== 'topadmin') {
        showToast('您没有权限进行此操作', 'error');
        return;
    }
    
    const currentProgress = safeGetElement('hazardEscalateProgressInput')?.value.trim();
    const escalateReason = safeGetElement('hazardEscalateReasonInput')?.value.trim();
    const nextStepAdvice = safeGetElement('hazardEscalateNextStepInput')?.value.trim();
    
    // 必填项校验 - 普通用户对这三项都改为非必填，其他角色保持必填
    const isNormalUser = currentRole === 'user';
    
    if (!isNormalUser && !currentProgress) {
        showToast('请填写当前整改情况', 'error');
        safeGetElement('hazardEscalateProgressInput')?.focus();
        return;
    }
    if (!isNormalUser && !escalateReason) {
        showToast('请填写无法完成原因', 'error');
        safeGetElement('hazardEscalateReasonInput')?.focus();
        return;
    }
    if (!isNormalUser && !nextStepAdvice) {
        showToast('请填写下一步整改建议', 'error');
        safeGetElement('hazardEscalateNextStepInput')?.focus();
        return;
    }
    
    const index = hazardData.findIndex(h => h.id === escalateHazardId);
    if (index === -1) {
        showToast('隐患不存在', 'error');
        return;
    }
    
    const currentStatus = hazardData[index].status;
    const currentUser = getCurrentUserInfo();
    const now = new Date().toLocaleString('zh-CN');
    const fromRole = getCurrentRole();
    
    // 添加升级记录
    if (!hazardData[index].escalate_records) {
        hazardData[index].escalate_records = [];
    }
    hazardData[index].escalate_records.push({
        time: now,
        fromRole: fromRole,
        toRole: getTargetRole(escalateTargetStatus),
        currentProgress: currentProgress,
        reason: escalateReason,
        nextStepAdvice: nextStepAdvice,
        operator: {
            username: currentUser.username || currentUser.name || '未知',
            name: currentUser.username || currentUser.name || '未知',
            role: currentUser.role || ''
        }
    });
    
    // 添加状态变更记录
    if (!hazardData[index].status_change_records) {
        hazardData[index].status_change_records = [];
    }
    hazardData[index].status_change_records.push({
        time: now,
        fromStatus: currentStatus,
        toStatus: escalateTargetStatus,
        operator: currentUser.username || currentUser.name || '未知',
        operatorRole: fromRole,
        note: `升级处理：${escalateReason}`
    });
    
    // 更新状态
    hazardData[index].status = escalateTargetStatus;
    hazardData[index].update_time = now;
    hazardData[index]._sync_version = (hazardData[index]._sync_version || 0) + 1;
    
    saveHazards();
    refreshHazardStats();
    filterHazards();
    
    showToast('升级处理成功', 'success');
    
    if (typeof logAudit === 'function') {
        logAudit('hazard', 'update', `升级处理: ${hazardData[index].title}`);
    }
    
    // 返回隐患列表
    escalateHazardId = null;
    escalateTargetStatus = null;
    showPage('hazard');
}

// 无法完成整改全局变量
