// 导出隐患数据到Excel（通用函数）
async function exportHazardDataToExcel(hazards) {
    if (hazards.length === 0) {
        showToast('没有数据可导出', 'info');
        return;
    }
    
    const exportData = hazards.map((hazard, index) => {
        // 获取处理结果：整改情况说明
        let treatmentResult = '-';
        if (hazard.completion_note) {
            treatmentResult = hazard.completion_note;
        }
        
        // 备注只显示原本的备注内容
        const remark = hazard.remark || hazard.notes || '-';
        
        return {
            '序号': index + 1,
            '隐患标题': hazard.title || '-',
            '隐患描述': hazard.description || '-',
            '处理结果': treatmentResult,
            '部门/单位': hazard.department || '-',
            '报告人': hazard.reporter || hazard.assignee || '-',
            '专业类别': hazard.category || '-',
            '隐患分类': hazard.hazard_type || hazard.hazardType || '-',
            '隐患等级': hazard.hazard_level || hazard.hazardLevel || '-',
            '填报日期': hazard.report_date || hazard.reportDate || '-',
            '优先级': getHazardPriorityText(hazard.priority) || '-',
            '状态': getHazardStatusText(hazard.status) || '-',
            '备注': remark
        };
    });
    
    const now = new Date();
    const dateStr = now.toISOString().split('T')[0];
    const fileName = `隐患排查治理台账_${dateStr}_${hazards.length}条.xlsx`;
    
    showToast(`正在导出 ${hazards.length} 条隐患数据...`, 'info');
    
    try {
        if (typeof exportToExcelWithStyle === 'function') {
            const headers = Object.keys(exportData[0]);
            const dataArray = exportData.map(item => headers.map(header => item[header] || ''));
            await exportToExcelWithStyle(dataArray, headers, '隐患排查治理台账', fileName);
            showToast(`✅ 成功导出 ${hazards.length} 条隐患数据`, 'success');
        } else if (typeof exportToExcel === 'function') {
            const headers = Object.keys(exportData[0]);
            await exportToExcel(exportData, headers, fileName);
            showToast(`✅ 成功导出 ${hazards.length} 条隐患数据`, 'success');
        } else {
            downloadCSV(exportData, fileName.replace('.xlsx', '.csv'));
            showToast(`✅ 成功导出 ${hazards.length} 条隐患数据（CSV格式）`, 'success');
        }
    } catch (error) {
        console.error('导出失败:', error);
        showToast('导出失败: ' + error.message, 'error');
    }
}

