// 打开编辑隐患模态框
function openEditHazardModal(hazardId) {
    // 复用添加隐患模态框的编辑功能
    openAddHazardModal(hazardId);
}

// 打开状态变更模态框（智能判断目标状态）
function openHazardStatusChangeModal(hazardId) {
    const hazard = hazardData.find(h => h.id === hazardId);
    if (!hazard) {
        showToast('隐患不存在', 'error');
        return;
    }

    const currentStatus = hazard.status;
    const role = getCurrentRole();

    // 根据当前状态智能判断目标状态
    let targetStatus = null;

    // 简化的线性状态流：草稿 -> 未开始 -> 进行中 -> 已完成
    switch (currentStatus) {
        case 'draft':
            targetStatus = 'pending';
            break;
        case 'pending':
        case 'waitingLeaderReview':
        case 'waitingAdminReview':
        case 'waitingTopAdminClose':
        case 'waitingRectify':
        case 'needRectify':
            targetStatus = 'progress';
            break;
        case 'progress':
        case 'leaderRectifying':
        case 'adminRectifying':
            targetStatus = 'completed';
            break;
        case 'completed':
            if (role === 'topadmin') {
                targetStatus = 'closed';
            }
            break;
        default:
            // 其他状态默认进入进行中
            if (currentStatus !== 'closed' && currentStatus !== 'cancelled' && 
                currentStatus !== 'notExists' && currentStatus !== 'notExistsByLeader') {
                targetStatus = 'progress';
            }
            break;
    }

    if (!targetStatus) {
        showToast('当前状态无法进一步变更', 'warning');
        return;
    }

    // 打开进展说明模态框
    openHazardProgressNoteModal(hazardId, targetStatus);
}

// 全局变量：存储当前正在处理状态变更的隐患ID和目标状态
let pendingHazardId = null;
let pendingHazardTargetStatus = null;

// 打开进展说明模态框
function openHazardProgressNoteModal(hazardId, targetStatus) {
    pendingHazardId = hazardId;
    pendingHazardTargetStatus = targetStatus;
    
    const hazard = hazardData.find(h => h.id === hazardId);
    if (!hazard) return;
    
    safeGetElement('currentHazardStatus').textContent = getHazardStatusText(hazard.status);
    safeGetElement('targetHazardStatus').textContent = getHazardStatusText(targetStatus);
    safeGetElement('hazardProgressNoteInput').value = '';
    
    safeSetDisplay('hazardProgressNoteModal', 'block');
}

// 关闭进展说明模态框
function closeHazardProgressNoteModal() {
    pendingHazardId = null;
    pendingHazardTargetStatus = null;
    safeSetDisplay('hazardProgressNoteModal', 'none');
}

// 确认提交进展说明
function confirmHazardProgressNote() {
    if (!pendingHazardId || !pendingHazardTargetStatus) return;
    
    const progressNote = safeGetElement('hazardProgressNoteInput').value.trim();
    if (!progressNote) {
        showToast('请填写进展说明或整改措施', 'warning');
        return;
    }
    
    const index = hazardData.findIndex(h => h.id === pendingHazardId);
    if (index === -1) return;
    
    const hazard = hazardData[index];
    
    // 保存进展记录
    if (!hazard.progress_records) hazard.progress_records = [];
    hazard.progress_records.push({
        time: new Date().toLocaleString('zh-CN'),
        fromStatus: hazard.status,
        toStatus: pendingHazardTargetStatus,
        note: progressNote,
        operator: getCurrentUserInfo()
    });
    
    // 更新隐患状态
    hazard.status = pendingHazardTargetStatus;
    hazard.update_time = new Date().toLocaleString('zh-CN');
    hazard._sync_version = (hazard._sync_version || 0) + 1;
    
    saveHazards();
    refreshHazardStats();
    filterHazards();
    closeHazardProgressNoteModal();
    openHazardDetailModal(pendingHazardId);
    
    showToast('进展说明已保存，状态已更新', 'success');
    logAudit('hazard', 'update', `隐患状态从 ${getHazardStatusText(hazard.status)} 更新为 ${getHazardStatusText(pendingHazardTargetStatus)}，进展说明：${progressNote}`);
}

// 安全获取当前用户信息
function getCurrentUserInfo() {
    const currentUser = JSON.parse(localStorage.getItem('currentUser') || '{}');
    const username = currentUser.username || localStorage.getItem('username') || '';
    const name = currentUser.name || username;
    return { username, name, role: getCurrentRole() };
}

