async function initSamplingCarLedger() {
    console.log('[SAMPLING-CAR-DEBUG] ========== 初始化采样车维修台账 ==========');
    
    try {
        // 同步前先记录当前 localStorage 的数据条数
        const beforeSync = localStorage.getItem(SAMPLING_CAR_STORAGE_KEY);
        const beforeCount = beforeSync ? JSON.parse(beforeSync).data?.length : '空';
        console.log(`[SAMPLING-CAR-DEBUG] 同步前 localStorage 数据条数: ${beforeCount}`);
        
        // 每次进入都从云端同步最新数据（覆盖模式）
        console.log('[SAMPLING-CAR-DEBUG] 开始从云端同步...');
        const syncResult = await syncModuleFromCloud('samplingCar', SAMPLING_CAR_STORAGE_KEY, 'samplingCarData', true);
        console.log(`[SAMPLING-CAR-DEBUG] 同步结果: ${syncResult}`);
        
        // 同步后记录 localStorage 的数据条数
        const afterSync = localStorage.getItem(SAMPLING_CAR_STORAGE_KEY);
        const afterCount = afterSync ? JSON.parse(afterSync).data?.length : '空';
        console.log(`[SAMPLING-CAR-DEBUG] 同步后 localStorage 数据条数: ${afterCount}`);
        
    } catch (error) {
        console.log('[SAMPLING-CAR-DEBUG] 云端同步失败，使用本地数据:', error.message);
    }
    
    samplingCarIsAddingNewRow = false;
    samplingCarNewRowIndex = -1;
    
    const addBtn = document.getElementById('samplingCarAddRowBtn');
    const saveBtn = document.getElementById('samplingCarSaveNewRowBtn');
    if (addBtn) addBtn.style.display = 'inline-flex';
    if (saveBtn) saveBtn.style.display = 'none';
    
    loadSamplingCarData();
    
    initSamplingCarYearFilter();
    samplingCarRenderTable();
    samplingCarUpdateStats();
    
    // 添加刷新按钮
    if (typeof addModuleRefreshButton === 'function') {
        addModuleRefreshButton('samplingCar', SAMPLING_CAR_STORAGE_KEY, 'samplingCarData', '#samplingCarPage .toolbar-left', () => {
            loadSamplingCarData();
            initSamplingCarYearFilter();
            samplingCarRenderTable();
        }, true); // 采样车是对象类型数据
    }
}

