// 加载采样车维修台账数据
function loadSamplingCarData() {
    try {
        const saved = localStorage.getItem(SAMPLING_CAR_STORAGE_KEY);
        if (saved) {
            const savedData = JSON.parse(saved);
            samplingCarData = savedData.data || [];
            console.log('从localStorage加载采样车维修台账数据，条数:', samplingCarData.length);
        } else {
            samplingCarData = [...mockSamplingCarData];
            console.log('使用默认采样车维修台账数据');
            saveSamplingCarData();
        }
    } catch (e) {
        console.error('加载采样车数据失败:', e);
        samplingCarData = [...mockSamplingCarData];
    }
    // 按故障日期倒序排序（时间晚的在前面）
    samplingCarData.sort((a, b) => {
        const dateA = new Date(a.faultDate || a.repairDate || a.date || '');
        const dateB = new Date(b.faultDate || b.repairDate || b.date || '');
        return dateB.getTime() - dateA.getTime();
    });
    samplingCarFilteredData = [...samplingCarData];
}

// 保存采样车维修台账数据
function saveSamplingCarData() {
    const dataToSave = {
        data: samplingCarData,
        lastModified: new Date().toISOString()
    };
    localStorage.setItem(SAMPLING_CAR_STORAGE_KEY, JSON.stringify(dataToSave));
}

const SAMPLING_CAR_HEADERS = ['维修厂家', '故障日期', '维修日期', '故障描述', '维修项目', '维修人', '费用', '备注'];

function samplingCarRenderTable() {
    const thead = document.getElementById('samplingCarTableHead');
    const tbody = document.getElementById('samplingCarTableBody');
    const emptyState = document.getElementById('samplingCarEmptyState');
    const exportBtn = document.getElementById('samplingCarExportBtn');

    safeSetDisplay('samplingCarEmptyState', samplingCarData.length === 0 ? 'block' : 'none');
    if (exportBtn) exportBtn.disabled = samplingCarData.length === 0;

    if (samplingCarData.length === 0) {
        thead.innerHTML = '';
        tbody.innerHTML = '';
        return;
    }

    samplingCarCalculatePagination();
    const startIndex = (samplingCarCurrentPage - 1) * SAMPLING_CAR_PAGE_SIZE;
    const endIndex = startIndex + SAMPLING_CAR_PAGE_SIZE;
    const pageData = samplingCarFilteredData.slice(startIndex, endIndex);

    // 检查当前页所有行是否都被选中
    let allChecked = pageData.length > 0;
    for (let i = 0; i < pageData.length; i++) {
        const row = pageData[i];
        if (!samplingCarSelectedIds.includes(row.id)) {
            allChecked = false;
            break;
        }
    }

    thead.innerHTML = `
        <tr>
            <th style="min-width: 40px;"><input type="checkbox" class="row-checkbox" onchange="samplingCarToggleSelectAll(this)" ${allChecked ? 'checked' : ''}></th>
            <th style="min-width: 50px;">序号</th>
            ${SAMPLING_CAR_HEADERS.map((header, index) => `
                <th data-col="${index}">
                    <span class="header-editable">${samplingCarEscapeHtml(header)}</span>
                    <span class="resize-handle" onmousedown="startColumnResize(event, ${index})"></span>
                </th>
            `).join('')}
            <th style="min-width: 100px;">操作</th>
        </tr>
    `;

    tbody.innerHTML = pageData.map((row, rowIndex) => {
        const actualIndex = startIndex + rowIndex;
        const isSelected = samplingCarSelectedIds.includes(row.id);
        const serialNumber = actualIndex + 1;
        const isNewRow = samplingCarIsAddingNewRow && actualIndex === samplingCarNewRowIndex;
        
        const fields = ['repairFactory', 'faultDate', 'repairDate', 'fault', 'repairItem', 'repairPerson', 'cost', 'remark'];
        const rowData = fields.map(field => row[field] || '');
        
        let cellsHtml;
        if (isNewRow) {
            cellsHtml = rowData.map((cell, cellIndex) => `
                <td>
                    <input type="text" class="new-row-input" data-col="${cellIndex}" value="${samplingCarEscapeHtml(cell)}" placeholder="请输入">
                </td>
            `).join('');
        } else {
            cellsHtml = rowData.map((cell, cellIndex) => `
                <td>
                    <span>${samplingCarEscapeHtml(cell)}</span>
                </td>
            `).join('');
        }
        
        return `
            <tr data-index="${actualIndex}" style="background-color: ${isNewRow ? '#fff3cd' : (isSelected ? '#E8F5E9' : '')}">
                <td><input type="checkbox" class="row-checkbox" data-id="${row.id}" ${isSelected ? 'checked' : ''} onchange="samplingCarToggleRowSelect(${row.id})"></td>
                <td>${serialNumber}</td>
                ${cellsHtml}
                <td>
                    <button class="action-btn btn-edit" onclick="samplingCarEditRow(${actualIndex})">编辑</button>
                    <button class="action-btn btn-delete" onclick="samplingCarDeleteRow(${actualIndex})">删除</button>
                </td>
            </tr>
        `;
    }).join('');

    samplingCarRenderPagination();
    samplingCarUpdateStats();
    
    // 表格渲染完成后，自动调整列宽
    setTimeout(() => {
        if (typeof autoAdjustTableColumnWidths === 'function') {
            autoAdjustTableColumnWidths('samplingCarDataTable');
        }
    }, 100);
}

function samplingCarCalculatePagination() {
    samplingCarTotalPages = Math.ceil(samplingCarFilteredData.length / SAMPLING_CAR_PAGE_SIZE) || 1;
    if (samplingCarCurrentPage > samplingCarTotalPages) samplingCarCurrentPage = samplingCarTotalPages;
    if (samplingCarCurrentPage < 1) samplingCarCurrentPage = 1;
}

function samplingCarRenderPagination() {
    const pagination = document.getElementById('samplingCarPagination');
    let html = '';

    html += `<button onclick="samplingCarGoToPage(${samplingCarCurrentPage - 1})" ${samplingCarCurrentPage === 1 ? 'disabled' : ''}>上一页</button>`;

    const maxButtons = 5;
    let startPage = Math.max(1, samplingCarCurrentPage - Math.floor(maxButtons / 2));
    let endPage = Math.min(samplingCarTotalPages, startPage + maxButtons - 1);

    if (endPage - startPage < maxButtons - 1) {
        startPage = Math.max(1, endPage - maxButtons + 1);
    }

    if (startPage > 1) {
        html += `<button onclick="samplingCarGoToPage(1)">1</button>`;
        if (startPage > 2) html += `<span style="padding: 0 5px;">...</span>`;
    }

    for (let i = startPage; i <= endPage; i++) {
        html += `<button onclick="samplingCarGoToPage(${i})" ${i === samplingCarCurrentPage ? 'class="active"' : ''}>${i}</button>`;
    }

    if (endPage < samplingCarTotalPages) {
        if (endPage < samplingCarTotalPages - 1) html += `<span style="padding: 0 5px;">...</span>`;
        html += `<button onclick="samplingCarGoToPage(${samplingCarTotalPages})">${samplingCarTotalPages}</button>`;
    }

    html += `<button onclick="samplingCarGoToPage(${samplingCarCurrentPage + 1})" ${samplingCarCurrentPage === samplingCarTotalPages ? 'disabled' : ''}>下一页</button>`;
    html += `<span class="page-info">第 ${samplingCarCurrentPage} / ${samplingCarTotalPages} 页</span>`;

    pagination.innerHTML = html;
}

function samplingCarGoToPage(page) {
    samplingCarCurrentPage = page;
    samplingCarRenderTable();
}

function samplingCarEditCell(rowIndex, colIndex) {
    if (samplingCarEditingCell) {
        samplingCarFinishEditing(true);
    }

    const tbody = document.getElementById('samplingCarTableBody');
    const rows = tbody.getElementsByTagName('tr');
    const row = rows[rowIndex - (samplingCarCurrentPage - 1) * SAMPLING_CAR_PAGE_SIZE];
    if (!row) return;

    const cells = row.getElementsByTagName('td');
    const cellIndex = colIndex + 2;
    const cell = cells[cellIndex];
    if (!cell) return;

    const currentValue = samplingCarFilteredData[rowIndex][colIndex];
    cell.innerHTML = `<input type="text" class="cell-editing" value="${samplingCarEscapeHtml(currentValue)}" onblur="samplingCarFinishEditing(true)" onkeydown="samplingCarHandleCellKeydown(event)">`;
    const input = cell.querySelector('input');
    input.focus();
    input.select();

    samplingCarEditingCell = { rowIndex, colIndex, element: cell };
}

function samplingCarFinishEditing(save) {
    if (!samplingCarEditingCell) return;

    const { rowIndex, colIndex, element } = samplingCarEditingCell;
    const input = element.querySelector('input');
    const fields = ['repairFactory', 'faultDate', 'repairDate', 'fault', 'repairItem', 'repairPerson', 'cost', 'remark'];

    if (save && input) {
        const oldValue = samplingCarData[rowIndex][fields[colIndex]];
        const newValue = input.value;
        
        if (fields[colIndex]) {
            samplingCarData[rowIndex][fields[colIndex]] = newValue;
            samplingCarFilteredData[rowIndex][fields[colIndex]] = newValue;
        }
        saveSamplingCarData();
        
        // 记录审计日志
        if (typeof recordAuditLog === 'function') {
            const carFieldMap = {
                'repairFactory': '维修厂家',
                'repairDate': '维修日期',
                'fault': '故障描述',
                'repairItem': '维修项目',
                'repairPerson': '维修人',
                'cost': '费用',
                'remark': '备注'
            };
            const fieldName = carFieldMap[fields[colIndex]] || fields[colIndex];
            recordAuditLog({
                module: 'samplingCar',
                action: 'update',
                targetId: rowId,
                targetDesc: `编辑采样车维修记录：${fieldName}`,
                changes: { [fields[colIndex]]: { old: oldValue, new: newValue } }
            });
        }
        
        samplingCarShowToast('修改成功', 'success');
    }

    samplingCarEditingCell = null;
    samplingCarRenderTable();
}

function samplingCarHandleCellKeydown(event) {
    if (event.key === 'Enter') {
        event.preventDefault();
        samplingCarFinishEditing(true);
    } else if (event.key === 'Escape') {
        event.preventDefault();
        samplingCarFinishEditing(false);
    }
}

function samplingCarEditHeader(colIndex) {
    samplingCarShowToast('表头不可编辑', 'warning');
}

function samplingCarFinishHeaderEdit(save) {
    samplingCarEditingHeader = null;
    samplingCarRenderTable();
}

function samplingCarHandleHeaderKeydown(event) {
    if (event.key === 'Enter' || event.key === 'Escape') {
        samplingCarFinishHeaderEdit(event.key === 'Enter');
    }
}

function samplingCarAddLedger() {
    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.style.cssText = `
        display: block;
    `;

    const modalContent = document.createElement('div');
    modalContent.className = 'modal-content';

    const headers = SAMPLING_CAR_HEADERS;
    const fields = ['repairFactory', 'faultDate', 'repairDate', 'fault', 'repairItem', 'repairPerson', 'cost', 'remark'];
    
    let formHtml = `
        <div class="modal-header">
            <h2>添加采样车维修台账</h2>
            <span class="close" id="sampling-car-add-close">&times;</span>
        </div>
        <form id="samplingCarAddForm">
            <div class="form-grid">
    `;

    for (let i = 0; i < headers.length; i++) {
        const header = headers[i];
        const fieldName = fields[i];
        const isTextArea = header === '故障描述' || header === '维修项目' || header === '备注';
        
        if (header === '维修日期' || header === '故障日期') {
            formHtml += `
                <div class="form-group">
                    <label>${header}</label>
                    <input type="date" id="sampling-car-add-field-${i}" value="${new Date().toISOString().split('T')[0]}">
                </div>
            `;
        } else if (isTextArea) {
            formHtml += `
                <div class="form-group">
                    <label>${header}</label>
                    <textarea id="sampling-car-add-field-${i}" placeholder="请输入${header}"></textarea>
                </div>
            `;
        } else {
            formHtml += `
                <div class="form-group">
                    <label>${header}</label>
                    <input type="text" id="sampling-car-add-field-${i}" placeholder="请输入${header}">
                </div>
            `;
        }
    }

    formHtml += `
            </div>
            <div class="form-actions">
                <button type="button" class="btn btn-cancel" id="sampling-car-add-cancel">取消</button>
                <button type="button" class="btn btn-primary" id="sampling-car-add-save">保存</button>
            </div>
        </form>
    `;

    modalContent.innerHTML = formHtml;
    modal.appendChild(modalContent);
    document.body.appendChild(modal);

    const closeModal = () => {
        document.body.removeChild(modal);
    };

    document.getElementById('sampling-car-add-close').addEventListener('click', closeModal);
    document.getElementById('sampling-car-add-cancel').addEventListener('click', closeModal);
    document.getElementById('sampling-car-add-save').addEventListener('click', () => {
        const newRow = { id: Date.now() };
        for (let i = 0; i < fields.length; i++) {
            const input = document.getElementById(`sampling-car-add-field-${i}`);
            if (input) {
                newRow[fields[i]] = input.value;
            }
        }

        samplingCarData.push(newRow);
        samplingCarFilteredData.push(newRow);
        saveSamplingCarData();
        samplingCarRenderTable();
        samplingCarUpdateStats();
        closeModal();
        samplingCarShowToast('台账添加成功', 'success');
    });

    modal.onclick = function(e) {
        if (e.target === modal) {
            closeModal();
        }
    };
}

function samplingCarAddNewRow() {
    const newId = Date.now();
    const newRow = {
        id: newId,
        repairFactory: '',
        faultDate: '',
        repairDate: new Date().toISOString().split('T')[0],
        fault: '',
        repairItem: '',
        repairPerson: '',
        cost: 0,
        remark: ''
    };
    
    samplingCarData.push(newRow);
    samplingCarFilteredData.push(newRow);
    samplingCarIsAddingNewRow = true;
    samplingCarNewRowIndex = samplingCarData.length - 1;
    
    const addBtn = document.getElementById('samplingCarAddRowBtn');
    const saveBtn = document.getElementById('samplingCarSaveNewRowBtn');
    if (addBtn) addBtn.style.display = 'none';
    if (saveBtn) saveBtn.style.display = 'inline-flex';
    
    saveSamplingCarData();
    samplingCarRenderTable();
    samplingCarShowToast('已添加新行，请填写内容后点击保存', 'success');
}

function samplingCarSaveNewRow() {
    if (!samplingCarIsAddingNewRow || samplingCarNewRowIndex < 0) {
        samplingCarShowToast('没有需要保存的新行', 'warning');
        return;
    }

    const tbody = document.getElementById('samplingCarTableBody');
    const rows = tbody.getElementsByTagName('tr');
    if (rows.length === 0) return;

    const lastRowIndex = rows.length - 1;
    const row = rows[lastRowIndex];
    const inputs = row.querySelectorAll('input.new-row-input');
    const fields = ['repairFactory', 'faultDate', 'repairDate', 'fault', 'repairItem', 'repairPerson', 'cost', 'remark'];
    
    inputs.forEach((input) => {
        const colIndex = parseInt(input.getAttribute('data-col'));
        if (!isNaN(colIndex) && fields[colIndex]) {
            samplingCarData[samplingCarNewRowIndex][fields[colIndex]] = input.value;
        }
    });
    
    saveSamplingCarData();
    
    // 添加到离线队列进行自动同步
    if (window.OfflineQueue) {
        const newRow = samplingCarData[samplingCarData.length - 1];
        if (newRow && newRow.id) {
            window.OfflineQueue.add({
                module: 'samplingCar',
                type: 'create',
                recordId: String(newRow.id),
                data: newRow
            });
        }
    }
    
    // 增量同步：添加新行后同步到云端（使用批量增量同步）
    if (typeof window.syncSamplingCarDataIncrementally === 'function') {
        window.syncSamplingCarDataIncrementally(samplingCarData).catch(err => {
            console.error('采样车维修数据同步到云端失败:', err);
        });
    }
    
    samplingCarIsAddingNewRow = false;
    samplingCarNewRowIndex = -1;
    
    const addBtn = document.getElementById('samplingCarAddRowBtn');
    const saveBtn = document.getElementById('samplingCarSaveNewRowBtn');
    if (addBtn) addBtn.style.display = 'inline-flex';
    if (saveBtn) saveBtn.style.display = 'none';
    
    samplingCarRenderTable();
    
    samplingCarShowToast('保存成功！', 'success');
}

function samplingCarEditRow(rowIndex) {
    console.log('[DEBUG] samplingCarEditRow called with rowIndex:', rowIndex);
    const data = samplingCarFilteredData[rowIndex];
    console.log('[DEBUG] row data:', data);
    if (!data) {
        console.log('[DEBUG] No data found for rowIndex:', rowIndex);
        return;
    }

    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.style.cssText = `
        display: block;
    `;

    const modalContent = document.createElement('div');
    modalContent.className = 'modal-content';

    const headers = SAMPLING_CAR_HEADERS;
    const fields = ['repairFactory', 'faultDate', 'repairDate', 'fault', 'repairItem', 'repairPerson', 'cost', 'remark'];
    let formHtml = `
        <div class="modal-header">
            <h2>编辑采样车维修记录</h2>
            <span class="close" id="sampling-car-edit-close">&times;</span>
        </div>
        <form id="samplingCarEditForm">
            <div class="form-grid">
    `;
    
    for (let i = 0; i < headers.length; i++) {
        const value = data[fields[i]] || '';
        const isTextArea = headers[i] === '故障描述' || headers[i] === '维修项目' || headers[i] === '备注';
        if (isTextArea) {
            formHtml += `
                <div class="form-group">
                    <label>${headers[i]}</label>
                    <textarea id="car-edit-field-${i}" placeholder="请输入${headers[i]}">${samplingCarEscapeHtml(value)}</textarea>
                </div>
            `;
        } else {
            const fieldType = headers[i] === '维修日期' || headers[i] === '故障日期' ? 'date' : 'text';
            formHtml += `
                <div class="form-group">
                    <label>${headers[i]}</label>
                    <input type="${fieldType}" id="car-edit-field-${i}" value="${samplingCarEscapeHtml(value)}" placeholder="请输入${headers[i]}">
                </div>
            `;
        }
    }

    formHtml += `
            </div>
            <div class="form-actions">
                <button type="button" class="btn btn-cancel">取消</button>
                <button type="button" class="btn btn-primary">保存</button>
            </div>
        </form>
    `;

    modalContent.innerHTML = formHtml;
    modal.appendChild(modalContent);
    document.body.appendChild(modal);

    const closeModal = () => {
        document.body.removeChild(modal);
    };

    modalContent.addEventListener('click', async (e) => {
        if (e.target.classList.contains('btn-primary') || e.target.closest('.btn-primary')) {
            const originalIndex = samplingCarData.findIndex(item => item.id === data.id);
            
            // 保存修改前的原值用于记录变更
            const oldData = originalIndex >= 0 ? { ...samplingCarData[originalIndex] } : null;
            
            for (let i = 0; i < fields.length; i++) {
                const input = modalContent.querySelector(`#car-edit-field-${i}`);
                if (input) {
                    const value = input.value;
                    if (originalIndex >= 0) {
                        samplingCarData[originalIndex][fields[i]] = value;
                    }
                    samplingCarFilteredData[rowIndex][fields[i]] = value;
                }
            }
            
            saveSamplingCarData();
            
            // 记录审计日志
            if (typeof recordAuditLog === 'function') {
                recordAuditLog({
                    module: 'samplingCar',
                    action: 'update',
                    targetId: data.id,
                    targetDesc: `编辑采样车维修记录：${samplingCarFilteredData[rowIndex]?.fault?.substring(0, 20) || ''}...`,
                    changes: { old: oldData, new: samplingCarFilteredData[rowIndex] }
                });
            }
            
            samplingCarShowToast('修改成功', 'success');
            samplingCarRenderTable();
            closeModal();
        } else if (e.target.classList.contains('btn-cancel') || e.target.closest('.btn-cancel')) {
            closeModal();
        } else if (e.target.id === 'sampling-car-edit-close') {
            closeModal();
        }
    });

    modal.addEventListener('click', (e) => {
        if (e.target === modal) closeModal();
    });
}

async function samplingCarDeleteRow(rowIndex) {
    console.log('[DEBUG] samplingCarDeleteRow called with rowIndex:', rowIndex);
    if (!confirm('确定要删除这一行吗？')) {
        console.log('[DEBUG] User cancelled deletion');
        return;
    }

    const rowData = samplingCarFilteredData[rowIndex];
    if (!rowData) return;
    
    // 通过id找到原始数据的正确索引
    const originalIndex = samplingCarData.findIndex(item => item.id === rowData.id);
    
    // 保存要删除的数据用于审计
    const deletedData = originalIndex >= 0 ? { ...samplingCarData[originalIndex] } : { ...rowData };
    
    // 删除本地数据
    if (originalIndex >= 0) {
        samplingCarData.splice(originalIndex, 1);
    }
    samplingCarFilteredData.splice(rowIndex, 1);
    
    samplingCarSelectedRows.delete(rowIndex);
    samplingCarUpdateSelectedRowsIndices();
    saveSamplingCarData();
    
    // 记录审计日志
    if (typeof recordAuditLog === 'function') {
        recordAuditLog({
            module: 'samplingCar',
            action: 'delete',
            targetId: rowData.id,
            targetDesc: `删除采样车维修记录：${deletedData?.fault?.substring(0, 20) || ''}...`,
            changes: null
        });
    }

    if (samplingCarData.length === 0) {
        samplingCarShowToast('最后一行已删除', 'info');
    } else {
        samplingCarShowToast('删除成功！数据已保存到本地，点击"保存到云端"按钮上传到数据库。', 'success');
    }
    
    samplingCarRenderTable();
}

function samplingCarDeleteSelectedRows() {
    if (samplingCarSelectedIds.length === 0) {
        samplingCarShowToast('请先选择要删除的行', 'warning');
        return;
    }

    if (!confirm(`确定要删除选中的 ${samplingCarSelectedIds.length} 行吗？`)) return;

    const deleteIds = [...samplingCarSelectedIds];
    
    // 保存要删除的数据用于审计
    const deletedItems = [];
    deleteIds.forEach(id => {
        const item = samplingCarData.find(item => item.id === id);
        if (item) {
            deletedItems.push({ ...item });
        }
    });
    
    // 根据ID删除数据
    deleteIds.forEach(id => {
        const index = samplingCarData.findIndex(item => item.id === id);
        if (index !== -1) {
            samplingCarData.splice(index, 1);
        }
        const filteredIndex = samplingCarFilteredData.findIndex(item => item.id === id);
        if (filteredIndex !== -1) {
            samplingCarFilteredData.splice(filteredIndex, 1);
        }
    });

    samplingCarSelectedIds = [];
    saveSamplingCarData();
    
    // 记录审计日志
    if (typeof recordAuditLog === 'function') {
        recordAuditLog({
            module: 'samplingCar',
            action: 'batchDelete',
            targetId: 'multiple',
            targetDesc: `批量删除 ${deleteIds.length} 条采样车维修记录`,
            changes: null
        });
    }

    if (samplingCarData.length === 0) {
        samplingCarShowToast(`已删除所有数据`, 'info');
    } else {
        samplingCarShowToast(`已删除 ${deleteIds.length} 行！数据已保存到本地，点击"保存到云端"按钮上传到数据库。`, 'success');
    }
    
    samplingCarUpdateBatchDeleteButton();
    samplingCarRenderTable();
}

async function syncSamplingCarToCloudSilent() {
    const samplingCarData = JSON.parse(localStorage.getItem(SAMPLING_CAR_STORAGE_KEY) || '{}');

    console.log('开始同步采样车维修台账数据到云端...');

    if (typeof supabaseRequest === 'function') {
        // 使用 UPSERT 方式
        const cloudData = {
            data: samplingCarData,
            updated_at: new Date().toISOString()
        };

        const existingData = await supabaseRequest('GET', 'sampling_car_data');

        let result;
        if (existingData && existingData.length > 0 && existingData[0].id) {
            console.log('云端已有数据，使用 PATCH 更新');
            result = await supabaseRequest('PATCH', 'sampling_car_data', cloudData, {
                id: `eq.${existingData[0].id}`
            });
        } else {
            console.log('云端没有数据，使用 POST 创建');
            result = await supabaseRequest('POST', 'sampling_car_data', {
                id: generateUUID(),
                ...cloudData,
                created_at: new Date().toISOString()
            });
        }

        if (result !== null) {
            console.log('采样车维修台账数据同步成功');
        } else {
            console.error('采样车维修台账数据同步失败');
        }
    }
}

function samplingCarToggleSelectAll(checkbox) {
    const checkboxes = document.querySelectorAll('#samplingCarTableBody .row-checkbox');
    
    if (checkbox.checked) {
        checkboxes.forEach(cb => {
            cb.checked = true;
            const id = parseFloat(cb.dataset.id);
            if (!samplingCarSelectedIds.includes(id)) {
                samplingCarSelectedIds.push(id);
            }
        });
    } else {
        checkboxes.forEach(cb => {
            cb.checked = false;
        });
        // 清空所有选中
        const idsToRemove = Array.from(document.querySelectorAll('#samplingCarTableBody .row-checkbox')).map(cb => parseFloat(cb.dataset.id));
        samplingCarSelectedIds = samplingCarSelectedIds.filter(id => !idsToRemove.includes(id));
    }
    samplingCarUpdateBatchDeleteButton();
}

function samplingCarToggleRowSelect(id) {
    const numericId = typeof id === 'string' ? parseFloat(id) : id;
    const checkbox = document.querySelector(`#samplingCarTableBody .row-checkbox[data-id="${numericId}"]`);
    if (checkbox) {
        if (checkbox.checked) {
            if (!samplingCarSelectedIds.includes(numericId)) {
                samplingCarSelectedIds.push(numericId);
            }
        } else {
            samplingCarSelectedIds = samplingCarSelectedIds.filter(selectedId => selectedId !== numericId);
        }
        samplingCarUpdateBatchDeleteButton();
    }
}

function samplingCarUpdateBatchDeleteButton() {
    const deleteBtn = document.getElementById('samplingCarDeleteBtn');
    const exportBtn = document.getElementById('samplingCarExportSelectedBtn');
    const selectedCountEl = document.getElementById('samplingCarSelectedCount');
    
    const hasSelection = samplingCarSelectedIds.length > 0;
    
    if (deleteBtn) {
        deleteBtn.style.display = hasSelection ? 'inline-flex' : 'none';
        deleteBtn.disabled = !hasSelection;
    }
    
    if (exportBtn) {
        exportBtn.style.display = hasSelection ? 'inline-flex' : 'none';
        exportBtn.disabled = !hasSelection;
    }
    
    if (selectedCountEl) {
        selectedCountEl.textContent = samplingCarSelectedIds.length;
    }
}

function samplingCarUpdateSelectedRowsIndices() {
    const newSelected = new Set();
    samplingCarSelectedRows.forEach(oldIndex => {
        let newIndex = oldIndex;
        samplingCarSelectedRows.forEach(idx => {
            if (idx < oldIndex) newIndex--;
        });
        if (newIndex >= 0 && newIndex < samplingCarFilteredData.length) {
            newSelected.add(newIndex);
        }
    });
    samplingCarSelectedRows = newSelected;
}

function samplingCarHandleSearch(event) {
    if (event.key === 'Enter') {
        samplingCarFilter();
    }
}

function samplingCarFilter() {
    const yearFilter = document.getElementById('samplingCarYearFilter')?.value || 'all';
    const monthFilter = document.getElementById('samplingCarMonthFilter')?.value || 'all';
    const dateFieldFilter = document.getElementById('samplingCarDateFieldFilter')?.value || 'faultDate';
    samplingCarSearchKeyword = document.getElementById('samplingCarSearchInput')?.value.trim().toLowerCase() || '';
    samplingCarCurrentPage = 1;
    const fields = ['repairFactory', 'faultDate', 'repairDate', 'fault', 'repairItem', 'repairPerson', 'cost', 'remark'];

    samplingCarFilteredData = samplingCarData.filter(row => {
        const matchSearch = !samplingCarSearchKeyword || fields.some(field =>
            String(row[field] || '').toLowerCase().includes(samplingCarSearchKeyword)
        );

        const filterDate = dateFieldFilter === 'faultDate' ? row.faultDate : row.repairDate;

        let matchYear = true;
        if (yearFilter !== 'all') {
            if (filterDate) {
                matchYear = filterDate.substring(0, 4) === yearFilter;
            } else {
                matchYear = false;
            }
        }

        let matchMonth = true;
        if (monthFilter !== 'all') {
            if (filterDate) {
                matchMonth = filterDate.substring(5, 7) === monthFilter;
            } else {
                matchMonth = false;
            }
        }

        return matchSearch && matchYear && matchMonth;
    });

    samplingCarSelectedRows.clear();
    samplingCarRenderTable();
}

function initSamplingCarYearFilter() {
    const yearFilter = document.getElementById('samplingCarYearFilter');
    if (!yearFilter) return;

    const years = new Set(['all']);

    // 同时遍历故障日期和维修日期，确保所有年份都被包含
    samplingCarData.forEach(item => {
        if (item.faultDate) {
            years.add(item.faultDate.substring(0, 4));
        }
        if (item.repairDate) {
            years.add(item.repairDate.substring(0, 4));
        }
    });

    const currentYear = new Date().getFullYear();
    for (let year = currentYear; year >= 2020; year--) {
        if (years.has(year.toString()) || year === currentYear || year === currentYear - 1) {
            years.add(year.toString());
        }
    }

    const sortedYears = Array.from(years).sort((a, b) => {
        if (a === 'all') return -1;
        if (b === 'all') return 1;
        return parseInt(b) - parseInt(a);
    });

    yearFilter.innerHTML = sortedYears.map(year =>
        `<option value="${year}">${year === 'all' ? '全部年份' : `${year}年`}</option>`
    ).join('');
}

