function samplingCarHandleDrop(event) {
    event.preventDefault();
    event.currentTarget.classList.remove('dragover');

    const file = event.dataTransfer.files[0];
    if (file) {
        samplingCarProcessFile(file);
    }
}

function samplingCarHandleFileSelect(event) {
    const file = event.target.files[0];
    if (!file) return;
    
    if (isSamplingCarImporting) {
        alert('正在导入中，请稍候...');
        return;
    }
    isSamplingCarImporting = true;
    
    samplingCarProcessFile(file);
}

function samplingCarProcessFile(file) {
    const fileName = file.name.toLowerCase();
    const isExcel = fileName.endsWith('.xlsx') || fileName.endsWith('.xls');
    const isImage = fileName.endsWith('.jpg') || fileName.endsWith('.jpeg') || fileName.endsWith('.png') || fileName.endsWith('.gif');

    if (!isExcel && !isImage) {
        samplingCarShowToast('请上传Excel文件（.xlsx, .xls）或图片文件（.jpg, .jpeg, .png, .gif）', 'error');
        return;
    }

    const selectedFileName = document.getElementById('samplingCarSelectedFileName');
    if (selectedFileName) selectedFileName.textContent = file.name;

    if (isExcel) {
        samplingCarProcessExcelFile(file);
    } else if (isImage) {
        samplingCarProcessImageFile(file);
    }
}

function samplingCarProcessExcelFile(file) {
    const reader = new FileReader();
    reader.onload = function(e) {
        try {
            const data = new Uint8Array(e.target.result);
            const workbook = XLSX.read(data, { type: 'array', cellDates: true, raw: false });

            if (!workbook || !workbook.SheetNames || workbook.SheetNames.length === 0) {
                samplingCarShowToast('Excel文件中没有工作表', 'error');
                isSamplingCarImporting = false;
                return;
            }

            const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
            const jsonData = XLSX.utils.sheet_to_json(firstSheet, { defval: '', raw: false });

            if (jsonData.length < 1) {
                samplingCarShowToast('Excel文件中没有数据', 'error');
                isSamplingCarImporting = false;
                return;
            }

            const headers = Object.keys(jsonData[0]);
            samplingCarPreviewData = { headers, data: jsonData };

            samplingCarShowPreview(headers, jsonData);
            safeSetDisplay('samplingCarPreviewSection', 'block');
            const confirmBtn = document.getElementById('samplingCarConfirmImportBtn');
            if (confirmBtn) confirmBtn.disabled = false;

        } catch (error) {
            console.error('解析Excel失败:', error);
            samplingCarShowToast('解析Excel文件失败：' + error.message, 'error');
            isSamplingCarImporting = false;
        }
    };
    reader.onerror = function() {
        samplingCarShowToast('文件读取失败，请重试', 'error');
        isSamplingCarImporting = false;
    };
    reader.readAsArrayBuffer(file);
}

function samplingCarProcessImageFile(file) {
    const reader = new FileReader();
    reader.onload = function(e) {
        try {
            const imageDataUrl = e.target.result;
            const headers = SAMPLING_CAR_HEADERS;
            const data = [headers.reduce((acc, h) => ({ ...acc, [h]: '' }), {})];
            samplingCarPreviewData = { headers, data, imageDataUrl };

            samplingCarShowImageWithExistingHeaders(imageDataUrl, headers, data);
            safeSetDisplay('samplingCarPreviewSection', 'block');
            const confirmBtn = document.getElementById('samplingCarConfirmImportBtn');
            if (confirmBtn) confirmBtn.disabled = false;

        } catch (error) {
            console.error('处理图片失败:', error);
            samplingCarShowToast('处理图片文件失败：' + error.message, 'error');
        }
    };
    reader.readAsDataURL(file);
}

