function samplingCarConfirmImport() {
    if (!samplingCarPreviewData) {
        samplingCarShowToast('请先选择文件', 'warning');
        return;
    }

    const newData = samplingCarPreviewData.data.map(row => {
        const newRow = {
            id: Date.now() + Math.random(),
            repairFactory: '',
            faultDate: '',
            repairDate: '',
            fault: '',
            repairItem: '',
            repairPerson: '',
            cost: '',
            remark: ''
        };
        
        samplingCarPreviewData.headers.forEach(header => {
            const headerTrimmed = header.trim();
            const cellValue = row[header] !== undefined ? row[header] : '';
            const value = String(cellValue).trim();
            
            if (headerTrimmed === '维修厂家') {
                newRow.repairFactory = value;
            } else if (headerTrimmed === '故障日期') {
                newRow.faultDate = value;
            } else if (headerTrimmed === '维修日期') {
                newRow.repairDate = value;
            } else if (headerTrimmed === '故障描述') {
                newRow.fault = value;
            } else if (headerTrimmed === '维修项目') {
                newRow.repairItem = value;
            } else if (headerTrimmed === '维修人') {
                newRow.repairPerson = value;
            } else if (headerTrimmed === '费用') {
                newRow.cost = value;
            } else if (headerTrimmed === '备注') {
                newRow.remark = value;
            }
        });
        
        if (!newRow.repairDate) {
            newRow.repairDate = new Date().toISOString().split('T')[0];
        }
        
        return newRow;
    });

    samplingCarData = [...samplingCarData, ...newData];
    samplingCarFilteredData = [...samplingCarData];
    samplingCarSearchKeyword = '';
    const searchInput = document.getElementById('samplingCarSearchInput');
    if (searchInput) searchInput.value = '';
    samplingCarCurrentPage = 1;
    samplingCarSelectedRows.clear();

    saveSamplingCarData();
    samplingCarRenderTable();
    closeSamplingCarUploadModal();
    
    samplingCarShowToast(`成功追加 ${newData.length} 行数据，总计 ${samplingCarData.length} 行，请点击"保存到云端"按钮上传到数据库`, 'success');
    isSamplingCarImporting = false;
}

function samplingCarClearFile() {
    samplingCarResetUploadModal();
}

async function samplingCarExportSelected() {
    if (samplingCarSelectedIds.length === 0) {
        samplingCarShowToast('请先选择要导出的数据', 'warning');
        return;
    }

    // 根据选中的ID筛选数据
    const selectedData = samplingCarData.filter(row => 
        samplingCarSelectedIds.includes(row.id)
    );

    const headers = SAMPLING_CAR_HEADERS;
    const fields = ['repairFactory', 'faultDate', 'repairDate', 'fault', 'repairItem', 'repairPerson', 'cost', 'remark'];
    const data = selectedData.map(row => {
        return fields.map(field => row[field] || '');
    });

    const filename = `采样车维修台账-选中-${new Date().getTime()}.xlsx`;
    await exportToExcelWithStyle(data, headers, '采样车维修台账-选中', filename);

    samplingCarShowToast('导出成功：' + filename, 'success');
}

async function samplingCarExportToExcel() {
    if (samplingCarFilteredData.length === 0) {
        samplingCarShowToast('没有数据可导出', 'warning');
        return;
    }

    const headers = SAMPLING_CAR_HEADERS;
    const fields = ['repairFactory', 'faultDate', 'repairDate', 'fault', 'repairItem', 'repairPerson', 'cost', 'remark'];
    const data = samplingCarFilteredData.map(row => {
        return fields.map(field => row[field] || '');
    });

    const yearFilter = document.getElementById('samplingCarYearFilter')?.value || 'all';
    const monthFilter = document.getElementById('samplingCarMonthFilter')?.value || 'all';
    const dateFieldFilter = document.getElementById('samplingCarDateFieldFilter')?.value || 'faultDate';

    let datePart = '';
    if (yearFilter !== 'all') {
        datePart += `${yearFilter}年`;
        if (monthFilter !== 'all') {
            datePart += `${monthFilter}月`;
        }
    }

    const dateFieldText = dateFieldFilter === 'faultDate' ? '故障日期' : '维修日期';
    
    const currentDate = new Date().toISOString().split('T')[0];
    let filename = `采样车维修台账`;
    if (datePart) {
        filename += `_${dateFieldText}_${datePart}`;
    }
    filename += `_${currentDate}.xlsx`;

    const sheetName = datePart ? `采样车维修台账${datePart}` : '采样车维修台账';

    await exportToExcelWithStyle(data, headers, sheetName, filename);

    samplingCarShowToast('导出成功：' + filename, 'success');
}

function samplingCarUpdateStats() {
    const totalRows = document.getElementById('samplingCarTotalRows');
    if (totalRows) totalRows.textContent = samplingCarFilteredData.length;
    const selectedCount = document.getElementById('samplingCarSelectedCount');
    if (selectedCount) selectedCount.textContent = samplingCarSelectedIds.length;

    const deleteBtn = document.getElementById('samplingCarDeleteBtn');
    if (deleteBtn) deleteBtn.disabled = samplingCarSelectedIds.length === 0;
}

function samplingCarShowToast(message, type = 'success') {
    const toast = document.getElementById('samplingCarToast');
    toast.textContent = message;
    toast.className = `toast ${type} show`;

    setTimeout(() => {
        toast.classList.remove('show');
    }, 3000);
}

function samplingCarEscapeHtml(str) {
    if (str === null || str === undefined) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

// ==================== 采样车表格列宽调整功能 ====================
let isResizing = false;
let resizeColIndex = -1;
let startX = 0;
let startWidth = 0;

function startColumnResize(e, colIndex) {
    isResizing = true;
    resizeColIndex = colIndex;
    startX = e.clientX;
    
    const th = document.querySelector(`#samplingCarDataTable th[data-col="${colIndex}"]`);
    if (th) {
        startWidth = th.offsetWidth;
    }
    
    document.addEventListener('mousemove', doColumnResize);
    document.addEventListener('mouseup', stopColumnResize);
    e.preventDefault();
}

function doColumnResize(e) {
    if (!isResizing) return;
    
    const th = document.querySelector(`#samplingCarDataTable th[data-col="${resizeColIndex}"]`);
    if (th) {
        const diff = e.clientX - startX;
        const newWidth = Math.max(60, startWidth + diff);
        th.style.minWidth = newWidth + 'px';
        th.style.maxWidth = (newWidth * 2) + 'px';
    }
}

function stopColumnResize() {
    isResizing = false;
    resizeColIndex = -1;
    startX = 0;
    startWidth = 0;
    document.removeEventListener('mousemove', doColumnResize);
    document.removeEventListener('mouseup', stopColumnResize);
}

// 加载仪器维修台账数据
function loadInstrumentData() {
    try {
        const saved = localStorage.getItem(INSTRUMENT_STORAGE_KEY);
        if (saved) {
            const savedData = JSON.parse(saved);
            instrumentData = savedData.data || [];
            console.log('从localStorage加载仪器维修台账数据，条数:', instrumentData.length);
        } else {
            instrumentData = [...mockInstrumentData];
            console.log('使用默认仪器维修台账数据');
            saveInstrumentData();
        }
    } catch (e) {
        console.error('加载仪器数据失败:', e);
        instrumentData = [...mockInstrumentData];
    }
    // 按故障日期倒序排序（时间晚的在前面）
    instrumentData.sort((a, b) => {
        const dateA = new Date(a.faultDate || a.repairDate || a.date || '');
        const dateB = new Date(b.faultDate || b.repairDate || b.date || '');
        return dateB.getTime() - dateA.getTime();
    });
    instrumentFilteredData = [...instrumentData];
}

// 保存仪器维修台账数据
function saveInstrumentData() {
    const dataToSave = {
        data: instrumentData,
        lastModified: new Date().toISOString()
    };
    localStorage.setItem(INSTRUMENT_STORAGE_KEY, JSON.stringify(dataToSave));
}

/**
 * 从云端刷新仪器维修数据（专用函数，与 saveInstrumentToCloud 配套使用）
 * 云端数据格式: { id, data: { data: [records...], lastModified }, updated_at, created_at }
 * @returns {boolean} true=成功从云端获取并更新, false=云端无数据或失败
 */
async function refreshInstrumentFromCloud() {
    try {
        console.log('[仪器模块] 开始从云端刷新数据...');

        if (typeof supabaseRequest !== 'function') {
            console.warn('[仪器模块] Supabase不可用，跳过刷新');
            return false;
        }

        const cloudData = await supabaseRequest('GET', 'instrument_data');

        if (!cloudData || cloudData.length === 0 || !cloudData[0].data) {
            console.log('[仪器模块] 云端没有数据，保留本地数据');
            return false;
        }

        // 云端 data 字段格式: 可能是数组，也可能是 { data: [...] }
        let instrumentArray = [];
        const recordData = cloudData[0].data;

        if (Array.isArray(recordData)) {
            instrumentArray = recordData;
        } else if (recordData.data && Array.isArray(recordData.data)) {
            instrumentArray = recordData.data;
        } else {
            console.warn('[仪器模块] 云端数据格式无法解析:', recordData);
            return false;
        }

        if (instrumentArray.length === 0) {
            console.log('[仪器模块] 云端数据是空的，保留本地数据');
            return false;
        }

        instrumentData = instrumentArray;
        instrumentFilteredData = [...instrumentArray];
        window.instrumentData = instrumentData;
        window.instrumentFilteredData = instrumentFilteredData;

        saveInstrumentData();

        console.log('[仪器模块] 已从云端刷新，记录数:', instrumentArray.length);
        instrumentRenderTable();
        instrumentUpdateStats();

        return true;
    } catch (error) {
        console.error('[仪器模块] 从云端刷新失败:', error);
        alert('⚠️ 从云端刷新失败: ' + (error.message || '未知错误'));
        return false;
    }
}

const INSTRUMENT_HEADERS = ['仪器编号', '仪器名称', '故障日期', '故障现象', '维修内容', '维修日期', '维修人', '更换配件', '备注'];

function instrumentRenderTable() {
    const thead = document.getElementById('instrumentTableHead');
    const tbody = document.getElementById('instrumentTableBody');
    const emptyState = document.getElementById('instrumentEmptyState');
    const exportBtn = document.getElementById('instrumentExportBtn');

    safeSetDisplay('instrumentEmptyState', instrumentData.length === 0 ? 'block' : 'none');
    if (exportBtn) exportBtn.disabled = instrumentData.length === 0;

    if (instrumentData.length === 0) {
        thead.innerHTML = '';
        tbody.innerHTML = '';
        return;
    }

    instrumentCalculatePagination();
    const startIndex = (instrumentCurrentPage - 1) * INSTRUMENT_PAGE_SIZE;
    const endIndex = startIndex + INSTRUMENT_PAGE_SIZE;
    const pageData = instrumentFilteredData.slice(startIndex, endIndex);

    // 检查当前页所有行是否都被选中
    let allChecked = true;
    for (let i = startIndex; i < endIndex; i++) {
        const row = instrumentFilteredData[i];
        if (!row || !row.id) {
            allChecked = false;
            break;
        }
        const rowId = String(row.id);
        const isInSelected = instrumentSelectedIds.some(id => String(id) === rowId);
        if (!isInSelected) {
            allChecked = false;
            break;
        }
    }

    thead.innerHTML = `
        <tr>
            <th style="min-width: 40px;"><input type="checkbox" class="row-checkbox" onchange="instrumentToggleSelectAll(this)" ${allChecked ? 'checked' : ''}></th>
            <th style="min-width: 50px;">序号</th>
            ${INSTRUMENT_HEADERS.map((header, index) => `
                <th data-col="${index}">
                    <span class="header-editable">${instrumentEscapeHtml(header)}</span>
                    <span class="resize-handle" onmousedown="startInstrumentColumnResize(event, ${index})"></span>
                </th>
            `).join('')}
            <th style="min-width: 100px;">操作</th>
        </tr>
    `;

    tbody.innerHTML = pageData.map((row, rowIndex) => {
        const actualIndex = startIndex + rowIndex;
        const rowId = row.id !== undefined && row.id !== null ? String(row.id) : '';
        const isSelected = rowId && instrumentSelectedIds.some(id => String(id) === rowId);
        const serialNumber = actualIndex + 1;
        const isNewRow = instrumentIsAddingNewRow && actualIndex === instrumentNewRowIndex;
        
        const fields = ['instrumentNo', 'instrumentName', 'faultDate', 'faultPhenomenon', 'repairContent', 'repairDate', 'repairPerson', 'spareParts', 'remark'];
        const rowData = fields.map(field => row[field] || '');
        
        let cellsHtml;
        if (isNewRow) {
            cellsHtml = rowData.map((cell, cellIndex) => `
                <td>
                    <input type="text" class="new-row-input" data-col="${cellIndex}" value="${instrumentEscapeHtml(cell)}" placeholder="请输入">
                </td>
            `).join('');
        } else {
            cellsHtml = rowData.map((cell, cellIndex) => `
                <td>
                    <span>${instrumentEscapeHtml(cell)}</span>
                </td>
            `).join('');
        }
        
        return `
            <tr data-index="${actualIndex}" style="background-color: ${isNewRow ? '#fff3cd' : (isSelected ? '#E8F5E9' : '')}">
                <td><input type="checkbox" class="row-checkbox" data-id="${rowId}" ${isSelected ? 'checked' : ''} onchange="instrumentToggleRowSelect('${rowId}')"></td>
                <td>${serialNumber}</td>
                ${cellsHtml}
                <td>
                    <button class="action-btn btn-edit" onclick="instrumentEditRow(${actualIndex})">编辑</button>
                    <button class="action-btn btn-delete" onclick="instrumentDeleteRow(${actualIndex})">删除</button>
                </td>
            </tr>
        `;
    }).join('');

    instrumentRenderPagination();
    instrumentUpdateStats();
    instrumentUpdateBatchDeleteButton();
    
    // 表格渲染完成后，自动调整列宽
    setTimeout(() => {
        if (typeof autoAdjustTableColumnWidths === 'function') {
            autoAdjustTableColumnWidths('instrumentDataTable');
        }
    }, 100);
}

function instrumentCalculatePagination() {
    instrumentTotalPages = Math.ceil(instrumentFilteredData.length / INSTRUMENT_PAGE_SIZE) || 1;
    if (instrumentCurrentPage > instrumentTotalPages) instrumentCurrentPage = instrumentTotalPages;
    if (instrumentCurrentPage < 1) instrumentCurrentPage = 1;
}

function instrumentRenderPagination() {
    const pagination = document.getElementById('instrumentPagination');
    let html = '';

    html += `<button onclick="instrumentGoToPage(${instrumentCurrentPage - 1})" ${instrumentCurrentPage === 1 ? 'disabled' : ''}>上一页</button>`;

    const maxButtons = 5;
    let startPage = Math.max(1, instrumentCurrentPage - Math.floor(maxButtons / 2));
    let endPage = Math.min(instrumentTotalPages, startPage + maxButtons - 1);

    if (endPage - startPage < maxButtons - 1) {
        startPage = Math.max(1, endPage - maxButtons + 1);
    }

    if (startPage > 1) {
        html += `<button onclick="instrumentGoToPage(1)">1</button>`;
        if (startPage > 2) html += `<span style="padding: 0 5px;">...</span>`;
    }

    for (let i = startPage; i <= endPage; i++) {
        html += `<button onclick="instrumentGoToPage(${i})" ${i === instrumentCurrentPage ? 'class="active"' : ''}>${i}</button>`;
    }

    if (endPage < instrumentTotalPages) {
        if (endPage < instrumentTotalPages - 1) html += `<span style="padding: 0 5px;">...</span>`;
        html += `<button onclick="instrumentGoToPage(${instrumentTotalPages})">${instrumentTotalPages}</button>`;
    }

    html += `<button onclick="instrumentGoToPage(${instrumentCurrentPage + 1})" ${instrumentCurrentPage === instrumentTotalPages ? 'disabled' : ''}>下一页</button>`;
    html += `<span class="page-info">第 ${instrumentCurrentPage} / ${instrumentTotalPages} 页</span>`;

    pagination.innerHTML = html;
}

function instrumentGoToPage(page) {
    instrumentCurrentPage = page;
    instrumentRenderTable();
}

function instrumentEditCell(rowIndex, colIndex) {
    if (instrumentEditingCell) {
        instrumentFinishEditing(true);
    }

    const tbody = document.getElementById('instrumentTableBody');
    const rows = tbody.getElementsByTagName('tr');
    const row = rows[rowIndex - (instrumentCurrentPage - 1) * INSTRUMENT_PAGE_SIZE];
    if (!row) return;

    const cells = row.getElementsByTagName('td');
    const cellIndex = colIndex + 2;
    const cell = cells[cellIndex];
    if (!cell) return;

    const currentValue = instrumentFilteredData[rowIndex][colIndex];
    cell.innerHTML = `<input type="text" class="cell-editing" value="${instrumentEscapeHtml(currentValue)}" onblur="instrumentFinishEditing(true)" onkeydown="instrumentHandleCellKeydown(event)">`;
    const input = cell.querySelector('input');
    input.focus();
    input.select();

    instrumentEditingCell = { rowIndex, colIndex, element: cell };
}

async function instrumentFinishEditing(save) {
    if (!instrumentEditingCell) return;

    const { rowIndex, colIndex, element } = instrumentEditingCell;
    const input = element.querySelector('input');
    const fields = ['instrumentNo', 'instrumentName', 'faultDate', 'faultPhenomenon', 'repairContent', 'repairDate', 'repairPerson', 'spareParts', 'remark'];

    if (save && input) {
        const oldValue = instrumentData[rowIndex][fields[colIndex]];
        const newValue = input.value;
        const rowId = instrumentData[rowIndex].id;
        
        if (fields[colIndex]) {
            instrumentData[rowIndex][fields[colIndex]] = newValue;
            instrumentFilteredData[rowIndex][fields[colIndex]] = newValue;
        }
        saveInstrumentData();

        if (typeof recordAuditLog === 'function') {
            const instrumentFieldMap = {
                'instrumentNo': '仪器编号',
                'instrumentName': '仪器名称',
                'faultDate': '故障日期',
                'faultPhenomenon': '故障现象',
                'repairContent': '维修内容',
                'repairDate': '维修日期',
                'repairPerson': '维修人',
                'spareParts': '更换配件',
                'remark': '备注'
            };
            const fieldName = instrumentFieldMap[fields[colIndex]] || fields[colIndex];
            await recordAuditLog({
                module: 'instrument',
                action: 'update',
                targetId: rowId,
                targetDesc: `编辑仪器维修记录：${fieldName}`,
                changes: { [fieldName]: { old: oldValue, new: newValue } }
            }, true);  // 立即记录
        }

        if (syncSuccess) {
            instrumentShowToast('修改成功', 'success');
        } else if (syncError) {
            instrumentShowToast(`修改成功，但云同步失败: ${syncError.message}`, 'warning');
        } else {
            instrumentShowToast('修改成功', 'success');
        }
    }

    instrumentEditingCell = null;
    instrumentRenderTable();
}

function instrumentHandleCellKeydown(event) {
    if (event.key === 'Enter') {
        event.preventDefault();
        instrumentFinishEditing(true);
    } else if (event.key === 'Escape') {
        event.preventDefault();
        instrumentFinishEditing(false);
    }
}

function instrumentEditHeader(colIndex) {
    instrumentShowToast('表头不可编辑', 'warning');
}

function instrumentFinishHeaderEdit(save) {
    instrumentEditingHeader = null;
    instrumentRenderTable();
}

function instrumentHandleHeaderKeydown(event) {
    if (event.key === 'Enter' || event.key === 'Escape') {
        instrumentFinishHeaderEdit(event.key === 'Enter');
    }
}

function instrumentAddLedger() {
    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.style.cssText = `
        display: block;
    `;

    const modalContent = document.createElement('div');
    modalContent.className = 'modal-content';

    const headers = INSTRUMENT_HEADERS;
    const fields = ['instrumentNo', 'instrumentName', 'faultDate', 'faultPhenomenon', 'repairContent', 'repairDate', 'repairPerson', 'spareParts', 'remark'];
    
    let formHtml = `
        <div class="modal-header">
            <h2>添加仪器维修台账</h2>
            <span class="close" id="instrument-add-close">&times;</span>
        </div>
        <form id="instrumentAddForm">
            <div class="form-grid">
    `;

    for (let i = 0; i < headers.length; i++) {
        const header = headers[i];
        const fieldName = fields[i];
        const isTextArea = header === '故障现象' || header === '维修内容' || header === '更换配件' || header === '备注';
        
        if (header === '维修日期' || header === '故障日期') {
            formHtml += `
                <div class="form-group">
                    <label>${header}</label>
                    <input type="date" id="instrument-add-field-${i}" value="${new Date().toISOString().split('T')[0]}">
                </div>
            `;
        } else if (isTextArea) {
            formHtml += `
                <div class="form-group">
                    <label>${header}</label>
                    <textarea id="instrument-add-field-${i}" placeholder="请输入${header}"></textarea>
                </div>
            `;
        } else {
            formHtml += `
                <div class="form-group">
                    <label>${header}</label>
                    <input type="text" id="instrument-add-field-${i}" placeholder="请输入${header}">
                </div>
            `;
        }
    }

    formHtml += `
            </div>
            <div class="form-actions">
                <button type="button" class="btn btn-cancel" id="instrument-add-cancel">取消</button>
                <button type="button" class="btn btn-primary" id="instrument-add-save">保存</button>
            </div>
        </form>
    `;

    modalContent.innerHTML = formHtml;
    modal.appendChild(modalContent);
    document.body.appendChild(modal);

    const closeModal = () => {
        document.body.removeChild(modal);
    };

    document.getElementById('instrument-add-close').addEventListener('click', closeModal);
    document.getElementById('instrument-add-cancel').addEventListener('click', closeModal);
    document.getElementById('instrument-add-save').addEventListener('click', () => {
        const newRow = { id: Date.now() };
        for (let i = 0; i < fields.length; i++) {
            const input = document.getElementById(`instrument-add-field-${i}`);
            if (input) {
                newRow[fields[i]] = input.value;
            }
        }

        instrumentData.push(newRow);
        instrumentFilteredData.push(newRow);
        saveInstrumentData();
        
        // 添加到离线队列进行自动同步
        if (window.OfflineQueue) {
            window.OfflineQueue.add({
                module: 'instrument',
                type: 'create',
                recordId: String(newRow.id),
                data: newRow
            });
        }
        
        instrumentRenderTable();
        instrumentUpdateStats();
        closeModal();
        instrumentShowToast('台账添加成功', 'success');
    });

    modal.onclick = function(e) {
        if (e.target === modal) {
            closeModal();
        }
    };
}

function instrumentSaveNewRow() {
    instrumentShowToast('此功能已移除，请使用"添加台账"按钮', 'warning');
    return;
}

function instrumentEditRow(rowIndex) {
    const data = instrumentFilteredData[rowIndex];
    if (!data) return;

    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.style.cssText = `
        display: block;
    `;

    const modalContent = document.createElement('div');
    modalContent.className = 'modal-content';

    const headers = INSTRUMENT_HEADERS;
    const fields = ['instrumentNo', 'instrumentName', 'faultDate', 'faultPhenomenon', 'repairContent', 'repairDate', 'repairPerson', 'spareParts', 'remark'];
    let formHtml = `
        <div class="modal-header">
            <h2>编辑仪器维修记录</h2>
            <span class="close" id="instrument-edit-close">&times;</span>
        </div>
        <form id="instrumentEditForm">
            <div class="form-grid">
    `;
    
    for (let i = 0; i < headers.length; i++) {
        const value = data[fields[i]] || '';
        const isTextArea = headers[i] === '维修内容' || headers[i] === '更换配件' || headers[i] === '备注';
        if (isTextArea) {
            formHtml += `
                <div class="form-group">
                    <label>${headers[i]}</label>
                    <textarea id="edit-field-${i}" placeholder="请输入${headers[i]}">${instrumentEscapeHtml(value)}</textarea>
                </div>
            `;
        } else {
            const fieldType = headers[i] === '维修日期' || headers[i] === '故障日期' ? 'date' : 'text';
            formHtml += `
                <div class="form-group">
                    <label>${headers[i]}</label>
                    <input type="${fieldType}" id="edit-field-${i}" value="${instrumentEscapeHtml(value)}" placeholder="请输入${headers[i]}">
                </div>
            `;
        }
    }

    formHtml += `
            </div>
            <div class="form-actions">
                <button type="button" class="btn btn-cancel">取消</button>
                <button type="button" class="btn btn-primary">保存</button>
            </div>
        </form>
    `;

    modalContent.innerHTML = formHtml;
    modal.appendChild(modalContent);
    document.body.appendChild(modal);

    const closeModal = () => {
        document.body.removeChild(modal);
    };

    modalContent.addEventListener('click', async (e) => {
        if (e.target.classList.contains('btn-primary') || e.target.closest('.btn-primary')) {
            const originalIndex = instrumentData.findIndex(item => item.id === data.id);
            
            // 保存修改前的原值用于记录变更
            const oldData = originalIndex >= 0 ? { ...instrumentData[originalIndex] } : null;
            
            for (let i = 0; i < fields.length; i++) {
                const input = modalContent.querySelector(`#edit-field-${i}`);
                if (input) {
                    const value = input.value;
                    if (originalIndex >= 0) {
                        instrumentData[originalIndex][fields[i]] = value;
                    }
                    instrumentFilteredData[rowIndex][fields[i]] = value;
                }
            }
        
            saveInstrumentData();
        
            // 记录审计日志
            if (typeof recordAuditLog === 'function') {
                recordAuditLog({
                    module: 'instrument',
                    action: 'update',
                    targetId: data.id,
                    targetDesc: `编辑仪器维修记录：${instrumentFilteredData[rowIndex]?.instrumentName || ''} - ${instrumentFilteredData[rowIndex]?.repairContent?.substring(0, 15) || ''}...`,
                    changes: { old: oldData, new: instrumentFilteredData[rowIndex] }
                });
            }

            instrumentShowToast('修改成功，数据已保存到本地', 'success');
            instrumentRenderTable();
            closeModal();
        } else if (e.target.classList.contains('btn-cancel') || e.target.closest('.btn-cancel')) {
            closeModal();
        } else if (e.target.id === 'instrument-edit-close') {
            closeModal();
        }
    });

    modal.addEventListener('click', (e) => {
        if (e.target === modal) closeModal();
    });
}

async function instrumentDeleteRow(rowIndex) {
    if (!confirm('确定要删除这一行吗？')) return;

    const rowData = instrumentFilteredData[rowIndex];
    if (!rowData) return;
    
    // 通过id找到原始数据的正确索引
    const originalIndex = instrumentData.findIndex(item => item.id === rowData.id);
    
    // 保存要删除的数据用于审计
    const deletedData = originalIndex >= 0 ? { ...instrumentData[originalIndex] } : { ...rowData };
    
    // 删除本地数据
    if (originalIndex >= 0) {
        instrumentData.splice(originalIndex, 1);
    }
    instrumentFilteredData.splice(rowIndex, 1);
    
    instrumentUpdateBatchDeleteButton();
    saveInstrumentData();
    
    // 记录审计日志
    if (typeof recordAuditLog === 'function') {
        await recordAuditLog({
            module: 'instrument',
            action: 'delete',
            targetId: rowData.id,
            targetDesc: `删除仪器维修记录：${deletedData?.instrumentName || ''} - ${deletedData?.repairContent?.substring(0, 15) || ''}...`,
            changes: null
        }, true);  // 立即记录
    }

    if (instrumentData.length === 0) {
        instrumentShowToast('最后一行已删除', 'info');
    } else {
        instrumentShowToast('删除成功！数据已保存到本地，点击"保存到云端"按钮上传到数据库。', 'success');
    }
    
    instrumentRenderTable();
}

async function instrumentDeleteSelectedRows() {
    if (instrumentSelectedIds.length === 0) {
        instrumentShowToast('请先选择要删除的行', 'warning');
        return;
    }

    if (!confirm(`确定要删除选中的 ${instrumentSelectedIds.length} 行吗？`)) return;

    const deleteIds = [...instrumentSelectedIds];
    
    // 保存要删除的数据用于审计
    const deletedItems = [];
    deleteIds.forEach(id => {
        const item = instrumentData.find(item => String(item.id) === String(id));
        if (item) {
            deletedItems.push({ ...item });
        }
    });
    
    // 根据ID删除数据（处理id类型可能是数字或字符串）
    instrumentData = instrumentData.filter(row => {
        const rowId = String(row.id);
        return !deleteIds.some(id => String(id) === rowId);
    });
    instrumentFilteredData = instrumentFilteredData.filter(row => {
        const rowId = String(row.id);
        return !deleteIds.some(id => String(id) === rowId);
    });

    instrumentSelectedIds = [];
    instrumentUpdateBatchDeleteButton();
    saveInstrumentData();

    // 记录审计日志
    if (typeof recordAuditLog === 'function') {
        await recordAuditLog({
            module: 'instrument',
            action: 'batchDelete',
            targetId: 'multiple',
            targetDesc: `批量删除 ${deleteIds.length} 条仪器维修记录`,
            changes: null
        }, true);  // 立即记录
    }

    if (instrumentData.length === 0) {
        instrumentShowToast(`已删除所有数据`, 'info');
    } else {
        instrumentShowToast(`已删除 ${deleteIds.length} 行，数据已保存到本地，点击"保存到云端"按钮上传到数据库。`, 'success');
    }
    
    instrumentRenderTable();
}

async function syncInstrumentToCloudSilent() {
    const instrumentData = JSON.parse(localStorage.getItem(INSTRUMENT_STORAGE_KEY) || '{}');

    console.log('开始同步仪器维修台账数据到云端...');

    if (typeof supabaseRequest === 'function') {
        // 使用 UPSERT 方式
        const cloudData = {
            data: instrumentData,
            updated_at: new Date().toISOString()
        };

        const existingData = await supabaseRequest('GET', 'instrument_data');

        let result;
        if (existingData && existingData.length > 0 && existingData[0].id) {
            console.log('云端已有数据，使用 PATCH 更新');
            result = await supabaseRequest('PATCH', 'instrument_data', cloudData, {
                id: `eq.${existingData[0].id}`
            });
        } else {
            console.log('云端没有数据，使用 POST 创建');
            result = await supabaseRequest('POST', 'instrument_data', {
                id: generateUUID(),
                ...cloudData,
                created_at: new Date().toISOString()
            });
        }

        if (result !== null) {
            console.log('仪器维修台账数据同步成功');
        } else {
            console.error('仪器维修台账数据同步失败');
        }
    }
}

function instrumentToggleSelectAll(checkbox) {
    const checked = checkbox.checked;
    const startIndex = (instrumentCurrentPage - 1) * INSTRUMENT_PAGE_SIZE;
    const endIndex = Math.min(startIndex + INSTRUMENT_PAGE_SIZE, instrumentFilteredData.length);

    if (checked) {
        for (let i = startIndex; i < endIndex; i++) {
            const row = instrumentFilteredData[i];
            if (row && row.id !== undefined && row.id !== null) {
                const rowId = String(row.id);
                if (!instrumentSelectedIds.includes(rowId)) {
                    instrumentSelectedIds.push(rowId);
                }
            } else if (row) {
                // 如果没有id，为该行生成一个临时id
                row.id = Date.now() + '_' + i;
                instrumentSelectedIds.push(row.id);
            }
        }
    } else {
        for (let i = startIndex; i < endIndex; i++) {
            const row = instrumentFilteredData[i];
            if (row && row.id !== undefined && row.id !== null) {
                const rowId = String(row.id);
                instrumentSelectedIds = instrumentSelectedIds.filter(id => String(id) !== rowId);
            }
        }
    }

    instrumentUpdateBatchDeleteButton();
    instrumentRenderTable();
}

function instrumentToggleRowSelect(id) {
    // id可能是数字或字符串（如 "1" 或 1）
    const rowId = String(id);
    
    const checkbox = document.querySelector(`.row-checkbox[data-id="${rowId}"]`);
    if (checkbox && checkbox.checked) {
        if (!instrumentSelectedIds.includes(rowId)) {
            instrumentSelectedIds.push(rowId);
        }
    } else {
        instrumentSelectedIds = instrumentSelectedIds.filter(selectedId => String(selectedId) !== rowId);
    }
    instrumentUpdateBatchDeleteButton();
    instrumentRenderTable();
}

function instrumentUpdateBatchDeleteButton() {
    const batchDeleteBtn = document.getElementById('instrumentDeleteBtn');
    const exportSelectedBtn = document.getElementById('instrumentExportSelectedBtn');
    const selectedCount = document.getElementById('instrumentSelectedCount');
    const selectAllCheckbox = document.querySelector('#instrumentDataTable thead .row-checkbox');
    
    if (selectedCount) selectedCount.textContent = instrumentSelectedIds.length;
    
    if (batchDeleteBtn) {
        batchDeleteBtn.style.display = instrumentSelectedIds.length > 0 ? 'inline-flex' : 'none';
    }
    
    if (exportSelectedBtn) {
        exportSelectedBtn.style.display = instrumentSelectedIds.length > 0 ? 'inline-flex' : 'none';
    }
    
    const checkboxes = document.querySelectorAll('#instrumentDataTable tbody .row-checkbox');
    const totalChecked = document.querySelectorAll('#instrumentDataTable tbody .row-checkbox:checked').length;
    if (selectAllCheckbox) {
        selectAllCheckbox.checked = totalChecked === checkboxes.length && checkboxes.length > 0;
    }
}

async function instrumentExportSelected() {
    if (instrumentSelectedIds.length === 0) {
        instrumentShowToast('请先选择要导出的数据', 'warning');
        return;
    }

    const selectedData = instrumentData.filter(item => {
        const itemId = String(item.id);
        return instrumentSelectedIds.some(id => String(id) === itemId);
    });
    if (selectedData.length === 0) {
        instrumentShowToast('没有找到选中的数据', 'warning');
        return;
    }

    const headers = ['序号', '仪器编号', '仪器名称', '故障日期', '故障现象', '维修内容', '维修日期', '维修人员', '更换配件', '备注'];
    const data = selectedData.map((item, index) => [
        index + 1,
        item.instrumentNo || '',
        item.instrumentName || '',
        item.faultDate || '',
        item.faultPhenomenon || '',
        item.repairContent || '',
        item.repairDate || '',
        item.repairPerson || '',
        item.spareParts || '',
        item.remark || ''
    ]);

    const fileName = `仪器维修台账-选中-${new Date().getTime()}.xlsx`;
    const success = await exportToExcelWithStyle(data, headers, '仪器维修台账', fileName);
    
    if (success) {
        instrumentShowToast(`成功导出 ${selectedData.length} 条数据`, 'success');
    } else {
        instrumentShowToast('导出失败', 'error');
    }
}

function instrumentUpdateSelectedRowsIndices() {
    const newSelected = new Set();
    instrumentSelectedRows.forEach(oldIndex => {
        let newIndex = oldIndex;
        instrumentSelectedRows.forEach(idx => {
            if (idx < oldIndex) newIndex--;
        });
        if (newIndex >= 0 && newIndex < instrumentFilteredData.length) {
            newSelected.add(newIndex);
        }
    });
    instrumentSelectedRows = newSelected;
}

function instrumentHandleSearch(event) {
    if (event.key === 'Enter') {
        instrumentFilter();
    }
}

function instrumentFilter() {
    const yearFilter = document.getElementById('instrumentYearFilter')?.value || 'all';
    const monthFilter = document.getElementById('instrumentMonthFilter')?.value || 'all';
    const dateFieldFilter = document.getElementById('instrumentDateFieldFilter')?.value || 'faultDate';
    instrumentSearchKeyword = document.getElementById('instrumentSearchInput')?.value.trim().toLowerCase() || '';
    instrumentCurrentPage = 1;
    const fields = ['instrumentNo', 'instrumentName', 'faultDate', 'faultPhenomenon', 'repairContent', 'repairDate', 'repairPerson', 'spareParts', 'remark'];

    instrumentFilteredData = instrumentData.filter(row => {
        const matchSearch = !instrumentSearchKeyword || fields.some(field =>
            String(row[field] || '').toLowerCase().includes(instrumentSearchKeyword)
        );

        const filterDate = dateFieldFilter === 'faultDate' ? row.faultDate : row.repairDate;

        let matchYear = true;
        if (yearFilter !== 'all') {
            if (filterDate) {
                matchYear = filterDate.substring(0, 4) === yearFilter;
            } else {
                matchYear = false;
            }
        }

        let matchMonth = true;
        if (monthFilter !== 'all') {
            if (filterDate) {
                matchMonth = filterDate.substring(5, 7) === monthFilter;
            } else {
                matchMonth = false;
            }
        }

        return matchSearch && matchYear && matchMonth;
    });

    instrumentSelectedIds = [];
    instrumentRenderTable();
}

function initInstrumentYearFilter() {
    const yearFilter = document.getElementById('instrumentYearFilter');
    if (!yearFilter) return;

    const years = new Set(['all']);

    // 同时遍历故障日期和维修日期，确保所有年份都被包含
    instrumentData.forEach(item => {
        if (item.faultDate) {
            years.add(item.faultDate.substring(0, 4));
        }
        if (item.repairDate) {
            years.add(item.repairDate.substring(0, 4));
        }
    });

    const currentYear = new Date().getFullYear();
    for (let year = currentYear; year >= 2020; year--) {
        if (years.has(year.toString()) || year === currentYear || year === currentYear - 1) {
            years.add(year.toString());
        }
    }

    const sortedYears = Array.from(years).sort((a, b) => {
        if (a === 'all') return -1;
        if (b === 'all') return 1;
        return parseInt(b) - parseInt(a);
    });

    yearFilter.innerHTML = sortedYears.map(year =>
        `<option value="${year}">${year === 'all' ? '全部年份' : `${year}年`}</option>`
    ).join('');
}

function openInstrumentUploadModal() {
    safeSetDisplay('instrumentUploadModal', 'block');
    instrumentResetUploadModal();
}

function closeInstrumentUploadModal() {
    safeSetDisplay('instrumentUploadModal', 'none');
}

function instrumentResetUploadModal() {
    const fileInput = document.getElementById('instrumentFileInput');
    if (fileInput) fileInput.value = '';
    safeSetDisplay('instrumentPreviewSection', 'none');
    instrumentPreviewData = null;
}

function instrumentHandleDragOver(event) {
    event.preventDefault();
    event.currentTarget.classList.add('dragover');
}

function instrumentHandleDragLeave(event) {
    event.currentTarget.classList.remove('dragover');
}

function instrumentHandleDrop(event) {
    event.preventDefault();
    event.currentTarget.classList.remove('dragover');

    const file = event.dataTransfer.files[0];
    if (file) {
        instrumentProcessFile(file);
    }
}

function instrumentHandleFileSelect(event) {
    const file = event.target.files[0];
    if (!file) return;
    
    if (isInstrumentImporting) {
        alert('正在导入中，请稍候...');
        return;
    }
    isInstrumentImporting = true;
    
    instrumentProcessFile(file);
}

function instrumentProcessFile(file) {
    const fileName = file.name.toLowerCase();
    const isExcel = fileName.endsWith('.xlsx') || fileName.endsWith('.xls');
    const isImage = fileName.endsWith('.jpg') || fileName.endsWith('.jpeg') || fileName.endsWith('.png') || fileName.endsWith('.gif');

    if (!isExcel && !isImage) {
        instrumentShowToast('请上传Excel文件（.xlsx, .xls）或图片文件（.jpg, .jpeg, .png, .gif）', 'error');
        return;
    }

    const selectedFileName = document.getElementById('instrumentSelectedFileName');
    if (selectedFileName) selectedFileName.textContent = file.name;

    if (isExcel) {
        instrumentProcessExcelFile(file);
    } else if (isImage) {
        instrumentProcessImageFile(file);
    }
}

function instrumentProcessExcelFile(file) {
    const reader = new FileReader();
    reader.onload = function(e) {
        try {
            const data = new Uint8Array(e.target.result);
            const workbook = XLSX.read(data, { type: 'array', cellDates: true, raw: false });

            if (!workbook || !workbook.SheetNames || workbook.SheetNames.length === 0) {
                instrumentShowToast('Excel文件中没有工作表', 'error');
                isInstrumentImporting = false;
                return;
            }

            const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
            const jsonData = XLSX.utils.sheet_to_json(firstSheet, { defval: '', raw: false });

            if (jsonData.length < 1) {
                instrumentShowToast('Excel文件中没有数据', 'error');
                isInstrumentImporting = false;
                return;
            }

            const headers = Object.keys(jsonData[0]);
            instrumentPreviewData = { headers, data: jsonData };

            instrumentShowPreview(headers, jsonData);
            safeSetDisplay('instrumentPreviewSection', 'block');
            const confirmBtn = document.getElementById('instrumentConfirmImportBtn');
            if (confirmBtn) confirmBtn.disabled = false;

        } catch (error) {
            console.error('解析Excel失败:', error);
            instrumentShowToast('解析Excel文件失败：' + error.message, 'error');
            isInstrumentImporting = false;
        }
    };
    reader.onerror = function() {
        instrumentShowToast('文件读取失败，请重试', 'error');
        isInstrumentImporting = false;
    };
    reader.readAsArrayBuffer(file);
}

function instrumentProcessImageFile(file) {
    const reader = new FileReader();
    reader.onload = function(e) {
        try {
            const imageDataUrl = e.target.result;
            const headers = INSTRUMENT_HEADERS;
            const data = [headers.reduce((acc, h) => ({ ...acc, [h]: '' }), {})];
            instrumentPreviewData = { headers, data, imageDataUrl };

            instrumentShowImageWithExistingHeaders(imageDataUrl, headers, data);
            safeSetDisplay('instrumentPreviewSection', 'block');
            const confirmBtn = document.getElementById('instrumentConfirmImportBtn');
            if (confirmBtn) confirmBtn.disabled = false;

        } catch (error) {
            console.error('处理图片失败:', error);
            instrumentShowToast('处理图片文件失败：' + error.message, 'error');
        }
    };
    reader.readAsDataURL(file);
}

function instrumentShowImageWithExistingHeaders(imageDataUrl, headers, data) {
    const previewContent = document.getElementById('instrumentPreviewContent');

    let html = '<div style="margin-bottom: 20px;">';
    html += '<h4 style="color: #4CAF50; margin-bottom: 10px;">📷 图片预览</h4>';
    html += `<img src="${imageDataUrl}" style="max-width: 100%; max-height: 300px; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.15);" alt="上传的图片">`;
    html += '</div>';

    html += '<div style="margin-top: 20px;">';
    html += '<h4 style="color: #2196F3; margin-bottom: 10px;">📝 已使用现有表头</h4>';
    html += '<p style="font-size: 13px; color: #888; margin-bottom: 15px;">系统已自动使用之前上传的表头配置</p>';

    html += '<table style="width: 100%; border-collapse: collapse; font-size: 13px;">';
    html += '<thead><tr>';
    headers.forEach(h => {
        html += `<th style="padding: 10px; border: 1px solid #ddd; background: #f5f5f5;">${instrumentEscapeHtml(h)}</th>`;
    });
    html += '</tr></thead><tbody>';

    data.forEach(row => {
        html += '<tr>';
        headers.forEach(h => {
            html += `<td style="padding: 10px; border: 1px solid #ddd;">${instrumentEscapeHtml(row[h] || '')}</td>`;
        });
        html += '</tr>';
    });
    html += '</tbody></table>';
    html += '</div>';

    previewContent.innerHTML = html;
}

