    html += '<button type="button" onclick="instrumentAddHeaderFromInput()" style="padding: 10px 20px; background-color: #4CAF50; color: white; border: none; border-radius: 6px; cursor: pointer; font-size: 14px;">添加</button>';
    html += '</div>';
