function instrumentParseQuickHeaders() {
    const input = document.getElementById('instrumentHeadersQuickInput');
    const confirmBtn = document.getElementById('instrumentConfirmImportBtn');
    const tablePreviewArea = document.getElementById('instrumentTablePreviewArea');

    const headers = input.value.split(',').map(h => h.trim()).filter(h => h);
    if (headers.length === 0) {
        instrumentShowToast('请输入表头', 'warning');
        return;
    }

    instrumentPreviewData.headers = headers;
    instrumentPreviewData.data = [headers.reduce((acc, h) => ({ ...acc, [h]: '' }), {})];

    if (confirmBtn) confirmBtn.disabled = false;
    instrumentRenderHeaderList();
    instrumentRenderTablePreview();
    if (tablePreviewArea) tablePreviewArea.style.display = 'block';

    instrumentShowToast(`已添加 ${headers.length} 个表头`, 'success');
}

function instrumentAddHeaderFromInput() {
    const input = document.getElementById('instrumentNewHeaderInput');
    const headerList = document.getElementById('instrumentHeaderList');
    const confirmBtn = document.getElementById('instrumentConfirmImportBtn');
    const tablePreviewArea = document.getElementById('instrumentTablePreviewArea');

    const header = input.value.trim();
    if (!header) {
        instrumentShowToast('请输入表头名称', 'warning');
        return;
    }

    if (!instrumentPreviewData.headers) instrumentPreviewData.headers = [];
    instrumentPreviewData.headers.push(header);
    instrumentPreviewData.data = [instrumentPreviewData.headers.reduce((acc, h) => ({ ...acc, [h]: '' }), {})];

    input.value = '';
    instrumentRenderHeaderList();

    if (instrumentPreviewData.headers.length > 0) {
        if (confirmBtn) confirmBtn.disabled = false;
        instrumentRenderTablePreview();
        if (tablePreviewArea) tablePreviewArea.style.display = 'block';
    }
}

function instrumentRenderHeaderList() {
    const headerList = document.getElementById('instrumentHeaderList');
    if (!headerList) return;

    let html = '<div style="display: flex; flex-wrap: wrap; gap: 8px;">';
    instrumentPreviewData.headers.forEach((h, i) => {
        html += `<div style="display: inline-flex; align-items: center; gap: 8px; padding: 8px 12px; background: #f0f9ff; border: 1px solid #86d1f9; border-radius: 6px;">`;
        html += `<span style="color: #1e88e5; font-weight: 500;">${instrumentEscapeHtml(h)}</span>`;
        html += `<button onclick="instrumentRemoveHeader(${i})" style="width: 20px; height: 20px; border: none; background: #e3f2fd; color: #1976d2; border-radius: 50%; cursor: pointer; font-size: 12px; display: flex; align-items: center; justify-content: center;">×</button>`;
        html += `</div>`;
    });
    html += '</div>';
    headerList.innerHTML = html;
}

function instrumentRemoveHeader(index) {
    const confirmBtn = document.getElementById('instrumentConfirmImportBtn');
    const tablePreviewArea = document.getElementById('instrumentTablePreviewArea');

    instrumentPreviewData.headers.splice(index, 1);
    instrumentPreviewData.data = [instrumentPreviewData.headers.reduce((acc, h) => ({ ...acc, [h]: '' }), {})];

    instrumentRenderHeaderList();

    if (instrumentPreviewData.headers.length === 0) {
        if (confirmBtn) confirmBtn.disabled = true;
        if (tablePreviewArea) tablePreviewArea.style.display = 'none';
    } else {
        instrumentRenderTablePreview();
    }
}

function instrumentRenderTablePreview() {
    const tablePreviewArea = document.getElementById('instrumentTablePreviewArea');
    if (!tablePreviewArea) return;

    let html = '<h4 style="color: #4CAF50; margin-bottom: 10px;">📋 表格预览</h4>';
    html += '<table style="width: 100%; border-collapse: collapse; font-size: 13px;">';
    html += '<thead><tr>';
    instrumentPreviewData.headers.forEach(h => {
        html += `<th style="padding: 10px; border: 1px solid #ddd; background: #f5f5f5;">${instrumentEscapeHtml(h)}</th>`;
    });
    html += '</tr></thead><tbody>';

    instrumentPreviewData.data.forEach(row => {
        html += '<tr>';
        instrumentPreviewData.headers.forEach(h => {
            html += `<td style="padding: 10px; border: 1px solid #ddd;">${instrumentEscapeHtml(row[h] || '')}</td>`;
        });
        html += '</tr>';
    });
    html += '</tbody></table>';

    tablePreviewArea.innerHTML = html;
}

function instrumentShowPreview(headers, data) {
    const previewContent = document.getElementById('instrumentPreviewContent');
    const previewData = data.slice(0, 5);

    let html = '<table style="width: 100%; border-collapse: collapse; font-size: 13px;">';
    html += '<thead><tr>';
    headers.forEach(h => {
        html += `<th style="padding: 10px; border: 1px solid #ddd; background: #f5f5f5;">${instrumentEscapeHtml(h)}</th>`;
    });
    html += '</tr></thead><tbody>';

    previewData.forEach(row => {
        html += '<tr>';
        headers.forEach(h => {
            html += `<td style="padding: 10px; border: 1px solid #ddd;">${instrumentEscapeHtml(row[h] || '')}</td>`;
        });
        html += '</tr>';
    });
    html += '</tbody></table>';
    html += `<p style="margin-top: 10px; font-size: 13px; color: #888;">显示前5行，共 ${data.length} 行数据</p>`;

    previewContent.innerHTML = html;
}

async function instrumentConfirmImport() {
    if (!instrumentPreviewData) {
        instrumentShowToast('请先选择文件', 'warning');
        return;
    }

    const newData = instrumentPreviewData.data.map(row => {
        const newRow = {
            id: Date.now() + Math.random(),
            instrumentNo: '',
            instrumentName: '',
            faultDate: '',
            faultPhenomenon: '',
            repairDate: new Date().toISOString().split('T')[0],
            repairContent: '',
            repairPerson: '',
            spareParts: '',
            remark: ''
        };
        
        // 根据预览数据的表头进行智能字段匹配
        instrumentPreviewData.headers.forEach((header, index) => {
            const headerLower = header.trim().toLowerCase();
            const cellValue = row[header] || row[index] || '';
            
            if (headerLower.includes('编号') || headerLower.includes('仪器编号')) {
                newRow.instrumentNo = cellValue;
            } else if (headerLower.includes('名称') || headerLower.includes('仪器名称')) {
                newRow.instrumentName = cellValue;
            } else if (headerLower.includes('故障日期') || headerLower.includes('故障时间')) {
                newRow.faultDate = cellValue;
            } else if (headerLower.includes('故障现象') || headerLower.includes('故障描述') || headerLower.includes('故障')) {
                newRow.faultPhenomenon = cellValue;
            } else if (headerLower.includes('维修日期') || headerLower.includes('修理日期')) {
                newRow.repairDate = cellValue;
            } else if (headerLower.includes('维修内容') || headerLower.includes('修理内容')) {
                newRow.repairContent = cellValue;
            } else if (headerLower.includes('维修人员') || headerLower.includes('修理人员') || headerLower.includes('维修人') || headerLower.includes('修理人')) {
                newRow.repairPerson = cellValue;
            } else if (headerLower.includes('更换配件') || headerLower.includes('配件')) {
                newRow.spareParts = cellValue;
            } else if (headerLower.includes('备注') || headerLower.includes('说明')) {
                newRow.remark = cellValue;
            }
        });
        
        return newRow;
    });

    instrumentData = [...instrumentData, ...newData];
    instrumentFilteredData = [...instrumentData];
    instrumentSearchKeyword = '';
    const searchInput = document.getElementById('instrumentSearchInput');
    if (searchInput) searchInput.value = '';
    instrumentCurrentPage = 1;
    instrumentSelectedIds = [];

    saveInstrumentData();
    instrumentRenderTable();
    closeInstrumentUploadModal();

    instrumentShowToast(`成功追加 ${newData.length} 行数据，总计 ${instrumentData.length} 行，请点击"保存到云端"按钮上传到数据库`, 'success');
    isInstrumentImporting = false;
}

function instrumentClearFile() {
    instrumentResetUploadModal();
}

async function instrumentExportToExcel() {
    if (instrumentFilteredData.length === 0) {
        instrumentShowToast('没有数据可导出', 'warning');
        return;
    }

    const headers = INSTRUMENT_HEADERS;
    const fields = ['instrumentNo', 'instrumentName', 'faultDate', 'faultPhenomenon', 'repairContent', 'repairDate', 'repairPerson', 'spareParts', 'remark'];
    const data = instrumentFilteredData.map(row => {
        return fields.map(field => row[field] || '');
    });

    const yearFilter = document.getElementById('instrumentYearFilter')?.value || 'all';
    const monthFilter = document.getElementById('instrumentMonthFilter')?.value || 'all';
    const dateFieldFilter = document.getElementById('instrumentDateFieldFilter')?.value || 'faultDate';

    let datePart = '';
    if (yearFilter !== 'all') {
        datePart += `${yearFilter}年`;
        if (monthFilter !== 'all') {
            datePart += `${monthFilter}月`;
        }
    }

    const dateFieldText = dateFieldFilter === 'faultDate' ? '故障日期' : '维修日期';
    
    const currentDate = new Date().toISOString().split('T')[0];
    let filename = `仪器维修台账`;
    if (datePart) {
        filename += `_${dateFieldText}_${datePart}`;
    }
    filename += `_${currentDate}.xlsx`;

    const sheetName = datePart ? `仪器维修台账${datePart}` : '仪器维修台账';

    await exportToExcelWithStyle(data, headers, sheetName, filename);

    instrumentShowToast('导出成功：' + filename, 'success');
}

function instrumentUpdateStats() {
    const totalRows = document.getElementById('instrumentTotalRows');
    if (totalRows) totalRows.textContent = instrumentFilteredData.length;
    const selectedCount = document.getElementById('instrumentSelectedCount');
    if (selectedCount) selectedCount.textContent = instrumentSelectedIds.length;

    const deleteBtn = document.getElementById('instrumentDeleteBtn');
    if (deleteBtn) deleteBtn.disabled = instrumentSelectedIds.length === 0;
}

function instrumentShowToast(message, type = 'success') {
    const toast = document.getElementById('instrumentToast');
    toast.textContent = message;
    toast.className = `toast ${type} show`;

    setTimeout(() => {
        toast.classList.remove('show');
    }, 3000);
}

function instrumentEscapeHtml(str) {
    if (str === null || str === undefined) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

// ==================== 仪器维修台账列宽调整功能 ====================
let isInstrumentResizing = false;
let instrumentResizeColIndex = -1;
let instrumentStartX = 0;
let instrumentStartWidth = 0;

function startInstrumentColumnResize(e, colIndex) {
    isInstrumentResizing = true;
    instrumentResizeColIndex = colIndex;
    instrumentStartX = e.clientX;
    
    const th = document.querySelector(`#instrumentDataTable th[data-col="${colIndex}"]`);
    if (th) {
        instrumentStartWidth = th.offsetWidth;
    }
    
    document.addEventListener('mousemove', doInstrumentColumnResize);
    document.addEventListener('mouseup', stopInstrumentColumnResize);
    e.preventDefault();
}

function doInstrumentColumnResize(e) {
    if (!isInstrumentResizing) return;
    
    const th = document.querySelector(`#instrumentDataTable th[data-col="${instrumentResizeColIndex}"]`);
    if (th) {
        const diff = e.clientX - instrumentStartX;
        const newWidth = Math.max(60, instrumentStartWidth + diff);
        th.style.minWidth = newWidth + 'px';
        th.style.maxWidth = (newWidth * 2) + 'px';
    }
}

function stopInstrumentColumnResize() {
    isInstrumentResizing = false;
    instrumentResizeColIndex = -1;
    instrumentStartX = 0;
    instrumentStartWidth = 0;
    document.removeEventListener('mousemove', doInstrumentColumnResize);
    document.removeEventListener('mouseup', stopInstrumentColumnResize);
}

