    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.style.cssText = `
        display: block;
    `;

    const modalContent = document.createElement('div');
    modalContent.className = 'modal-content';

    const headers = PATROL_HEADERS;
    const fields = ['recordDate', 'name', 'department', 'category', 'facts', 'occurDate', 'basis', 'punishmentLevel', 'economicPenalty', 'safetyScore', 'rectificationStatus', 'remark'];
