    const editBtn = document.getElementById('teamEditBtn');
    const addBtn = document.getElementById('teamAddRowBtn');
    const toolbarActions = document.getElementById('teamToolbarActions');
    
    editBtn.innerHTML = '<span class="btn-icon">✏️</span> 编辑表格';
    editBtn.className = 'btn btn-primary';
    if (addBtn) addBtn.style.display = 'none';
    if (toolbarActions) toolbarActions.style.display = 'none';
    
    teamCompShowToast('已取消修改', 'info');
