function honorEditHonor(filteredIndex) {
    // 从 filteredData 中获取数据
    const filteredData = window.honorFilteredData || honorFilteredData;
    const honorData = filteredData[filteredIndex];
    
    if (!honorData) {
        console.error('找不到对应的荣誉记录');
        alert('找不到对应的荣誉记录');
        return;
    }
    
    // 获取全局变量
    const globalTableData = window.honorTableData || honorTableData;
    
    // 在 honorTableData.data 中查找对应的记录
    let originalIndex = -1;
    
    if (honorData.id) {
        originalIndex = globalTableData.data.findIndex(h => h.id === honorData.id);
    }
    
    if (originalIndex === -1) {
        originalIndex = globalTableData.data.findIndex(h => {
            const nameMatch = (!h.honorName && !honorData.honorName) || 
                             (h.honorName && h.honorName.trim() === honorData.honorName.trim());
            const recipientMatch = (!h.honorRecipient && !honorData.honorRecipient) || 
                                  (h.honorRecipient && h.honorRecipient.trim() === honorData.honorRecipient.trim());
            const levelMatch = (!h.honorLevel && !honorData.honorLevel) || 
                               (h.honorLevel && h.honorLevel === honorData.honorLevel);
            return nameMatch && recipientMatch && levelMatch;
        });
    }
    
    if (originalIndex !== -1) {
        // 设置全局编辑ID
        window.honorEditingId = originalIndex;
        honorEditingId = originalIndex;
        openAddHonorModal(originalIndex);
    } else {
        console.error('找不到对应的荣誉记录');
        alert('找不到对应的荣誉记录');
    }
}

