async function honorDeleteHonor(filteredIndex) {
    if (!confirm('确定要删除这条荣誉记录吗？')) {
        return;
    }
    
    try {
        // 从 filteredData 中获取数据
        const filteredData = window.honorFilteredData || honorFilteredData;
        const honorData = filteredData[filteredIndex];
        
        if (!honorData) {
            console.error('找不到对应的荣誉记录');
            alert('找不到对应的荣誉记录');
            return;
        }
        
        // 获取全局变量
        const globalTableData = window.honorTableData || honorTableData;
        
        // 在 honorTableData.data 中查找对应的记录
        let originalIndex = -1;
        
        if (honorData.id) {
            originalIndex = globalTableData.data.findIndex(h => h.id === honorData.id);
        }
        
        if (originalIndex === -1) {
            originalIndex = globalTableData.data.findIndex(h => {
                const nameMatch = (!h.honorName && !honorData.honorName) || 
                                 (h.honorName && h.honorName.trim() === honorData.honorName.trim());
                const recipientMatch = (!h.honorRecipient && !honorData.honorRecipient) || 
                                      (h.honorRecipient && h.honorRecipient.trim() === honorData.honorRecipient.trim());
                const levelMatch = (!h.honorLevel && !honorData.honorLevel) || 
                                   (h.honorLevel && h.honorLevel === honorData.honorLevel);
                return nameMatch && recipientMatch && levelMatch;
            });
        }
        
        if (originalIndex !== -1) {
            globalTableData.data.splice(originalIndex, 1);
            
            // 同时更新局部变量和全局变量
            honorTableData = globalTableData;
            window.honorTableData = globalTableData;
            
            honorFilteredData = [...globalTableData.data];
            window.honorFilteredData = honorFilteredData;
            
            // 保存到localStorage
            honorTableData.lastModified = new Date().toISOString();
            localStorage.setItem(HONOR_STORAGE_KEY, JSON.stringify(honorTableData));
            
            // 增量同步到云端
            if (typeof syncModuleChangesToCloud === 'function') {
                syncModuleChangesToCloud('honor', {
                    added: [],
                    updated: [],
                    deleted: [honorData.id]
                }).catch(err => {
                    console.error('获得荣誉数据同步到云端失败:', err);
                });
            }

            // 记录变更历史
            if (typeof window.reliableSync !== 'undefined') {
                window.reliableSync.recordDataChange(
                    'honor',
                    'delete',
                    honorData.id,
                    honorData,
                    null
                );
            }

            // 记录审计日志
            if (typeof recordAuditLog === 'function') {
                recordAuditLog({
                    module: 'honor',
                    action: 'delete',
                    targetId: honorData.id,
                    targetDesc: `删除荣誉: ${honorData.honorName || '未知荣誉'}`,
                    changes: null
                });
            }
            
            honorRenderTable();
            honorUpdateStats();
            honorShowToast('删除成功！', 'success');
        } else {
            console.error('找不到对应的荣誉记录');
            alert('找不到对应的荣誉记录');
        }
    } catch (error) {
        console.error('删除荣誉记录失败:', error);
        honorShowToast('删除失败: ' + error.message, 'error');
    }
}

