function searchHonor() {
    const searchInput = document.getElementById('honorSearchInput');
    if (!searchInput) return;
    
    honorSearchKeyword = searchInput.value.trim().toLowerCase();
    
    if (!honorSearchKeyword) {
        honorFilteredData = [...honorTableData.data];
    } else {
        honorFilteredData = honorTableData.data.filter(honor => {
            return (honor.honorName && honor.honorName.toLowerCase().includes(honorSearchKeyword)) ||
                   (honor.honorRecipient && honor.honorRecipient.toLowerCase().includes(honorSearchKeyword)) ||
                   (honor.honorLevel && honor.honorLevel.toLowerCase().includes(honorSearchKeyword)) ||
                   (honor.honorIssuer && honor.honorIssuer.toLowerCase().includes(honorSearchKeyword)) ||
                   (honor.honorRemark && honor.honorRemark.toLowerCase().includes(honorSearchKeyword));
        });
    }
    
    honorCurrentPage = 1;
    honorRenderTable();
    honorUpdateStats();
}

async function exportHonorData() {
    console.log('exportHonorData called');
    
    let currentTableData = window.honorTableData || honorTableData;
    
    console.log('honorTableData:', currentTableData);
    
    if (!currentTableData || !currentTableData.data || !Array.isArray(currentTableData.data)) {
        console.error('honorTableData or honorTableData.data is undefined or not an array');
        // 尝试重新加载数据
        try {
            honorLoadFromStorage();
            // 重新加载后更新变量
            currentTableData = window.honorTableData || honorTableData;
            if (!currentTableData || !currentTableData.data || !Array.isArray(currentTableData.data)) {
                honorShowToast('数据未初始化', 'error');
                return;
            }
        } catch (e) {
            console.error('重新加载数据失败:', e);
            honorShowToast('数据未初始化', 'error');
            return;
        }
    }
    
    if (!currentTableData.data || currentTableData.data.length === 0) {
        console.log('No data to export');
        honorShowToast('没有数据可导出', 'warning');
        return;
    }
    
    try {
        const headers = ['序号', '荣誉名称', '获奖人/单位', '荣誉级别', '颁发单位', '获奖日期', '备注'];
        
        const data = currentTableData.data.map((honor, index) => [
            index + 1,
            honor.honorName || '',
            honor.honorRecipient || '',
            honor.honorLevel || '',
            honor.honorIssuer || '',
            honor.honorDate || '',
            honor.honorRemark || ''
        ]);
        
        console.log('exportData:', data);
        
        const filename = `获得荣誉台账_${new Date().toISOString().split('T')[0]}.xlsx`;
        console.log('Exporting to:', filename);
        await exportToExcelWithStyle(data, headers, '获得荣誉', filename);
        
        honorShowToast('导出成功', 'success');
    } catch (error) {
        console.error('导出失败:', error);
        honorShowToast('导出失败: ' + error.message, 'error');
    }
}

