async function downloadHonorTemplate(e) {
    if (e) e.preventDefault();
    
    const headers = ['荣誉名称', '获奖人/单位', '荣誉级别', '颁发单位', '获奖日期', '备注'];
    
    const templateData = [
        {
            '荣誉名称': '优秀员工',
            '获奖人/单位': '张三',
            '荣誉级别': '公司级',
            '颁发单位': '甲醇作业区',
            '获奖日期': '2025-01-01',
            '备注': '示例数据'
        },
        {
            '荣誉名称': '安全生产标兵',
            '获奖人/单位': '李四',
            '荣誉级别': '作业区级',
            '颁发单位': '甲醇作业区',
            '获奖日期': '2025-02-15',
            '备注': ''
        }
    ];
    
    const ws = XLSX.utils.aoa_to_sheet([headers]);
    XLSX.utils.sheet_add_json(ws, templateData, {skipHeader: true, origin: 'A2'});
    
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, '获得荣誉模板');
    
    const wss = wb.Sheets['获得荣誉模板'];
    wss['!cols'] = [
        {wch: 15},
        {wch: 15},
        {wch: 12},
        {wch: 15},
        {wch: 12},
        {wch: 20}
    ];
    
    const range = XLSX.utils.decode_range(wss['!ref']);
    for (let col = range.s.c; col <= range.e.c; col++) {
        for (let row = range.s.r; row <= range.e.r; row++) {
            const cell_address = {c: col, r: row};
            const cell_ref = XLSX.utils.encode_cell(cell_address);
            if (!wss[cell_ref]) {
                wss[cell_ref] = {v: ''};
            }
            if (!wss[cell_ref].s) {
                wss[cell_ref].s = {};
            }
            wss[cell_ref].s.alignment = {horizontal: 'center', vertical: 'center'};
            wss[cell_ref].s.border = {
                top: {style: 'thin'},
                bottom: {style: 'thin'},
                left: {style: 'thin'},
                right: {style: 'thin'}
            };
            if (row === 0) {
                wss[cell_ref].s.font = {bold: true};
                wss[cell_ref].s.fill = {fgColor: {rgb: 'CCCCCC'}};
            }
        }
    }
    
    const now = new Date();
    const dateStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
    await exportWorkbook(wb, `获得荣誉模板_${dateStr}.xlsx`);
}

function handleHonorFileSelect(event) {
    const file = event.target.files[0];
    if (!file) return;
    
    if (isHonorImporting) {
        alert('正在导入中，请稍候...');
        return;
    }
    isHonorImporting = true;
    
    const fileNameDisplay = document.getElementById('honorFileNameDisplay');
    if (fileNameDisplay) {
        fileNameDisplay.textContent = `已选择文件: ${file.name}`;
    }
    
    const reader = new FileReader();
    reader.onload = function(e) {
        try {
            const data = new Uint8Array(e.target.result);
            const workbook = XLSX.read(data, {type: 'array'});
            const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
            const jsonData = XLSX.utils.sheet_to_json(firstSheet);
            
            if (jsonData.length === 0) {
                honorShowToast('文件为空或格式不正确', 'error');
                isHonorImporting = false;
                return;
            }
            
            honorPreviewData = jsonData;
            
            const previewSection = document.getElementById('honorPreviewSection');
            const previewContent = document.getElementById('honorPreviewContent');
            const confirmBtn = document.getElementById('honorConfirmImportBtn');
            
            if (previewSection) previewSection.style.display = 'block';
            
            if (previewContent) {
                let tableHtml = '<table class="preview-table"><thead><tr>';
                const firstRow = jsonData[0];
                const headers = Object.keys(firstRow);
                headers.forEach(header => {
                    tableHtml += `<th>${header}</th>`;
                });
                tableHtml += '</tr></thead><tbody>';
                
                jsonData.slice(0, 5).forEach(row => {
                    tableHtml += '<tr>';
                    headers.forEach(header => {
                        tableHtml += `<td>${row[header] || ''}</td>`;
                    });
                    tableHtml += '</tr>';
                });
                tableHtml += '</tbody></table>';
                
                if (jsonData.length > 5) {
                    tableHtml += `<p style="text-align: center; color: #666; margin-top: 10px;">... 共 ${jsonData.length} 条数据</p>`;
                }
                
                previewContent.innerHTML = tableHtml;
            }
            
            if (confirmBtn) confirmBtn.disabled = false;
        } catch (error) {
            console.error('读取文件失败:', error);
            honorShowToast('读取文件失败', 'error');
            isHonorImporting = false;
        }
    };
    reader.onerror = function() {
        honorShowToast('文件读取失败，请重试', 'error');
        isHonorImporting = false;
    };
    reader.readAsArrayBuffer(file);
}

function honorClearFile() {
    const previewSection = document.getElementById('honorPreviewSection');
    const previewContent = document.getElementById('honorPreviewContent');
    const confirmBtn = document.getElementById('honorConfirmImportBtn');
    const fileNameDisplay = document.getElementById('honorFileNameDisplay');
    const fileInput = document.getElementById('honorImportFileInput');
    
    if (previewSection) previewSection.style.display = 'none';
    if (previewContent) previewContent.innerHTML = '';
    if (confirmBtn) confirmBtn.disabled = true;
    if (fileNameDisplay) fileNameDisplay.textContent = '';
    if (fileInput) fileInput.value = '';
    
    honorPreviewData = null;
}

function honorConfirmImport() {
    if (!honorPreviewData || honorPreviewData.length === 0) {
        honorShowToast('没有可导入的数据', 'error');
        return;
    }
    
    const importedData = honorPreviewData.map((row, index) => {
        return {
            id: Date.now() + index,
            honorName: row['荣誉名称'] || row['honorName'] || '',
            honorRecipient: row['获奖人/单位'] || row['honorRecipient'] || '',
            honorLevel: row['荣誉级别'] || row['honorLevel'] || '',
            honorIssuer: row['颁发单位'] || row['honorIssuer'] || '',
            honorDate: row['获奖日期'] || row['honorDate'] || '',
            honorRemark: row['备注'] || row['remark'] || ''
        };
    });
    
    honorTableData.data = [...honorTableData.data, ...importedData];
    honorFilteredData = [...honorTableData.data];
    honorSaveToStorage();
    honorRenderTable();
    honorUpdateStats();
    closeHonorImportModal();
    
    // 异步增量同步到云端
    if (typeof syncModuleChangesToCloud === 'function') {
        const addedRecords = importedData.map(item => ({
            rowId: item.id,
            data: item
        }));
        syncModuleChangesToCloud('honor', {
            added: addedRecords,
            updated: [],
            deleted: []
        }).catch(err => {
            console.error('获得荣誉批量导入数据增量同步失败:', err);
        });
    }
    
    honorShowToast(`成功导入 ${importedData.length} 条数据`, 'success');
    isHonorImporting = false;
}

function honorShowToast(message, type = 'info') {
    const toast = document.getElementById('honorToast');
    if (!toast) return;
    
    toast.textContent = message;
    toast.className = `toast toast-${type}`;
    toast.style.display = 'block';
    
    setTimeout(() => {
        toast.style.display = 'none';
    }, 3000);
}

// 将关键函数导出到 window 对象，使其可以在其他脚本和内联脚本中访问
window.addModuleRefreshButton = addModuleRefreshButton;
window.addBottomStatsBar = addBottomStatsBar;
window.syncModuleFromCloud = syncModuleFromCloud;

// ==================== 采样点异常排查模块 ====================

const SAMPLING_ANOMALY_STORAGE_KEY = 'samplingAnomalyData';

let samplingAnomalyData = [];
let filteredSamplingAnomalyData = [];
let editingSamplingAnomalyId = null;

// 完成状态文本映射（完整故障处理流程）
const SAMPLING_ANOMALY_STATUS_MAP = {
    // 基础状态
    'draft': '草稿',
    'pending': '未开始',
    'progress': '进行中',
    'completed': '已完成',
    'closed': '已闭环',
    
    // 普通用户流程状态
    'waitingLeaderConfirm': '待班长确认',      // 用户提交完成情况后
    'needRectify': '需重新整改',              // 班长打回
    'leaderRectifying': '班长整改中',          // 班长升级后
    
    // 管理人员流程状态
    'waitingRectify': '待整改',               // 管理人员创建后
    'waitingTopAdminClose': '待主任闭环',     // 等待主任闭环
    
    // 升级流程状态
    'escalatedToLeader': '已升级至班长',      // 用户升级
    'escalatedToAdmin': '已升级至管理人员',   // 班长升级
    'escalatedToTopAdmin': '已升级至主任',    // 管理人员升级
    
    // 班长确认状态
    'leaderConfirmedExists': '班长已确认故障存在',  // 班长确认故障存在
    'notExistsByLeader': '故障不存在(班长确认)', // 班长确认故障不存在
    
    // 管理人员确认状态
    'confirmedByAdmin': '管理人员已确认故障',      // 管理人员确认故障存在
    'notExists': '故障不存在',                // 管理人员确认故障不存在
    
    // 历史状态（兼容旧数据）
    'waitingAdminConfirm': '待管理人员确认',
    'leaderConfirmed': '班长已确认',
    'waitingTopAdminConfirm': '等待主任闭环',
    'waitingTopAdminHandle': '等待主任处理',
    'adminRectifying': '管理人员整改中'
};

// 完成状态样式类映射
const SAMPLING_ANOMALY_STATUS_CLASS_MAP = {
    'draft': 'status-pending',
    'pending': 'status-pending',
    'progress': 'status-progress',
    'completed': 'status-completed',
    'closed': 'status-closed',
    'waitingLeaderConfirm': 'status-pending',
    'needRectify': 'status-progress',
    'leaderRectifying': 'status-progress',
    'waitingRectify': 'status-pending',
    'waitingTopAdminClose': 'status-pending',
    'escalatedToLeader': 'status-progress',
    'escalatedToAdmin': 'status-progress',
    'escalatedToTopAdmin': 'status-progress',
    'leaderConfirmedExists': 'status-progress',
    'notExistsByLeader': 'status-disabled',
    'confirmedByAdmin': 'status-progress',
    'notExists': 'status-disabled',
    'waitingAdminConfirm': 'status-pending',
    'leaderConfirmed': 'status-progress',
    'waitingTopAdminConfirm': 'status-pending',
    'waitingTopAdminHandle': 'status-pending',
    'adminRectifying': 'status-progress'
};

// 获取状态文本（统一格式）
function getSamplingAnomalyStatusText(status) {
    return SAMPLING_ANOMALY_STATUS_MAP[status] || status || '未知状态';
}

// 获取状态样式类（统一格式）
function getSamplingAnomalyStatusClass(status) {
    return SAMPLING_ANOMALY_STATUS_CLASS_MAP[status] || 'status-pending';
}

// 状态变更处理函数（完整故障处理流程）
function onSamplingAnomalyStatusChange() {
    const statusSelect = safeGetElement('samplingAnomalyCompletionStatus');
    const completionNoteGroup = safeGetElement('samplingAnomalyCompletionNoteGroup');
    const rejectReasonGroup = safeGetElement('samplingAnomalyRejectReasonGroup');
    const reformNoteGroup = safeGetElement('samplingAnomalyReformNoteGroup');
    const currentRole = getCurrentRole();
    
    if (!statusSelect || !completionNoteGroup) return;
    
    const status = statusSelect.value;
    
    // 显示/隐藏完成情况说明（待班长确认、待主任闭环、已完成、已闭环时显示）
    const showCompletionNote = ['waitingLeaderConfirm', 'waitingTopAdminClose', 'completed', 'closed'].includes(status);
    completionNoteGroup.style.display = showCompletionNote ? 'block' : 'none';
    
    // 显示/隐藏整改情况说明（有打回记录且状态为待班长确认/待主任闭环/已完成/已闭环时显示）
    if (reformNoteGroup) {
        if (editingSamplingAnomalyId) {
            const anomaly = samplingAnomalyData.find(a => a.id === editingSamplingAnomalyId);
            const hasRejectRecords = anomaly && anomaly.reject_records && anomaly.reject_records.length > 0;
            const showReformNote = showCompletionNote && hasRejectRecords;
            reformNoteGroup.style.display = showReformNote ? 'block' : 'none';
        } else {
            reformNoteGroup.style.display = 'none';
        }
    }
    
    // 显示/隐藏打回原因（主任打回时显示）
    if (rejectReasonGroup && editingSamplingAnomalyId) {
        const anomaly = samplingAnomalyData.find(a => a.id === editingSamplingAnomalyId);
        // 只有主任可以打回，且当前状态是待闭环或已完成状态时
        const isTopAdmin = currentRole === 'topadmin';
        const isRejectStatus = ['needRectify', 'leaderRectifying', 'adminRectifying'].includes(status);
        const wasInFinalStatus = anomaly && ['waitingTopAdminClose', 'completed', 'closed'].includes(anomaly.completion_status);
        
        rejectReasonGroup.style.display = (isTopAdmin && isRejectStatus && wasInFinalStatus) ? 'block' : 'none';
    }
}

// 判断故障是否可以删除（已闭环的故障禁止删除）
function canDeleteSamplingAnomaly(anomaly) {
    if (!anomaly) return false;
    // 已闭环的故障禁止删除
    if (anomaly.completion_status === 'closed') {
        return false;
    }
    // 检查删除保护标志
    if (anomaly.protected === true) {
        return false;
    }
    return true;
}

// 升级故障处理
function escalateSamplingAnomaly(anomalyId, targetRole, customData = null) {
    const anomaly = samplingAnomalyData.find(a => a.id === anomalyId);
    if (!anomaly) return false;
    
    const currentRole = getCurrentRole();
    const currentUser = getCurrentUsername();
    const currentStatus = anomaly.completion_status || anomaly.completionStatus || '';
    
    // 验证升级权限和路径
    const validEscalations = {
        'user': ['escalatedToLeader', 'waitingLeaderConfirm'],           // 用户可以升级到班长或提交审核（草稿状态）
        'leader': ['escalatedToAdmin'],          // 班长只能升级到管理人员
        'manager': ['escalatedToTopAdmin'],      // 管理人员只能升级到主任
        'topadmin': []                           // 主任不能再升级
    };
    
    const allowedEscalations = validEscalations[currentRole] || [];
    if (!allowedEscalations.includes(targetRole)) {
        console.error(`当前角色 ${currentRole} 不允许升级到 ${targetRole}`);
        return false;
    }
    
    // 记录之前的状态用于状态变更记录
    const previousStatus = currentStatus;
    
    // 更新状态
    anomaly.completion_status = targetRole;
    anomaly.completionStatus = targetRole;  // 同步设置驼峰命名
    anomaly.update_time = new Date().toLocaleString('zh-CN');
    anomaly.updated_at = new Date().toISOString();  // 同步设置ISO格式
    
    // 记录升级历史（参考版本9.0：优先使用驼峰命名）
    if (!anomaly.escalateRecords || !Array.isArray(anomaly.escalateRecords)) {
        if (anomaly.escalate_records && Array.isArray(anomaly.escalate_records)) {
            anomaly.escalateRecords = [...anomaly.escalate_records];
        } else {
            anomaly.escalateRecords = [];
        }
    }
    
    // 如果提供了自定义数据，使用自定义数据；否则使用默认数据
    if (customData) {
        const escalateRec = {
            time: new Date().toISOString(),
            fromRole: currentRole,
            from_role: currentRole,
            operator: currentUser,
            operatorRole: currentRole,
            operator_role: currentRole,
            targetRole: targetRole,
            target_role: targetRole,
            currentProgress: customData.progress,
            current_progress: customData.progress,
            reason: customData.reason,
            nextStepAdvice: customData.suggestion,
            next_step_advice: customData.suggestion
        };
        anomaly.escalateRecords.push(escalateRec);
    } else {
        const escalateRec = {
            time: new Date().toISOString(),
            from_role: currentRole,
            fromRole: currentRole,
            operator: currentUser,
            operatorRole: currentRole,
            operator_role: currentRole,
            targetRole: targetRole,
            target_role: targetRole,
            currentProgress: '当前操作人无法整改，请求升级处理',
            current_progress: '当前操作人无法整改，请求升级处理',
            reason: '无法完成整改，请求升级处理',
            nextStepAdvice: '请上级处理',
            next_step_advice: '请上级处理'
        };
        anomaly.escalateRecords.push(escalateRec);
        
        // 添加状态变更记录
        addStatusRecordSafely(anomaly, {
            timestamp: new Date().toISOString(),
            status: targetRole,
            changedBy: currentUser,
            changedByRole: currentRole,
            changed_by: currentUser,
            changed_by_role: currentRole,
            previousStatus: previousStatus,
            previous_status: previousStatus
        });
    }
    
    // 同步到下划线版本（用于云端存储）
    anomaly.escalate_records = [...anomaly.escalateRecords];
    
    saveSamplingAnomalies();
    console.log(`故障 ${anomalyId} 已升级至 ${targetRole}`);
    return true;
}

// ==================== 采样点异常权限控制函数 ====================

// 检查当前用户是否可以管理（编辑/删除）指定的采样点异常
function canManageSamplingAnomaly(anomaly) {
    if (!anomaly) return false;
    const role = getCurrentRole();
    const currentUser = getCurrentUsername();
    
    // 已闭环的禁止删除
    if (anomaly.completionStatus === 'closed' || anomaly.completion_status === 'closed') {
        return false;
    }
    
    // 检查删除保护标志
    if (anomaly.protected === true) {
        return false;
    }
    
    // 主任可以管理所有
    if (role === 'topadmin') return true;
    
    // 管理人员可以管理所有
    if (role === 'manager') return true;
    
    // 班长可以管理自己创建的
    if (role === 'leader') {
        return anomaly.reporter === currentUser || anomaly.creator === currentUser;
    }
    
    // 普通用户只能管理自己创建的草稿
    if (role === 'user') {
        const isCreator = anomaly.reporter === currentUser || anomaly.creator === currentUser;
        const isDraft = anomaly.completionStatus === 'draft' || anomaly.completion_status === 'draft';
        return isCreator && isDraft;
    }
    
    return false;
}

// 检查当前用户是否可以确认采样点异常已完成
function canConfirmSamplingAnomaly(anomaly) {
    if (!anomaly) return false;
    const role = getCurrentRole();
    
    // 确认整改完成权限：班长、管理人员、主任可以确认
    if (role === 'leader' || role === 'manager' || role === 'topadmin') {
        const status = anomaly.completionStatus || anomaly.completion_status || '';
        // 待班长确认状态下可以确认
        return status === 'waitingLeaderConfirm';
    }
    
    return false;
}

// 检查当前用户是否可以打回采样点异常
function canRejectSamplingAnomaly(anomaly) {
    if (!anomaly) return false;
    const role = getCurrentRole();
    const status = anomaly.completionStatus || anomaly.completion_status || '';
    
    // 主任可以将任何状态打回到草稿
    if (role === 'topadmin') {
        return ['closed', 'completed', 'waitingTopAdminClose'].includes(status);
    }
    
    // 管理人员可以将待确认状态打回
    if (role === 'manager') {
        return ['waitingLeaderConfirm'].includes(status);
    }
    
    return false;
}

// 检查当前用户是否可以将采样点异常升级为隐患
function canUpgradeSamplingAnomaly(anomaly) {
    if (!anomaly) return false;
    const role = getCurrentRole();
    const status = anomaly.completionStatus || anomaly.completion_status || '';
    if (status === 'closed') return false;
    return role === 'topadmin' || role === 'manager' || role === 'leader';
}

// 将采样点异常升级为隐患
function upgradeSamplingAnomaly(anomalyId) {
    const anomaly = samplingAnomalyData.find(a => a.id === anomalyId);
    if (!anomaly) {
        showToast('未找到该采样点异常', 'error');
        return;
    }
    const hazard = {
        id: 'hazard_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
        title: (anomaly.device || '') + ' - ' + (anomaly.tag || ''),
        description: anomaly.description || '',
        assignee: anomaly.reporter || '',
        priority: 'high',
        deadline: anomaly.deadline || '',
        status: 'pending',
        progress: 0,
        category: '安全类',
        hazardType: '设备设施',
        hazardLevel: '一般隐患',
        reportDate: anomaly.reportDate || anomaly.report_date || '',
        department: anomaly.area || anomaly.department || '',
        reporter: anomaly.reporter || '',
        source: 'sampling_anomaly',
        sourceId: anomaly.id,
        createTime: new Date().toLocaleString('zh-CN'),
        completionStatus: 'pending',
        completionUser: '',
        protected: false
    };
    if (!hazardData) hazardData = [];
    hazardData.push(hazard);
    saveHazards();
    showToast('已升级为隐患', 'success');
    filterSamplingAnomalies();
}

// 检查当前用户是否可以升级采样点异常
function canEscalateSamplingAnomaly(anomaly) {
    if (!anomaly) return false;
    const role = getCurrentRole();
    const currentUser = getCurrentUsername();
    const status = anomaly.completionStatus || anomaly.completion_status || '';
    
    // 主任不能升级
    if (role === 'topadmin') return false;
    
    // 管理人员可以将待闭环状态升级到主任
    if (role === 'manager') {
        return ['waitingTopAdminClose'].includes(status);
    }
    
    // 班长可以将待确认状态升级到管理人员
    if (role === 'leader') {
        const isCreator = anomaly.reporter === currentUser || anomaly.creator === currentUser;
        return isCreator && ['waitingLeaderConfirm'].includes(status);
    }
    
    // 普通用户可以将待班长确认状态升级到班长
    if (role === 'user') {
        const isCreator = anomaly.reporter === currentUser || anomaly.creator === currentUser;
        return isCreator && ['waitingLeaderConfirm'].includes(status);
    }
    
    return false;
}

// 检查当前用户是否可以标记无法完成
function canMarkCannotCompleteSamplingAnomaly(anomaly) {
    if (!anomaly) return false;
    const role = getCurrentRole();
    const currentUser = getCurrentUsername();
    const status = anomaly.completionStatus || anomaly.completion_status || '';
    
    // 只有创建者才能标记无法完成
    const isCreator = anomaly.reporter === currentUser || anomaly.creator === currentUser;
    if (!isCreator) return false;
    
    // 待班长确认状态下可以标记无法完成
    return status === 'waitingLeaderConfirm' && role === 'user';
}

// 检查当前用户是否可以删除采样点异常
function canDeleteSamplingAnomalyByRole(anomaly) {
    if (!anomaly) return false;
    const role = getCurrentRole();
    const currentUser = getCurrentUsername();
    
    // 已闭环的禁止删除
    if (anomaly.completionStatus === 'closed' || anomaly.completion_status === 'closed') {
        return false;
    }
    
    // 检查删除保护标志
    if (anomaly.protected === true) {
        return false;
    }
    
    // 主任可以删除所有
    if (role === 'topadmin') return true;
    
    // 管理人员可以删除所有
    if (role === 'manager') return true;
    
    // 班长可以删除自己创建的
    if (role === 'leader') {
        return anomaly.reporter === currentUser || anomaly.creator === currentUser;
    }
    
    // 普通用户只能删除自己创建的草稿
    if (role === 'user') {
        const isCreator = anomaly.reporter === currentUser || anomaly.creator === currentUser;
        const isDraft = anomaly.completionStatus === 'draft' || anomaly.completion_status === 'draft';
        return isCreator && isDraft;
    }
    
    return false;
}

// 生成采样点异常的操作按钮HTML
function getSamplingAnomalyActionButtons(anomaly) {
    let buttons = '';
    
    buttons += `<span class="sampling-anomaly-view-btn" 
                      data-id="${anomaly.id}" 
                      onmouseenter="showSamplingAnomalyTooltip(event, '${anomaly.id}')"
                      onmouseleave="hideSamplingAnomalyTooltip()">查看</span>`;
    
    return buttons;
}

// ==================== 采样点异常悬浮查看功能 ====================

let samplingAnomalyTooltipHideTimer = null;
let isMouseInSamplingTooltip = false;

function initSamplingAnomalyTooltip() {
    let tooltip = document.getElementById('sampling-anomaly-tooltip');
    if (tooltip) return;
    
    tooltip = document.createElement('div');
    tooltip.id = 'sampling-anomaly-tooltip';
    tooltip.className = 'sampling-anomaly-tooltip';
    tooltip.style.cssText = 'position: fixed; z-index: 9999; width: 360px; max-height: 400px; overflow-y: auto; background: #fff; border: 1px solid #ddd; border-radius: 6px; box-shadow: 0 4px 20px rgba(0,0,0,0.15); padding: 12px; display: none; pointer-events: auto;';
    document.body.appendChild(tooltip);
    
    tooltip.addEventListener('mouseenter', function(e) {
        e.stopPropagation();
        isMouseInSamplingTooltip = true;
        if (samplingAnomalyTooltipHideTimer) {
            clearTimeout(samplingAnomalyTooltipHideTimer);
            samplingAnomalyTooltipHideTimer = null;
        }
    });
    
    tooltip.addEventListener('mouseleave', function(e) {
        e.stopPropagation();
        isMouseInSamplingTooltip = false;
        hideSamplingAnomalyTooltip();
    });
}

function showSamplingAnomalyTooltip(event, anomalyId) {
    initSamplingAnomalyTooltip();
    
    if (samplingAnomalyTooltipHideTimer) {
        clearTimeout(samplingAnomalyTooltipHideTimer);
        samplingAnomalyTooltipHideTimer = null;
    }
    
    const anomaly = samplingAnomalyData.find(a => a.id === anomalyId);
    if (!anomaly) return;
    
    let html = generateSamplingAnomalyOperationRecordsHtml(anomaly);
    const tooltip = document.getElementById('sampling-anomaly-tooltip');
    
    tooltip.innerHTML = html;
    tooltip.style.display = 'block';
    
    const rect = event.target.getBoundingClientRect();
    const tooltipWidth = 360;
    const tooltipHeight = 400;
    const windowHeight = window.innerHeight;
    const windowWidth = window.innerWidth;
    
    let left = rect.left - tooltipWidth;
    let top = rect.top;
    
    if (left < 10) {
        left = rect.right + 10;
    }
    
    const spaceBelow = windowHeight - rect.bottom;
    const spaceAbove = rect.top;
    
    if (spaceBelow < tooltipHeight && spaceAbove > spaceBelow) {
        top = rect.bottom - tooltipHeight;
    }
    
    if (top < 10) {
        top = 10;
    }
    
    if (left + tooltipWidth > windowWidth - 10) {
        left = windowWidth - tooltipWidth - 10;
    }
    
    tooltip.style.left = left + 'px';
    tooltip.style.top = top + 'px';
}

function hideSamplingAnomalyTooltip() {
    const tooltip = document.getElementById('sampling-anomaly-tooltip');
    if (!tooltip) return;
    
    samplingAnomalyTooltipHideTimer = setTimeout(function() {
        if (!isMouseInSamplingTooltip) {
            tooltip.style.display = 'none';
        }
        samplingAnomalyTooltipHideTimer = null;
    }, 300);
}

function generateSamplingAnomalyOperationRecordsHtml(anomaly) {
    const allRecords = [];
    
    // 获取操作人信息的辅助函数
    const getOperatorInfo = (record) => {
        const opName = typeof record.operator === 'object' ? (record.operator.name || record.operator.username || record.operator.realname || '-') : (record.operator || '-');
        const opRole = typeof record.operator === 'object' ? (record.operator.role || '') : '';
        const displayName = opName ? getUserDisplayName(opName) : '-';
        const roleText = opRole ? `(${getHazardRoleText(opRole)})` : '';
        return `${displayName}${roleText}`;
    };
    
    // 打回记录
    const rejectRecords = anomaly.rejectRecords || anomaly.reject_records || [];
    if (rejectRecords.length > 0) {
        rejectRecords.forEach((record) => {
            allRecords.push({
                time: record.rejectTime || record.time,
                type: '打回情况说明',
                operator: getOperatorInfo(record),
                content: record.rejectReason || '-'
            });
        });
    }
    
    // 升级记录
    const escalateRecords = anomaly.escalateRecords || anomaly.escalate_records || [];
    if (escalateRecords.length > 0) {
        escalateRecords.forEach((record) => {
            const contentParts = [];
            if (record.currentProgress) contentParts.push(`当前整改情况：${record.currentProgress}`);
            if (record.reason) contentParts.push(`无法完成原因：${record.reason}`);
            if (record.nextStepAdvice) contentParts.push(`下一步整改建议：${record.nextStepAdvice}`);
            if (record.escalateReason) contentParts.push(record.escalateReason);
            const content = contentParts.join('\n') || '-';
            allRecords.push({
                time: record.time || record.escalateTime || record.timestamp,
                type: '升级记录',
                operator: getOperatorInfo(record),
                content: content
            });
        });
    }
    
    // 状态变更记录
    const statusHistory = anomaly.statusHistory || anomaly.status_history || [];
    if (statusHistory.length > 0) {
        statusHistory.forEach((record) => {
            const opName = typeof record.changedBy === 'object' ? (record.changedBy.name || record.changedBy.username || record.changedBy.realname || '-') : (record.changedBy || '-');
            const opRole = typeof record.changedBy === 'object' ? (record.changedBy.role || record.changedByRole || '') : (record.changedByRole || '');
            const displayName = opName ? getUserDisplayName(opName) : '-';
            const roleText = opRole ? `(${getHazardRoleText(opRole)})` : '';
            const statusLabel = SAMPLING_ANOMALY_STATUS_MAP[record.status] || record.status || '';
            allRecords.push({
                time: record.timestamp || record.time,
                type: '状态变更',
                operator: `${displayName}${roleText}`,
                content: statusLabel
            });
        });
    }
    
    // 整改完成记录
    const completionRecords = anomaly.completionRecords || anomaly.completion_records || [];
    if (completionRecords.length > 0) {
        completionRecords.forEach((record) => {
            allRecords.push({
                time: record.completionTime || record.time,
                type: '完成情况说明',
                operator: getOperatorInfo(record),
                content: record.completionNote || record.content || '-'
            });
        });
    }
    
    // 无法完成整改记录
    const cannotCompleteRecords = anomaly.cannotCompleteRecords || anomaly.cannot_complete_records || [];
    if (cannotCompleteRecords.length > 0) {
        cannotCompleteRecords.forEach((record) => {
            allRecords.push({
                time: record.time || record.created_at,
                type: '无法完成整改',
                operator: getOperatorInfo(record),
                content: record.reason || record.content || '-'
            });
        });
    }
    
    // 按时间升序排序，最早的记录显示在前面
    allRecords.sort((a, b) => new Date(a.time) - new Date(b.time));
    
    // 构建HTML，与备注栏格式完全一致
    let html = '';
    
    if (allRecords.length > 0) {
        html = allRecords.map((record, idx) => {
            const formattedTime = formatDateTime(record.time);
            const escapedContent = escapeHtml(record.content).replace(/\n/g, '<br>');
            return `[${idx + 1}] ${formattedTime} 【${record.type} ${record.operator}】<br>${escapedContent}`;
        }).join('<br><br>');
    } else {
        html = '<span style="color:#999;font-size:12px;">暂无操作记录</span>';
    }
    
    return html;
}

