// 渲染异常列表
function renderSamplingAnomalyList() {
    const container = safeGetElement('samplingAnomalyList');
    const emptyState = safeGetElement('samplingAnomalyEmptyState');
    if (!container) return;

    const data = filteredSamplingAnomalyData.length > 0 ? filteredSamplingAnomalyData : samplingAnomalyData;

    if (data.length === 0) {
        if (emptyState) emptyState.style.display = 'block';
        container.innerHTML = '<div class="empty-state"><div class="empty-icon">🔍</div><p>暂无采样点异常数据</p><p class="empty-hint">点击"新增异常"创建新的异常记录</p></div>';
        return;
    }

    if (emptyState) emptyState.style.display = 'none';

    const role = getCurrentRole();
    const currentUser = getCurrentUserInfo();
    const currentUsername = currentUser ? currentUser.username : '';
    const isAdmin = role === 'topadmin';
    const isManager = role === 'manager';
    const isLeader = role === 'leader';
    const isUser = role === 'user';

    // 生成卡片HTML - 与隐患排查治理保持一致的样式
    container.innerHTML = data.map(item => {
        let cardClass = 'task-card';
        const disabledStatuses = ['notExists', 'notExistsByLeader', 'completed'];
        
        if (item.completionStatus === 'notExists' || item.completionStatus === 'notExistsByLeader') {
            cardClass = 'task-card disabled-card';
        } else if (isSamplingAnomalyOverdue(item.deadline, item.completionStatus)) {
            cardClass = 'task-card overdue';
        }
        
        const statusClass = getSamplingAnomalyStatusClass(item.completionStatus);
        const statusText = getSamplingAnomalyStatusText(item.completionStatus);
        
        // 获取提报人信息
        const reporterName = getUserDisplayName(item.reporter);
        const reporterRole = item.creatorRole || item.creator_role || '';
        const isCreator = item.reporter === currentUsername || item.creator === currentUsername;
        
        // 获取样品名称（用于高亮显示）
        const sampleName = item.sampleName || item.sample_name || '';
        
        // 获取分析项目
        const analysisItem = item.analysisItem || item.analysis_item || item.testItem || '';
        
        // 获取异常描述
        const anomalyDescription = item.anomalyDescription || item.anomaly_description || item.description || item.content || '';
        const shortDescription = anomalyDescription.length > 60 ? anomalyDescription.substring(0, 60) + '...' : anomalyDescription;
        
        // 获取异常值
        const anomalyValue = item.anomalyValue || item.anomaly_value || item.testValue || '';
        const standardValue = item.standardValue || item.standard_value || '';
        
        // 获取填报日期
        const reportTime = item.reportTime || item.report_time || item.created_at || '';
        const formattedReportTime = reportTime ? formatDate(reportTime) : '';
        
        // 获取整改负责人
        const rectificationPerson = item.rectificationPerson || item.rectification_person || '';
        
        // 智能计算显示进度
        const displayProgress = getSamplingAnomalyDisplayProgress(item);
        
        // 权限判断
        const canEdit = canManageSamplingAnomaly(item, currentUsername, role);
        const canDelete = canDeleteSamplingAnomaly(item, currentUsername, role);
        const canComplete = canConfirmSamplingAnomaly(item, currentUsername, role);
        const canReject = canRejectSamplingAnomaly(item, currentUsername, role);
        const canUpgrade = canUpgradeSamplingAnomaly(item, currentUsername, role);
        
        // 构建信息元数据区
        let metaInfo = '<div class="task-meta">';
        if (formattedReportTime) {
            metaInfo += `<div><span style="color: #718096;">📅 填报: ${formattedReportTime}</span></div>`;
        }
        if (item.deadline) {
            const deadlineClass = isSamplingAnomalyOverdue(item.deadline, item.completionStatus) ? 'color: #e53e3e; font-weight: 600;' : 'color: #718096;';
            metaInfo += `<div><span style="${deadlineClass}">⏰ 截止: ${item.deadline}</span></div>`;
        }
        if (analysisItem) {
            metaInfo += `<div><span style="color: #667eea; font-weight: 500;">🧪 ${escapeHtml(analysisItem)}</span></div>`;
        }
        if (rectificationPerson) {
            metaInfo += `<div><span style="color: #4a5568;">👷 整改人: ${escapeHtml(rectificationPerson)}</span></div>`;
        }
        if (anomalyValue) {
            const valueColor = standardValue ? '#e53e3e' : '#718096';
            metaInfo += `<div><span style="color: ${valueColor}; font-weight: 500;">⚠️ 异常值: ${escapeHtml(anomalyValue)}${standardValue ? ` (标准: ${escapeHtml(standardValue)})` : ''}</span></div>`;
        }
        metaInfo += '</div>';
        
        // 构建描述区
        let descriptionHtml = '';
        if (shortDescription) {
            descriptionHtml = `<div class="task-description" style="padding: 8px 12px; background: #f7fafc; border-radius: 8px; margin-bottom: 10px; color: #4a5568; font-size: 13px; line-height: 1.5; border-left: 3px solid #f59e0b;">${escapeHtml(shortDescription)}</div>`;
        }
        
        // 构建操作按钮
        let actionsHtml = '';
        if (canEdit || canDelete || canComplete || canReject || canUpgrade) {
            actionsHtml = '<div class="card-actions" onclick="event.stopPropagation();">';
            // 查看按钮始终显示
            actionsHtml += `<button class="card-action-btn btn-view" onclick="openSamplingAnomalyDetailModal('${item.id}')">📄 查看详情</button>`;
            
            if (canEdit && !disabledStatuses.includes(item.completionStatus)) {
                actionsHtml += `<button class="card-action-btn btn-edit" onclick="openEditSamplingAnomalyModal('${item.id}')">✏️ 编辑</button>`;
            }
            
            if (canComplete && !disabledStatuses.includes(item.completionStatus)) {
                actionsHtml += `<button class="card-action-btn btn-status" onclick="confirmSamplingAnomalyComplete('${item.id}')">✅ 确认完成</button>`;
            }
            
            if (canReject && !disabledStatuses.includes(item.completionStatus)) {
                actionsHtml += `<button class="card-action-btn btn-delete" onclick="rejectSamplingAnomaly('${item.id}')">🔄 打回</button>`;
            }
            
            if (canUpgrade && !disabledStatuses.includes(item.completionStatus)) {
                actionsHtml += `<button class="card-action-btn btn-status" onclick="upgradeSamplingAnomaly('${item.id}')">⬆️ 升级隐患</button>`;
            }
            
            if (canDelete) {
                actionsHtml += `<button class="card-action-btn btn-delete" onclick="deleteSamplingAnomalyItem('${item.id}')">🗑️ 删除</button>`;
            }
            
            actionsHtml += '</div>';
        }
        
        return `
            <div class="${cardClass}" data-anomaly-id="${item.id}" onclick="openSamplingAnomalyDetailModal('${item.id}')">
                <div class="task-header">
                    <div class="task-title">${escapeHtml(item.device || '')} - ${escapeHtml(item.tag || '')}</div>
                    <div class="task-status ${statusClass}">${statusText}</div>
                </div>
                <div class="task-info">
                    <span class="task-assignee">👁️ ${escapeHtml(reporterName)}${reporterRole ? `(${getHazardRoleText(reporterRole)})` : ''}</span>
                    <span class="task-priority" style="background: #dbeafe; color: #1d4ed8; padding: 3px 10px; border-radius: 6px; font-size: 12px; font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 180px;">🧪 ${escapeHtml(sampleName || '-')}</span>
                </div>
                ${metaInfo}
                ${descriptionHtml}
                <div class="task-progress-bar">
                    <div class="task-progress-fill" style="width: ${displayProgress}%"></div>
                </div>
                <div class="task-footer">
                    <span class="task-progress-text">进度 ${displayProgress}%</span>
                    <span class="task-deadline">${item.deadline ? `⏰ ${item.deadline}` : ''}</span>
                </div>
                ${actionsHtml}
            </div>
        `;
    }).join('');
}

// 获取采样点异常进度百分比（根据状态）
/**
 * 智能计算采样点异常进度（采样点异常排查专用）
 * 多维度计算：状态映射 + 记录细化 + 时间辅助 + 优先级调整
 */
function calculateSamplingAnomalyProgress(item) {
    if (!item) return 0;
    
    const status = item.completionStatus || item.completion_status;
    
    // 1. 终态直接返回
    if (status === 'completed') return 80;
    if (status === 'closed') return 100;
    if (status === 'notExists' || status === 'notExistsByLeader') return 0;
    
    // 2. 根据状态映射基准进度
    let baseProgress = 0;
    
    // 起始阶段
    if (['draft', 'pending'].includes(status)) {
        baseProgress = 5;
    }
    else if (['waitingLeaderConfirm'].includes(status)) {
        baseProgress = 15;
    }
    // 整改中
    else if (['progress'].includes(status)) {
        baseProgress = 35;
    }
    else if (['leaderRectifying', 'adminRectifying'].includes(status)) {
        baseProgress = 45;
    }
    // 已确认存在但正在处理
    else if (['leaderConfirmed', 'confirmedByAdmin', 'leaderConfirmedExists'].includes(status)) {
        baseProgress = 40;
    }
    // 升级状态
    else if (status === 'escalatedToLeader') {
        baseProgress = 30;
    }
    else if (status === 'escalatedToAdmin') {
        baseProgress = 35;
    }
    else if (status === 'escalatedToTopAdmin') {
        baseProgress = 40;
    }
    // 审核阶段
    else if (status === 'waitingLeaderReview') {
        baseProgress = 55;
    }
    else if (status === 'waitingAdminReview') {
        baseProgress = 70;
    }
    // 待闭环
    else if (['waitingTopAdminClose', 'waitingAdminConfirm', 'waitingTopAdminConfirm', 'waitingTopAdminHandle'].includes(status)) {
        baseProgress = 85;
    }
    // 需重新整改
    else if (status === 'needRectify') {
        baseProgress = 25;
    }
    else if (status === 'waitingRectify') {
        baseProgress = 10;
    }
    
    // 3. 记录维度：根据整改/进度/拒绝记录细化
    let recordAdjustment = 0;
    
    // 整改完成记录
    const completionRecords = (item.completion_records?.length || 0) + 
                              (item.completionRecords?.length || 0);
    recordAdjustment += Math.min(completionRecords * 8, 40);
    
    // 进度记录/状态历史
    const statusHistory = (item.status_history?.length || 0) + (item.statusHistory?.length || 0);
    recordAdjustment += Math.min(statusHistory * 3, 20);
    
    // 拒绝记录
    const rejectRecords = (item.reject_records?.length || 0) + 
                          (item.rejectRecords?.length || 0);
    recordAdjustment -= Math.min(rejectRecords * 5, 20);
    
    // 升级记录
    const escalateRecords = (item.escalate_records?.length || 0) + 
                           (item.escalateRecords?.length || 0);
    recordAdjustment += Math.min(escalateRecords * 3, 15);
    
    // 4. 时间维度：结合截止日期
    let progress = baseProgress + recordAdjustment;
    
    const timeProgress = calculateTimeBasedProgress(item);
    if (timeProgress > 0) {
        progress = Math.round(progress * 0.7 + timeProgress * 0.3);
    }
    
    // 5. 超期处理
    if (item.deadline && isSamplingAnomalyOverdue(item.deadline, status)) {
        progress = Math.max(progress, 80);
    }
    
    // 6. 优先级微调
    const priority = item.priority;
    if (priority === 'high' && progress > 0 && progress < 100) {
        progress = Math.min(progress + 5, 95);
    }
    
    // 限制范围
    progress = Math.min(Math.max(progress, 0), 95);
    return progress;
}

/**
 * 获取采样点异常卡片显示的进度值
 * 优先使用用户手动设置的进度，否则使用智能计算的进度
 */
function getSamplingAnomalyDisplayProgress(item) {
    if (!item) return 0;
    
    const status = item.completionStatus || item.completion_status;
    
    // 终态直接返回
    if (status === 'completed') return 80;
    if (status === 'closed') return 100;
    if (status === 'notExists' || status === 'notExistsByLeader') return 0;
    
    // 如果已有手动设置的进度，优先显示
    if (item.progress !== undefined && item.progress !== null && 
        item.progress !== 0 && item.progress > 0 && item.progress < 100) {
        return item.progress;
    }
    
    // 使用智能计算的进度
    return calculateSamplingAnomalyProgress(item);
}

// 根据角色生成状态选项
function generateSamplingAnomalyStatusOptions(currentStatus = 'progress') {
    const role = getCurrentRole();
    const statusSelect = safeGetElement('samplingAnomalyCompletionStatus');
    if (!statusSelect) return;
    
    // 主任可以看到所有状态
    const allStatuses = [
        { value: 'draft', label: '草稿' },
        { value: 'pending', label: '未开始' },
        { value: 'progress', label: '进行中' },
        { value: 'completed', label: '已完成' },
        { value: 'closed', label: '已闭环' },
        { value: 'waitingLeaderConfirm', label: '待班长确认' },
        { value: 'needRectify', label: '需重新整改' },
        { value: 'waitingRectify', label: '待整改' },
        { value: 'waitingTopAdminClose', label: '待主任闭环' },
        { value: 'escalatedToLeader', label: '已升级至班长' },
        { value: 'escalatedToAdmin', label: '已升级至管理人员' },
        { value: 'escalatedToTopAdmin', label: '已升级至主任' },
        { value: 'leaderRectifying', label: '班长整改中' },
        { value: 'adminRectifying', label: '管理人员整改中' },
        { value: 'leaderConfirmedExists', label: '班长已确认故障存在' },
        { value: 'notExistsByLeader', label: '故障不存在(班长确认)' },
        { value: 'confirmedByAdmin', label: '管理人员已确认故障' },
        { value: 'notExists', label: '故障不存在' }
    ];
    
    // 非主任角色只能看到基础状态
    const basicStatuses = [
        { value: 'draft', label: '草稿' },
        { value: 'pending', label: '未开始' },
        { value: 'progress', label: '进行中' },
        { value: 'completed', label: '已完成' },
        { value: 'closed', label: '已闭环' }
    ];
    
    const statuses = role === 'topadmin' ? allStatuses : basicStatuses;
    
    statusSelect.innerHTML = statuses.map(s => 
        `<option value="${s.value}" ${s.value === currentStatus ? 'selected' : ''}>${s.label}</option>`
    ).join('');
}

// 打开添加/编辑模态框
function openAddSamplingAnomalyModal(anomalyId = null) {
    // 先关闭详情模态框
    closeSamplingAnomalyDetailModal();
    
    const modal = safeGetElement('addSamplingAnomalyModal');
    const title = safeGetElement('addSamplingAnomalyTitle');
    const form = safeGetElement('addSamplingAnomalyForm');
    if (!modal || !title || !form) return;

    editingSamplingAnomalyId = anomalyId;
    loadSamplingAnomalyReporters();
    loadSamplingAnomalyRectifiers();
    loadSamplingAnomalyConfirmers();

    if (anomalyId) {
        const item = samplingAnomalyData.find(a => a.id === anomalyId);
        if (item) {
            title.textContent = ' 编辑采样点异常';
            safeGetElement('samplingAnomalyDevice').value = item.device || '';
            safeGetElement('samplingAnomalyTag').value = item.tag || '';
            safeGetElement('samplingAnomalySampleName').value = item.sampleName || '';
            safeGetElement('samplingAnomalyProblemDesc').value = item.problemDesc || '';
            safeGetElement('samplingAnomalyReportTime').value = item.reportTime || '';
            safeGetElement('samplingAnomalyReporter').value = item.reporter || '';
            safeGetElement('samplingAnomalyRectifier').value = item.rectifier || '';
            
            const currentRole = getCurrentRole();
            
            // 状态（完成情况）：只有主任可以编辑
            const statusField = safeGetElement('samplingAnomalyCompletionStatus');
            if (statusField) {
                generateSamplingAnomalyStatusOptions(item.completionStatus || 'progress');
                if (currentRole !== 'topadmin') {
                    statusField.disabled = true;
                    statusField.style.backgroundColor = '#f5f5f5';
                } else {
                    statusField.disabled = false;
                    statusField.style.backgroundColor = '';
                }
            }
            
            // 进度条：只有主任可以编辑
            const progressField = safeGetElement('samplingAnomalyProgress');
            if (progressField) {
                progressField.value = item.progress || 0;
                safeGetElement('samplingAnomalyProgressValue').textContent = (item.progress || 0) + '%';
                if (currentRole !== 'topadmin') {
                    progressField.disabled = true;
                } else {
                    progressField.disabled = false;
                }
            }
            
            // 完成情况说明
            const completionNoteField = safeGetElement('samplingAnomalyCompletionNote');
            if (completionNoteField) {
                completionNoteField.value = item.completionNote || '';
            }
            
            safeGetElement('samplingAnomalyConfirmer').value = item.confirmer || '';
            safeGetElement('samplingAnomalyRemark').value = item.remark || '';
        }
    } else {
        title.textContent = ' 新建采样点异常';
        form.reset();
        // 动态生成状态选项
        generateSamplingAnomalyStatusOptions('progress');
        // 设置默认提报时间为当前日期
        const now = new Date();
        const formattedDate = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
        safeGetElement('samplingAnomalyReportTime').value = formattedDate;
        // 设置提报人为当前登录用户的姓名
        const currentUsername = localStorage.getItem('username') || '';
        if (currentUsername) {
            const displayName = getUserDisplayName(currentUsername);
            safeGetElement('samplingAnomalyReporter').value = displayName || currentUsername;
        }
    }

    safeSetDisplay('addSamplingAnomalyModal', 'block');
}

// 关闭添加/编辑模态框
function closeAddSamplingAnomalyModal() {
    const modal = safeGetElement('addSamplingAnomalyModal');
    if (modal) {
        // 移除可能存在的动画类
        modal.classList.remove('modal-show');
        // 设置隐藏
        safeSetDisplay('addSamplingAnomalyModal', 'none');
        // 重置表单
        const form = safeGetElement('addSamplingAnomalyForm');
        if (form) form.reset();
        // 清理编辑状态
        editingSamplingAnomalyId = null;
        // 清理焦点，防止键盘导航问题
        if (document.activeElement && document.activeElement !== document.body) {
            document.activeElement.blur();
        }
        console.log('[采样点异常] 添加/编辑模态框已关闭');
    }
}

// 关闭详情模态框
function closeSamplingAnomalyDetailModal() {
    const modal = safeGetElement('samplingAnomalyDetailModal');
    if (modal) {
        modal.classList.remove('modal-show');
        safeSetDisplay('samplingAnomalyDetailModal', 'none');
        // 清理内容，防止内存泄漏
        const content = safeGetElement('samplingAnomalyDetailContent');
        if (content) content.innerHTML = '';
        // 清理焦点
        if (document.activeElement && document.activeElement !== document.body) {
            document.activeElement.blur();
        }
        console.log('[采样点异常] 详情模态框已关闭');
    }
}

