/**
 * 台账类表格列宽自适应调整功能
 * 实现：1) 根据内容长度自动调整列宽 2) 限制最大宽度为15个中文字符 3) 响应式调整
 */

// 计算中文字符宽度的辅助函数
function calculateChineseCharWidth() {
    // 创建临时元素来测量单个中文字符宽度
    const testElement = document.createElement('span');
    testElement.textContent = '中';
    testElement.style.cssText = `
        position: absolute;
        visibility: hidden;
        font-size: 13px;
        font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
        white-space: nowrap;
    `;
    document.body.appendChild(testElement);
    const width = testElement.offsetWidth;
    document.body.removeChild(testElement);
    return width || 16; // 默认16px，如果测量失败
}

// 动态调整表格列宽 - 根据内容和表头自适应
function autoAdjustTableColumnWidths(tableId) {
    const table = document.getElementById(tableId);
    if (!table) {
        console.log(`[表格自适应] 未找到表格: ${tableId}`);
        return;
    }

    const tbody = table.querySelector('tbody');
    const thead = table.querySelector('thead');
    if (!tbody || !thead) {
        console.log(`[表格自适应] 表格结构不完整: ${tableId}`);
        return;
    }

    const rows = tbody.querySelectorAll('tr');

    // 计算15个中文字符的宽度
    const singleCharWidth = calculateChineseCharWidth();
    const minColumnWidth = 80;

    // 测量单元格的 padding + border 横向补偿（因 td 使用 border-box，设 width 时会吃掉这部分空间）
    let horizontalPad = 24; // 默认补偿
    if (rows.length > 0) {
        const sampleCell = rows[0].querySelector('td');
        if (sampleCell) {
            const cs = window.getComputedStyle(sampleCell);
            const pl = parseFloat(cs.paddingLeft) || 0;
            const pr = parseFloat(cs.paddingRight) || 0;
            const bl = parseFloat(cs.borderLeftWidth) || 0;
            const br = parseFloat(cs.borderRightWidth) || 0;
            horizontalPad = pl + pr + bl + br;
        }
    }
    // maxColumnWidth = 15个汉字的内容宽度 + 横向补偿 = 总列宽
    const maxColumnWidth = singleCharWidth * 15 + horizontalPad;

    // 获取所有列
    const headerCells = thead.querySelectorAll('th');
    const numColumns = headerCells.length;

    // 计算每列的最大内容长度 - 同时考虑表头和数据
    const columnWidths = new Array(numColumns).fill(minColumnWidth + horizontalPad);

    // 1. 首先测量表头内容的宽度（重要，确保长表头可以显示）
    headerCells.forEach((th, index) => {
        const content = th.textContent.trim();
        if (content) {
            let contentLength = 0;
            for (let i = 0; i < content.length; i++) {
                const char = content[i];
                if (/[\u4e00-\u9fa5]/.test(char)) {
                    contentLength += 2;
                } else {
                    contentLength += 1;
                }
            }
            // 表头更宽松的宽度限制，确保长表头可以适应
            const estimatedWidth = Math.min(
                Math.max(contentLength * (singleCharWidth / 2) + horizontalPad, minColumnWidth + horizontalPad), maxColumnWidth);
            if (estimatedWidth > columnWidths[index]) {
                columnWidths[index] = estimatedWidth;
            }
        }
    });

    // 2. 然后测量数据内容的宽度
    if (rows.length > 0) {
        rows.forEach((row) => {
            const cells = row.querySelectorAll('td');
            cells.forEach((cell, cellIndex) => {
                if (cellIndex >= numColumns) return;

                const content = cell.textContent.trim();
                if (content) {
                    let contentLength = 0;
                    for (let i = 0; i < content.length; i++) {
                        const char = content[i];
                        if (/[\u4e00-\u9fa5]/.test(char)) {
                            contentLength += 2;
                        } else {
                            contentLength += 1;
                        }
                    }

                    const estimatedWidth = Math.min(
                        Math.max(contentLength * (singleCharWidth / 2) + horizontalPad, minColumnWidth + horizontalPad),
                        maxColumnWidth);

                    if (estimatedWidth > columnWidths[cellIndex]) {
                        columnWidths[cellIndex] = estimatedWidth;
                    }
                }
            });
        });
    }

    // 3. 计算总列宽并设置 table 宽度（确保 fixed 布局按实际像素分配）
    const totalWidth = columnWidths.reduce((s, w) => s + w, 0);
    table.style.width = totalWidth + 'px';
    table.style.minWidth = totalWidth + 'px';
    table.style.maxWidth = totalWidth + 'px';
    table.style.tableLayout = 'fixed';

    // 4. 应用列宽到表头
    headerCells.forEach((th, index) => {
        const width = Math.round(columnWidths[index]);
        th.style.width = `${width}px`;
        th.style.whiteSpace = 'normal';
        th.style.wordBreak = 'break-word';
        th.style.overflowWrap = 'break-word';
    });

    // 5. 应用列宽到数据单元格
    if (rows.length > 0) {
        rows.forEach((row) => {
            const cells = row.querySelectorAll('td');
            cells.forEach((cell, cellIndex) => {
                if (cellIndex < numColumns) {
                    const width = Math.round(columnWidths[cellIndex]);
                    cell.style.width = `${width}px`;
                    cell.style.whiteSpace = 'normal';
                    cell.style.wordBreak = 'break-word';
                    cell.style.overflowWrap = 'break-word';
                }
            });
        });
    }

    console.log(`[表格自适应] 已完成表格列宽调整: ${tableId}`);
}

// 批量调整所有台账类表格 - 包含更多表格
function adjustAllLedgerTableColumns() {
    const ledgerTables = [
        'patrolDataTable',
        'samplingCarDataTable',
        'instrumentDataTable',
        'inspectionTable',
        'honorTable',
        'teamDataTable',
        'trainingTable',
        'teamPersonnelTable',
        'personnelTable',
        'taskLedgerTable',
        'hazardLedgerTable',
        'samplingAnomalyLedgerTable'
    ];

    ledgerTables.forEach((tableId) => {
        setTimeout(() => {
            autoAdjustTableColumnWidths(tableId);
        }, 100); // 延迟执行，确保表格已渲染完成
    });
}

// 添加窗口大小变化时的自动调整
function setupResponsiveTableAdjustment() {
    let resizeTimer;

    window.addEventListener('resize', () => {
        // 清除之前的定时器，避免频繁触发
        if (resizeTimer) {
            clearTimeout(resizeTimer);
        }

        // 延迟200ms后执行，避免在窗口调整过程中频繁计算
        resizeTimer = setTimeout(() => {
            adjustAllLedgerTableColumns();
        }, 200);
    });
}

// 初始化表格列宽调整功能 - 在页面加载完成后执行
document.addEventListener('DOMContentLoaded', () => {
    setTimeout(() => {
        adjustAllLedgerTableColumns();
        setupResponsiveTableAdjustment();
        console.log('[表格列宽自适应] 功能初始化完成');
    }, 500);
});

// 暴露给外部调用的接口
window.autoAdjustTableColumnWidths = autoAdjustTableColumnWidths;
window.adjustAllLedgerTableColumns = adjustAllLedgerTableColumns;

/**
 * 获取允许的状态转换（借鉴隐患排查治理流程）
 * @param {string} role - 当前用户角色
 * @param {string} currentStatus - 当前状态
 * @returns {string[]} 允许转换到的状态列表
 */
function getAllowedTransitions(role, currentStatus) {
    // 基础转换：所有角色都可以保持原状态或升级
    const baseTransitions = [currentStatus, 'escalatedToLeader', 'escalatedToAdmin', 'escalatedToTopAdmin'];
    
    switch (role) {
        case 'user':
            // 普通用户：可以在草稿、未开始、进行中之间切换，也可以提交完成
            return [...baseTransitions, 'draft', 'pending', 'waitingLeaderConfirm', 'progress', 'needRectify'];
        
        case 'leader':
            // 班长：可以确认完成（进入待管理人员确认），打回整改，或升级至管理人员
            return [...baseTransitions, 'waitingAdminConfirm', 'needRectify', 'leaderRectifying', 'progress', 'completed', 'draft', 'pending'];
        
        case 'manager':
            // 管理人员：可以确认完成（进入待主任终审），打回整改，或升级至主任
            return [...baseTransitions, 'waitingTopAdminClose', 'needRectify', 'adminRectifying', 'leaderRectifying', 'progress', 'completed', 'draft', 'pending'];
        
        case 'topadmin':
            // 主任：可以进行任何状态转换
            return ['draft', 'pending', 'progress', 'completed', 'closed', 
                    'waitingLeaderConfirm', 'waitingAdminConfirm', 'waitingTopAdminClose', 'waitingTopAdminClose',
                    'needRectify', 'waitingRectify', 'leaderRectifying', 'adminRectifying',
                    'escalatedToLeader', 'escalatedToAdmin', 'escalatedToTopAdmin',
                    'leaderConfirmed', 'confirmedByAdmin', 'waitingTopAdminConfirm', 'waitingTopAdminHandle',
                    'notExists', 'notExistsByLeader', 'leaderConfirmedExists'];
        
        default:
            return baseTransitions;
    }
}

// 保存采样点异常
async function saveSamplingAnomaly(event) {
    event.preventDefault();

    const device = safeGetElement('samplingAnomalyDevice').value.trim();
    const tag = safeGetElement('samplingAnomalyTag').value.trim();
    const sampleName = safeGetElement('samplingAnomalySampleName').value.trim();
    const problemDesc = safeGetElement('samplingAnomalyProblemDesc').value.trim();
    const reportTime = safeGetElement('samplingAnomalyReportTime').value;
    const reporter = safeGetElement('samplingAnomalyReporter').value;
    const rectifier = safeGetElement('samplingAnomalyRectifier').value;
    const completionStatus = safeGetElement('samplingAnomalyCompletionStatus').value;
    const completionNote = safeGetElement('samplingAnomalyCompletionNote').value.trim();
    const confirmer = safeGetElement('samplingAnomalyConfirmer').value;
    const remark = safeGetElement('samplingAnomalyRemark').value.trim();
    const rejectReason = safeGetElement('samplingAnomalyRejectReason').value.trim();
    const reformNote = safeGetElement('samplingAnomalyReformNote').value.trim();

    if (!device || !tag || !sampleName || !problemDesc || !reportTime || !reporter) {
        showToast('请填写所有必填字段', 'error');
        return;
    }

    const currentRole = getCurrentRole();
    const currentUser = getCurrentUsername();
    const now = new Date().toLocaleString('zh-CN');
    const isoNow = new Date().toISOString();

    // 状态转换逻辑（借鉴隐患排查治理流程）
    let effectiveStatus = completionStatus;
    
    // 普通用户提交整改完成 -> 待班长确认
    if (currentRole === 'user' && (completionStatus === 'completed' || completionStatus === 'closed')) {
        effectiveStatus = 'waitingLeaderConfirm';
    }
    
    // 班长确认完成 -> 待管理人员确认
    if (currentRole === 'leader' && (completionStatus === 'completed' || completionStatus === 'closed')) {
        effectiveStatus = 'waitingAdminConfirm';
    }
    
    // 管理人员确认完成 -> 待主任终审
    if (currentRole === 'manager' && (completionStatus === 'completed' || completionStatus === 'closed')) {
        effectiveStatus = 'waitingTopAdminClose';
    }

    if (editingSamplingAnomalyId) {
        // 编辑模式
        const index = samplingAnomalyData.findIndex(a => a.id === editingSamplingAnomalyId);
        if (index >= 0) {
            const originalItem = { ...samplingAnomalyData[index] };
            const originalStatus = originalItem.completionStatus;
            
            // 【权限检查】只有有权限的人才可以编辑
            if (!canManageSamplingAnomaly(originalItem)) {
                showToast('您没有权限编辑此记录', 'error');
                return;
            }
            
            // 状态（完成情况）：只有主任可以自由修改，其他人按流程
            let finalCompletionStatus = effectiveStatus;
            if (currentRole !== 'topadmin') {
                // 非主任角色：根据流程限制状态变更
                const allowedTransitions = getAllowedTransitions(currentRole, originalStatus);
                if (!allowedTransitions.includes(effectiveStatus)) {
                    finalCompletionStatus = originalStatus;
                }
            }
            
            // 创建更新对象
            const updateObj = {
                ...samplingAnomalyData[index],
                device, tag, 
                sample_name: sampleName, sampleName,
                problem_desc: problemDesc, problemDesc,
                report_time: reportTime, reportTime,
                reporter,
                rectifier, 
                completion_status: finalCompletionStatus, completionStatus: finalCompletionStatus, 
                completion_note: completionNote, completionNote,
                confirmer, remark,
                updated_at: isoNow, updateTime: isoNow,
                _sync_version: (samplingAnomalyData[index]._sync_version || 0) + 1
            };
            
            // 状态变更处理
            if (finalCompletionStatus !== originalStatus) {
                // 记录状态历史（同时设置 snake_case 和 camelCase）
                if (!updateObj.statusHistory) {
                    updateObj.statusHistory = [];
                }
                if (!updateObj.status_history) {
                    updateObj.status_history = [];
                }
                const statusRecord = {
                    timestamp: isoNow,
                    status: finalCompletionStatus,
                    changedBy: currentUser,
                    changedByRole: currentRole
                };
                // 检查是否已存在重复记录
                const existingRec = updateObj.statusHistory.find(r => 
                    r.status === statusRecord.status && 
                    r.changedBy === statusRecord.changedBy &&
                    Math.abs(new Date(r.timestamp) - new Date(statusRecord.timestamp)) < 30000
                );
                if (!existingRec) {
                    updateObj.statusHistory.push(statusRecord);
                    updateObj.status_history = [...updateObj.statusHistory];
                }
                
                // 打回处理（主任或上级角色打回下级）
                const isRejectToRectify = ['needRectify', 'leaderRectifying', 'adminRectifying', 'progress'].includes(finalCompletionStatus);
                const wasInFinalStatus = ['waitingTopAdminClose', 'waitingTopAdminClose', 'completed', 'closed'].includes(originalStatus);
                
                if (isRejectToRectify && wasInFinalStatus) {
                    // 添加打回记录（同时设置两种命名）
                    if (!updateObj.rejectRecords) {
                        updateObj.rejectRecords = [];
                    }
                    if (!updateObj.reject_records) {
                        updateObj.reject_records = [];
                    }
                    const rejectRecord = {
                        rejectTime: isoNow,
                        rejectReason: rejectReason || '未填写打回原因',
                        reformNote: reformNote || '',
                        operator: currentUser,
                        operatorRole: currentRole
                    };
                    updateObj.rejectRecords.push(rejectRecord);
                    updateObj.reject_records.push(rejectRecord);
                }
                
                // 闭环处理（主任确认闭环）
                if (finalCompletionStatus === 'closed' && currentRole === 'topadmin') {
                    // 设置删除保护
                    updateObj.protected = true;
                    // 生成处理报告
                    const report = generateSamplingAnomalyReport(updateObj);
                    updateObj.processingReport = report;
                    updateObj.processing_report = report;
                }
                
                // 完成记录处理（任何状态下只要填写了完成说明就记录）
                if (completionNote) {
                    if (!updateObj.completionRecords) {
                        updateObj.completionRecords = [];
                    }
                    if (!updateObj.completion_records) {
                        updateObj.completion_records = [];
                    }
                    
                    // 检查是否是新的完成记录（状态变化或内容变化）
                    const isNewCompletion = finalCompletionStatus !== originalStatus;
                    const lastRecord = updateObj.completionRecords.length > 0 ? updateObj.completionRecords[updateObj.completionRecords.length - 1] : null;
                    const contentChanged = lastRecord && lastRecord.completionNote !== completionNote;
                    
                    if (isNewCompletion || contentChanged || !lastRecord) {
                        const completionRecord = {
                            completionTime: isoNow,
                            completionNote: completionNote,
                            operator: currentUser,
                            operatorRole: currentRole
                        };
                        updateObj.completionRecords.push(completionRecord);
                        updateObj.completion_records.push(completionRecord);
                    }
                }
                
                // 如果是打回后重新完成，记录整改说明
                if ((finalCompletionStatus === 'completed' || finalCompletionStatus === 'closed') && 
                    updateObj.rejectRecords && updateObj.rejectRecords.length > 0 && reformNote) {
                    updateObj.rejectRecords[updateObj.rejectRecords.length - 1].reformNote = reformNote;
                    if (updateObj.reject_records && updateObj.reject_records.length > 0) {
                        updateObj.reject_records[updateObj.reject_records.length - 1].reformNote = reformNote;
                    }
                }
            }
            
            samplingAnomalyData[index] = updateObj;
            logAudit('samplingAnomaly', 'update', `编辑采样点异常: ${device} - ${tag}`);
        }
    } else {
        // 新建模式
        const newId = generateSamplingAnomalyId();
        let initialStatus = 'draft';
        let initialRectifier = rectifier;
        
        // 根据角色设置初始状态
        if (currentRole === 'leader') {
            // 班长创建：状态为班长整改中，整改负责人为班长
            initialStatus = 'leaderRectifying';
            initialRectifier = currentUser;
        } else if (currentRole === 'manager' || currentRole === 'topadmin') {
            // 管理人员创建：状态为待整改，整改负责人为提交人
            initialStatus = 'waitingRectify';
            initialRectifier = currentUser;
        } else {
            // 普通用户创建：状态为草稿（可自由编辑/删除）
            initialStatus = 'draft';
        }
        
        const newItem = {
            id: newId,
            device, tag, 
            sample_name: sampleName, 
            problem_desc: problemDesc, 
            report_time: reportTime, 
            reporter,
            rectifier: initialRectifier,
            completion_status: initialStatus,
            completion_note: completionNote,
            confirmer: confirmer,
            remark: remark,
            priority: 'medium',
            progress: 0,
            created_at: isoNow,
            updated_at: isoNow,
            _sync_version: 1,
            protected: false,
            creator_role: currentRole,      // 添加创建者角色（下划线命名）
            creatorRole: currentRole,        // 添加创建者角色（驼峰命名）
            creator: currentUser,           // 添加创建者
            // 前端兼容驼峰字段（用于本地展示）
            sampleName, problemDesc, reportTime, completionStatus: initialStatus, completionNote,
            createTime: isoNow, updateTime: isoNow,
            status_history: [{
                timestamp: isoNow,
                status: initialStatus,
                changedBy: currentUser,
                changedByRole: currentRole
            }],
            statusHistory: [{
                timestamp: isoNow,
                status: initialStatus,
                changedBy: currentUser,
                changedByRole: currentRole
            }],
            completion_records: [],
            completionRecords: [],
            reject_records: [],
            rejectRecords: [],
            escalate_records: [],
            escalateRecords: [],
            processing_report: '',
            processingReport: '',
            confirmed_by_leader: '',
            confirmedByLeader: ''
        };
        samplingAnomalyData.push(newItem);
        logAudit('samplingAnomaly', 'create', `新增采样点异常: ${device} - ${tag}`);
    }

    saveSamplingAnomalies();
    
    closeAddSamplingAnomalyModal();
    filterSamplingAnomalies();

    showToast(editingSamplingAnomalyId ? '更新成功，请手动点击"保存到云端"按钮同步数据' : '添加成功，请手动点击"保存到云端"按钮同步数据', 'success');
}

// 生成唯一ID - 使用UUID确保全局唯一性，避免多用户同时创建时ID冲突
function generateSamplingAnomalyId() {
    return 'sa_' + generateUUID();
}

/**
 * 获取采样点异常状态（兼容 camelCase 和 snake_case）
 */
function getSamplingAnomalyStatus(anomaly) {
    return anomaly.completion_status || anomaly.completionStatus || '';
}

// 权限判断函数 - 采样点异常（参考隐患排查治理模块）
function canEditSamplingAnomaly(anomaly) {
    const role = getCurrentRole();
    const currentUser = getCurrentUsername();
    const currentUserName = getUserDisplayName(currentUser);
    const status = anomaly.completion_status || anomaly.completionStatus || '';
    const reporter = anomaly.reporter;
    
    // 主任始终可以编辑
    if (role === 'topadmin') return true;
    
    // 草稿状态：创建者可以自由编辑，班长/管理员也可以编辑
    if (status === 'draft') {
        // 检查当前用户是否是创建者（支持用户名和姓名两种匹配）
        if (reporter === currentUser || reporter === currentUserName) return true;
        if (role === 'manager' || role === 'leader') return true;
        return false;
    }
    
    // 如果是管理员创建的异常（通过状态判断：waitingRectify）
    if (status === 'waitingRectify') {
        // 只有管理员和主任可以编辑
        if (role === 'manager') return true;
        return false;
    }
    
    // 待班长确认、已升级至班长或班长已确认存在状态下，班长和管理员可以编辑
    if (status === 'waitingLeaderConfirm' || 
        status === 'escalatedToLeader' || 
        status === 'leaderConfirmedExists') {
        if (role === 'leader' || role === 'manager') return true;
        return false;
    }
    
    // 待管理人员确认、已升级至管理人员状态下，管理人员可以编辑
    if (status === 'waitingAdminConfirm' || 
        status === 'escalatedToAdmin') {
        if (role === 'manager') return true;
        return false;
    }
    
    // 管理人员已确认状态下，管理人员可以编辑（升级至管理人员时不能编辑，需先确认）
    if (status === 'confirmedByAdmin') {
        if (role === 'manager') return true;
        return false;
    }
    
    // 普通用户创建者：在草稿之外的进行中/未开始状态也可以编辑自己的记录
    if (status === 'progress' || status === 'pending') {
        if (reporter === currentUser) return true;
    }
    
    // 其他状态（已完成、已闭环等）只有主任可以编辑
    return false;
}

function canDeleteSamplingAnomaly(anomaly) {
    const role = getCurrentRole();
    const currentUser = getCurrentUsername();
    const currentUserName = getUserDisplayName(currentUser);
    const status = anomaly.completion_status || anomaly.completionStatus || '';
    
    // 主任始终可以删除
    if (role === 'topadmin') return true;
    
    // 已闭环或故障不存在的记录禁止删除（除主任外）
    if (status === 'closed' || 
        status === 'notExists' || 
        status === 'notExistsByLeader') return false;
    
    // 已确认故障存在的状态禁止删除（除主任外）
    if (status === 'leaderConfirmedExists' || 
        status === 'confirmedByAdmin') return false;
    
    // 如果是管理员创建的异常（待整改状态）
    if (status === 'waitingRectify') {
        // 只有管理员可以删除
        return role === 'manager';
    }
    
    // 班长整改中状态下，只有当前整改负责人（班长）可以删除
    if (status === 'leaderRectifying') {
        return role === 'leader' && anomaly.rectifier === currentUser;
    }
    
    // 管理员整改中状态下，只有当前整改负责人（管理员）可以删除
    if (status === 'adminRectifying') {
        return role === 'manager' && anomaly.rectifier === currentUser;
    }
    
    // 待班长确认或已升级至班长状态下，班长和管理员可以删除
    if (status === 'waitingLeaderConfirm' || 
        status === 'escalatedToLeader') {
        if (role === 'leader' || role === 'manager') return true;
        return false;
    }
    
    // 已升级至管理人员状态下，管理人员可以删除
    if (status === 'escalatedToAdmin') {
        if (role === 'manager') return true;
        return false;
    }
    
    // 已升级至主任状态下，只有主任可以删除
    if (status === 'escalatedToTopAdmin') {
        return false;
    }
    
    // 其他状态（待开始、草稿、进行中等）只有创建者可以删除
    if (anomaly.reporter === currentUser || anomaly.reporter === currentUserName) {
        const deletableStatuses = ['draft', 'pending', 'progress'];
        if (deletableStatuses.includes(status)) {
            return true;
        }
    }
    
    return false;
}

function canSubmitCompletionNote(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    
    // 普通用户可以在进行中或需重新整改状态提交完成说明
    if (role === 'user' && (status === 'progress' || status === 'needRectify')) {
        return true;
    }
    
    return false;
}

function canConfirmByLeader(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    
    // 如果是管理员创建的异常，班长不能确认
    if (status === 'waitingRectify') return false;
    
    // 班长可以确认待班长确认状态的异常
    return role === 'leader' && status === 'waitingLeaderConfirm';
}

function canLeaderRectify(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    
    // 如果是管理员创建的异常，班长不能整改
    if (status === 'waitingRectify') return false;
    
    // 班长可以在已升级至班长状态或待班长确认状态点击"开始整改"
    return role === 'leader' && 
           (status === 'escalatedToLeader' || 
            status === 'waitingLeaderConfirm');
}

function canAdminRectify(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    
    // 管理员和主任可以在管理员整改中状态整改，或在已升级至管理人员状态/待管理人员确认状态点击"开始整改"
    return (role === 'manager' || role === 'topadmin') && 
           (status === 'adminRectifying' || status === 'escalatedToAdmin' || status === 'waitingAdminConfirm');
}

function canConfirmExistsByLeader(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    return role === 'leader' && status === 'escalatedToLeader';
}

function canConfirmNotExistsByLeader(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    return role === 'leader' && status === 'escalatedToLeader';
}

function canConfirmExistsByAdmin(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    
    // 管理人员可以在已升级至管理人员状态确认故障存在
    return role === 'manager' && status === 'escalatedToAdmin';
}

function canConfirmNotExistsByAdmin(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    
    // 管理人员可以在已升级至管理人员状态或待管理人员确认状态确认故障不存在
    return role === 'manager' && (status === 'escalatedToAdmin' || status === 'waitingAdminConfirm');
}

function canConfirmByAdmin(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    
    // 管理人员和主任可以在待管理人员确认状态确认整改完成
    return (role === 'manager' || role === 'topadmin') && status === 'waitingAdminConfirm';
}

function canEscalateToTopAdmin(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    
    // 管理人员可以在待管理人员确认状态升级到主任
    return role === 'manager' && status === 'waitingAdminConfirm';
}

function canRejectByAdmin(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    
    // 管理人员可以在待管理人员确认状态打回整改
    return role === 'manager' && status === 'waitingAdminConfirm';
}

function canMarkComplete(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    
    // 普通用户可以在草稿、进行中或需重新整改状态标记完成
    if (role === 'user' && (status === 'draft' || status === 'progress' || status === 'needRectify')) {
        return true;
    }
    
    // 班长可以在班长整改中状态、已升级至班长状态或班长已确认存在状态标记完成
    if (role === 'leader' && 
        (status === 'leaderRectifying' || 
         status === 'escalatedToLeader' ||
         status === 'leaderConfirmedExists')) {
        return true;
    }
    
    // 管理员可以在管理员整改中状态或管理人员已确认状态标记完成
    if (role === 'manager' && 
        (status === 'adminRectifying' || status === 'confirmedByAdmin')) {
        return true;
    }
    
    // 主任可以在任何整改状态标记完成
    if (role === 'topadmin') {
        return status === 'leaderRectifying' || status === 'adminRectifying';
    }
    
    return false;
}

function canClose(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    
    // 只有主任可以闭环
    if (role === 'topadmin') {
        // 可以在待主任闭环、已完成、已升级至主任、故障不存在或班长确认不存在状态下闭环
        return status === 'waitingTopAdminClose' || 
               status === 'completed' ||
               status === 'escalatedToTopAdmin' ||
               status === 'notExists' ||
               status === 'notExistsByLeader';
    }
    
    return false;
}

function canReject(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    
    // 只有主任可以打回
    if (role === 'topadmin') {
        // 可以在待主任闭环或已升级至主任状态下打回
        return status === 'waitingTopAdminClose' ||
               status === 'escalatedToTopAdmin';
    }
    
    return false;
}

function canEscalate(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    
    // 普通用户可以在草稿、进行中或需重新整改状态升级
    if (role === 'user' && (status === 'draft' || status === 'progress' || status === 'needRectify')) {
        return true;
    }
    
    // 班长可以在待班长确认、班长整改中、已升级至班长或班长已确认存在状态升级到管理员
    if (role === 'leader' && 
        (status === 'waitingLeaderConfirm' || 
         status === 'leaderRectifying' ||
         status === 'escalatedToLeader' ||
         status === 'leaderConfirmedExists')) {
        return true;
    }
    
    // 管理员可以在管理人员已确认或管理员整改中状态升级到主任
    if (role === 'manager' && (status === 'adminRectifying' || status === 'confirmedByAdmin')) {
        return true;
    }
    
    return false;
}

function canConfirmNotExistsByLeader(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    // 班长可以在待班长确认或已升级至班长状态确认故障不存在
    return role === 'leader' && 
           (status === 'waitingLeaderConfirm' || 
            status === 'escalatedToLeader');
}

function canAssignAdmin(anomaly) {
    const role = getCurrentRole();
    const status = getSamplingAnomalyStatus(anomaly);
    
    // 主任可以指派管理员处理
    return role === 'topadmin' && status === 'needRectify';
}

// 打开详情模态框
function openSamplingAnomalyDetailModal(anomalyId) {
    const item = samplingAnomalyData.find(a => a.id === anomalyId);
    if (!item) return;

    const modal = safeGetElement('samplingAnomalyDetailModal');
    const content = safeGetElement('samplingAnomalyDetailContent');
    const actions = safeGetElement('samplingAnomalyDetailActions');
    if (!modal || !content || !actions) return;

    const statusText = getSamplingAnomalyStatusText(item.completion_status);
    const statusClass = getSamplingAnomalyStatusClass(item.completion_status);

    content.innerHTML = `
        <div class="detail-section">
            <div class="detail-header">
                <span class="detail-icon">🔬</span>
                <h3>采样点异常信息</h3>
            </div>
            
            <div class="detail-grid">
                <div class="detail-card detail-card-primary">
                    <div class="detail-card-label">装置 - 位号</div>
                    <div class="detail-card-value">${escapeHtml(item.device || '')} - ${escapeHtml(item.tag || '')}</div>
                </div>
                
                <div class="detail-card">
                    <div class="detail-card-label">样品名称</div>
                    <div class="detail-card-value">
                        <span class="assignee-badge">🧪 ${escapeHtml(item.sample_name || '-')}</span>
                    </div>
                </div>
                
                <div class="detail-card">
                    <div class="detail-card-label">完成情况</div>
                    <div class="detail-card-value">
                        <span class="status-badge status-${statusClass}">${statusText}</span>
                    </div>
                </div>
                
                <div class="detail-card">
                    <div class="detail-card-label">提报人</div>
                    <div class="detail-card-value">
                        <span class="assignee-badge">👤 ${getUserWithRoleDisplay(item.reporter)}</span>
                    </div>
                </div>
            </div>
            
            <div class="detail-card detail-card-full">
                <div class="detail-card-label">问题描述</div>
                <div class="detail-card-value">${escapeHtml(item.problem_desc) || '暂无描述'}</div>
            </div>
            
            <div class="detail-grid">
                <div class="detail-card">
                    <div class="detail-card-label">提报时间</div>
                    <div class="detail-card-value">
                        <span class="time-badge"> ${formatDateTime(item.report_time)}</span>
                    </div>
                </div>
                
                <div class="detail-card">
                    <div class="detail-card-label">整改负责人</div>
                    <div class="detail-card-value">
                        <span class="assignee-badge">👷 ${getUserWithRoleDisplay(item.rectifier)}</span>
                    </div>
                </div>
            </div>
            
            ${(item.completionRecords && item.completionRecords.length > 0) ? `
            <div class="detail-card" style="border-left: 4px solid #4CAF50; background: #E8F5E9;">
                <div class="detail-card-label">✅ 整改完成情况记录</div>
                <div class="detail-card-value">
                    ${item.completionRecords.map((record, index) => {
                        const displayName = record.operator ? getUserDisplayName(record.operator) : '';
                        const roleText = (record.operator_role || record.operatorRole) ? getHazardRoleText(record.operator_role || record.operatorRole) : '';
                        const operatorInfo = roleText ? `${displayName}(${roleText})` : displayName;
                        return `
                        <div style="border-bottom: 1px solid #C8E6C9; padding: 8px 0; margin-bottom: 8px;">
                            <span style="font-size: 12px; color: #666;">【第${index + 1}次${operatorInfo ? ` ${operatorInfo}` : ''}】${formatDateTime(record.completionTime || record.completion_time || item.update_time || item.created_at)}</span>
                            <div style="margin-top: 5px; font-size: 14px;">整改说明：${escapeHtml(record.completion_note || record.completionNote || '')}</div>
                        </div>
                        `;
                    }).join('')}
                </div>
            </div>
            ` : (item.completion_note ? `
            <div class="detail-card" style="border-left: 4px solid #4CAF50; background: #E8F5E9;">
                <div class="detail-card-label">✅ 完成情况说明</div>
                <div class="detail-card-value">
                    <div style="border-bottom: 1px solid #C8E6C9; padding: 8px 0; margin-bottom: 8px;">
                        <span style="font-size: 12px; color: #666;">【第1次】${formatDateTime(item.updated_at || item.created_at)}</span>
                        <div style="margin-top: 5px; font-size: 14px;">
                            <strong>${escapeHtml(item.completion_note)}</strong>
                        </div>
                        ${item.reporter ? `<div style="font-size: 12px; color: #888; margin-top: 3px;">操作人：${getUserWithRoleDisplay(item.reporter)}</div>` : ''}
                    </div>
                </div>
            </div>
            ` : '')}
            
            ${item.confirmer ? `
            <div class="detail-card">
                <div class="detail-card-label">装置确认人</div>
                <div class="detail-card-value">
                    <span class="assignee-badge">👁️ ${getUserWithRoleDisplay(item.confirmer)}</span>
                </div>
            </div>
            ` : ''}
            
            ${item.confirmedByLeader ? `
            <div class="detail-card">
                <div class="detail-card-label">故障确认人</div>
                <div class="detail-card-value">
                    <span class="assignee-badge">👤 ${getUserWithRoleDisplay(item.confirmedByLeader)}</span>
                </div>
            </div>
            ` : ''}
            
            ${(item.rejectRecords && item.rejectRecords.length > 0) ? `
            <div class="detail-card detail-card-danger">
                <div class="detail-card-label">❌ 打回情况说明记录</div>
                <div class="detail-card-value">
                    ${item.rejectRecords.map((record, index) => {
                        const displayName = record.operator ? getUserDisplayName(record.operator) : '';
                        const roleText = record.operatorRole ? getHazardRoleText(record.operatorRole) : '';
                        const operatorInfo = roleText ? `${displayName}(${roleText})` : displayName;
                        return `
                        <div style="border-bottom: 1px solid #FFCDD2; padding: 8px 0; margin-bottom: 8px;">
                            <span style="font-size: 12px; color: #666;">【第${index + 1}次${operatorInfo ? ` ${operatorInfo}` : ''}】${formatDateTime(record.rejectTime)}</span>
                            <div style="margin-top: 5px; font-size: 14px;">打回原因：${escapeHtml(record.rejectReason)}</div>
                            ${record.reformNote ? `<div style="font-size: 14px; margin-top: 3px;">整改说明：${escapeHtml(record.reformNote)}</div>` : ''}
                        </div>
                        `;
                    }).join('')}
                </div>
            </div>
            ` : ''}
            
            ${(item.escalateRecords && item.escalateRecords.length > 0) ? `
            <div class="detail-card" style="border-left: 4px solid #FF9800; background: #FFF8E1;">
                <div class="detail-card-label">⬆️ 升级处理记录</div>
                <div class="detail-card-value">
                    ${item.escalateRecords.map((record, index) => {
                        const displayName = record.operator ? getUserDisplayName(record.operator) : '';
                        const roleText = record.operatorRole ? getHazardRoleText(record.operatorRole) : '';
                        const operatorInfo = roleText ? `${displayName}(${roleText})` : displayName;
                        return `
                        <div style="border-bottom: 1px solid #FFECB3; padding: 8px 0; margin-bottom: 8px;">
                            <span style="font-size: 12px; color: #666;">【第${index + 1}次${operatorInfo ? ` ${operatorInfo}` : ''}】${formatDateTime(record.time)}</span>
                            <div style="margin-top: 5px; font-size: 14px;">升级至：${getSamplingAnomalyStatusText(record.targetRole)}</div>
                            <div style="font-size: 14px;">当前整改情况：${escapeHtml(record.currentProgress)}</div>
                            <div style="font-size: 14px;">无法完成原因：${escapeHtml(record.reason)}</div>
                            <div style="font-size: 14px;">下一步整改建议：${escapeHtml(record.nextStepAdvice)}</div>
                        </div>
                        `;
                    }).join('')}
                </div>
            </div>
            ` : ''}
            
            ${(item.statusHistory && item.statusHistory.length > 0) ? `
            <div class="detail-card" style="border-left: 4px solid #2196F3; background: #E3F2FD;">
                <div class="detail-card-label">🔄 状态变更记录</div>
                <div class="detail-card-value">
                    ${item.statusHistory.map((record, index) => {
                        const displayName = record.changedBy ? getUserDisplayName(record.changedBy) : '';
                        const roleText = record.changedByRole ? getHazardRoleText(record.changedByRole) : '';
                        const operatorInfo = roleText ? `${displayName}(${roleText})` : displayName;
                        const fromStatus = record.previousStatus || record.previous_status;
                        return `
                        <div style="border-bottom: 1px solid #BBDEFB; padding: 8px 0; margin-bottom: 8px;">
                            <span style="font-size: 12px; color: #666;">【第${index + 1}次】${formatDateTime(record.timestamp)}</span>
                            ${operatorInfo ? `<span style="font-size: 12px; color: #666; margin-left: 10px;">操作人：${operatorInfo}</span>` : ''}
                            <div style="margin-top: 5px; font-size: 14px;">
                                ${fromStatus ? `<span style="color: #9E9E9E;">${getSamplingAnomalyStatusText(fromStatus)}</span> <span style="margin: 0 5px;">→</span> ` : ''}
                                <strong>${getSamplingAnomalyStatusText(record.status)}</strong>
                            </div>
                        </div>
                        `;
                    }).join('')}
                </div>
            </div>
            ` : ''}
            
            ${item.remark ? `
            <div class="detail-card detail-card-full">
                <div class="detail-card-label">备注</div>
                <div class="detail-card-value">${escapeHtml(item.remark)}</div>
            </div>
            ` : ''}
            
            <div class="detail-footer">
                <div class="detail-meta-item">
                    <span class="meta-label">创建时间</span>
                    <span class="meta-value">${formatDateTime(item.createTime)}</span>
                </div>
                <div class="detail-meta-item">
                    <span class="meta-label">最后更新</span>
                    <span class="meta-value">${formatDateTime(item.updateTime)}</span>
                </div>
            </div>
        </div>
    `;

    // 根据状态显示不同的按钮
    let actionButtons = '';
    const currentRole = getCurrentRole();
    
    // 主任在任何状态下都有全部操作权限（主任是最高层，不需要升级处理按钮）
    if (currentRole === 'topadmin') {
        actionButtons = `
            <button class="btn btn-primary btn-sm" onclick="openAddSamplingAnomalyModal('${item.id}')">编辑故障</button>
            <button class="btn btn-success btn-sm" onclick="markSamplingAnomalyComplete('${item.id}')">标记完成</button>
            <button class="btn btn-info btn-sm" onclick="closeSamplingAnomalyByTopAdmin('${item.id}')">确认闭环</button>
            <button class="btn btn-warning btn-sm" onclick="rejectSamplingAnomalyToLeader('${item.id}')">打回至班长</button>
            <button class="btn btn-danger btn-sm" onclick="rejectSamplingAnomalyToAdmin('${item.id}')">打回至管理人员</button>
            <button class="btn btn-danger btn-sm" onclick="deleteSamplingAnomaly('${item.id}')">删除故障</button>
        `;
    } else if (item.completionStatus === 'draft') {
        // 草稿状态：普通用户有编辑、标记完成、升级处理、删除4个按钮
        actionButtons = `
            ${canEditSamplingAnomaly(item) ? `<button class="btn btn-primary btn-sm" onclick="openAddSamplingAnomalyModal('${item.id}')">编辑异常</button>` : ''}
            ${canMarkComplete(item) ? `<button class="btn btn-success btn-sm" onclick="markSamplingAnomalyComplete('${item.id}')">标记完成</button>` : ''}
            ${canEscalate(item) ? `<button class="btn btn-warning btn-sm" onclick="escalateSamplingAnomalyAction('${item.id}')">升级处理</button>` : ''}
            ${canDeleteSamplingAnomaly(item) ? `<button class="btn btn-danger btn-sm" onclick="deleteSamplingAnomaly('${item.id}')">删除异常</button>` : ''}
        `;
    } else if (item.completionStatus === 'escalatedToTopAdmin') {
        // 已升级至主任状态（只有主任可以操作）
        actionButtons = `
            ${canEditSamplingAnomaly(item) ? `<button class="btn btn-primary btn-sm" onclick="openAddSamplingAnomalyModal('${item.id}')">编辑故障</button>` : ''}
            ${canClose(item) ? `<button class="btn btn-info btn-sm" onclick="closeSamplingAnomalyByTopAdmin('${item.id}')">确认闭环</button>` : ''}
            ${canReject(item) ? `<button class="btn btn-warning btn-sm" onclick="rejectSamplingAnomalyToLeader('${item.id}')">打回至班长</button><button class="btn btn-danger btn-sm" onclick="rejectSamplingAnomalyToAdmin('${item.id}')">打回至管理人员</button>` : ''}
            ${canDeleteSamplingAnomaly(item) ? `<button class="btn btn-danger btn-sm" onclick="deleteSamplingAnomaly('${item.id}')">删除故障</button>` : ''}
        `;
    } else if (item.completionStatus === 'escalatedToAdmin') {
        // 已升级至管理人员状态（管理人员确认故障是否存在或开始整改）
        actionButtons = `
            ${canAdminRectify(item) ? `<button class="btn btn-info" onclick="startAdminRectify('${item.id}')">开始整改</button>` : ''}
            ${canConfirmExistsByAdmin(item) ? `<button class="btn btn-success" onclick="confirmSamplingAnomalyExists('${item.id}')">确认故障存在</button>` : ''}
            ${canConfirmNotExistsByAdmin(item) ? `<button class="btn btn-danger" onclick="confirmSamplingAnomalyNotExists('${item.id}')">故障不存在</button>` : ''}
        `;
    } else if (item.completionStatus === 'escalatedToLeader') {
        // 已升级至班长状态（班长确认故障是否存在或开始整改）
        actionButtons = `
            ${canLeaderRectify(item) ? `<button class="btn btn-info" onclick="startLeaderRectify('${item.id}')">开始整改</button>` : ''}
            ${canConfirmExistsByLeader(item) ? `<button class="btn btn-success" onclick="confirmSamplingAnomalyExistsByLeader('${item.id}')">确认故障存在</button>` : ''}
            ${canConfirmNotExistsByLeader(item) ? `<button class="btn btn-danger" onclick="confirmSamplingAnomalyNotExistsByLeader('${item.id}')">故障不存在</button>` : ''}
        `;
    } else if (item.completionStatus === 'waitingLeaderConfirm') {
        // 待班长确认状态（班长操作）
        actionButtons = `
            ${canEditSamplingAnomaly(item) ? `<button class="btn btn-primary btn-xs" onclick="openAddSamplingAnomalyModal('${item.id}')">编辑</button>` : ''}
            ${canConfirmByLeader(item) ? `<button class="btn btn-success btn-xs" onclick="confirmSamplingAnomalyByLeader('${item.id}')">确认整改完成</button>` : ''}
            ${canLeaderRectify(item) ? `<button class="btn btn-info btn-xs" onclick="startLeaderRectify('${item.id}')">开始整改</button>` : ''}
            ${canEscalate(item) ? `<button class="btn btn-warning btn-xs" onclick="escalateSamplingAnomalyAction('${item.id}')">升级处理</button>` : ''}
            ${canConfirmNotExistsByLeader(item) ? `<button class="btn btn-danger btn-xs" onclick="confirmSamplingAnomalyNotExistsByLeader('${item.id}')">故障不存在</button>` : ''}
            ${canLeaderRectify(item) ? `<button class="btn btn-warning btn-xs" onclick="rejectSamplingAnomalyByLeader('${item.id}')">未完成整改</button>` : ''}
        `;
    } else if (item.completionStatus === 'needRectify') {
        // 需重新整改状态（普通用户操作）
        actionButtons = `
            ${canEditSamplingAnomaly(item) ? `<button class="btn btn-primary btn-xs" onclick="openAddSamplingAnomalyModal('${item.id}')">编辑</button>` : ''}
            ${canMarkComplete(item) ? `<button class="btn btn-success btn-xs" onclick="markSamplingAnomalyComplete('${item.id}')">标记完成</button>` : ''}
            ${canEscalate(item) ? `<button class="btn btn-warning btn-xs" onclick="escalateSamplingAnomalyAction('${item.id}')">升级处理</button>` : ''}
        `;
    } else if (item.completionStatus === 'waitingAdminConfirm') {
        // 待管理人员确认状态（管理人员操作）
        actionButtons = `
            ${canEditSamplingAnomaly(item) ? `<button class="btn btn-primary btn-xs" onclick="openAddSamplingAnomalyModal('${item.id}')">编辑</button>` : ''}
            ${canConfirmByAdmin(item) ? `<button class="btn btn-success btn-xs" onclick="confirmSamplingAnomalyByAdmin('${item.id}')">确认整改完成</button>` : ''}
            ${canAdminRectify(item) ? `<button class="btn btn-info btn-xs" onclick="startAdminRectify('${item.id}')">开始整改</button>` : ''}
            ${canEscalateToTopAdmin(item) ? `<button class="btn btn-warning btn-xs" onclick="escalateSamplingAnomalyAction('${item.id}')">升级处理</button>` : ''}
            ${canConfirmNotExistsByAdmin(item) ? `<button class="btn btn-danger btn-xs" onclick="confirmSamplingAnomalyNotExists('${item.id}')">故障不存在</button>` : ''}
            ${canRejectByAdmin(item) ? `<button class="btn btn-warning btn-xs" onclick="rejectSamplingAnomalyByAdmin('${item.id}')">未完成整改</button>` : ''}
        `;
    } else if (item.completionStatus === 'leaderConfirmedExists') {
        // 班长已确认故障存在（不能删除）
        actionButtons = `
            ${canEditSamplingAnomaly(item) ? `<button class="btn btn-primary" onclick="openAddSamplingAnomalyModal('${item.id}')">编辑故障</button>` : ''}
            ${canMarkComplete(item) ? `<button class="btn btn-success" onclick="markSamplingAnomalyComplete('${item.id}')">标记完成</button>` : ''}
            ${canEscalate(item) ? `<button class="btn btn-warning" onclick="escalateSamplingAnomalyAction('${item.id}')">升级处理</button>` : ''}
        `;
    } else if (item.completionStatus === 'notExistsByLeader') {
        // 班长确认故障不存在（只有主任可以操作）
        actionButtons = `
            ${canEditSamplingAnomaly(item) ? `<button class="btn btn-primary" onclick="openAddSamplingAnomalyModal('${item.id}')">编辑故障</button>` : ''}
            ${canClose(item) ? `<button class="btn btn-info" onclick="closeSamplingAnomalyByTopAdmin('${item.id}')">确认闭环</button>` : ''}
            ${canDeleteSamplingAnomaly(item) ? `<button class="btn btn-danger" onclick="deleteSamplingAnomaly('${item.id}')">删除故障</button>` : ''}
        `;
    } else if (item.completionStatus === 'confirmedByAdmin') {
        // 管理人员已确认故障存在
        actionButtons = `
            ${canEditSamplingAnomaly(item) ? `<button class="btn btn-primary" onclick="openAddSamplingAnomalyModal('${item.id}')">编辑故障</button>` : ''}
            ${canMarkComplete(item) ? `<button class="btn btn-success" onclick="markSamplingAnomalyComplete('${item.id}')">标记完成</button>` : ''}
            ${canEscalate(item) ? `<button class="btn btn-warning" onclick="escalateSamplingAnomalyAction('${item.id}')">无法完成</button>` : ''}
        `;
    } else if (item.completionStatus === 'leaderRectifying') {
        // 班长整改中状态
        actionButtons = `
            ${canEditSamplingAnomaly(item) ? `<button class="btn btn-primary" onclick="openAddSamplingAnomalyModal('${item.id}')">编辑故障</button>` : ''}
            ${canMarkComplete(item) ? `<button class="btn btn-success" onclick="markSamplingAnomalyComplete('${item.id}')">标记完成</button>` : ''}
            ${canEscalate(item) ? `<button class="btn btn-warning" onclick="escalateSamplingAnomalyAction('${item.id}')">升级处理</button>` : ''}
            ${canDeleteSamplingAnomaly(item) ? `<button class="btn btn-danger" onclick="deleteSamplingAnomaly('${item.id}')">删除故障</button>` : ''}
        `;
    } else if (item.completionStatus === 'adminRectifying') {
        // 管理员整改中状态
        actionButtons = `
            ${canEditSamplingAnomaly(item) ? `<button class="btn btn-primary" onclick="openAddSamplingAnomalyModal('${item.id}')">编辑故障</button>` : ''}
            ${canMarkComplete(item) ? `<button class="btn btn-success" onclick="markSamplingAnomalyComplete('${item.id}')">标记完成</button>` : ''}
            ${canEscalate(item) ? `<button class="btn btn-warning" onclick="escalateSamplingAnomalyAction('${item.id}')">升级处理</button>` : ''}
            ${canDeleteSamplingAnomaly(item) ? `<button class="btn btn-danger" onclick="deleteSamplingAnomaly('${item.id}')">删除故障</button>` : ''}
        `;
    } else if (item.completionStatus === 'notExists') {
        // 故障不存在状态（只有主任可以操作）
        actionButtons = `
            ${canEditSamplingAnomaly(item) ? `<button class="btn btn-primary btn-sm" onclick="openAddSamplingAnomalyModal('${item.id}')">编辑故障</button>` : ''}
            ${canClose(item) ? `<button class="btn btn-info btn-sm" onclick="closeSamplingAnomalyByTopAdmin('${item.id}')">确认闭环</button>` : ''}
            ${canDeleteSamplingAnomaly(item) ? `<button class="btn btn-danger btn-sm" onclick="deleteSamplingAnomaly('${item.id}')">删除故障</button>` : ''}
        `;
    } else {
        // 其他状态
        actionButtons = `
            ${canEditSamplingAnomaly(item) ? `<button class="btn btn-primary" onclick="openAddSamplingAnomalyModal('${item.id}')">编辑</button>` : ''}
            ${canConfirmByLeader(item) ? `<button class="btn btn-warning" onclick="confirmSamplingAnomalyByLeader('${item.id}')">确认整改完成</button>` : ''}
            ${canClose(item) ? `<button class="btn btn-info" onclick="closeSamplingAnomalyByTopAdmin('${item.id}')">确认闭环</button>` : ''}
            ${canReject(item) ? `<button class="btn btn-warning" onclick="rejectSamplingAnomalyToLeader('${item.id}')">打回至班长</button><button class="btn btn-danger" onclick="rejectSamplingAnomalyToAdmin('${item.id}')">打回至管理人员</button>` : ''}
            ${canMarkComplete(item) ? `<button class="btn btn-success" onclick="markSamplingAnomalyComplete('${item.id}')">标记完成</button>` : ''}
            ${canEscalate(item) ? `<button class="btn btn-warning" onclick="escalateSamplingAnomalyAction('${item.id}')">升级处理</button>` : ''}
            ${canLeaderRectify(item) ? `<button class="btn btn-info" onclick="startLeaderRectify('${item.id}')">开始整改</button>` : ''}
            ${canAdminRectify(item) ? `<button class="btn btn-info" onclick="startAdminRectify('${item.id}')">开始整改</button>` : ''}
            ${canAssignAdmin(item) ? `<button class="btn btn-info" onclick="assignSamplingAnomalyToAdmin('${item.id}')">指派管理人员</button>` : ''}
            ${canDeleteSamplingAnomaly(item) ? `<button class="btn btn-danger" onclick="deleteSamplingAnomaly('${item.id}')">删除</button>` : ''}
        `;
    }
    
    actions.innerHTML = `
        <div class="detail-actions">
            <div class="detail-actions-group">
                ${actionButtons}
            </div>
            <button class="btn btn-secondary" onclick="closeSamplingAnomalyDetailModal()">返回</button>
        </div>
    `;
    
    // 【关键修复】给所有按钮添加防重复点击保护
    // 点击一次后禁用所有按钮，防止重复点击导致重复记录
    const anomalyActionButtons = actions.querySelectorAll('.detail-actions .btn:not(.btn-secondary)');
    anomalyActionButtons.forEach(btn => {
        const originalOnClick = btn.getAttribute('onclick');
        if (originalOnClick) {
            btn.setAttribute('onclick', `
                if (this.disabled) return false;
                const _allBtns = this.parentElement.querySelectorAll('.btn:not(.btn-secondary)');
                _allBtns.forEach(b => { b.disabled = true; b.style.opacity = '0.5'; b.style.cursor = 'not-allowed'; });
                ${originalOnClick}
            `);
        }
    });

    safeSetDisplay('samplingAnomalyDetailModal', 'block');
    content.scrollTop = 0;
}

// 班长确认整改完成
function confirmSamplingAnomalyByLeader(anomalyId) {
    const index = samplingAnomalyData.findIndex(a => a.id === anomalyId);
    if (index === -1) return;
    
    const anomaly = samplingAnomalyData[index];
    const now = new Date().toLocaleString('zh-CN');
    const currentUser = getCurrentUserInfo();
    const currentRole = 'leader';
    const currentStatus = anomaly.completion_status;
    
    // 班长确认后转到待管理人员确认状态
    anomaly.completion_status = 'waitingAdminConfirm';
    anomaly.completionStatus = 'waitingAdminConfirm';
    anomaly.update_time = now;
    anomaly.updated_at = new Date().toISOString();
    anomaly._sync_version = (anomaly._sync_version || 0) + 1;
    anomaly.rectifier = currentUser.username || currentUser.name || '未知';
    
    // 添加整改完成记录（参考隐患排查治理模块）
    if (!anomaly.completionRecords || !Array.isArray(anomaly.completionRecords)) {
        if (anomaly.completion_records && Array.isArray(anomaly.completion_records)) {
            anomaly.completionRecords = [...anomaly.completion_records];
        } else {
            anomaly.completionRecords = [];
        }
    }
    
    const completionRec = {
        id: `completion_${Date.now()}`,
        completionTime: now,
        completionNote: '班长确认故障已整改',
        operator: currentUser.username || currentUser.name || '未知',
        operatorRole: currentRole,
        operator_role: currentRole,
        completion_time: now,
        completion_note: '班长确认故障已整改',
        timestamp: Date.now()
    };
    
    anomaly.completionRecords.push(completionRec);
    anomaly.completion_records = [...anomaly.completionRecords];
    
    // 记录状态变更
    const statusRecord = {
        timestamp: new Date().toISOString(),
        status: 'waitingAdminConfirm',
        previousStatus: currentStatus,
        previous_status: currentStatus,
        changedBy: currentUser.username || currentUser.name || '未知',
        changedByRole: 'leader',
        changed_by: currentUser.username || currentUser.name || '未知',
        changed_by_role: 'leader'
    };
    addStatusRecordSafely(anomaly, statusRecord);

    saveSamplingAnomalies();
    closeSamplingAnomalyDetailModal();
    filterSamplingAnomalies();
    showToast('已完成整改，等待管理人员确认', 'success');
}

