// 管理人员打回整改
function rejectSamplingAnomalyByAdmin(anomalyId) {
    const anomaly = samplingAnomalyData.find(a => a.id === anomalyId);
    if (!anomaly) return;
    
    const rejectReason = prompt('请填写打回原因：');
    if (!rejectReason || rejectReason.trim() === '') {
        showToast('请填写打回原因', 'warning');
        return;
    }
    
    const currentUser = getCurrentUsername();
    const isoNow = new Date().toISOString();
    
    anomaly.completion_status = 'leaderRectifying';
    anomaly.completionStatus = 'leaderRectifying';  // 同步设置驼峰命名
    anomaly.update_time = new Date().toLocaleString('zh-CN');
    anomaly.updated_at = isoNow;  // 同步设置ISO格式
    anomaly.rectifier = currentUser;
    
    // 记录打回历史（参考版本9.0：优先使用驼峰命名）
    if (!anomaly.rejectRecords || !Array.isArray(anomaly.rejectRecords)) {
        if (anomaly.reject_records && Array.isArray(anomaly.reject_records)) {
            anomaly.rejectRecords = [...anomaly.reject_records];
        } else {
            anomaly.rejectRecords = [];
        }
    }
    
    const rejectRec = {
        reject_time: isoNow,
        reject_reason: rejectReason.trim(),
        reform_note: '',
        operator: currentUser,
        operator_role: 'manager',
        rejectTime: isoNow,
        rejectReason: rejectReason.trim(),
        reformNote: '',
        operatorRole: 'manager'
    };
    
    // 参考版本9.0：只使用 rejectRecords 数组
    anomaly.rejectRecords.push(rejectRec);
    
    // 同步到下划线版本（用于云端存储）
    anomaly.reject_records = [...anomaly.rejectRecords];
    
    // 记录状态变更（参考版本9.0：优先使用驼峰命名）
    if (!anomaly.statusHistory || !Array.isArray(anomaly.statusHistory)) {
        if (anomaly.status_history && Array.isArray(anomaly.status_history)) {
            anomaly.statusHistory = [...anomaly.status_history];
        } else {
            anomaly.statusHistory = [];
        }
    }
    const statusRecord = {
        timestamp: isoNow,
        status: 'leaderRectifying',
        changed_by: currentUser,
        changed_by_role: 'manager',
        changedBy: currentUser,
        changedByRole: 'manager'
    };
    addStatusRecordSafely(anomaly, statusRecord);
    
    saveSamplingAnomalies();
    closeSamplingAnomalyDetailModal();
    filterSamplingAnomalies();
    showToast('已打回整改至班长', 'success');
}

// 主任确认闭环
function closeSamplingAnomalyByTopAdmin(anomalyId) {
    const anomaly = samplingAnomalyData.find(a => a.id === anomalyId);
    if (!anomaly) return;
    
    const currentUser = getCurrentUsername();
    const isoNow = new Date().toISOString();
    
    anomaly.completion_status = 'closed';
    anomaly.completionStatus = 'closed';  // 同步设置驼峰命名
    anomaly.protected = true;
    anomaly.update_time = new Date().toLocaleString('zh-CN');
    anomaly.updated_at = isoNow;  // 同步设置ISO格式
    
    const statusRecord = {
        timestamp: isoNow,
        status: 'closed',
        changed_by: currentUser,
        changed_by_role: 'topadmin',
        changedBy: currentUser,
        changedByRole: 'topadmin'
    };
    addStatusRecordSafely(anomaly, statusRecord);
    
    // 添加确认整改完成记录（主任闭环）
    if (!anomaly.confirm_records) anomaly.confirm_records = [];
    if (!anomaly.confirmRecords) anomaly.confirmRecords = [];
    const confirmRecordData = {
        time: isoNow,
        confirm_time: isoNow,
        note: '主任确认闭环完成',
        confirm_note: '主任确认闭环完成',
        operator: currentUser,
        operatorRole: 'topadmin',
        operator_role: 'topadmin'
    };
    anomaly.confirm_records.push(confirmRecordData);
    anomaly.confirmRecords = [...anomaly.confirm_records];
    
    const report = generateSamplingAnomalyReport(anomaly);
    anomaly.processing_report = report;
    anomaly.processingReport = report;  // 同步设置驼峰命名
    
    saveSamplingAnomalies();
    closeSamplingAnomalyDetailModal();
    filterSamplingAnomalies();
    showToast('已闭环，记录已保护', 'success');
}

