// 标记完成
function markSamplingAnomalyComplete(anomalyId) {
    const note = prompt('请输入整改完成情况说明：');
    if (!note) return;
    
    const confirmer = prompt('请输入装置确认人：');
    if (!confirmer) return;
    
    const anomaly = samplingAnomalyData.find(a => a.id === anomalyId);
    if (!anomaly) return;
    
    const currentRole = getCurrentRole();
    const currentUser = getCurrentUsername();
    const isoNow = new Date().toISOString();
    
    // 根据角色确定目标状态（借鉴隐患排查治理流程）
    let newStatus;
    if (currentRole === 'user') {
        // 普通用户提交完成 -> 待班长确认
        newStatus = 'waitingLeaderConfirm';
    } else if (currentRole === 'leader') {
        // 班长确认完成 -> 待管理人员确认
        newStatus = 'waitingAdminConfirm';
    } else if (currentRole === 'manager') {
        // 管理人员确认完成 -> 待主任终审
        newStatus = 'waitingTopAdminClose';
    } else if (currentRole === 'topadmin') {
        // 主任确认完成 -> 已闭环
        newStatus = 'closed';
    } else {
        // 默认
        newStatus = 'waitingLeaderConfirm';
    }
    
    const oldStatus = anomaly.completion_status;
    anomaly.completion_status = newStatus;
    anomaly.completion_note = note;
    anomaly.completionNote = note;
    anomaly.completionStatus = newStatus;
    anomaly.confirmer = confirmer;  // 保存装置确认人
    anomaly.updated_at = isoNow;
    anomaly.update_time = isoNow;
    anomaly.updateTime = isoNow;
    
    // 记录完成情况（参考版本9.0：优先使用驼峰命名）
    if (!anomaly.completionRecords || !Array.isArray(anomaly.completionRecords)) {
        // 如果下划线版本有数据，先迁移到驼峰版本
        if (anomaly.completion_records && Array.isArray(anomaly.completion_records)) {
            anomaly.completionRecords = [...anomaly.completion_records];
        } else {
            anomaly.completionRecords = [];
        }
    }
    
    const completionRecord = {
        completionTime: isoNow,
        completionNote: note,
        completion_time: isoNow,
        completion_note: note,
        operator: currentUser,
        operatorRole: currentRole,
        operator_role: currentRole
    };
    
    // 参考版本9.0：只使用 completionRecords 数组
    anomaly.completionRecords.push(completionRecord);
    
    // 同步到下划线版本（用于云端存储）
    anomaly.completion_records = [...anomaly.completionRecords];
    
    // 添加确认整改完成记录
    if (!anomaly.confirm_records) anomaly.confirm_records = [];
    if (!anomaly.confirmRecords) anomaly.confirmRecords = [];
    const confirmRecordData = {
        time: isoNow,
        confirm_time: isoNow,
        note: note,
        confirm_note: note,
        operator: currentUser,
        operatorRole: currentRole,
        operator_role: currentRole
    };
    anomaly.confirm_records.push(confirmRecordData);
    anomaly.confirmRecords = [...anomaly.confirm_records];
    
    // 记录状态变更（同时设置 camelCase 和 snake_case）
    if (!anomaly.status_history) anomaly.status_history = [];
    if (!anomaly.statusHistory) anomaly.statusHistory = [];
    const statusRecord = {
        timestamp: isoNow,
        status: newStatus,
        changedBy: currentUser,
        changedByRole: currentRole,
        changed_by: currentUser,
        changed_by_role: currentRole,
        previousStatus: oldStatus,
        previous_status: oldStatus
    };
    addStatusRecordSafely(anomaly, statusRecord);
    
    saveSamplingAnomalies();
    closeSamplingAnomalyDetailModal();
    filterSamplingAnomalies();
    showToast('已标记完成，请手动点击"保存到云端"按钮同步数据', 'success');
}

