// 升级处理操作
let pendingEscalateAnomalyId = null;

function escalateSamplingAnomalyAction(anomalyId) {
    const role = getCurrentRole();
    const anomaly = samplingAnomalyData.find(a => a.id === anomalyId);
    const currentStatus = anomaly ? getSamplingAnomalyStatus(anomaly) : '';
    
    // 普通用户升级处理
    if (role === 'user') {
        // 草稿状态下升级 → 待班长确认（提交给班长审核）
        let targetRole = currentStatus === 'draft' ? 'waitingLeaderConfirm' : 'escalatedToLeader';
        escalateSamplingAnomaly(anomalyId, targetRole);
        closeSamplingAnomalyDetailModal();
        filterSamplingAnomalies();
        showToast(`已${currentStatus === 'draft' ? '提交审核，待班长确认' : `升级至${getSamplingAnomalyStatusText(targetRole)}`}`, 'success');
        return;
    }
    
    // 班长和管理人员需要填写表单
    pendingEscalateAnomalyId = anomalyId;
    
    safeGetElement('samplingAnomalyEscalateProgress').value = '';
    safeGetElement('samplingAnomalyEscalateReason').value = '';
    safeGetElement('samplingAnomalyEscalateSuggestion').value = '';
    
    safeSetDisplay('samplingAnomalyEscalateModal', 'block');
}

function closeSamplingAnomalyEscalateModal() {
    pendingEscalateAnomalyId = null;
    safeSetDisplay('samplingAnomalyEscalateModal', 'none');
}

function confirmSamplingAnomalyEscalate() {
    if (!pendingEscalateAnomalyId) return;
    
    const progress = safeGetElement('samplingAnomalyEscalateProgress').value.trim();
    const reason = safeGetElement('samplingAnomalyEscalateReason').value.trim();
    const suggestion = safeGetElement('samplingAnomalyEscalateSuggestion').value.trim();
    
    if (!progress) {
        showToast('请填写故障当前整改情况', 'warning');
        return;
    }
    if (!reason) {
        showToast('请填写无法完成整改原因说明', 'warning');
        return;
    }
    if (!suggestion) {
        showToast('请填写下一步整改建议', 'warning');
        return;
    }
    
    const role = getCurrentRole();
    let targetRole = '';
    
    switch(role) {
        case 'user': targetRole = 'escalatedToLeader'; break;
        case 'leader': targetRole = 'escalatedToAdmin'; break;
        case 'manager': targetRole = 'escalatedToTopAdmin'; break;
        default: return;
    }
    
    // 将自定义数据传递给升级函数
    const customData = {
        progress: progress,
        reason: reason,
        suggestion: suggestion
    };
    
    escalateSamplingAnomaly(pendingEscalateAnomalyId, targetRole, customData);
    closeSamplingAnomalyEscalateModal();
    closeSamplingAnomalyDetailModal();
    filterSamplingAnomalies();
    showToast(`已升级至${getSamplingAnomalyStatusText(targetRole)}`, 'success');
}

// 指派管理人员处理
function assignSamplingAnomalyToAdmin(anomalyId) {
    const anomaly = samplingAnomalyData.find(a => a.id === anomalyId);
    if (!anomaly) return;
    
    const users = JSON.parse(localStorage.getItem('systemUsers') || '[]');
    const managers = users.filter(u => u.role === 'manager');
    
    if (managers.length === 0) {
        showToast('没有可用的管理人员', 'error');
        return;
    }
    
    const managerNames = managers.map(m => m.username).join('\n');
    const selected = prompt(`请选择管理人员：\n${managerNames}`);
    
    if (!selected || !managers.some(m => m.username === selected)) {
        showToast('请选择有效的管理人员', 'error');
        return;
    }
    
    anomaly.completion_status = 'adminRectifying';
    anomaly.rectifier = selected;
    anomaly.update_time = new Date().toLocaleString('zh-CN');
    
    addStatusRecordSafely(anomaly, {
        timestamp: new Date().toISOString(),
        status: 'adminRectifying',
        changedBy: getCurrentUsername(),
        changedByRole: 'topadmin'
    });
    
    saveSamplingAnomalies();
    closeSamplingAnomalyDetailModal();
    filterSamplingAnomalies();
    showToast(`已指派${selected}处理`, 'success');
}

// 删除采样点异常
function deleteSamplingAnomaly(anomalyId) {
    const anomaly = samplingAnomalyData.find(a => a.id === anomalyId);
    if (!anomaly) return;
    
    // 检查删除保护
    if (!canDeleteSamplingAnomaly(anomaly)) {
        showToast('已闭环的故障记录禁止删除', 'error');
        return;
    }
    
    if (!confirm('确定要删除这条采样点异常记录吗？')) return;
    
    const index = samplingAnomalyData.findIndex(a => a.id === anomalyId);
    if (index >= 0) {
        const item = samplingAnomalyData[index];
        logAudit('samplingAnomaly', 'delete', `删除采样点异常: ${item.device} - ${item.tag}`);
        samplingAnomalyData.splice(index, 1);
        saveSamplingAnomalies();
        
        closeSamplingAnomalyDetailModal();
        filterSamplingAnomalies();
        showToast('删除成功，请手动点击"保存到云端"按钮同步数据', 'success');
    }
}

// 显示台账
function showSamplingAnomalyLedger() {
    showPage('samplingAnomalyLedger');
}

// 智能计算采样点异常处理进度
function calculateSamplingAnomalyProgress(item) {
    const status = item.completion_status || item.completionStatus;
    
    // 根据状态自动计算进度
    const statusProgressMap = {
        'pending': 10,
        'waitingLeaderConfirm': 20,
        'leaderRectify': 40,
        'leaderConfirmed': 50,
        'waitingAdminConfirm': 60,
        'adminRectify': 70,
        'adminConfirmed': 80,
        'waitingTopAdminConfirm': 90,
        'completed': 100,
        'closed': 100,
        'escalated': 30
    };
    
    if (statusProgressMap[status] !== undefined) {
        return statusProgressMap[status];
    }
    
    // 根据记录数量计算进度
    const totalRecords = (item.completion_records?.length || 0) + 
                         (item.completionRecords?.length || 0) +
                         (item.reject_records?.length || 0) +
                         (item.rejectRecords?.length || 0) +
                         (item.escalate_records?.length || 0) +
                         (item.escalateRecords?.length || 0);
    
    if (totalRecords > 0) {
        const completionCount = (item.completion_records?.length || 0) + 
                               (item.completionRecords?.length || 0);
        return Math.min(Math.round((completionCount / totalRecords) * 100), 100);
    }
    
    return 0;
}

// 渲染台账
function renderSamplingAnomalyLedger() {
    const tbody = safeGetElement('samplingAnomalyLedgerTableBody');
    const emptyState = safeGetElement('samplingAnomalyLedgerEmptyState');
    const table = safeGetElement('samplingAnomalyLedgerTable');
    if (!tbody) return;

    let data = filteredSamplingAnomalyData.length > 0 ? filteredSamplingAnomalyData : samplingAnomalyData;
    
    // 按填报日期倒序排列，最新的显示在前面
    data = data.sort((a, b) => {
        const dateA = new Date(a.reportTime || a.created_at || a.createdAt || a.update_time || Date.now());
        const dateB = new Date(b.reportTime || b.created_at || b.createdAt || b.update_time || Date.now());
        return dateB - dateA;
    });

    if (data.length === 0) {
        if (table) table.style.display = 'none';
        if (emptyState) emptyState.style.display = 'block';
        tbody.innerHTML = '';
        return;
    }

    if (table) table.style.display = '';
    if (emptyState) emptyState.style.display = 'none';

    tbody.innerHTML = data.map((item, i) => {
        const statusText = SAMPLING_ANOMALY_STATUS_MAP[item.completionStatus] || '未开始';
        const statusClass = SAMPLING_ANOMALY_STATUS_CLASS_MAP[item.completionStatus] || 'status-pending';
        
        // 备注栏只显示原本的备注内容
        const remarkContent = item.remark || item.note || '-';
        
        // 根据角色权限生成操作按钮
        const actionButtons = getSamplingAnomalyActionButtons(item);
        
        return `<tr>
            <td><input type="checkbox" class="sampling-anomaly-checkbox" data-id="${item.id}"></td>
            <td>${i + 1}</td>
            <td>${escapeHtml(item.device || '-')}</td>
            <td>${escapeHtml(item.tag || '-')}</td>
            <td>${escapeHtml(item.sampleName || '-')}</td>
            <td>${escapeHtml(item.problemDesc || '-')}</td>
            <td>${formatDate(item.reportTime)}</td>
            <td>${getUserDisplayName(item.reporter) || '-'}</td>
            <td>${getUserDisplayName(item.rectifier) || '-'}</td>
            <td><span class="status-badge ${statusClass}">${statusText}</span></td>
            <td>${escapeHtml(item.completionNote || '-')}</td>
            <td>${getUserDisplayName(item.confirmer) || '-'}</td>
            <td style="text-align: left;">${escapeHtml(remarkContent)}</td>
            <td style="text-align: center; white-space: nowrap;">${actionButtons}</td>
        </tr>`;
    }).join('');
    
    setupSamplingAnomalyLedgerHeaderFreeze();
    setTimeout(() => {
        if (typeof autoAdjustTableColumnWidths === 'function') {
            autoAdjustTableColumnWidths('samplingAnomalyLedgerTable');
        }
    }, 100);
}

