// 获取选中的采样点异常ID
function getSelectedSamplingAnomalyIds() {
    const checkboxes = document.querySelectorAll('.sampling-anomaly-checkbox:checked');
    return Array.from(checkboxes).map(cb => cb.getAttribute('data-id'));
}

// 导出选中的采样点异常
function exportSelectedSamplingAnomalies() {
    const selectedIds = getSelectedSamplingAnomalyIds();
    if (selectedIds.length === 0) {
        showToast('请先选择要导出的记录', 'warning');
        return;
    }
    
    const data = samplingAnomalyData.filter(item => selectedIds.includes(item.id));
    
    // 构建Excel数据
    const headers = ['序号', '装置', '位号', '样品名称', '问题描述', '提报时间', '提报人', '整改负责人', '完成情况', '完成情况说明', '装置确认人', '备注'];
    const rows = data.map((item, i) => {
        // 备注只显示原本的备注内容
        const remarkContent = item.remark || item.note || '';
        
        // 获取整改负责人姓名
        const rectifierName = getUserDisplayName(item.rectifier) || '';
        
        // 获取提报人姓名
        const reporterName = getUserDisplayName(item.reporter) || '';
        
        // 获取装置确认人姓名
        const confirmerName = getUserDisplayName(item.confirmer) || '';
        
        return [
            i + 1,
            item.device || '',
            item.tag || '',
            item.sampleName || '',
            item.problemDesc || '',
            formatDate(item.reportTime),
            reporterName,
            rectifierName,
            SAMPLING_ANOMALY_STATUS_MAP[item.completionStatus] || '',
            item.completionNote || '',
            confirmerName,
            remarkContent
        ];
    });
    
    // 创建工作簿
    const workbook = XLSX.utils.book_new();
    const worksheet = XLSX.utils.aoa_to_sheet([headers, ...rows]);
    
    // 设置列宽
    worksheet['!cols'] = [
        { wch: 8 }, { wch: 15 }, { wch: 10 }, { wch: 12 }, { wch: 25 }, 
        { wch: 15 }, { wch: 10 }, { wch: 12 }, { wch: 12 }, { wch: 20 }, 
        { wch: 12 }, { wch: 20 }
    ];
    
    // 创建样式
    const style = {
        alignment: { horizontal: 'center', vertical: 'center', wrapText: true },
        border: {
            top: { style: 'thin' },
            bottom: { style: 'thin' },
            left: { style: 'thin' },
            right: { style: 'thin' }
        },
        font: { name: '微软雅黑', sz: 11 }
    };
    
    // 获取单元格范围
    const range = XLSX.utils.decode_range(worksheet['!ref']);
    
    // 应用样式到所有单元格
    for (let row = range.s.r; row <= range.e.r; row++) {
        for (let col = range.s.c; col <= range.e.c; col++) {
            const cellAddress = XLSX.utils.encode_cell({ r: row, c: col });
            worksheet[cellAddress].s = style;
        }
    }
    
    XLSX.utils.book_append_sheet(workbook, worksheet, '采样点异常数据');
    
    const fileName = `采样点异常数据_${selectedIds.length}条_${formatDate(new Date())}.xlsx`;
    XLSX.writeFile(workbook, fileName);
    showToast(`成功导出 ${selectedIds.length} 条记录`, 'success');
}

// 导出到Excel
function exportSamplingAnomaliesToExcel() {
    const startDate = safeGetElement('samplingAnomalyExportStartDate')?.value;
    const endDate = safeGetElement('samplingAnomalyExportEndDate')?.value;
    const statuses = [];
    ['Pending', 'Progress', 'Completed', 'Closed'].forEach(s => {
        const cb = safeGetElement(`samplingAnomalyExportStatus${s}`);
        if (cb && cb.checked) statuses.push(cb.value);
    });

    let data = [...samplingAnomalyData];
    
    // 检查是否有选中的项
    const selectedIds = getSelectedSamplingAnomalyIds();
    if (selectedIds.length > 0) {
        data = data.filter(item => selectedIds.includes(item.id));
    }

    // 日期筛选
    if (startDate) {
        data = data.filter(item => {
            if (!item.reportTime) return false;
            return item.reportTime >= startDate;
        });
    }
    if (endDate) {
        data = data.filter(item => {
            if (!item.reportTime) return false;
            return item.reportTime <= endDate;
        });
    }

    // 状态筛选
    if (statuses.length > 0) {
        data = data.filter(item => statuses.includes(item.completionStatus));
    }

    if (data.length === 0) {
        showToast('没有符合筛选条件的数据', 'error');
        return;
    }

    // 构建Excel数据
    const headers = ['序号', '装置', '位号', '样品名称', '问题描述', '提报时间', '提报人', '整改负责人', '完成情况', '完成情况说明', '装置确认人', '备注'];
    const rows = data.map((item, i) => {
        // 备注只显示原本的备注内容
        const remarkContent = item.remark || item.note || '';
        
        // 获取整改负责人姓名
        const rectifierName = getUserDisplayName(item.rectifier) || '';
        
        // 获取提报人姓名
        const reporterName = getUserDisplayName(item.reporter) || '';
        
        // 获取装置确认人姓名
        const confirmerName = getUserDisplayName(item.confirmer) || '';
        
        return [
            i + 1,
            item.device || '',
            item.tag || '',
            item.sampleName || '',
            item.problemDesc || '',
            formatDate(item.reportTime),
            reporterName,
            rectifierName,
            SAMPLING_ANOMALY_STATUS_MAP[item.completionStatus] || '',
            item.completionNote || '',
            confirmerName,
            remarkContent
        ];
    });

    const wsData = [headers, ...rows];
    const ws = XLSX.utils.aoa_to_sheet(wsData);

    // 设置列宽
    ws['!cols'] = [
        { wch: 8 }, { wch: 15 }, { wch: 10 }, { wch: 12 }, { wch: 25 },
        { wch: 15 }, { wch: 10 }, { wch: 12 }, { wch: 12 }, { wch: 20 },
        { wch: 12 }, { wch: 20 }
    ];
    
    // 创建样式
    const style = {
        alignment: { horizontal: 'center', vertical: 'center', wrapText: true },
        border: {
            top: { style: 'thin' },
            bottom: { style: 'thin' },
            left: { style: 'thin' },
            right: { style: 'thin' }
        },
        font: { name: '微软雅黑', sz: 11 }
    };
    
    // 获取单元格范围
    const range = XLSX.utils.decode_range(ws['!ref']);
    
    // 应用样式到所有单元格
    for (let row = range.s.r; row <= range.e.r; row++) {
        for (let col = range.s.c; col <= range.e.c; col++) {
            const cellAddress = XLSX.utils.encode_cell({ r: row, c: col });
            ws[cellAddress].s = style;
        }
    }

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, '采样点异常排查');

    const fileName = `采样点异常排查台账_${new Date().toISOString().slice(0, 10)}.xlsx`;
    XLSX.writeFile(wb, fileName);

    closeSamplingAnomalyExportModal();
    showToast(` 成功导出 ${data.length} 条数据`, 'success');
}

// 关闭导出模态框
function closeSamplingAnomalyExportModal() {
    safeSetDisplay('samplingAnomalyExportModal', 'none');
}

// 打开导出模态框
function openSamplingAnomalyExportModal() {
    const modal = safeGetElement('samplingAnomalyExportModal');
    if (modal) safeSetDisplay('samplingAnomalyExportModal', 'block');
    // 设置默认日期范围（本月）
    const now = new Date();
    const start = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const end = now.toISOString().split('T')[0];
    const startInput = safeGetElement('samplingAnomalyExportStartDate');
    const endInput = safeGetElement('samplingAnomalyExportEndDate');
    if (startInput) startInput.value = start;
    if (endInput) endInput.value = end;
}

// 采样点异常模块初始化标志
let samplingAnomalyModuleInitialized = false;

// 初始化模块
async function initSamplingAnomalyModule() {
    // 防止重复初始化
    if (samplingAnomalyModuleInitialized) {
        console.log('[采样点异常] 模块已初始化，跳过');
        return;
    }
    
    console.log('[采样点异常] ========== 初始化采样点异常排查模块 ==========');

    loadSamplingAnomalies();
    initSamplingAnomalyYearFilter();
    refreshSamplingAnomalyStats();
    filterSamplingAnomalies();

    // 初始化动态同步状态指示器
    if (window.DynamicSync) {
        window.DynamicSync.initModule('samplingAnomaly', 'saveSamplingAnomalyToCloudBtn', '#samplingAnomalyPage .page-header');
    }

    console.log('[采样点异常] === 模块初始化完成 ===');

    // 绑定事件
    const closeAddBtn = safeGetElement('closeAddSamplingAnomalyModal');
    const closeDetailBtn = safeGetElement('closeSamplingAnomalyDetailModal');
    const cancelBtn = safeGetElement('cancelAddSamplingAnomalyBtn');
    const saveBtn = safeGetElement('saveSamplingAnomalyBtn');
    const closeEscalateBtn = safeGetElement('closeSamplingAnomalyEscalateModal');
    const cancelEscalateBtn = safeGetElement('cancelSamplingAnomalyEscalateBtn');
    const confirmEscalateBtn = safeGetElement('confirmSamplingAnomalyEscalateBtn');

    if (closeAddBtn) closeAddBtn.addEventListener('click', closeAddSamplingAnomalyModal);
    if (closeDetailBtn) closeDetailBtn.addEventListener('click', closeSamplingAnomalyDetailModal);
    if (cancelBtn) cancelBtn.addEventListener('click', closeAddSamplingAnomalyModal);
    if (closeEscalateBtn) closeEscalateBtn.addEventListener('click', closeSamplingAnomalyEscalateModal);
    if (cancelEscalateBtn) cancelEscalateBtn.addEventListener('click', closeSamplingAnomalyEscalateModal);
    if (confirmEscalateBtn) confirmEscalateBtn.addEventListener('click', confirmSamplingAnomalyEscalate);
    if (saveBtn) saveBtn.addEventListener('click', async function() {
        saveBtn.disabled = true;
        saveBtn.textContent = '保存中...';
        try {
            await saveSamplingAnomaly({ preventDefault: function(){} });
        } catch (e) {
            console.error('保存出错:', e);
            showToast('保存出错: ' + e.message, 'error');
        } finally {
            saveBtn.disabled = false;
            saveBtn.textContent = '保存';
        }
    });

    // 关闭导出模态框
    const closeExportBtn = safeGetElement('closeSamplingAnomalyExportModal');
    if (closeExportBtn) closeExportBtn.addEventListener('click', closeSamplingAnomalyExportModal);

    // 点击模态框外部关闭（所有模态框）
    window.addEventListener('click', (e) => {
        // 添加/编辑模态框
        if (e.target === safeGetElement('addSamplingAnomalyModal')) {
            closeAddSamplingAnomalyModal();
            return;
        }
        // 详情模态框
        if (e.target === safeGetElement('samplingAnomalyDetailModal')) {
            closeSamplingAnomalyDetailModal();
            return;
        }
        // 导出模态框
        if (e.target === safeGetElement('samplingAnomalyExportModal')) {
            closeSamplingAnomalyExportModal();
            return;
        }
        if (e.target === safeGetElement('samplingAnomalyEscalateModal')) {
            closeSamplingAnomalyEscalateModal();
            return;
        }
    });
    
    // 标记初始化完成
    samplingAnomalyModuleInitialized = true;
    console.log('[采样点异常] 模块初始化完成');
}

// 格式化日期
function formatDate(dateStr) {
    if (!dateStr) return '-';
    try {
        const d = new Date(dateStr);
        if (isNaN(d.getTime())) return dateStr;
        const y = d.getFullYear();
        const m = String(d.getMonth() + 1).padStart(2, '0');
        const day = String(d.getDate()).padStart(2, '0');
        return `${y}-${m}-${day}`;
    } catch (e) {
        return dateStr;
    }
}

// 格式化日期时间（与隐患排查治理模块保持一致）
function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    try {
        const d = new Date(dateStr);
        if (isNaN(d.getTime())) return dateStr;
        const y = d.getFullYear();
        const m = String(d.getMonth() + 1).padStart(2, '0');
        const day = String(d.getDate()).padStart(2, '0');
        const h = String(d.getHours()).padStart(2, '0');
        const min = String(d.getMinutes()).padStart(2, '0');
        return `${y}-${m}-${day} ${h}:${min}`;
    } catch (e) {
        return dateStr;
    }
}

// HTML转义
function escapeHtml(text) {
    if (!text) return '';
    const map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' };
    return String(text).replace(/[&<>"']/g, c => map[c]);
}

// ==================== 审计日志功能 ====================

// 打开审计日志模态框
function openAuditLogModal() {
    // 检查是否为主任
    if (typeof isTopAdmin === 'function' && !isTopAdmin()) {
        alert('⚠️ 只有主任才能查看审计日志');
        return;
    }
    
    const modal = document.getElementById('auditLogModal');
    if (modal) {
        modal.style.display = 'flex';
        initAuditLogModal();
    }
}

// 初始化审计日志模态框
async function initAuditLogModal() {
    // 从云端同步审计日志
    if (typeof syncAuditLogsFromCloud === 'function') {
        try {
            await syncAuditLogsFromCloud();
        } catch (e) {
            console.log('云端同步失败，使用本地数据:', e.message);
        }
    }
    
    // 加载统计数据
    if (typeof getAuditStats === 'function') {
        const stats = getAuditStats();
        document.getElementById('auditTotalCount').textContent = stats.total;
        document.getElementById('auditTodayCount').textContent = stats.todayCount;
        document.getElementById('auditWeekCount').textContent = stats.weekCount;
    }
    
    // 填充模块筛选下拉框
    const moduleSelect = document.getElementById('auditFilterModule');
    if (moduleSelect && typeof AUDIT_CONFIG !== 'undefined') {
        moduleSelect.innerHTML = '<option value="all">全部模块</option>';
        for (const [key, value] of Object.entries(AUDIT_CONFIG.MODULE_INFO)) {
            moduleSelect.innerHTML += `<option value="${key}">${value.icon} ${value.name}</option>`;
        }
    }
    
    // 填充用户筛选下拉框（只显示实际有操作记录的人员）
    const userSelect = document.getElementById('auditFilterUser');
    if (userSelect) {
        // 从系统用户列表获取用户信息
        const systemUsers = JSON.parse(localStorage.getItem('systemUsers') || '[]');
        const logs = typeof getAuditLogs === 'function' ? getAuditLogs() : [];
        
        // 从系统用户列表创建用户名到真实姓名的映射
        const usernameMap = {};
        systemUsers.forEach(user => {
            usernameMap[user.username] = user.realname || user.realName || user.username;
        });
        
        // 从审计日志中获取实际有操作记录的用户，并构建显示姓名映射
        const operatorMap = {};
        logs.forEach(log => {
            if (log.username) {
                // 优先从日志中获取真实姓名，其次从系统用户列表获取
                const displayName = log.realname || log.realName || log.real_name || usernameMap[log.username] || log.username;
                operatorMap[log.username] = displayName;
            }
        });
        
        // 填充下拉框（只显示有操作记录的人员）
        userSelect.innerHTML = '<option value="all">全部用户</option>';
        Object.keys(operatorMap).forEach(username => {
            userSelect.innerHTML += `<option value="${username}">${operatorMap[username]}</option>`;
        });
    }
    
    // 设置日期筛选默认值（最近7天）
    const today = new Date();
    const weekAgo = new Date(today);
    weekAgo.setDate(weekAgo.getDate() - 7);
    
    const endDateInput = document.getElementById('auditFilterEndDate');
    const startDateInput = document.getElementById('auditFilterStartDate');
    if (endDateInput) endDateInput.value = formatDateString(today);
    if (startDateInput) startDateInput.value = formatDateString(weekAgo);
    
    // 初始查询
    queryAuditLogs();
}

// 格式化日期为 YYYY-MM-DD
function formatDateString(date) {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
}

// 查询审计日志
function queryAuditLogs(page = 1) {
    const filters = {
        module: document.getElementById('auditFilterModule')?.value || 'all',
        action: document.getElementById('auditFilterAction')?.value || 'all',
        username: document.getElementById('auditFilterUser')?.value || 'all',
        startDate: document.getElementById('auditFilterStartDate')?.value || null,
        endDate: document.getElementById('auditFilterEndDate')?.value || null,
        keyword: document.getElementById('auditFilterKeyword')?.value || '',
        page: page,
        pageSize: 50
    };
    
    if (typeof queryAuditLogsCore === 'function') {
        const result = queryAuditLogsCore(filters);
        renderAuditLogTable(result.logs);
        renderAuditPagination(result.page, result.totalPages, result.total);
    }
}

// 渲染审计日志表格
function renderAuditLogTable(logs) {
    const tableBody = document.getElementById('auditLogTableBody');
    const table = document.getElementById('auditLogTable');
    const empty = document.getElementById('auditLogEmpty');
    
    if (!tableBody) return;
    
    if (!logs || logs.length === 0) {
        table.style.display = 'none';
        empty.style.display = 'flex';
        return;
    }
    
    table.style.display = 'block';
    empty.style.display = 'none';
    
    // 模块名称映射
    const moduleMap = {
        'personnel': '人员信息管理',
        'inspection': '检查问题台账',
        'training': '培训成绩',
        'samplingCar': '采样车维修',
        'instrument': '仪器维修',
        'patrol': '违章违纪台账',
        'team': '红旗班组',
        'honor': '获得荣誉台账'
    };
    
    // 模块图标映射
    const moduleIconMap = {
        'personnel': '👥',
        'inspection': '📋',
        'training': '📚',
        'samplingCar': '🚛',
        'instrument': '🔧',
        'patrol': '🔍',
        'team': '🏆',
        'honor': '🏅'
    };
    
    // 操作类型映射
    const actionMap = {
        'create': '新增',
        'update': '修改',
        'delete': '删除',
        'batchDelete': '批量删除',
        'import': '批量导入',
        'export': '导出'
    };
    
    // 操作颜色映射
    const actionColorMap = {
        'create': '#28a745',
        'update': '#ffc107',
        'delete': '#dc3545',
        'batchDelete': '#dc3545',
        'import': '#17a2b8',
        'export': '#6c757d'
    };
    
    tableBody.innerHTML = logs.map(log => {
        // 获取操作文本（优先使用日志中已有的 action_name，如果没有则用 action 映射）
        const actionText = log.actionName || log.action_name || actionMap[log.action] || log.action;
        // 获取模块名称
        const moduleName = log.moduleName || log.module_name || moduleMap[log.module] || log.module;
        // 获取模块图标
        const moduleIcon = log.moduleIcon || log.module_icon || moduleIconMap[log.module] || '📄';
        // 获取操作颜色
        const actionColor = log.actionColor || log.action_color || actionColorMap[log.action] || '#6b7280';
        // 获取操作描述
        const targetDesc = log.targetDesc || log.target_desc || '-';
        // 获取操作人（优先显示真实姓名，支持多种字段名）
        const operatorName = log.realname || log.realName || log.real_name || log.username || '未知';
        
        return `
        <tr>
            <td>${formatDateTimeString(log.timestamp)}</td>
            <td>${operatorName}</td>
            <td>${moduleIcon} ${moduleName}</td>
            <td><span class="action-badge" style="background: ${actionColor}">${actionText}</span></td>
            <td title="${targetDesc}">${truncateText(targetDesc, 40)}</td>
            <td>${log.changes ? '<button class="btn btn-sm" onclick="showAuditChanges(\'' + log.id + '\')">查看</button>' : '-'}</td>
        </tr>
        `;
    }).join('');
    
    // 存储当前日志用于详情查看
    window.currentAuditLogs = logs;
}

// 渲染审计日志分页
function renderAuditPagination(currentPage, totalPages, total) {
    const pagination = document.getElementById('auditPagination');
    if (!pagination) return;
    
    if (totalPages <= 1) {
        pagination.innerHTML = `<div class="pagination-info">共 ${total} 条记录</div>`;
        return;
    }
    
    let html = `<div class="pagination-info">共 ${total} 条记录</div>`;
    html += '<div class="pagination-buttons">';
    
    if (currentPage > 1) {
        html += `<button class="btn btn-sm" onclick="queryAuditLogs(${currentPage - 1})">上一页</button>`;
    }
    
    html += `<span class="pagination-current">第 ${currentPage} / ${totalPages} 页</span>`;
    
    if (currentPage < totalPages) {
        html += `<button class="btn btn-sm" onclick="queryAuditLogs(${currentPage + 1})">下一页</button>`;
    }
    
    html += '</div>';
    pagination.innerHTML = html;
}

// 格式化日期时间字符串
function formatDateTimeString(timestamp) {
    const date = new Date(timestamp);
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    const h = String(date.getHours()).padStart(2, '0');
    const min = String(date.getMinutes()).padStart(2, '0');
    const s = String(date.getSeconds()).padStart(2, '0');
    return `${y}-${m}-${d} ${h}:${min}:${s}`;
}

// 截断文本
function truncateText(text, maxLength) {
    if (!text) return '';
    if (text.length <= maxLength) return text;
    return text.substring(0, maxLength) + '...';
}

// 清理过期审计日志
